INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b186f1f8-4957-44dc-bf30-d0b00064ce6f', 167, 'pt', 'Abdominal', '• Deite-se de barriga para cima no chão com os joelhos dobrados.

• Curve os ombros em direção a pélvis. As mãos podem ficar atrás ou do lado do pescoço ou cruzadas sobre o peito.

• Repita', 'core', '["abdômen"]', '["serrátil"]', '["Colchonete"]', 'https://wger.de/media/exercise-images/91/Crunches-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/167/view/', 'abdominal abdomen serratil colchonete', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('30ac081b-fb79-4253-9457-8efc07568790', 616, 'pt', 'Agachamento de impulso', 'Posição inicial:

 Comece na posição de prancha alta:costas, braços e pernas retos e as mãos afastadas alinhadas aos ombros.

 Passos:

 

• Pule jogando seus pés para frente entre os braços, mantendo as costas reta.

• Mantendo suas mãos no chão, retorne suas pernas para a posição de prancha altas.

• Repita.', 'pernas', '["glúteos","quadríceps","abdômen","sóleo"]', '[]', '["Peso corporal"]', NULL, 'CC0', 'BFad07', 'https://wger.de/en/exercise/616/view/', 'agachamento de impulso gluteos quadriceps abdomen soleo peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('46ee5805-512a-43a2-944c-97f7744b0078', 718, 'pt', 'Agachamento parede', '• Encoste na parede, de frente com os pés firmes no chão, alinhados na largura dos ombros e afastados da parede cerca de 60 centímetros

• Deslize pela parede, mantendo as costas pressionada, até que as pernas fiquem em ângulo reto, paralelas ao chão. Os joelhos devem estar diretamente acima dos tornozelos.Dor no quadríceps é normal. Pare se sentir dor nos joelhos ou na rótula do joelho', 'pernas', '["posteriores de coxa","quadríceps"]', '[]', '["Peso corporal"]', NULL, 'CC0', 'Blablabla', 'https://wger.de/en/exercise/718/view/', 'agachamento parede posteriores de coxa quadriceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a2f5b6ef-b780-49c0-8d96-fdaff23e27ce', 615, 'pt', 'Agachamentos', '• Fique com os pés alinhados com os ombros

• Mova o quadril para trás e dobre os joelhos e o quadril para abaixar o troco

• Repita', 'pernas', '["quadríceps"]', '["glúteos"]', '["Barra"]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/615/view/', 'agachamentos quadriceps gluteos barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0a5a7661-1e24-4c15-bb2b-503672141307', 632, 'pt', 'Agachamentos de sumô', 'Posição inicial:

 Fique em pé com as pernas separadas e os dedos dos pés virados para fora.

 Passos:

 

• Agache lentamente dobrando os joelhos. Jogue os braços para frente. Mantenha a cabeça, o peito e os quadris em linha reta. Aperte seus glúteos.

• Levante de volta para a posição inicial.

• Repita este exercício em um movimento pulsante.', 'pernas', '["glúteos","quadríceps"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'sophialj', 'https://wger.de/en/exercise/632/view/', 'agachamentos de sumo gluteos quadriceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b646e62d-c616-4460-b4d1-23cc6a6ddb51', 1010, 'pt', 'Alongamento de pescoço', 'Posição inicial:

 Sente-se ereto em uma cadeira ou em um travesseiro firme.

 Passos:

 

• Expire e incline a cabeça para frente, queixo no peito, colocando as mãos atrás da cabeça.

• Use as mãos para puxar a cabeça levemente para baixo. Segure por 5 segundos.

• Puxe os ombros para trás e para baixo usando os músculos das costas. Isso deve aumentar o alongamento do pescoço. Segure por 5 segundos.

• Agora empurre suavemente a cabeça para cima, enquanto também a puxa para baixo com as mãos. Equilibre as duas forças para que sua cabeça não se mova. Segure por pelo menos 5 segundos.

• Leve os dedos à testa e use-os para mover suavemente a cabeça de volta à posição original.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1010/view/', 'alongamento de pescoco costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7ea504e7-3310-4638-a111-054fabfd4b80', 1009, 'pt', 'Alongamento de pescoço para direita', 'Posição inicial:

 Sente-se ou fique em pé com as costas retas.

 Passos:

 

• Incline a cabeça para o lado e segure por 8 segundos para alongar a lateral do pescoço.

• Com a mão mais próxima no topo da cabeça, puxe suavemente para alongar ainda mais. Segure por 8 segundos.

• Vire o queixo para o ombro. Segure por 8 segundos.

• Solte e retorne à posição inicial.', 'ombros', '["ombros"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1009/view/', 'alongamento de pescoco para direita ombros peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2ecf2e55-c1f3-40ac-b20e-0954f41a2021', 1008, 'pt', 'Alongamento de pescoço para esquerda', 'Posição inicial:

 Sente-se ou fique em pé com as costas retas.

 Passos:

 

• Incline a cabeça para o lado e segure por 8 segundos para alongar a lateral do pescoço.

• Com a mão mais próxima no topo da cabeça, puxe suavemente para alongar ainda mais. Segure por 8 segundos.

• Vire o queixo para o ombro. Segure por 8 segundos.

• Solte e retorne à posição inicial.', 'ombros', '["ombros"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1008/view/', 'alongamento de pescoco para esquerda ombros peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('dcbfa3f0-ba88-4633-a30d-c188dccc5d3f', 1011, 'pt', 'Alongamento frontal do pescoço', 'Posição inicial:

 Sente-se ou fique em pé com as costas retas.

 Passos:

 

• Abra bem a boca.

• Incline lentamente a cabeça para trás com a boca aberta. Se sentir necessidade de apoio, junte as mãos atrás da cabeça.

• Feche e abra a boca muito lentamente.

• Ao final, retorne lentamente à posição inicial e feche a boca.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1011/view/', 'alongamento frontal do pescoco costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c0d9fe98-f4fe-49f3-8037-05e1984e7d2d', 272, 'pt', 'Biceps Martelo', 'Segure dois halteres e sente-se em um banco com as costas retas, os ombros estão ligados rolados para trás. Seus amigos apostam para seu corpo. Dobre os braços e levante o peso com um movimento rápido. Não gire como homens, como acontece com os cachos. Sem nenhuma pausa, baixar o haltere com um movimento lento e controlado.

 Não balance o corpo durante o exercício, o bíceps deve fazer todo o trabalho aqui. Os cotovelos estão ao seu lado e não se movem.', 'braços', '["bíceps"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/86/Bicep-hammer-curl-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/272/view/', 'biceps martelo biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('44afe80f-1ab2-4149-adbf-d8e0ece990ce', 989, 'pt', 'Bulgarian split squats direita', '• Fique de pé em frente a uma cadeira e dê um grande passo. Coloque a parte superior de um de seus pés sobre a cadeira.

• Dobre o joelho da frente, equilibrando-se com os braços até que o joelho de trás quase toque o chão

• Empurre de volta para a posição inicial e repita.', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/989/view/', 'bulgarian split squats direita gluteos quadriceps posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7ce489d2-1948-46de-aa80-277b2ca737aa', 988, 'pt', 'Bulgarian split squats esquerda', '• Fique de pé em frente a uma cadeira e dê um grande passo. Coloque a parte superior de um de seus pés sobre a cadeira.

• Dobre o joelho da frente, equilibrando-se com os braços até que o joelho de trás quase toque o chão

• Empurre de volta para a posição inicial e repita.', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/988/6283b258-a4d7-4833-84f7-a38987022d3d.png', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/988/view/', 'bulgarian split squats esquerda gluteos quadriceps posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('18d277a0-7222-46e7-b2bf-47c8ed169c30', 997, 'pt', 'Burpee sem flexão', 'Posição inicial:

 Fique de pé reto, com os pés afastados alinhados ao quadris.

 Passos:

 

• Se agache e se apoie com as mãos no chão entre os joelhos e a frente de seus pés, mantendo as costas retas.

• Mantendo as mãos no chão, pule jogando as pernas para trás para a posição de prancha altas

• Pule os pés para frente para voltar à posição de agachamento.

• Repita.', 'peito', '["peito"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/997/view/', 'burpee sem flexao peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('853e4429-da4a-492d-b042-5c124282c005', 998, 'pt', 'Burpee sem flexão', 'Posição inicial:

 Fique de pé reto, com os pés afastados alinhados ao quadris.

 Passos:

 

• Se agache e se apoie com as mãos no chão entre os joelhos e a frente de seus pés, mantendo as costas retas.

• Mantendo as mãos no chão, pule jogando as pernas para trás para a posição de prancha altas.

• Pule os pés para frente para voltar à posição de agachamento.

• Salte.

• Repita.', 'peito', '["peito"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/998/view/', 'burpee sem flexao peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9d9c4c9f-045f-4af5-adf2-8bb07c3516dc', 994, 'pt', 'Círculos com o braço pra frente', '• Fique em pé com as costas retas.

• Mantendo os braços esticados, traga-os à sua frente, mova-os para baixo, atrás das costas, depois sobre a cabeça e de volta à posição inicial.

• Continue circulando seus braços conforme descrito na etapa 2.', 'braços', '["braços"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/994/view/', 'circulos com o braco pra frente bracos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('69b3da17-11cc-41fe-bbc1-ee6c45ced41c', 995, 'pt', 'Círculos com o braço pra trás', '• Fique em pé com as costas retas.

• Mantendo os braços esticados, leve-os à sua frente, levante-os acima da cabeça e, a seguir, continue o movimento atrás das costas e desça até a posição inicial.

• Continue circulando seus braços conforme descrito na etapa 2.', 'braços', '["braços"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/995/view/', 'circulos com o braco pra tras bracos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1fae7d45-0731-4640-8809-94c76b836571', 1670, 'pt', 'Círculos de perna (frente-trás)', 'Fique em pé ao lado de uma parede ou apoio estável. Balance uma perna para frente e para trás em movimento controlado, mantendo o tronco ereto e o abdômen contraído. Troque de perna após completar as repetições.', 'pernas', '["posteriores de coxa"]', '["glúteos","quadríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Jhonatan', 'https://wger.de/en/exercise/1670/view/', 'circulos de perna (frente-tras) posteriores de coxa gluteos quadriceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6ddea666-5a57-4ac0-926f-01f8cfdaa4fd', 990, 'pt', 'Coice', '• Fique em posição de quatro.

• Empurre um pé para trás até que esteja totalmente estendido, concentrando-se nos músculos dos glúteos.

• Fique por um segundo depois retorne à posição inicial.

• Repita, alternando os pés', 'pernas', '["glúteos"]', '["posteriores de coxa"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/990/de20457c-914a-45c9-8cf9-0ad9739759a1.png', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/990/view/', 'coice gluteos posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('04ba9a37-4725-43f0-a0b6-767cdab9a79e', 1021, 'pt', 'Elevação da panturrilha direita', '• Fique de pé no chão ou na borda de um degrau para aumentar o alcance do movimento. Levante um pé, colocando a parte superior sobre sua panturrilha.

• Levante os calcanhares até ficar de pé sobre os dedos do pé.

• Fique nesta posição por três segundos, depois abaixe o pé sem tocar o chão com seu calcanhar.', 'panturrilhas', '["panturrilhas"]', '["sóleo"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1021/view/', 'elevacao da panturrilha direita panturrilhas soleo peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4e752292-051a-4043-8f80-a390c23875e6', 702, 'pt', 'Elevação da panturrilha esquerda', '• Fique de pé no chão ou na borda de um degrau para aumentar o alcance do movimento. Levante um pé, colocando a parte superior sobre sua panturrilha.

• Levante os calcanhares até ficar de pé sobre os dedos do pé.

• Fique nesta posição por três segundos, depois abaixe o pé sem tocar o chão com seu calcanhar.', 'panturrilhas', '["panturrilhas"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'McMarcel13', 'https://wger.de/en/exercise/702/view/', 'elevacao da panturrilha esquerda panturrilhas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3d2adf99-8fe9-45cb-b669-c5b18242e282', 1654, 'pt', 'Elevação lateral na mãquina', 'A elevação lateral na máquina é um exercício isolado que trabalha o músculo deltoide medial (lateral) para construir ombros mais largos e definidos. O caminho de movimento fixo da máquina proporciona maior estabilidade do que com halteres, tornando-a ideal para iniciantes ou para aqueles que desejam se concentrar apenas na ativação muscular.', 'ombros', '["ombros"]', '[]', '["Colchonete"]', 'https://wger.de/media/exercise-images/1654/aa724a58-b3b5-4522-b278-1155416236a5.jpg', 'CC-BY-SA 4', 'roneydya', 'https://wger.de/en/exercise/1654/view/', 'elevacao lateral na maquina ombros colchonete', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f956977e-cc05-4db2-a387-ba6140b1ef34', 570, 'pt', 'Encolher os ombros', 'Posicão inicial:

 Sente-se ou fique de pé com as costas retas.

 Passos:

 

• Levante os ombros o máximo possível e segure por 5 segundos.

• Solte os ombros de volta para uma posição relaxada.

• Repita.', 'ombros', '["trapézio"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/570/68b4a33f-40f1-4dda-b56c-a2e20ed13903.jpg', 'CC0', 'BFad07', 'https://wger.de/en/exercise/570/view/', 'encolher os ombros trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f00630d6-578f-487f-8bf5-39c96366ccb8', 660, 'pt', 'Extensões de tríceps no cabo com barra', 'Agarre a barra, fique em pé com os pés afastados dos ombros, mantenha as costas retas e incline-se um pouco para a frente. Empurre a barra para baixo, certificando-se de que os cotovelos não se movam durante o exercício. Sem pausa, volte à posição inicial.', 'braços', '["tríceps"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/660/view/', 'extensoes de triceps no cabo com barra triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('48ee1385-47c5-4821-8b6a-57fac6130776', 132, 'pt', 'Flexão burpee', 'Posição inicial:

 Fique de pé reto, com os pés afastados alinhados ao quadris.

 Passos:

 

• Se agache e se apoie com as mãos no chão entre os joelhos e a frente de seus pés, mantendo as costas retas.

• Mantendo as mãos no chão, pule jogando as pernas para trás para a posição de prancha altas.

• Faça uma flexão de braços.

• Pule os pés para frente para voltar à posição de agachamento.

• Repita.', 'peito', '["peito"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'er0355', 'https://wger.de/en/exercise/132/view/', 'flexao burpee peito', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('cfb6a754-57be-431b-b8d0-d9963120bd5a', 51, 'pt', 'Flexão de Punho com Barra', 'Sentado em um banco, pegue uma barra com as palmas das mãos voltadas para cima e as mãos afastadas na largura dos ombros. Descanse os antebraços nas coxas e deixe os pulsos pendurados sobre os joelhos. Execute o movimento curvando as palmas das mãos e os pulsos em direção ao rosto.
Faça uma pausa por um momento na posição superior e, em seguida, retorne lentamente a barra à posição inicial.', 'braços', '[]', '["bíceps"]', '["Barra","Banco"]', 'https://wger.de/media/exercise-images/51/f1730f56-7aca-4566-8338-3e42b1bee6e1.webp', 'CC-BY-SA 4', 'burenl', 'https://wger.de/en/exercise/51/view/', 'flexao de punho com barra biceps barra banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('04e7fd92-e2e5-4212-ad7c-7542e98f7d83', 1006, 'pt', 'Flexão de queixo', 'Posicão inicial:

 Sente-se ou fique de pé com as costas retas.

 Passos:

 

• Coloque os dedos no queixo para incliná-lo para dentro lentamente, movendo a cabeça para trás para alinhá-la com a coluna.

• Segure por 5 segundos.

• Volte à posição normal da cabeça e repita.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1006/view/', 'flexao de queixo costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a9633731-1d86-4b4a-996f-33a1dee0b0e1', 985, 'pt', 'Flexão em T', '• Faça uma flexão de braços pradrão1.a Deite-se de barriga para baixo1.b Coloque suas mãos perto dos ouvidos1.c Use suas mão para levantar a barriga até que os braços estejam retos, mantendo as costas retas1.d Dobre os braços até que o peito quase toque o chão, certificando-se de que as costas estejam retas1.e Repita a partir do passo 1.c

• Gire seu corpo para o lado para que as costas fiquem retas, de modo que a mão inferior que sustenta o corpo fique totalmente estendida, e apenas a mão inferior e o pé toquem o chão

• Repita, mudando de lado no passo 2 cada vez', 'braços', '["peito","tríceps"]', '["ombros","oblíquos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/985/view/', 'flexao em t peito triceps ombros obliquos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3b96a05b-9705-48da-b43e-6e098234bb35', 454, 'pt', 'Flexão Pike', 'Posição inicial:

 Com a cara virada para baixo:Seu corpo deve fazer uma forma em V, com as costas, braços e pernas retas. Seus quadris devem estar para cima no ar.Você pode chegar a esta posição caminhando com as mãos para trás a partir de uma prancha alta.

 Passos:

 

• Dobre os cotovelos para o lado, mantendo suas costas e pernas retas e movendo sua cabeça para mais perto do chão.

• Endireite os braços, empurrando os quadris para cima e mantendo as costas e as pernas retas.

• Repita.', 'braços', '["peito"]', '["tríceps"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/454/447f3c17-405f-46e0-b138-65c2a8caaab0.png', 'CC-BY-SA 4', 'Nash', 'https://wger.de/en/exercise/454/view/', 'flexao pike peito triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8e420408-0682-4ab6-89f5-2681e54c7ce0', 475, 'pt', 'Flexões de braço', 'Posição inicial:

 Comece pendurando-se na barra de pull-up, com as palmas das mãos voltadas para fora e os pés fora do chão.Suas mãos devem estar ligeiramente mais afastadas do que a largura dos ombros. Apenas ligeiramente, de modo que os cotovelos ainda estejam na frente do corpo e não diretamente para o lado.Seu corpo deve ser reto e apontado ligeiramente para a frente. Seus braços devem estar estendidos.

 Passos:

 

• Use sua força para puxar o corpo para cima de maneira uniforme, aproximando o peito da barra e o queixo logo acima dela. NÃO se levante usando impulso, como chutar.

• Abaixe cuidadosamente o corpo de volta à posição inicial.

• Repita.

 Dicas:

 

• Para fazer flexões corretamente, você deve primeiro aumentar a força em várias áreas-chave, incluindo ombros, braços e abdominais. Comece com flexões somente depois de ter construído força suficiente com outros exercícios.', 'costas', '["dorsais"]', '["ombros","bíceps","trapézio"]', '["Barra fixa"]', 'https://wger.de/media/exercise-images/475/b0554016-16fd-4dbe-be47-a2a17d16ae0e.jpg', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/475/view/', 'flexoes de braco dorsais ombros biceps trapezio barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('09dd3e3c-e53a-4e2c-a2e3-645d334f53e2', 194, 'pt', 'Fundos Para Tríceps', 'Levante-se em barras paralelas mantenha pressionado por 1 segundo, abaixe lentamente e controle por 4 segundos, depois volte sem descanso', 'peito', '["peito","tríceps"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/194/34600351-8b0b-4cb0-8daa-583537be15b0.png', 'CC0', 'BFad07', 'https://wger.de/en/exercise/194/view/', 'fundos para triceps peito triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3284fd27-5402-4821-9c32-29066d4e2667', 984, 'pt', 'Investidas', '• Fique de pé com as costas retas

• Dê um grande passo adiante com sua perna esquerda

• Desça com sua pélvis até quase tocar o chão com o seu joelho direito

• Leve sua pélvis de volta para cima

• Retorne para a posição de pé, dando um passo atrás

• Repita, trocando de pernas a cada vez', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/984/5c7ffe68-e7b2-47f3-a22a-f9cc28640432.png', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/984/view/', 'investidas gluteos quadriceps posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c2078aac-e4e2-4103-a845-6252a3eb795e', 376, 'pt', 'Levantamento de pernas', 'Posição inicial:

 Deite-se de costas, com os pés juntos, e os braços ao seu lado.

 Passos:

 

• Dobre os joelhos, depois os endireite para apontar para cima.

• Mantenha as pernas retas, abaixe-as juntas, sem tocar o chão. Quanto mais baixo você for, mais intenso será o exercício.

• Levante as duas pernas juntas para apontar para cima novamente.

• Repita a partir do passo 2.', 'pernas', '["oblíquos","abdômen"]', '[]', '[]', NULL, 'CC0', 'BFad07', 'https://wger.de/en/exercise/376/view/', 'levantamento de pernas obliquos abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ee8e8db4-2d82-49e1-ab7f-891e9a354934', 184, 'pt', 'Levantamento terra', 'Fique firme, com os pés ligeiramente mais afastados do que os ombros. Fique diretamente atrás da barra, onde ela mal deve tocar sua canela, com os pés apontando um pouco para fora. Curve-se com as costas retas, os joelhos também apontando um pouco para fora. Agarre a barra com uma pegada na largura dos ombros, uma pegada por baixo e uma pegada reversa.
Puxe o peso para cima. No ponto mais alto, faça uma leve depressão para trás e puxe a barra para trás. Segure 1 ou 2 segundos nessa posição. Desça, certificando-se de que as costas não estão dobradas. Depois de descer, você pode voltar assim que os pesos tocarem o chão ou fazer uma pausa, dependendo do peso.', 'costas', '["dorsais"]', '["glúteos"]', '["Barra"]', 'https://wger.de/media/exercise-images/184/1709c405-620a-4d07-9658-fade2b66a2df.jpeg', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/184/view/', 'levantamento terra dorsais gluteos barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9b5f8c6e-2436-4ded-aea9-8c698b0c8768', 1003, 'pt', 'Levantamento terra com Kettlebell', 'Posição inicial:

 Fique em pé na largura do quadril, com o kettlebell centralizado entre os tornozelos. Suas costas devem estar retas, sua cabeça voltada para a frente.

 Passos:

 

• Dobre os quadris e dobre levemente os joelhos para colocar as mãos nas alças do kettlebell. Suas costas devem estar retas enquanto você executa o movimento.

• Agarre as alças do kettlebell, com as mãos empurrando em direções opostas, como se fosse separar a alça.

• Enquanto faz contato com seus abdominais e glúteos, fique em pé.

• Dobre os quadris novamente para trazer o kettlebell de volta para baixo, semelhante ao passo 1.

• Repita a partir da etapa 3.

 Dicas:

 

• Certifique-se de realizar os movimentos corretamente, pois fazer o contrário pode causar lesões. Por exemplo, não se agache em vez de dobrar os quadris, não arredonde as costas ao alcançar o kettlebell e não se incline para trás ao se levantar.', 'costas', '["posteriores de coxa","glúteos"]', '["quadríceps","trapézio"]', '["Kettlebell"]', 'https://wger.de/media/exercise-images/1003/772d6e47-3865-4944-9255-7435d0b06782.png', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1003/view/', 'levantamento terra com kettlebell posteriores de coxa gluteos quadriceps trapezio kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a6c2a970-a621-4e03-be1d-4a29118b1687', 484, 'pt', 'Levantamento terra em rack', 'O levantamento terra deve ser feito usando uma máquina Smith ou um rack livre. A barra ou haltere deve ficar logo abaixo do nível da rótula. Levante usando os glúteos e através dos calcanhares e depois volte à posição inicial com um movimento de controle de 2 segundos.

 Este exercício tem como alvo principalmente a região lombar e os glúteos.', 'costas', '["glúteos"]', '["bíceps"]', '[]', 'https://wger.de/media/exercise-images/161/Dead-lifts-2.png', 'CC-BY-SA 3', 'Mahoney', 'https://wger.de/en/exercise/484/view/', 'levantamento terra em rack gluteos biceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('616f9026-1a1d-4ed8-b068-cfbb81b6a000', 999, 'pt', 'Lunge reverso', 'Posição inicial:

 Fique de pé reto, com os pés afastados.

 Passos:

 

• Dê um passo para trás com uma perna para que você possa dobrar-se confortavelmente a um ângulo de 90 graus.

• Dobre lentamente ambos os joelhos para formar ângulos de 90 graus.

• Retorne para a posição inicial.

• Repita, alternando as pernas.', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/999/d0931eb3-8db0-4049-bb08-aa4036072056.jfif', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/999/view/', 'lunge reverso gluteos quadriceps posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('cf79d9fb-ffce-4648-a64f-27e4274e4c20', 1000, 'pt', 'Mergulho em solo', 'Posição inicial:

 Sente-se com seus braços atrás de você, apoiando suas costas.Seus dedos devem apontar para frente.Seus joelhos devem estar dobrados, com os pés juntos.

 Passos:

 

• Levante seus quadris do chão, endireitando seus braços.

• Dobre os cotovelos, abaixando os quadris.

• Endireite os braços, voltando à posição anterior.

• Repita os passos 2 e 3.

 Notas:

 A dificuldade do exercício depende do quanto você eleva seus quadris.', 'braços', '["tríceps"]', '["ombros","peito"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1000/553266a8-a972-48c5-a014-b12afac66f65.png', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1000/view/', 'mergulho em solo triceps ombros peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('53324f8e-df38-456f-9b7d-8f3a43f45f31', 996, 'pt', 'Montanhistas', 'Posição inicial:

 Começar na posição vertical de flexão, ou na prancha alta.As mãos devem estar diretamente abaixo dos seus ombros.Manter a cabeça alinhada com as costas, virada para o chão.Os pés devem ter a distância entre os quadris.

 Passos:

 

• Mova um joelho em direção ao centro do corpo, em direção aos cotovelos, mantendo a outra perna estendida.

• Num movimento de salto rápido, endireite a perna dobrada para fora e puxe o outro joelho em direção ao seu corpo.

• Continue a repetir o passo 2, alternando as pernas.

 Notas:

 Ao longo do exercício, as costas devem permanecer o mais reto o possível - evite uma corcunda ou uma curvatura nas costas.', 'peito', '["peito"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/996/view/', 'montanhistas peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ec9dca8d-1456-430a-abed-70b8bab4779a', 1020, 'pt', 'Pistol squats direita', '• Fique de pé em uma perna, com a outra perna reta e ligeiramente para frente.

• Dobre um joelho lentamente, descendo para um agachamento e mantendo as costas e a outra perna reta.

• Levante-se lentamente do agachamento, endireitando o joelho dobrado e mantendo a outra perna reta.

• Repita', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa","panturrilhas","abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1020/view/', 'pistol squats direita gluteos quadriceps posteriores de coxa panturrilhas abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fe04cf35-1af5-4b51-89d4-c38d7eaa0db1', 456, 'pt', 'Pistol squats esquerda', '• Fique de pé em uma perna, com a outra perna reta e ligeiramente para frente.

• Dobre um joelho lentamente, descendo para um agachamento e mantendo as costas e a outra perna reta.

• Levante-se lentamente do agachamento, endireitando o joelho dobrado e mantendo a outra perna reta.

• Repita', 'pernas', '["posteriores de coxa","glúteos"]', '["ombros","bíceps","braquial"]', '[]', 'https://wger.de/media/exercise-images/456/3b681e59-377b-40db-9113-ca5873ce084b.jpg', 'CC-BY-SA 3', 'minifigmaster125', 'https://wger.de/en/exercise/456/view/', 'pistol squats esquerda posteriores de coxa gluteos ombros biceps braquial', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4d255f25-f199-401a-bc81-7ffab1d0ed24', 320, 'pt', 'Polichinelos', '• Fique com seus pés juntos e os braços em repouso de cada lado

• Pule para uma posição em que suas pernas fiquem abertas e as mãos toquem sob sua cabeça

• Repita', 'pernas', '["quadríceps"]', '[]', '[]', 'https://wger.de/media/exercise-images/320/6c9124b6-3551-47a8-9c22-20141c8b9c53.png', 'CC-BY-SA 4', 'student1234', 'https://wger.de/en/exercise/320/view/', 'polichinelos quadriceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6e1af72c-f9f5-490d-8977-564df4f24b6f', 1002, 'pt', 'Postura da criança (Balsana)', 'Posição inicial:

 Comece de quatro, joelhos, dedos dos pés e mãos tocando o chão. Seus dois dedões dos pés devem estar se tocando.

 Passos:

 

• Mova os joelhos para que fiquem aproximadamente na largura do quadril.

• Ao expirar, mova a pélvis para trás para se sentar sobre os calcanhares. Suas mãos ainda devem estar tocando o chão.

• Relaxe a parte superior do corpo, abaixando a testa até o chão e deixando as mãos avançarem naturalmente.

• Permaneça nesta postura.

 Dicas:

 

• Para sair da postura, passe os braços para trás sob os ombros e mova a parte superior do corpo para cima, para uma posição sentada.', 'costas', '["costas"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1002/ddf91765-8045-4087-bece-de17f33332ce.png', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1002/view/', 'postura da crianca (balsana) costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b2b40a54-e42b-49ec-97da-4c929ae41d42', 1001, 'pt', 'Prancha alta', 'Posição inicial:

 Entre na posição de prancha alta:as mãos e os dedos dos pés devem tocar o chão, as costas, os braços e as pernas devem estar retos.Para chegar a essa posição, você pode deitar de bruços, colocar as mãos voltadas para baixo ao lado da cabeça e levantar os braços até que estejam retos.

 Passos:

 

• Mantenha a posição inicial durante todo o exercício.', 'peito', '["abdômen"]', '["ombros","oblíquos","tríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1001/view/', 'prancha alta abdomen ombros obliquos triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c9e57bbe-e839-44c6-861d-1c8dd2845e36', 458, 'pt', 'Prancha horizontal', 'Posição inicial:

 

• Inicie na posição de quatro.Os braços devem dobrar-se em um ângulo reto, com os ombro alinhados aos cotovelos.As costas devem estar direitas, com todo o corpo em linha reta.

 Passos:

 

• Mantenha essa posição.', 'core', '["oblíquos","abdômen"]', '["bíceps","quadríceps","tríceps"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/458/b7bd9c28-9f1d-4647-bd17-ab6a3adf5770.png', 'CC-BY-SA 3', 'YYCfit / BFad07', 'https://wger.de/en/exercise/458/view/', 'prancha horizontal obliquos abdomen biceps quadriceps triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5e2761cf-839e-435e-bedb-35e132dcb5ce', 1019, 'pt', 'Prancha lateral direita', '• Deite-se de lado, com o cotovelo inferior em ângulo reto, com o braço para fora

• Levante sua pélvis do chão levantando o ombro inferior para cima, mantendo o antebraço no chão; sua cabeça, pélvis e pés devem estar em linha reta

• Mantenha esta posição', 'core', '["abdômen"]', '["oblíquos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1019/view/', 'prancha lateral direita abdomen obliquos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e1b99153-0102-47fc-b0cd-c21509827b0b', 580, 'pt', 'Prancha lateral esquerda', '• Deite-se de lado, com o cotovelo inferior em ângulo reto, com o braço para fora

• Levante sua pélvis do chão levantando o ombro inferior para cima, mantendo o antebraço no chão; sua cabeça, pélvis e pés devem estar em linha reta

• Mantenha esta posição', 'core', '["abdômen"]', '["oblíquos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'http://www.bodybuilding.com/', 'https://wger.de/en/exercise/580/view/', 'prancha lateral esquerda abdomen obliquos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9e6dae29-5d03-440a-bdf1-2cb25a5179c2', 981, 'pt', 'Progressos', '• Fique de pé de frente para uma cadeira

• Suba na cadeira

• Desça da cadeira

• Repita', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa","panturrilhas"]', '["Banco"]', 'https://wger.de/media/exercise-images/981/f9377a7e-eb58-4cca-b805-2d36863aeb03.png', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/981/view/', 'progressos gluteos quadriceps posteriores de coxa panturrilhas banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7f834f07-fa7b-46b6-8ffa-45930b0602db', 477, 'pt', 'Pull Ups na máquina', 'Os pull-ups da máquina são uma variação assistida do exercício pull-up tradicional. Eles são projetados para ajudar as pessoas que estão desenvolvendo a força necessária para realizar o movimento completo. A máquina permite ajustar o peso para fornecer suporte adequado durante o exercício.
Para realizar flexões na máquina, siga os seguintes passos: posicione-se corretamente, ajuste o peso para o suporte desejado, segure a barra com as mãos alinhadas com os ombros, mantenha os braços retos e a postura ereta. Inicie o movimento flexionando os cotovelos e puxando o corpo em direção à barra. Suba até que seu queixo esteja acima da barra e seus ombros estejam firmes.
A descida deve ser feita de forma controlada, estendendo totalmente os braços. Realize o número desejado de repetições, adaptando-o à sua habilidade. Lembre-se de respirar corretamente durante o exercício, inspirando na fase descendente e expirando ao puxar o corpo para cima.
A prática regular de flexões na máquina fortalecerá os músculos das costas, ombros e braços, ajudando a melhorar a postura e a força geral. À medida que você ganha mais força, pode reduzir gradualmente a assistência fornecida pela máquina e progredir para a tradicional flexão sem ajuda.
Essa variação do exercício é uma opção acessível para iniciantes ou pessoas que lutam para realizar flexões completas. Lembre-se de adaptar o peso e o número de repetições de acordo com seu nível de força e capacidade. A prática regular e a progressão gradual ajudarão a melhorar sua forma e progredir em direção a flexões completas.', 'costas', '["dorsais"]', '["ombros","bíceps","trapézio"]', '[]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/477/view/', 'pull ups na maquina dorsais ombros biceps trapezio', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fff05d7a-f374-4c8a-9885-39f49076918f', 355, 'pt', 'Puxada Alta', 'Puxe a barra para baixo até o strenum e mantenha as costas retas.', 'costas', '["dorsais"]', '[]', '[]', NULL, 'CC-BY-SA 3', 'drthurlow', 'https://wger.de/en/exercise/355/view/', 'puxada alta dorsais', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8bb42000-834f-48ab-af5c-0c31d94e0181', 1280, 'pt', 'Puxada de Biceps', 'Na máquina de puxada de costas, segure a barra com as mãos relativamente próximas. Use uma pegada pronada (P.ex.: o dorso das suas mãos vão ficar voltados para a máquina). Então puxe a barra em uma linha reta, como se fosse em direção ao chão. Garanta que seus bíceps sejam a força motriz do movimento. Você provavelmente sentirá seus ombros e latíssimo trabalhando, mas garanta que seus bíceps sejam os músculos mais afetados.', 'braços', '["bíceps"]', '["ombros","dorsais"]', '[]', NULL, 'CC-BY-SA 4', 'daniel.escada', 'https://wger.de/en/exercise/1280/view/', 'puxada de biceps biceps ombros dorsais', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a7e6c20a-6ddc-4401-9935-ace2d02e3995', 394, 'pt', 'Remada baixa', 'Sente-se, coloque os pés nos pontos de apoio e agarre a barra com uma pegada larga. Puxe o peso com um movimento rápido em direção ao umbigo, não para cima. Mantenha os braços e cotovelos durante o movimento próximos ao corpo. Seus ombros são puxados juntos. Deixe o peso cair lentamente até que seus braços estejam completamente esticados.', 'costas', '["dorsais"]', '["bíceps","braquial"]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/394/5e0c015f-9e4c-4034-beea-b0afbf15d0bd.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/394/view/', 'remada baixa dorsais biceps braquial maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4af6dbd9-8991-484b-9810-68f117c21edf', 83, 'pt', 'Remada Curvada', '• Segurando uma barra com pegada pronada (palmas das mãos voltadas para baixo), dobre ligeiramente os joelhos e incline o tronco para a frente, flexionando a cintura, mantendo as costas retas até que fiquem quase paralelas ao chão. Dica: Certifique-se de manter a cabeça erguida. A barra deve ficar pendurada diretamente à sua frente, com os braços perpendiculares ao chão e ao tronco. Esta é a sua posição inicial.

• Agora, mantendo o tronco imóvel, expire e levante a barra em sua direção. Mantenha os cotovelos próximos ao corpo e use apenas os antebraços para sustentar o peso. Na posição de contração máxima, contraia os músculos das costas e mantenha a posição por uma breve pausa.

• Em seguida, inspire e abaixe lentamente a barra de volta à posição inicial.

• Repita o número de repetições recomendado.', 'costas', '["dorsais"]', '["ombros","bíceps"]', '["Barra"]', 'https://wger.de/media/exercise-images/109/Barbell-rear-delt-row-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/83/view/', 'remada curvada dorsais ombros biceps barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7b99a081-6b1a-4aa5-b86a-5a935d083a35', 91, 'pt', 'Rosca direta com barra reta', 'Segure a barra na largura dos ombros, pois as costas estão retas, os ombros ligamente para trás e os braços estão armazenados. Dobre os braços, levantando o peso, com um movimento rápido. Sem fazer uma pausa, baixar a barra com um movimento lento e controlado.

 Não dê seu corpo equilibrar durante o exercício, todo o trabalho é feito pelos bíceps, que são os humanos múltiplos que devem se mover (preste atenção aos cotovelos).', 'braços', '["bíceps"]', '["braquial"]', '["Barra"]', 'https://wger.de/media/exercise-images/74/Bicep-curls-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/91/view/', 'rosca direta com barra reta biceps braquial barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4b278f57-4505-419a-8b34-172b53eb4adc', 1004, 'pt', 'Rotação do ombro para frente', 'Posicão inicial:

 Sente-se ou fique de pé com as costas retas.

 Passos:

 

• Coloque as mãos nos ombros.

• Gire repetidamente ambas as articulações dos ombros em um movimento circular em um ritmo moderado.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1004/view/', 'rotacao do ombro para frente costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1a40cc23-4609-4951-9b76-237715ae85ed', 1005, 'pt', 'Rotação do ombro para trás', 'Posicão inicial:

 Sente-se ou fique de pé com as costas retas.

 Passos:

 

• Coloque as mãos nos ombros.

• Gire repetidamente ambas as articulações dos ombros em um movimento circular em um ritmo moderado.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1005/view/', 'rotacao do ombro para tras costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fa9838ed-84e8-476c-8157-1774a9c90aff', 987, 'pt', 'Side split squats direita', '• Fique de pé e dê um passo lateral largo, apenas maior que a largura dos ombros.

• Dobre um joelho até que sua coxa fique parelela ao chão. O joelho dobrado deve estar em linha com o pé.

• Empurre de volta para a posição inicial e repita.', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/987/view/', 'side split squats direita pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9801e20b-69c3-43d0-9066-450a68230c42', 986, 'pt', 'Side split squats esquerda', '• Fique de pé e dê um passo lateral largo, apenas maior que a largura dos ombros.

• Dobre um joelho até que sua coxa fique parelela ao chão. O joelho dobrado deve estar em linha com o pé.

• Empurre de volta para a posição inicial e repita.', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/986/view/', 'side split squats esquerda pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1d8599d8-59a5-4faf-a9cf-b81639cbf68b', 992, 'pt', 'Split squats direita', '• Fique de pé com as costas retas

• Dê um grande passo para frente com sua perna esquerda

• Leve sua pélvis para baixo até quase tocar o chão com seu joelho direito

• Leve sua pélvis de volta para cima

• Repita a partir do passo 3.', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/992/view/', 'split squats direita gluteos quadriceps posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('80d83f98-efe5-4d87-a403-c0feadc8650f', 991, 'pt', 'Split squats esquerda', '• Fique de pé com as costas retas

• Dê um grande passo para frente com sua perna esquerda

• Leve sua pélvis para baixo até quase tocar o chão com seu joelho direito

• Leve sua pélvis de volta para cima

• Repita a partir do passo 3.', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/991/view/', 'split squats esquerda gluteos quadriceps posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('22c59ede-970b-43e1-bb51-ac1c2be0b0e0', 627, 'pt', 'Stiff', 'Voce pega o halter, trava a dorsal estufa o peito, inclina até a altura do calcanhar', 'pernas', '["posteriores de coxa"]', '["glúteos"]', '["Barra"]', NULL, 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/627/view/', 'stiff posteriores de coxa gluteos barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('28321cf3-70e6-48a4-ade1-d11382180cb3', 75, 'pt', 'Supino com halteres', 'O movimento é muito semelhante ao supino com barra; no entanto, o peso é abaixado até o peito em um ponto mais baixo.

 Segure dois halteres e deite-se em um banco. Mantenha os pesos próximos ao peito, na altura dos mamilos, e empurre-os para cima até que os braços fiquem estendidos. Abaixe o peso de forma lenta e controlada.', 'peito', '["peito"]', '["ombros","tríceps"]', '["Banco","Halteres"]', 'https://wger.de/media/exercise-images/97/Dumbbell-bench-press-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/75/view/', 'supino com halteres peito ombros triceps banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('57e17672-52b9-43cf-8d0d-4b3f06a0c0d0', 537, 'pt', 'Supino Inclinado com Halteres.', '• 
 

• O banco deve estar inclinado entre 30 e 45 graus.

• 
 

• Certifique-se de empurrar os halteres diretamente para cima (perpendiculares ao chão).', 'peito', '["peito"]', '["ombros","tríceps"]', '["Halteres","Banco inclinado"]', 'https://wger.de/media/exercise-images/16/Incline-press-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/537/view/', 'supino inclinado com halteres. peito ombros triceps halteres banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6c671e43-497f-4863-8d78-b592f3b5e7c6', 661, 'pt', 'Tríceps na máquina', 'Sente-se
e segure a barra firmemente com as mãos. Agora pressione o peso para
cima (não estenda totalmente os braços) e abaixe-o lentamente novamente.
Tal como acontece com outros exercícios de tríceps, é importante não
mover a parte superior dos braços.', 'braços', '["tríceps"]', '[]', '[]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/661/view/', 'triceps na maquina triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('336e224a-a7a1-4808-9871-1ad8cfc3fee7', 1007, 'pt', 'Virar a cabeça', 'Posição inicial:

 Sente-se ou fique em pé com as costas retas e com os ombros para baixo.

 Passos:

 

• Sente-se ou levante-se ereto, ombros caídos.

• Vire a cabeça para o lado o máximo possível. Pare quando você atingir um limite e segure por 5 segundos.

• Retorne à posição central e repita, mudando de lado.', 'ombros', '["ombros"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1007/757846d3-78e4-4068-bbca-62e567372c94.png', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1007/view/', 'virar a cabeca ombros peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('804cd574-1247-4035-915b-47ceab94e78e', 2534, 'en', '(D) Puente de glúteos', 'Lie on you back with your hips and knees flexed, feet on the ground. From this position, raise your butt off of the ground to a height where your body makes a straight line from your knees to your shoulders. To make the exercise more intense, you can add weight by letting a barbell rest on your hips as you complete the motion, or you can put your feet on a slightly higher surface such as a step or a bench.', 'pernas', '["pernas"]', '[]', '[]', 'https://wger.de/media/exercise-images/2534/cedd0b51-c6cf-40b9-881d-58d6c572bf9d.png', 'CC-BY-SA 4', 'dvdfernandez95', 'https://wger.de/en/exercise/2534/view/', '(d) puente de gluteos pernas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c463f618-2777-4836-9c57-92a46d87cf1b', 1948, 'en', '1 Leg Box Squat', 'This exercise requires a sturdy box or a chair. Simple stand ~6 inches in front of it and balance yourself on one leg. From here, begin squatting down in a smooth controlled motion while keeping your other leg straight out in front of you for balance. Slowly sit down on the box, pause for a 1 count and push back up with the working leg, while never letting your other leg touch the ground.', 'pernas', '["posteriores de coxa","quadríceps"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'jesusd', 'https://wger.de/en/exercise/1948/view/', '1 leg box squat posteriores de coxa quadriceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a8a4ea81-9531-48e1-b6dc-f7621c7b9283', 1470, 'en', '1-Arm Half-Kneeling Lat Pulldown', 'Attach a D-Handle to a high pully. And use your lat muscles to pull the weight single handedly.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1470/view/', '1-arm half-kneeling lat pulldown dorsais maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d561c00c-436d-47d9-b647-222e7b637abd', 1966, 'en', '1/2 Kneeling Thoracic Rotation', '• Begin in a half kneeling position with the
leg away from the wall stabilized against the wall
with a ball.

• With both hands directly in front of
you, rotate one arm open attempting to reach
the wall behind you.

• Exhale as you rotate, inhale
as you return to neutral and repeat.', 'core', '["core"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'amwang4', 'https://wger.de/en/exercise/1966/view/', '1/2 kneeling thoracic rotation core peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1b020b3a-3732-4c7e-92fd-a0cec90ed69b', 9, 'en', '2 Handed Kettlebell Swing', 'Two Handed Russian Style Kettlebell swing', 'core', '["posteriores de coxa","glúteos"]', '["quadríceps","abdômen"]', '["Kettlebell"]', NULL, 'CC-BY-SA 4', 'deusinvictus', 'https://wger.de/en/exercise/9/view/', '2 handed kettlebell swing posteriores de coxa gluteos quadriceps abdomen kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7870ad8d-a0c1-4e3a-a4fe-a237908eba9b', 1924, 'en', '3008 Abdominal Crunch', 'This is especially for the gym80 device 3008 Abdominal Crunch.', 'core', '["abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1924/view/', '3008 abdominal crunch abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1f2ba913-3b2e-4621-a70b-b7f0ce649032', 1754, 'en', '45° lateral raises', 'dumbbell raise in the space between front and side raises', 'ombros', '["ombros"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1754/view/', '45° lateral raises ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7bd11f85-69a1-42ea-9924-7df7ba6d4f10', 2564, 'en', '90/90 Breathing', 'Controlled breathing drill performed in a 90/90 position to encourage rib, abdominal, and pelvic coordination.', 'core', '["core"]', '[]', '[]', NULL, 'CC-BY-SA 3', '', 'https://wger.de/en/exercise/2564/view/', '90/90 breathing core', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e205aa88-c7b8-43a7-a527-c881b2d5f259', 2615, 'en', '90/90 Hamstring / Barre-Style Stretch', 'Custom description created by the Integrated Conditioning routine importer for wger.', 'pernas', '["posteriores de coxa"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2615/view/', '90/90 hamstring / barre-style stretch posteriores de coxa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a825d0f7-de61-4ca3-a2b2-0f8b00303464', 2613, 'en', '90/90 Hip Switches', 'Custom description created by the Integrated Conditioning routine importer for wger.', 'pernas', '["glúteos"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2613/view/', '90/90 hip switches gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('203a6fee-7436-4313-858f-c1e364136793', 1573, 'en', 'Ab wheel', '• Starting Position : Kneel on the floor with the ab wheel in front of you.

• Grip the Wheel : Hold the handles firmly.

• Roll Out : Slowly roll the wheel forward, extending your body while keeping your core tight.

• Return : Pull the wheel back towards your knees, maintaining tension in your core.', 'core', '["abdômen"]', '["oblíquos","serrátil"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1573/a9ab402b-61ef-4d60-b91a-df52bf7f41a9.jpg', 'CC-BY-SA 4', 'lhegedus', 'https://wger.de/en/exercise/1573/view/', 'ab wheel abdomen obliquos serratil peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2ac901e6-f0c2-416f-998f-e01e00fe0aa1', 1933, 'en', 'Abdominal Crunch', 'The Abdominal Crunch is a classic core isolation exercise performed on the floor or a mat. Unlike a full sit-up, it involves a smaller range of motion where you only lift your shoulders and upper back off the ground, keeping your lower back pressed firmly against the floor.', 'core', '["abdômen"]', '["oblíquos","serrátil"]', '["Colchonete"]', NULL, 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1933/view/', 'abdominal crunch abdomen obliquos serratil colchonete', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('793b0e5f-8dea-48a6-84c8-9123b59c2721', 1828, 'en', 'Abdominal Draw-In', 'Lie
on your back with knees bent. Gently pull your belly button toward your
spine without moving your hips or holding your breath.', 'core', '["abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1828/view/', 'abdominal draw-in abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d015a276-02ad-4c28-9d36-aedfbb431f53', 1096, 'en', 'Abduction while standing', 'Training a stable stance, predominantly on one leg, is crucial for both sides. On the one hand, it prevents discomfort and, on the other, it establishes a stable foundation. The practitioner assumes the usual standing position and, with a stable upper body, attempts to repeatedly lift the unloaded leg, bend it at the hip and knee, and then lower it again. The movement is also repeated on the other side. The exercise trains the stability of the hip-surrounding muscles.', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'tregga', 'https://wger.de/en/exercise/1096/view/', 'abduction while standing pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d02f6fe0-8ae3-4251-8f94-a63e38249a55', 2491, 'en', 'Abductors', 'Based on Abductors Sel. by Technogym.
Position yourself on the machine and open your legs as much as possible.
Return slowly to the original position.', 'pernas', '["glúteos"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'lbroggi', 'https://wger.de/en/exercise/2491/view/', 'abductors gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4e396da7-b25e-42de-a507-fe1aeb4f3f77', 2614, 'en', 'Adductor Rock Backs', 'Custom description created by the Integrated Conditioning routine importer for wger.', 'pernas', '["pernas"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2614/view/', 'adductor rock backs pernas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1c60ade0-1e8c-475b-b2d3-bfdf313987f4', 2493, 'en', 'Adductor Side Plank', 'Set up next to a bench in a 90° angle on your side. One leg goes up on the bench with the side of your calf touching it. The other leg goes below the bench. Forearm closer to the ground is at a 90° angle, hand pointing front. Now push off the floor with the forearm closer to the ground, upper side of your body should be completely straight, level with the bench (it''s a side plank after all). Hold that position.', 'pernas', '["posteriores de coxa","glúteos"]', '[]', '["Banco"]', NULL, 'CC-BY-SA 4', 'hurr99', 'https://wger.de/en/exercise/2493/view/', 'adductor side plank posteriores de coxa gluteos banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('701d9cee-0797-4177-8556-252de669b56c', 2492, 'en', 'Adductors', 'Based on Adductor Sel. by Technogym.
Sit on the machine and set the rest position to a comfortable opening angle.
Close your legs.
Gently return to the rest position.', 'pernas', '["glúteos"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'lbroggi', 'https://wger.de/en/exercise/2492/view/', 'adductors gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5831bcbb-28a7-4bd5-930d-a740acccf747', 1102, 'en', 'Alternate back lunges', 'The posterior muscles of the buttocks, hamstrings, soleus and gastrocnemius are trained more', 'pernas', '["glúteos","quadríceps"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1102/view/', 'alternate back lunges gluteos quadriceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a136959c-b0c8-49d3-99b9-0a5f41abf00e', 1012, 'en', 'Alternating bicep curls', 'Starting position:

 Start standing up with dumbbells in each hand, your back straight and feet hip-width apart. Your arms should be relaxed, pointing down. Your knees should be slightly bent, your abs contracted, and your shoulders down.

 Steps:

 

• Bend one arm at the elbow, bringing the dumbbell up to your shoulder. Your upper arm should remain motionless during this movement.

• Bring the dumbbell back down until your arm is in its original relaxed position.

• Repeat, switching arms.', 'braços', '["bíceps"]', '["braquial"]', '["Halteres"]', 'https://wger.de/media/exercise-images/1012/8270fdb8-28f1-4eff-b410-af8642085b3f.png', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1012/view/', 'alternating bicep curls biceps braquial halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('94238bef-15ee-42b6-8035-79854b3c6e65', 1192, 'en', 'Alternating Biceps Curls With Dumbbell', 'Hold two dumbbells, the arms are streched, the hands are on your
side, the palms face inwards. Bend one arm at a time and bring the weight with a
fast movement up. At the same time, rotate your arms by 90 degrees at
the very beginning of the movement. At the highest point, rotate a
little the weights further outwards. Without a pause, bring the arm back down, slowly, and do the same with the other arm.

 Don''t allow your body to swing during the exercise, all work is done
by the biceps, which are the only mucles that should move (pay attention
to the elbows).', 'braços', '["bíceps"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1192/651a4535-8210-4dbd-8f06-61d95fdd9963.png', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1192/view/', 'alternating biceps curls with dumbbell biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('eb9476ac-2c00-4f49-a40f-f81682161a75', 1567, 'en', 'Alternating dumbbell hammer curl', 'Stand with your knees slightly bent and your back straight. Hold a dumbbell in each hand, using a neutral grip at your sides.', 'braços', '["bíceps"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1567/0a8c155c-a48e-47e8-9df3-e39f025c6cad.png', 'CC-BY-SA 4', 'Mariano_O', 'https://wger.de/en/exercise/1567/view/', 'alternating dumbbell hammer curl biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('45251627-5f89-4858-bf0c-8884a21cbb1f', 1486, 'en', 'Alternating High Cable Row', '• Start
by putting the attachment in a high position on the cable station and step back about 1m from the attachment. Grab
the cable pulley handle in your left hand at about head height with your elbow slightly bent. Step back with your left foot.

• Pull
your elbow joint in toward the torso twisting slightly and perform a
single-arm row. Engage the lats as you twist.

• Return
to the starting position with cable pulley and left foot and grab the cable pulley handle in the right
hand. Repeat this motion on the opposite side with your right foot stepped back.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1486/view/', 'alternating high cable row dorsais maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('81015468-545f-4170-9b46-701afe77848e', 1501, 'en', 'Alternative DB Gorilla rows', 'Slightly bent down and knees to mimic a gorilla position and pull/row up the DBs to the chest. DB stay straight (thumbs pointing up)', 'costas', '["dorsais"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1501/view/', 'alternative db gorilla rows dorsais halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fa5252d3-973c-4b35-9324-a02460545283', 1804, 'en', 'ankle dorsiflexion rocks', 'Move your knee forward, keeping your heel on the ground. Hold the position for a couple of seconds and return to the starting position.', 'pernas', '["panturrilhas","sóleo"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1804/691c69b8-c3db-4177-8435-dd3a97d88542.webp', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1804/view/', 'ankle dorsiflexion rocks panturrilhas soleo peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('979e3433-4db8-4f37-a5e0-f43c86756690', 1864, 'en', 'Ankle Roll', 'View the video to undestand the exercise', 'pernas', '["pernas"]', '[]', '[]', 'https://wger.de/media/exercise-images/1864/5970cdd8-0123-4eba-a921-2157fb6adacf.png', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1864/view/', 'ankle roll pernas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7dd7a735-c1fe-4ca0-a6e8-e825d897b065', 1141, 'en', 'Arabesque', 'Take all your weight onto one leg and you''re going to maintain that position, keeping your hips and pelvis level the whole time. With your back in a neutral position you want to tilt yourself forward kicking your leg back up and then slowly with your glutes bring yourself back up to neutral.', 'pernas', '["posteriores de coxa","glúteos"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1141/c7be1cd1-46c5-4a86-a114-5f0fe861c3e0.jpg', 'CC-BY-SA 4', 'cleen', 'https://wger.de/en/exercise/1141/view/', 'arabesque posteriores de coxa gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f4291da4-09c2-4605-a90c-c926c6a92515', 2533, 'en', 'Arch Hang', 'https://www.youtube.com/watch?v=C995b3KLXS4&t=7s

 

• Elbows should stay straight

• Hold it for time/reps

• Start at an active hang: https://www.youtube.com/watch?v=HoE-C85ZlCE

• Progress towards a 90 degree in your shoulder', 'ombros', '["ombros"]', '[]', '["Barra fixa"]', NULL, 'CC-BY-SA 4', 'wintercyan', 'https://wger.de/en/exercise/2533/view/', 'arch hang ombros barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('56808c52-050e-4c24-9f27-2657f0462499', 1545, 'en', 'Archer Pull Up', 'An archer pull-up is an advanced bodyweight exercise that strengthens your back and biceps, serving as a progression towards a one-arm pull-up. It gets its name from the "bow-drawing" position your body takes at the top.Here''s how to do it:

 

• Grip: Grasp a pull-up bar with a wider-than-shoulder-width overhand grip.

• Starting Position: Hang with arms fully extended, engaging your core and keeping your shoulder blades pulled down.

• The Pull: Pull your body up towards one hand, similar to a regular pull-up. At the same time, extend the other arm out to the side, keeping it as straight as possible. Your chin should come towards the hand that is pulling.

• Hold & Lower: Briefly hold the top position where one arm is bent and pulling, and the other is extended. Slowly lower yourself back to the starting position with control.

• Alternate: Repeat the movement, pulling up towards the opposite hand.The key to this exercise is to keep the assisting arm as straight as possible to maximise the load on the working arm. This makes it a challenging but effective exercise for unilateral pulling strength.', 'costas', '["dorsais"]', '["bíceps","trapézio"]', '[]', NULL, 'CC-BY-SA 4', 'Antsy6277', 'https://wger.de/en/exercise/1545/view/', 'archer pull up dorsais biceps trapezio', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b48cd640-dd9f-4557-a4db-8cd33d5655a6', 1590, 'en', 'Arm and neck stretch', 'Relieves tension in the upper body, especially useful for people with office jobs or prolonged postures.', 'core', '["ombros","trapézio","tríceps"]', '["dorsais","serrátil"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'MrAlfaRobot', 'https://wger.de/en/exercise/1590/view/', 'arm and neck stretch ombros trapezio triceps dorsais serratil peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e62d52fa-32f9-4747-9005-f88f05dc8334', 1606, 'en', 'Arm Raises (T/Y/I)', 'Stand upright with feet hip-width apart, core engaged, and arms relaxed at your sides. From this position, perform three different arm raises to target the shoulders and upper back:

 

• T Raise: Lift your arms straight out to the sides until they are parallel to the floor, forming a “T” shape.

• Y Raise: Lift your arms upward at about a 45° angle from your body to form a “Y” shape.

• I Raise: Raise your arms straight overhead, close together, forming an “I” shape.

 Maintain a neutral spine, avoid arching your lower back, and move slowly with control. Focus on squeezing your shoulder blades together and keeping your shoulders down away from your ears.', 'braços', '["ombros","dorsais","serrátil","trapézio"]', '["oblíquos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'WiNNiE', 'https://wger.de/en/exercise/1606/view/', 'arm raises (t/y/i) ombros dorsais serratil trapezio obliquos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f24cb758-9c0d-42d4-ad9e-6025c527dd13', 20, 'en', 'Arnold Shoulder Press', 'Very common shoulder exercise.

 As shown here: https://www.youtube.com/watch?v=vj2w851ZHRM', 'ombros', '["ombros"]', '["trapézio","tríceps"]', '["Halteres"]', NULL, 'CC-BY-SA 3', 'trzr23', 'https://wger.de/en/exercise/20/view/', 'arnold shoulder press ombros trapezio triceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e4bbd8d8-20e1-4174-b785-2590d2a1a7ad', 1737, 'en', 'Assisted chin-ups', 'Chin-ups with machine assistance (counterweights)', 'costas', '["bíceps","dorsais"]', '["braquial","trapézio"]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1737/view/', 'assisted chin-ups biceps dorsais braquial trapezio', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8bc4c616-e76b-4291-9074-186ecbbb3cfd', 1929, 'en', 'Assisted Pull-Up', 'The Assisted Pull-Up is a compound vertical pulling exercise performed on a machine with a counterweight platform or by using resistance bands. It mimics the mechanics of a standard pull-up but reduces the total weight you have to lift, making it an excellent tool for building functional strength and perfecting your technique.', 'costas', '["dorsais","trapézio"]', '["ombros","bíceps","abdômen","serrátil"]', '["Elástico"]', NULL, 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1929/view/', 'assisted pull-up dorsais trapezio ombros biceps abdomen serratil elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4037fc14-d7a9-4901-8341-6538e415adc4', 1219, 'en', 'Australian pull-ups', '• Lie down under a high bar or suspension bar, positioned at an appropriate height.

• Position yourself on your back under the bar, gripping the bar with a supinated grip (palms facing you).

• Adjust your position so that your body is aligned straight from head to toe. Arms should be fully extended, shoulders stabilized, and legs aligned with the rest of the body.

• Bend your elbows and pull your chest towards the bar, contracting your back muscles. Imagine you''re trying to bring your shoulder blades together.

• Hold the contraction at the top of the movement for a moment to maximize muscle activation.

• Slowly return to the starting position, extending your elbows.', 'braços', '["ombros","bíceps","dorsais"]', '["trapézio"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'PaukOne', 'https://wger.de/en/exercise/1219/view/', 'australian pull-ups ombros biceps dorsais trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f2733700-aa5d-4df7-bc52-1876ab4fb479', 31, 'en', 'Axe Hold', 'Grab dumbbells and extend arms to side and hold as long as you can', 'braços', '["braços"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/31/92f6451b-f89d-49d6-9531-8970ea420d97.png', 'CC-BY-SA 3', 'GrosseHund', 'https://wger.de/en/exercise/31/view/', 'axe hold bracos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('17593b54-1e4e-49d7-8f9f-3a706823a4c5', 1263, 'en', 'Back bridge', 'Lie on the floor with your back resting on the floor and your legs bent, feet flat on the floor, leaving about 20 cm between your feet and your buttocks. Your hands remain flat on the floor, pressed against your ears, with your fingers pointing toward your toes. Your elbows are bent and pointing toward the ceiling. This is the starting position. Now push your hips as high as you can, raising your body off the floor, and continue pushing through your hands, extending your elbows and knees, until your back is fully arched (lumbar bridge). Your head also comes off the floor and should be level with your elbows, looking back. This is the final position. The descent should be slow and controlled. Your spine should be in a convex curve. It''s not good to lift your back off the floor; it should remain straight. It should be well rounded. You''ll also notice a feeling of increased oxygenation in your back. After lifting off the floor, your hips should be very high, even above the level of your head. Your arms and legs should remain straight. It seems easy, but it requires a good level of flexibility. Breathing should be deep. This posture stretches the rib cage and puts pressure on the diaphragm. If the posture is performed correctly, breathing will be perfect. Never hold your breath during the exercise.', 'costas', '[]', '["ombros","posteriores de coxa","panturrilhas","dorsais","trapézio","tríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1263/view/', 'back bridge ombros posteriores de coxa panturrilhas dorsais trapezio triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('deebd257-f84d-4879-9dc4-353ee0ea534f', 1143, 'en', 'Back extensión', 'Espalda en maquina de extensión con peso', 'costas', '["dorsais","serrátil"]', '[]', '[]', 'https://wger.de/media/exercise-images/1143/6e21cb6c-da09-4bcd-b9d2-1ef75237b763.png', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1143/view/', 'back extension dorsais serratil', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8e1cda15-542b-4714-8cc5-c1fe5089ee27', 1742, 'en', 'Back Lever', 'Hanging from a pull-up bar facing downwards with your arms extended', 'costas', '["costas"]', '[]', '["Barra fixa"]', NULL, 'CC-BY-SA 4', 'Happy', 'https://wger.de/en/exercise/1742/view/', 'back lever costas barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d301d901-a2c6-4916-b09e-07ab7a3c8519', 1092, 'en', 'Bag training', 'Bag training improves muscle definition of: deltoids; rear deltoids; triceps; biceps, as well as being a great cardio exercise', 'cardio', '["ombros","peito","trapézio"]', '["bíceps","posteriores de coxa","panturrilhas","dorsais","oblíquos","abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1092/view/', 'bag training ombros peito trapezio biceps posteriores de coxa panturrilhas dorsais obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a1e8759d-72b9-422f-87a8-9d316fa18498', 1525, 'en', 'Ball Slams', '• Stand with your feet about shoulder-width apart, your knees and hips slightly bent, holding the ball in both hands at chest height. Engage your core, and keep a good posture.

• Extend your knees and drive your hips forward while simultaneously lifting the ball. Aim for being as tall as possible, the ball overhead, arms up, hips slightly forward, and on your toes from the force of your drive.

• Use your core and arms to slam the medicine ball straight down between your feet with as much force as possible. Press your hips back and bend your knees to further power the slam. Exhale as you slam the ball down.

• Squat down to pick up the ball from the floor, then immediately move into the next slam by repeating the movement. Repeat for reps or time.', 'cardio', '["dorsais","oblíquos","abdômen"]', '["ombros","glúteos"]', '[]', NULL, 'CC-BY-SA 4', 'flanny', 'https://wger.de/en/exercise/1525/view/', 'ball slams dorsais obliquos abdomen ombros gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('83650b79-add8-4846-b114-b4f28d96495a', 1826, 'en', 'Band pull-apart with external rotation', 'Stand tall with your feet shoulder-width apart, chest out, and shoulders back.

 Hold the resistance band with both hands, palms facing up or facing each other, depending on the band type.

 Bend your elbows at a 90-degree angle and glue your upper arms to your sides.

 The band should have some tension in the starting position, with your hands closer together in front of your stomach.

 Rotate Outward: While keeping your elbows tucked into your sides, slowly move your hands away from each other, stretching the band.

 Squeeze: Squeeze your shoulder blades together and down as you rotate your hands outward.

 Range of Motion: Rotate your hands as far outward as you comfortably can without allowing your elbows to leave your sides.

 Hold: Hold the end position for 1–2 seconds to maximize muscle engagement.

 Return: Slowly and with control, bring your hands back to the starting position.', 'ombros', '["ombros"]', '[]', '["Elástico"]', NULL, 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1826/view/', 'band pull-apart with external rotation ombros elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f18eb684-9a9b-4566-9771-e22a87d536b1', 1380, 'en', 'Band pull-aparts', '• Hold the band with your arms extended in front of you at shoulder height.

• Keep your elbows slightly bent but fixed throughout the movement.

• Pull the band apart by spreading your arms until the band touches or comes close to your chest.

• Slowly bring your arms back to the starting position, controlling the tension on the band.', 'costas', '["costas"]', '[]', '["Elástico"]', NULL, 'CC-BY-SA 4', 'schwolfar', 'https://wger.de/en/exercise/1380/view/', 'band pull-aparts costas elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3096b34e-1781-4f99-8187-d9acac8e712b', 2494, 'en', 'Band Terminal Knee extension', 'This is an end range strengthening exercise for the knee extensors. Start by looping a band around the back of one knee and anchoring the other end to a stable surface in front of you. Stand in a split stance with the banded knee bent and placed as the front leg. Straighten the knee to pull against the bands resistance and maintain a contraction in your quadriceps for up to 5 seconds before releasing.', 'pernas', '["quadríceps"]', '[]', '["Elástico"]', 'https://wger.de/media/exercise-images/2494/02f1ae86-d374-4b5a-b314-a76c487ea1e9.png', 'CC-BY-SA 4', 'Rehab Hero', 'https://wger.de/en/exercise/2494/view/', 'band terminal knee extension quadriceps elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fcdc26c0-a20d-4b93-a629-2a3a15eae426', 1865, 'en', 'Banded Ankle Mobility', 'View the video to undestand the exercise', 'pernas', '["pernas"]', '[]', '[]', 'https://wger.de/media/exercise-images/1865/c2c9848e-5094-4ed9-bd81-0831b6551483.png', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1865/view/', 'banded ankle mobility pernas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8cc84753-e638-4c43-91c6-51c097813ca4', 1842, 'en', 'Banded Clamshell', 'Position 
Side plank with the elbow and the forearm on the ground and the legs slightly bent. Stretch a doubled-up resistance band between your thighs, just above the knee.

 Execution 
Lift
your upper knee while keeping your feet close together, like a “shell
opening,” then slowly return to the starting position. Keep your core
stable and your hips aligned.', 'pernas', '["glúteos","abdômen"]', '["quadríceps"]', '["Elástico"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1842/view/', 'banded clamshell gluteos abdomen quadriceps elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('add364ed-4444-4752-9a22-d85d58199fe5', 1877, 'en', 'Banded Scapular Retraction', 'Attach one end of resistance band to wall/upright/... at shoulder height. Insert arm into the loop, at the tricep. Step back until band is pulled straight. Pull back elbow and shoulder against the resistance of the band.', 'costas', '["ombros","trapézio"]', '[]', '["Elástico"]', NULL, 'CC-BY-SA 4', 'hurr99', 'https://wger.de/en/exercise/1877/view/', 'banded scapular retraction ombros trapezio elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4c317795-c301-4081-9f96-6036682f80c1', 1838, 'en', 'Banded Shoulder Drills', '• Attach a resistance band to something solid behind you. Stand away from it, holding it in your hand so it is taut.

• See the attached youtube video: https://www.youtube.com/watch?v=zdwEWchSjrI .', 'ombros', '["ombros","peito","trapézio"]', '[]', '["Elástico"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1838/view/', 'banded shoulder drills ombros peito trapezio elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a6bced3c-72f5-42a3-9438-5569d46f49fd', 41, 'en', 'Barbell Ab Rollout', 'Place a barbell on the floor at your feet.

 Bending at the waist, grip the barbell with a shoulder with overhand grip.

 With a slow controlled motion, roll the bar out so that your back is straight.

 Roll back up raising your hips and butt as you return to the starting position.', 'core', '["oblíquos"]', '[]', '["Barra"]', 'https://wger.de/media/exercise-images/41/34b37423-269f-43d4-9d29-d2a90eeaa6b4.png', 'CC-BY-SA 4', 'sevae', 'https://wger.de/en/exercise/41/view/', 'barbell ab rollout obliquos barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e9e7372c-b5c1-45d9-ae5c-b1aa0fc2e2ce', 1638, 'en', 'Barbell Clean and press', 'This exercise involves lifting a barbell from the ground to the shoulders, then pressing it overhead. It is a compound movement that targets multiple muscle groups, including the legs, back, shoulders, and arms. It is often used in strength and conditioning programs to improve overall power and athleticism.', 'ombros', '["ombros","peito"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1638/046c09b0-c35d-48d0-a552-39dd49f956d2.webp', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1638/view/', 'barbell clean and press ombros peito halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5d0e0a8b-1940-4034-b4ae-b965859f1ff0', 1801, 'en', 'Barbell Full Squat', '• The barbell full squat is a compound exercise that targets multiple muscle groups in the lower body, including the quadriceps, hamstrings, and glutes.

• Proper form is crucial for maximizing results and preventing injuries during the barbell full squat. This includes maintaining a shoulder-width stance, creating whole body tension, controlling your descent, and maintaining proper depth and knee positioning.

• Assistance moves such as the front squat, goblet squat, split squat, and Bulgarian split squat can help improve your performance in the barbell full squat by targeting specific muscle groups and improving overall technique.

• To achieve new personal records in your back squat, gradually increase weight over time, vary rep ranges and sets to stimulate muscle growth, and prioritize rest and recovery between training sessions.', 'pernas', '["posteriores de coxa","glúteos","quadríceps"]', '["panturrilhas","abdômen"]', '["Barra"]', 'https://wger.de/media/exercise-images/1801/60043328-1cfb-4289-9865-aaf64d5aaa28.jpg', 'CC-BY-SA 4', 'fabrice', 'https://wger.de/en/exercise/1801/view/', 'barbell full squat posteriores de coxa gluteos quadriceps panturrilhas abdomen barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('dae6f6ed-9408-4e62-a59a-1a33f4e8ab36', 43, 'en', 'Barbell Hack Squats', 'Perform leg squats with barbell behind your legs', 'pernas', '["quadríceps"]', '["posteriores de coxa","glúteos"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'BePieToday', 'https://wger.de/en/exercise/43/view/', 'barbell hack squats quadriceps posteriores de coxa gluteos barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('04e7d7e4-f8d2-406d-97df-3df3bceec22c', 46, 'en', 'Barbell Lunges Standing', 'Put barbell on the back of your shoulders. Stand upright, then take the first step forward. Step should bring you forward so that your supporting legs knee can touch the floor. Then stand back up and repeat with the other leg.

 Remember to keep good posture.', 'pernas', '["quadríceps"]', '["glúteos"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'Mikko Ruohola', 'https://wger.de/en/exercise/46/view/', 'barbell lunges standing quadriceps gluteos barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('67c26c9b-32f3-4b8b-b13a-4d8be4803975', 48, 'en', 'Barbell Reverse Wrist Curl', 'Sitting on a bench, grab a barbell with your palms facing down and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees.

 Curl your knuckles towards your face, lifting the barbell. Pause for a moment in the top position, then slowly return the barbell to the starting position.', 'braços', '["braços"]', '[]', '["Barra","Banco"]', NULL, 'CC-BY-SA 4', 'burenl', 'https://wger.de/en/exercise/48/view/', 'barbell reverse wrist curl bracos barra banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('72129e4f-df97-4869-9561-33a1ba3c9186', 1700, 'en', 'Barbell Romanian Deadlift (RDL)', 'Execution 
 

• 
 Hinge at the hips: 

 

• Push your hips backward , keeping a slight bend in the knees (soft knees).

• Lower the barbell along the front of your thighs/shins while maintaining a neutral spine .

• Keep the bar close to your body .', 'costas', '["posteriores de coxa","glúteos"]', '[]', '["Barra"]', NULL, 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1700/view/', 'barbell romanian deadlift (rdl) posteriores de coxa gluteos barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6ce25688-ae91-4dc7-9b17-0b66a47151fa', 1698, 'en', 'Barbell Row (Overhand)', 'Execution 
 

• 
 Starting position: 

 

• Hold the barbell with arms fully extended toward the floor.

• Maintain tension in your lats and back muscles.', 'costas', '["dorsais"]', '[]', '["Barra"]', NULL, 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1698/view/', 'barbell row (overhand) dorsais barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3c2b5e2d-bd9d-43e8-8b5f-e6363331faa1', 1699, 'en', 'Barbell Row (Underhand)', 'Execution 
 

• 
 Starting position: 

 

• Hold the barbell with arms fully extended toward the floor.

• Maintain tension in your lats and back muscles.', 'costas', '["dorsais"]', '[]', '["Barra"]', NULL, 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1699/view/', 'barbell row (underhand) dorsais barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('64b50772-c73d-4833-8518-947a648fa623', 1925, 'en', 'Barbell Silverback Shrug', '• Stand with your feet shoulder width apart holding the barbell with both hands in front just past shoulder width.

• Bend forward at the hips with a slight bend in your knees, keeping your back straight.

• Engage your shoulder blades, as if you are trying to touch them together.

• Release the shrug.
Description taken from MuscleWiki', 'ombros', '["trapézio"]', '[]', '["Barra"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1925/view/', 'barbell silverback shrug trapezio barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('928eeae3-d849-4605-a470-048ca259a8c5', 1830, 'en', 'Barbell Step Back Lunge', 'Step 1: Stand with your feet hip-width apart, holding a barbell on your upper back.
Step 2: Keep your back straight, chest up, and core engaged.
Step 3: Take a step back with one leg and lower your body by bending both knees. Ensure that your back knee nearly touches the ground.
Step 4: Push off your back foot to return to the starting position.
Step 5: Repeat the movement with the other leg.
Continue alternating between legs for the desired repetitions.', 'pernas', '["quadríceps"]', '[]', '["Barra"]', 'https://wger.de/media/exercise-images/1830/3b6c547c-ab3d-4472-93cf-561710279eab.jpg', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1830/view/', 'barbell step back lunge quadriceps barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('13234b53-ea0c-41f1-9069-776865ea8eff', 50, 'en', 'Barbell Triceps Extension', 'Position barbell overhead with narrow overhand grip.

 Lower forearm behind upper arm with elbows remaining overhead. Extend forearm overhead. Lower and repeat.', 'braços', '["tríceps"]', '["ombros","peito"]', '["Barra"]', 'https://wger.de/media/exercise-images/50/695ced5c-9961-4076-add2-cb250d01089e.png', 'CC-BY-SA 4', 'sevae', 'https://wger.de/en/exercise/50/view/', 'barbell triceps extension triceps ombros peito barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a5d1f45b-ff07-45d7-a699-a654f9328934', 1524, 'en', 'Battle Ropes', '• Hold the ends of the rope at arm''s length in front of your hips with your hands shoulder-width apart.

• Brace your core and begin alternately raising and lowering each arm explosively.

• Keep alternating arms for three to four sets of 1 to 2 minutes.', 'cardio', '["posteriores de coxa","glúteos","dorsais","oblíquos","quadríceps","abdômen"]', '["ombros","bíceps","peito","trapézio","tríceps"]', '[]', NULL, 'CC-BY-SA 4', 'flanny', 'https://wger.de/en/exercise/1524/view/', 'battle ropes posteriores de coxa gluteos dorsais obliquos quadriceps abdomen ombros biceps peito trapezio triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('06968051-a818-489c-9fbb-ddb94a001245', 1493, 'en', 'Bayesian Curl', 'Cable curl with stretched shoulder (backwards)', 'braços', '["bíceps"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'aahuja', 'https://wger.de/en/exercise/1493/view/', 'bayesian curl biceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b4dc15da-4d4d-4a93-a30a-74aaf99192ff', 1687, 'en', 'Bear crawl pull through', 'Place a dumbbell at around hip level and assume a bear crawl position. Push the knees off the floor and hold.

 With the opposite hand reach for the dumbbell and pull it to the other side. Place your hand back on the floor and repeat with your other hand.', 'core', '["ombros","glúteos","quadríceps","abdômen"]', '["posteriores de coxa","panturrilhas","trapézio"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'meldun', 'https://wger.de/en/exercise/1687/view/', 'bear crawl pull through ombros gluteos quadriceps abdomen posteriores de coxa panturrilhas trapezio halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b7267f90-8706-442b-b918-507e16092b8e', 57, 'en', 'Bear Walk 2', '-Rest your weight on your palms and the balls of your feet, not dissimilar to normal pushup position

 -Move by stepping with your R palm and L foot, then your L palm and R foot. Basically, walk like a lumbering bear.

 -Move as fast as you can. Measure your reps/sets in either distance (i.e. 40 yards) or time (i.e. 45 seconds)

 -Works your Pecs, Deltoids, Triceps, Traps, Lats, Abs and Lower Back, Hip Flexors, Quads, Glutes and Calves', 'peito', '["ombros","panturrilhas","peito","abdômen","serrátil","sóleo","tríceps"]', '["glúteos","dorsais","oblíquos","quadríceps","trapézio"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/57/view/', 'bear walk 2 ombros panturrilhas peito abdomen serratil soleo triceps gluteos dorsais obliquos quadriceps trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('57018827-f344-4627-88e5-03e4f2f49859', 1807, 'en', 'Behind the Back Cable Lateral Raise', 'Lateral raises have long been a staple for building capped delts, and lifters use everything from dumbbells and bands to machines and single-arm variations to make them grow.', 'ombros', '["ombros"]', '["trapézio"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'LEBRERO', 'https://wger.de/en/exercise/1807/view/', 'behind the back cable lateral raise ombros trapezio maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e9f3446f-ca98-4bf2-817c-0dacd123cecd', 1935, 'en', 'Belt Squat', 'Belt Squat: a squat variation done with a belt attached to a loading machine or platform so the weight is supported at the hips instead of on the spine. It mainly trains the quads and glutes, with much less lower-back fatigue than a barbell squat. Use a full range of motion, keep the torso upright, and drive through the mid-foot.', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa"]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1935/view/', 'belt squat gluteos quadriceps posteriores de coxa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fbeb1fd5-d259-4a85-a993-03569d8146dc', 1320, 'en', 'Bench Dips On Floor HD', 'Triceps dips on floor are a compound exercise as they worked multiple muscle groups simultaneously. Although this bodyweight exercise mainly targets the triceps, it also hits your chest and front of your shoulder.
Triceps dips on floor are one of the most effective exercises to increase arm strength and also build lean muscle in your upper arms.
Triceps dips on floor are a closed kinetic chain exercise and express that you do the movements around a fixed point. It increases compression force on your joints thereby improving stability.', 'braços', '["bíceps","braquial","tríceps"]', '["ombros","peito","sóleo","trapézio"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1320/view/', 'bench dips on floor hd biceps braquial triceps ombros peito soleo trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3717d144-7815-4a97-9a56-956fb889c996', 73, 'en', 'Bench Press', 'Lay down on a bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up.

 If you train with a high weight it is advisable to have a spotter that can help you up if you can''t lift the weight on your own.

 With the width of the grip you can also control which part of the chest is trained more:

 

• wide grip: outer chest muscles

• narrow grip: inner chest muscles and triceps', 'peito', '["peito"]', '["ombros","tríceps"]', '["Barra","Banco"]', 'https://wger.de/media/exercise-images/192/Bench-press-1.png', 'CC-BY-SA 3', 'sistab2', 'https://wger.de/en/exercise/73/view/', 'bench press peito ombros triceps barra banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('20d8df5a-c9d6-4c69-bdf2-d97af68ac83f', 2536, 'en', 'Bench Press Isometric', 'A bench press isometric hold is a static strength exercise where you pause and hold a barbell or dumbbells either at your chest, mid-press, or at lockout without moving for a set time', 'peito', '["ombros","peito","tríceps"]', '["oblíquos","abdômen","serrátil"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2536/view/', 'bench press isometric ombros peito triceps obliquos abdomen serratil barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3db63138-a047-4a4d-b616-1a0b7dfca105', 76, 'en', 'Bench Press Narrow Grip', '• Setup: Lie flat on the bench and grip the bar at shoulder-width (closer than a standard bench press).

• Descent: Lower the bar with control to your lower chest.

• Form: Keep your elbows tucked in tight against your torso—do not let them flare out.

• Ascent: Press the bar straight back up, squeezing your triceps at the top.', 'braços', '["tríceps"]', '["ombros","peito"]', '["Barra","Banco"]', 'https://wger.de/media/exercise-images/88/Narrow-grip-bench-press-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/76/view/', 'bench press narrow grip triceps ombros peito barra banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('01271ea0-088c-4e2b-95ad-876af7127057', 79, 'en', 'Bent High Pulls', 'Bend over slightly while holding two dumbbells. Pull the dumbbells up to your chest, keeping your elbows as high as you can.', 'ombros', '["trapézio"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/79/da58dfbf-748a-461b-891e-3d6bc9cc4be2.png', 'CC-BY-SA 3', 'lakerbeezel', 'https://wger.de/en/exercise/79/view/', 'bent high pulls trapezio halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7ef2e00e-067c-48e0-9b42-3d622e0df8a4', 1469, 'en', 'Bent over Cable Flye', 'Holding your upper body at an approximate 105° angle.', 'peito', '["peito"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1469/view/', 'bent over cable flye peito maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('94a5c406-7bcd-47f3-9687-bdf92a763932', 81, 'en', 'Bent Over Dumbbell Rows', 'With dumbbells in hand, bend at the hip until hands hang just below the knees (similar to straight-legged-deadlift starting position). Keep upper body angle constant while contracting your lats to pull you ellbows back pinching the shoulder blades at the top. Try not to stand up with every rep, check hands go below knees on every rep.', 'costas', '["dorsais"]', '[]', '["Banco","Halteres"]', 'https://wger.de/media/exercise-images/81/a751a438-ae2d-4751-8d61-cef0e9292174.png', 'CC-BY-SA 4', 'sebk', 'https://wger.de/en/exercise/81/view/', 'bent over dumbbell rows dorsais banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f3f4e9c5-9bf6-43f6-a2cf-798507a50293', 1082, 'en', 'Bent over row to external rotation', 'Starting position: 
Stand behind a chair or in front of a table. Bend at the waist to put your forehead on the chair''s headrest or table, keeping your back straight. Your arms should be hanging straight down, pointed at the floor.
 Steps: 

 

• Bring your elbows up to shoulder height. Your forearms should be pointing down, perpendicular to your biceps. Your biceps should be at the same height as your back and perpendicular to your spine.

• Hold for a bit.

• Rotate at your elbows to bring your hands as far up as you can.

• Hold for a bit.

• Rotate at your elbows back to the previous position.

• Bring your arms down to the original position.

• Repeat.', 'costas', '["costas"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1082/view/', 'bent over row to external rotation costas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2f0ddf9a-f520-4c55-8883-f0d4a789f481', 84, 'en', 'Bent Over Rowing Reverse', 'The same as regular rowing, but holding a reversed grip (your palms pointing forwards):

 Grab the barbell with a wide grIp (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest''s out during the whole exercise.

 Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don''t swing with your body and keep your arms next to your body.', 'costas', '["dorsais"]', '["ombros","bíceps"]', '["Barra"]', 'https://wger.de/media/exercise-images/110/Reverse-grip-bent-over-rows-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/84/view/', 'bent over rowing reverse dorsais ombros biceps barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4ce9740f-313d-4419-8a23-6c884d3a1a17', 1953, 'en', 'Bent-knee Iron Cross', 'Bent-knee Iron Cross
Part of: Limber 11
Source: Joe DeFranco
Prescription: 5-10 reps each side
Type: dynamic', 'pernas', '["pernas"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1953/view/', 'bent-knee iron cross pernas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('abdd2b41-0c30-4ec1-8d14-f6dc5deb3561', 1840, 'en', 'Bent-Leg Hamstring Stretch', 'See this instructional video from Stretch Therapy: https://www.youtube.com/watch?v=CrF2iMnn09w .', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1840/view/', 'bent-leg hamstring stretch pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6f79b381-98a4-40d5-8a45-3bb0558be6fe', 82, 'en', 'Bent-over Lateral Raises', 'Sit on bench while holding weights. Bend forward as far as possible, with arms slightly bent at the elbow. Perform a lateral raise while maintaining the bend in your elbow.', 'ombros', '["ombros"]', '[]', '["Banco","Halteres"]', NULL, 'CC-BY-SA 4', 'apeschel', 'https://wger.de/en/exercise/82/view/', 'bent-over lateral raises ombros banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e68f6d51-fe02-4175-b277-dec0c1521f36', 1424, 'en', 'Biceps Curl Machine', 'The biceps curl machine is designed to isolate the biceps muscles and provide a controlled range of motion. Sit on the machine with your back against the pad and adjust the seat so your arms are aligned with the machine''s handles or pads. Grip the handles firmly, keeping your elbows fixed in place, and curl the handles upward by contracting your biceps. Slowly lower the handles to the starting position, maintaining control throughout the movement.', 'braços', '["bíceps"]', '["braquial"]', '[]', NULL, 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1424/view/', 'biceps curl machine biceps braquial', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('bcb7020c-8678-496d-8f4d-aad0e233a5bd', 95, 'en', 'Biceps Curl With Cable', 'Stand around 30 - 40cm away from the cable, the feet are firmly on the floor. Take the bar and lift the weight with a fast movements. Lower the weight as with the dumbbell curls slowly and controlled.', 'braços', '["bíceps"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/129/Standing-biceps-curl-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/95/view/', 'biceps curl with cable biceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1ae6a28d-10e7-4ecf-af4f-905f8193e2c6', 92, 'en', 'Biceps Curls With Dumbbell', 'Hold two dumbbells, the arms are streched, the hands are on your side, the palms face inwards. Bend the arms and bring the weight with a fast movement up. At the same time, rotate your arms by 90 degrees at the very beginning of the movement. At the highest point, rotate a little the weights further outwards. Without a pause, bring them down, slowly.

 Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).', 'braços', '["bíceps"]', '["braquial"]', '["Halteres"]', 'https://wger.de/media/exercise-images/81/Biceps-curl-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/92/view/', 'biceps curls with dumbbell biceps braquial halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('42227131-9b1e-4220-b082-c523f0651057', 94, 'en', 'Biceps Curls With SZ-bar', 'Hold the SZ-bar shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement.

 Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).', 'braços', '["bíceps"]', '["braquial"]', '["Barra W"]', 'https://wger.de/media/exercise-images/94/6dee2f60-aea2-4f2d-9bf6-aef50c4f9483.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/94/view/', 'biceps curls with sz-bar biceps braquial barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('596b9d2d-0f01-41a0-97e1-1839ffdb824d', 958, 'en', 'Biceps with TRX', 'Grab the handles of the TRX straps, lean your body back, arms and legs extended, with your body positioned in a single straight line. (This is an arm exercise, not an abdominal one.)', 'braços', '["bíceps"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/958/947ac249-475d-44ed-bed3-8dc433374f59.png', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/958/view/', 'biceps with trx biceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fcf5039b-7784-4f82-830a-b213b597a646', 1412, 'en', 'bicycle crunches', 'Bicycle crunches are a core exercise performed on the floor. Lie on your back with your hands behind your head and legs extended. Lift your shoulders off the ground, bring one knee toward your chest, and twist your torso so your opposite elbow meets the knee. Alternate sides in a pedaling motion, ensuring controlled movements and engaging your core throughout the exercise.', 'core', '["abdômen"]', '["oblíquos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1412/view/', 'bicycle crunches abdomen obliquos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6349365e-e901-4280-a1b7-65734986f47d', 1572, 'en', 'Bird Dog', 'The Bird Dog is a core stability exercise that enhances balance, coordination, and spinal alignment. It’s a low-impact movement ideal for strengthening the posterior chain and improving overall functional control.

 

• Begin on all fours with hands under shoulders and knees under hips, keeping your spine neutral.

• Extend your right arm forward and left leg backward simultaneously, keeping hips square.

• Pause briefly at full extension while engaging your core and glutes.

• Return to the starting position and repeat on the opposite side', 'core', '["abdômen"]', '["ombros","glúteos"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1572/3d14e761-a73d-49da-8804-f3016a7573ff.png', 'CC-BY-SA 4', 'Settebello', 'https://wger.de/en/exercise/1572/view/', 'bird dog abdomen ombros gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6d45afed-05c4-42a2-994b-5ef62a9d0aed', 2508, 'en', 'Bird Dog (Core L1)', 'Vasco custom bird dog - foundational contralateral limb coordination and lumbar stability. Teaches hip dissociation from spine, glute activation, and scapular control.', 'core', '["abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Vasco Custom', 'https://wger.de/en/exercise/2508/view/', 'bird dog (core l1) abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('da6ab4d8-edd2-428d-b194-fb15948d3fd5', 1483, 'en', 'Bizeps Curls Trifecta', 'This exercise is a mixture of three different curls: the Supinated Cross Body Curl, the Pronated Cross Body Curl and the No Money Curl. You
alternate between three curl variations that each accomplish different goals,
and you’ll keep the set going beyond the usual 8-12 rep range which gives
us that intensity.

 

• For the Supinated Cross Body
Curl, supinate the forearm with palms facing toward the ceiling and
forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.

• For the Pronated Cross Body
Curl, pronate the forearm with palms facing toward the floor (pronated
grip or overhand grip) and forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.

• For the No Money Curl, you’ll
curl the dumbbell as you outwardly rotate the shoulder. Lift the inner-facing weight of the dumbbell towards your outer side of the shoulder.', 'braços', '["bíceps"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1483/view/', 'bizeps curls trifecta biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('64ebb7a5-15ec-48dd-8f82-47cdb022f215', 1475, 'en', 'Black Widow Knee Slides', 'In
this bottom-up rotation exercise movement, you’ll cross your knee over and
drive it into that opposite elbow. Start in high plank position (or tabletop
position) with hands directly beneath your shoulders. Lift the left knee toward
the right arm and slide it up the forearm to get more of that posterior pelvic
tilt and engagement of the abdominal muscles. Then do the opposite side,
bringing your right knee toward your left hand.', 'core', '["oblíquos","abdômen"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1475/view/', 'black widow knee slides obliquos abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1fe103e2-1def-41de-8eab-e2e11296446d', 1363, 'en', 'Blackroll', '• Controlled movements

• Slow movements

• Don''t use momentum', 'costas', '["costas"]', '[]', '[]', 'https://wger.de/media/exercise-images/1363/1dba566b-e799-4bde-abb0-c011a3c75e52.webp', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1363/view/', 'blackroll costas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('24f988e7-51eb-44f5-92f2-d4e0199c2269', 1630, 'en', 'Blaze', 'BLAZE is a full-body HIIT workout. Designed to supercharge your cardio fitness and strength. Delivered in its own purpose-built studio, BLAZE is a unique mix of martial arts, intense cardio and strength training.', 'cardio', '["ombros","glúteos","peito","quadríceps"]', '["bíceps","posteriores de coxa","dorsais","abdômen"]', '["Banco","Halteres","Kettlebell"]', NULL, 'CC-BY-SA 4', 'ricwheatley', 'https://wger.de/en/exercise/1630/view/', 'blaze ombros gluteos peito quadriceps biceps posteriores de coxa dorsais abdomen banco halteres kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c4b2ed05-38d5-47fc-9ad1-c23f09fddd61', 2482, 'en', 'Bobbing Exhale Drill', 'Stand in chest-deep water. Take a breath, submerge your face fully, and exhale slowly and completely through your nose and/or mouth the whole time you''re underwater — a gentle humming sound can help keep the exhale steady and controlled. Once you''re empty of air, lift your head, take a fresh breath, and go back under. Repeat continuously. The goal is training your body that all your exhaling happens underwater, so all you need to do at the surface is inhale.', 'cardio', '["abdômen"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2482/view/', 'bobbing exhale drill abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d551f24d-44fe-4761-9448-edf14d627827', 112, 'en', 'Body-Ups', '• Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.

• Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.

• Slowly lower your forearms back to the ground by allowing the elbows to flex.

• Repeat as needed.', 'braços', '["tríceps"]', '["ombros","abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'cal.zabel', 'https://wger.de/en/exercise/112/view/', 'body-ups triceps ombros abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a94623fc-518f-4a74-947b-febd086264bf', 1608, 'en', 'Bodyweight Biceps Curl', 'Set up under a straight bar (around waist or chest height). Grip the bar with your palms facing you (supinated grip), hands about shoulder-width apart. Lean back with straight arms so that your body is at an angle to the ground. Keeping your elbows high and close to the bar, pull your upper body toward the bar by flexing your elbows, similar to a biceps curl. Lower yourself back down in a controlled manner. Keep your core tight and movement slow to maximize tension on the biceps.', 'braços', '["bíceps"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'tenebrizz', 'https://wger.de/en/exercise/1608/view/', 'bodyweight biceps curl biceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f9a0a918-3c0c-464e-bbba-1bd309d4a519', 1324, 'en', 'Bodyweight lunge HD', 'Bodyweight lunges are an effective calisthenic exercise for
strengthening the lower body, improving balance and stability, and
developing functional strength. They are a popular choice for bodyweight workouts, home workouts, and can also be included as part of a larger strength training routine.', 'pernas', '["quadríceps"]', '["glúteos","sóleo"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1324/view/', 'bodyweight lunge hd quadriceps gluteos soleo peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('edc3f6b7-96b0-4967-90d7-bba9d7d442cb', 1312, 'en', 'Bodyweight Squat HD', 'Squat is a type of bodyweight exercise. It is one of the most popular exercises for strength and muscle growth. Squat is particularly effective for focusing on the muscles of the leg and hips.
Squat are an easy exercise for beginners to do. It can help strengthen leg muscles, tighten hip muscles and burn calories to lose weight.
It tightens the butt and legs. Squats are very effective for firming and strengthening your legs by acting on the gluteus,hip flexors, quadriceps, hamstrings and inner thigh muscles. Also, bodyweight squats can help shape your glutes and butt.', 'pernas', '["quadríceps"]', '["panturrilhas","glúteos","oblíquos","abdômen","sóleo"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'admin', 'https://wger.de/en/exercise/1312/view/', 'bodyweight squat hd quadriceps panturrilhas gluteos obliquos abdomen soleo peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('002c6a4f-28ac-4b07-8e94-053e5b05d52b', 1373, 'en', 'box jumps', 'Jump from a standing position onto the box, stretch your body, then step down again (do not jump)', 'cardio', '["glúteos"]', '["panturrilhas"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'tekknokrat@gmx.de', 'https://wger.de/en/exercise/1373/view/', 'box jumps gluteos panturrilhas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('151434a5-c046-459f-a3a9-c3125075856f', 977, 'en', 'Box squat', '• Set up the box: Position the box behind you, about 3 feet from a squat rack if you''re using a barbell. Choose a height that allows you to squat down and gently tap your glutes on the box with your back straight.

• Stand with proper form: Stand with your feet shoulder-width apart, toes pointed slightly outward. Engage your core and keep your back neutral. If using a barbell, rack it at shoulder height.

• Lower down: Sit back as if going to sit on a chair, bending your knees and lowering your hips towards the box. Keep your core tight and back straight throughout the movement.

• Controlled descent: Descend in a controlled manner until your glutes gently touch the box. Don''t plop down.

• Pause and press up: Briefly pause at the bottom with your back straight and core engaged. Then, press through your heels to drive yourself back up to the starting position.

 Improvements in coordination, balance and endurance, toning of the leg and buttock muscles and an overall increase in bone density eliminating the risk of osteoporosis.', 'pernas', '["glúteos","quadríceps","sóleo"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/977/3124c091-6395-4377-96c5-56048b627ceb.png', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/977/view/', 'box squat gluteos quadriceps soleo peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0829749c-de42-49a5-a24b-451b0eac8627', 2542, 'en', 'Boxing', 'Bag workout for boxing skill development and cardio improvement', 'cardio', '["ombros","tríceps"]', '["bíceps","dorsais"]', '[]', NULL, 'CC-BY-SA 4', 'SAH', 'https://wger.de/en/exercise/2542/view/', 'boxing ombros triceps biceps dorsais', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8c6428f3-d41d-4ffc-8444-bb9b823bc42b', 124, 'en', 'Braced Squat', 'Stand with feet slightly wider than shoulder-width apart, while standing as tall as you can.

 Grab a weight plate and hold it out in front of your body with arms straight out. Keep your core tight and stand with a natural arch in your back.

 Now, push hips back and bend knees down into a squat as far as you can. Hold for a few moments and bring yourself back up to the starting position.', 'pernas', '["quadríceps"]', '["glúteos"]', '[]', NULL, 'CC-BY-SA 4', 'sevae', 'https://wger.de/en/exercise/124/view/', 'braced squat quadriceps gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a94c635d-096c-45a8-a68c-64941d0b6ba4', 1577, 'en', 'Bretzel stretch', 'How to Perform the Bretzel Stretch Starting Position: Lie on your back on a flat surface, such as a mat. Bend your knees and place your feet flat on the ground. Leg Positioning: Lift your right leg and cross it over your left leg, placing your right foot on the outside of your left knee. Your left leg should remain flat on the ground. Arm Positioning: Extend your left arm out to the side at shoulder height, keeping it straight. Use your right hand to gently pull your right knee towards the floor on the left side of your body. Stretching: As you pull your knee down, try to keep your left shoulder flat on the ground. You should feel a stretch in your hip, lower back, and possibly your chest. Hold the Position: Maintain this position for 20-30 seconds, breathing deeply and relaxing into the stretch. Switch sides and repeat the process.', 'costas', '["glúteos"]', '["posteriores de coxa","dorsais","peito"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'mountain.potato', 'https://wger.de/en/exercise/1577/view/', 'bretzel stretch gluteos posteriores de coxa dorsais peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('60d2c34b-43a1-48a3-b43b-160e4c0157f2', 1706, 'en', 'Bulgarian Squat with Dumbbells', 'The Bulgarian split squat consists of performing a squat on one leg with the rear foot resting on a raised platform. Elevating your back leg on a bench creates instability and increases the range of motion of the exercise.', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa"]', '["Halteres"]', 'https://wger.de/media/exercise-images/1706/0c5243cc-2539-4005-aee0-d3a8c5d3a32c.jfif', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1706/view/', 'bulgarian squat with dumbbells gluteos quadriceps posteriores de coxa halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3d85bdce-e1a9-48a2-b14d-8032820ebf25', 915, 'en', 'Bus Drivers', 'Sitting with a Weight Plate, used as wheel, in both hands; raised slightly below eye level', 'ombros', '["ombros"]', '[]', '[]', 'https://wger.de/media/exercise-images/915/fe8ebece-dff8-4700-b84c-9110e2e074f5.png', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/915/view/', 'bus drivers ombros', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4885c051-154b-4a9b-a0fe-ccb70a652fa4', 1710, 'en', 'Butchers Block Stretch', '• Kneel down with the hands together

• Rest the elbows on a bench in front of you and lower the chest down

• Keep the elbows bent with good posture and hold', 'ombros', '["dorsais"]', '["trapézio"]', '["Banco"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1710/view/', 'butchers block stretch dorsais trapezio banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('99449eae-0eae-44ab-a57f-fc094bbdda13', 135, 'en', 'Butterfly', 'Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air.', 'peito', '["peito"]', '["ombros"]', '[]', 'https://wger.de/media/exercise-images/98/Butterfly-machine-2.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/135/view/', 'butterfly peito ombros', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('80ff0a3a-ae45-497d-8c27-2b12e3b6e1b8', 137, 'en', 'Butterfly Narrow Grip', 'The movement is the same as with a regular butterfly, only that the grip is narrow:

 Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air.', 'peito', '["peito"]', '[]', '[]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/137/view/', 'butterfly narrow grip peito', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1bb3bbaf-2dc2-4651-95db-71faf5304075', 1476, 'en', 'Butterfly Sit Up', 'In
this midrange exercise your arm muscles provide you with a little bit of
momentum to help to get you off the ground. You also open them up in overhead
position which engages the upper back. Start
lying with feet flat on the ground, knees at an angle, arms crossed in towards your chest. Using
your ab muscles, bring your upper body off the ground as you open your arms
into goal post position, then slowly lower yourself back down to return to
starting position.', 'core', '["oblíquos","abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1476/view/', 'butterfly sit up obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('df3a6900-55c1-435b-bcde-7510dc229b20', 1843, 'en', 'Butterfly Stretch', '• Sit in a prayer position with the soles of your feet gently pressed together.

• Use your hands to slowly pull your feet inwards towards your groin. Hold for as long as required.', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1843/view/', 'butterfly stretch pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('de06856d-109d-4bef-acab-0918028cea36', 1908, 'en', 'Butterfly Superman', 'Lie on stomach, intertwine fingers behind the head and start raising your head and raise elbows as far as they go.', 'costas', '["trapézio"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1908/view/', 'butterfly superman trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b2865908-b93e-4507-ada4-a5bb9317566c', 1656, 'en', 'Cable Chest Press - Decline', 'Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight decline and aiming towards the center of your chest.', 'peito', '["peito"]', '["tríceps"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1656/view/', 'cable chest press - decline peito triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e22c4320-7753-49c6-b7f7-4be21b025fb6', 1660, 'en', 'Cable Chest Press - Incline', 'Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight incline and aiming towards the center of your chest.', 'peito', '["peito"]', '["tríceps"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1660/view/', 'cable chest press - incline peito triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b1bf02cf-17b2-4bfc-a5b0-4ff7a2768dbb', 1109, 'en', 'Cable Concentration Curl', 'The concentration curl is a classic exercise for building the biceps one arm at a time. It can be performed bent over or kneeling, but is more often performed seated on a bench. It''s great for emphasizing the biceps peak and is often used to finish a biceps workout', 'braços', '["bíceps","braquial"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1109/00b0a0bf-c14a-4f13-bb14-62c09030a1aa.png', 'CC-BY-SA 4', 'cshep442', 'https://wger.de/en/exercise/1109/view/', 'cable concentration curl biceps braquial maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b16e3e5d-8401-4d2b-919c-15b536f9ec5e', 323, 'en', 'Cable Cross-over', 'Begin with cables at about shoulder height, one in each hand. Take a step forward so that one foot is in front of the other, for stability, and so that there is tension on the cables. Bring hands together in front of you. Try to make your hands overlap (so that the cables cross) a few inches.', 'peito', '["peito"]', '["ombros"]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/71/Cable-crossover-2.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/323/view/', 'cable cross-over peito ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('479ef6f0-5274-4da7-b5ad-67528ff3c8fd', 1531, 'en', 'Cable Curls', 'Bicep Curls using cables. Can be seated or standing', 'braços', '["bíceps"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Brigade7938', 'https://wger.de/en/exercise/1531/view/', 'cable curls biceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('dc3a2072-abc3-4ef9-b8e6-f5ae6b11bc7f', 142, 'en', 'Cable External Rotation', 'Steps:

 

• Start off placing an extension band around a post or in a secure position where it will not release and is at elbow level.

• Position yourself to the side of the band and with your hand that is opposite of the band, reach out and grab the handle.

• Bring the band to your chest keeping your elbow bent in a 90 degree angle then slowly rotate your arm in a backhand motion so that the band externally rotates out

• Continue out as far as possible so that you feel a stretch in your shoulders, hold for a count and then return back to the starting position.

• Repeat for as many reps and sets as desired.', 'ombros', '["ombros"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 3', 'lauroernesto', 'https://wger.de/en/exercise/142/view/', 'cable external rotation ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ae695660-7cee-4601-8241-edd3e2a6d896', 1691, 'en', 'Cable Fly Lower Chest', 'Execution 
 

• 
 Start position: 

 

• Arms extended out to your sides in a “Y” shape.

• Feel a stretch in your chest (slight bend in elbows — don’t lock them).

• 
 Movement: 

 

• Bring your hands downward and together in front of your lower chest or upper abs , in a smooth arc motion.

• Squeeze your chest hard at the bottom for 1–2 seconds.

• 
 Return: 

 

• Slowly raise your arms back up along the same path until you feel a good stretch in your chest.

• Maintain control — don’t let the weights pull you back too quickly.', 'peito', '["peito"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1691/view/', 'cable fly lower chest peito maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5b4fb3ec-53a1-4525-a58a-c070798ea86e', 1689, 'en', 'Cable Fly Middle Chest', 'Execution 
 

• 
 Start position: Arms extended out to your sides (a big “T” shape), feeling a stretch in your chest.

• 
 Movement: Bring your hands together in front of your chest in a wide hugging motion .

 

• Focus on squeezing your chest at the center.

• Do not lock your elbows or turn it into a press.

• 
 Return: Slowly open your arms back to the start, maintaining tension on the chest.', 'peito', '["peito"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1689/view/', 'cable fly middle chest peito maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b16a28c4-40bf-42d4-94b3-bf3f56fab743', 1690, 'en', 'Cable Fly Upper Chest', 'Execution 
 

• 
 Start position: 

 

• Arms down and slightly behind your body, elbows slightly bent.

• Feel a light stretch across your chest.

• 
 Movement: 

 

• Bring your hands upward and together in front of your upper chest — roughly at chin to collarbone level .

• Use a smooth, controlled motion (avoid jerking).

• Squeeze your chest at the top for 1–2 seconds.

• 
 Return: 

 

• Slowly let your arms move back down and out to the sides, keeping control and tension.', 'peito', '["peito"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1690/view/', 'cable fly upper chest peito maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6e03ecb3-6bfe-4b34-be9d-e5c33e820cc6', 1745, 'en', 'Cable Front Raise with a small bar', 'The Cable Front Raise with a small bar isolates your anterior deltoids (front shoulders) by providing constant tension, requiring you to stand facing away from a low pulley, grab the bar with an overhand grip, and lift it in front of you to shoulder height with slightly bent arms, avoiding swinging and keeping your core tight for controlled movement up and down. Use a light-to-moderate weight, focusing on slow, controlled reps to feel the muscle work, not momentum.

 How to Perform the Cable Front Raise (Bar)

 Setup: Attach a small straight bar to a low cable pulley. Set the weight to a light or moderate setting.

 Starting Position: Stand with your back to the machine, holding the bar with an overhand grip (palms facing down) at hip level, arms extended but not locked. Feet shoulder-width apart, core braced, shoulders back and down.

 The Lift: Exhale and slowly raise the bar straight up in front of you, keeping a slight bend in your elbows, until your hands reach shoulder height (or slightly below).

 The Hold: Pause briefly at the top, squeezing your front delts.

 The Lower: Inhale as you slowly and controllably lower the bar back to the starting position, maintaining tension.', 'ombros', '["ombros"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1745/9c92843a-6b90-428b-a868-9af4b11bad38.jpg', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1745/view/', 'cable front raise with a small bar ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('19a9f67b-60f5-4367-9134-b805f3e73956', 1131, 'en', 'Cable glute extension', 'This exercise lets you work the upper, or larger, part of the glutes. For that reason, it should never be missing from your routine of isolated exercises for training the glutes.
Stand in front of a cable machine and locate the low pulley. Then attach the ankle strap to work on the low pulley. As for your posture, you should stay upright at all times. Pay special attention to your back to keep it straight and avoid injury.
It is advisable to hold on to the machine for better balance. With the leg that is holding the weight of the cable, perform a slow stretch backward without bending the knee.', 'pernas', '["glúteos"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1131/3bcf3024-2dcc-4995-9694-55aa2c2e4a9a.png', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1131/view/', 'cable glute extension gluteos maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('81942f3d-d92c-431c-b9d0-0da12918d1e4', 1378, 'en', 'Cable Lateral Raises (Single Arm)', 'The single arm cable lateral raise is a variation of the lateral raise and an exercise used to build the muscles of the shoulders.

 

• Position a cable at the lowest position possible and attach a single handle.

• Reach across your body and grab the handle with a neutral grip.

• Keep the elbow slightly bent and pull the handle across your body and raise laterally.

• Slowly lower the handle back to the starting position under control.', 'ombros', '["ombros"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1378/7c1fcf34-fb7e-45e7-a0c1-51f296235315.jpg', 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1378/view/', 'cable lateral raises (single arm) ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('70479b75-0df4-4ac2-a324-4a44b148304c', 1457, 'en', 'Cable Press Around', 'Set the cable pulley at chest height and attach a D-handle bar. Grab
the handle with a neutral grip and hold it next to your chest with your
elbow fully flexed and tight to your side. Turn away from the pulley so
your torso is at 45 degrees.

 Hold the other side of the functional trainer with your corresponding hand. Assume a staggered stance for better balance.

 While keeping your chest proud, extend your elbow at 45 degrees
across your midline while keeping your arm parallel to the floor. Stop
shy of lockout and contract your chest at the top of the range of motion
(ROM).', 'peito', '["ombros","peito","tríceps"]', '["bíceps","serrátil"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1457/view/', 'cable press around ombros peito triceps biceps serratil maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('821e289e-bd39-4410-b436-6f2a43bc3649', 1751, 'en', 'Cable pull through', 'The Cable Pull Through is a lower-body exercise that targets the glutes and hamstrings using a "hip hinge" motion. To perform it, attach a rope to the lowest pulley setting, face away from the machine with the rope between your legs, and step forward to create tension. Keeping your back flat and knees slightly soft, push your hips backward as if trying to close a door behind you until you feel a deep stretch in your hamstrings.

 To finish the rep, explosively drive your hips forward to return to a standing position, squeezing your glutes hard at the top. It is vital to remember that this is not a squat ; your knees should not bend deeply, and your arms should remain straight and relaxed, acting only as hooks for the rope. This movement provides constant tension on the glutes while placing less stress on the lower back than a traditional deadlift.', 'pernas', '["glúteos"]', '["posteriores de coxa","panturrilhas","quadríceps","sóleo"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'manuher89', 'https://wger.de/en/exercise/1751/view/', 'cable pull through gluteos posteriores de coxa panturrilhas quadriceps soleo maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5d244235-cd56-472a-876e-6e530a899ef2', 822, 'en', 'Cable Rear Delt Fly', 'The reverse cable fly, also known as the cable rear delt fly, is a deltoid muscle strengthening and definition exercise. It’s one of the best isolation exercises for your back and posterior deltoid.This workout targets your posterior (back) deltoids while using a range of upper body muscles.

 

• Adjust the weight and the pulleys to the right height. You should be able to see the pulleys because they should be above your head.

• With your right hand, grab the left pulley, and with your left hand, grab the right pulley, crossing them in front of you. This is where you’ll begin your journey.

• Start the movement by moving your arms back and forth while keeping your arms straight.

• Pause at the finish of the move for a brief moment before returning the handles to their starting positions.', 'ombros', '["ombros","trapézio"]', '["tríceps"]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/822/74affc0d-03b6-4f33-b5f4-a822a2615f68.png', 'CC-BY-SA 4', 'cshep442', 'https://wger.de/en/exercise/822/view/', 'cable rear delt fly ombros trapezio triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0285f198-36d5-4a77-bb76-5f72e1a4d6c9', 1936, 'en', 'Cable Rear-Delt Fly (single arm)', 'Cable rear delt fly (single arm): 
Stand sideways to a cable machine with the handle set around shoulder height. With a slight bend in the elbow, pull the handle out and back in a wide arc so the upper arm moves away from the body. Keep your torso still and focus on the rear delt doing the work. Use light to moderate weight and controlled reps.', 'ombros', '["ombros"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Dulive', 'https://wger.de/en/exercise/1936/view/', 'cable rear-delt fly (single arm) ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('05853a58-4426-450c-9b06-bfa461a767bf', 1472, 'en', 'Cable Shrug-In', 'Attach two D-Handles to two low cables and shrug in using your upper traps.', 'ombros', '["trapézio"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1472/view/', 'cable shrug-in trapezio maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('07ded945-de5d-4e77-b13c-17d51a2f0007', 1662, 'en', 'Cable Tri Extension - Internal Rotation', 'single arm exercise with cable held at opposite shoulder with elbow bent. Turn towards the cable, and the straighten the elbow across the body.', 'braços', '["tríceps"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1662/view/', 'cable tri extension - internal rotation triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1ea73578-08a5-4f3e-9255-3c58b29b170d', 1509, 'en', 'Cable Tricep Kickback', 'Grab onto the handle, and pull your elbow up and back slightly above
your torso. Keep your upper arm to be parallel to the ground for the
duration of the set', 'braços', '["tríceps"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1509/view/', 'cable tricep kickback triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5aee8ae1-2752-4868-af62-e3c79954d811', 1661, 'en', 'Cable Triceps Press', 'A single arm exercise that starts with the hand close to the chest with with the elbows bent, and the elbow flared out. Press forward and down against the cable straightening the elbow.', 'braços', '["tríceps"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1661/view/', 'cable triceps press triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c867836d-2929-4977-b23c-014bc21ec08d', 145, 'en', 'Cable Woodchoppers', 'Set cable pulley slightly lower than chest height. Keep body facing forward with hips stable. Grab the pulley handle, fully extend your arms and bring your arms forward and across your body. Hold for 1 second at the end of the movement and slowly return to starting position.', 'core', '["oblíquos"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 3', 'robhoyt', 'https://wger.de/en/exercise/145/view/', 'cable woodchoppers obliquos maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0d79f259-3b28-4258-8a08-cffec062a710', 146, 'en', 'Calf Press Using Leg Press Machine', 'Put the balls of your feet on an extended leg press pad. Use your calves to press the weight by flexing your feet/toes into a pointed position, and releasing back into a relaxed position.

 This exercise builds mass and strength in the Gastrocnemius and Soleus muscles as well, if not better, than any calf exercise.', 'panturrilhas', '["panturrilhas","sóleo"]', '[]', '[]', 'https://wger.de/media/exercise-images/146/8b284904-d072-4381-a256-4c81d8fd9c1f.png', 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/146/view/', 'calf press using leg press machine panturrilhas soleo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('efeccb1b-73c0-4303-8542-bb4f45ef831a', 1466, 'en', 'Calf Raise using Hack Squat Machine', 'Ideally using a trapeze addon, Lift the weight up using your calves by getting on your toes.', 'pernas', '["panturrilhas","sóleo"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1466/view/', 'calf raise using hack squat machine panturrilhas soleo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('95a9cc46-270e-45f2-8a17-5665a23ff70b', 148, 'en', 'Calf Raises on Hackenschmitt Machine', 'Place yourself on the machine with your back firmly against the backrest, the feet are on the platform for calf raises. Check that the feet are half free and that you can completely stretch the calf muscles down.

 With straight knees pull up your weight as much as you can. Go with a fluid movement down till the calves are completely stretched. Repeat.', 'panturrilhas', '["panturrilhas"]', '["sóleo"]', '[]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/148/view/', 'calf raises on hackenschmitt machine panturrilhas soleo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('db4eaf0f-f4d4-4e63-b9fb-258985bc2858', 1203, 'en', 'Calf raises, left leg', '• Stand on the floor or on the edge of a step to increase the range of movement.

• Raise one foot.

• Lift your heel until you''re standing on your toes.

• (variable) Stay in this position for three seconds

• Slowly lower your foot until you almost touch the ground with your heel - don''t slam your foot!', 'panturrilhas', '["panturrilhas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'wakanda90', 'https://wger.de/en/exercise/1203/view/', 'calf raises, left leg panturrilhas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('05b36227-a331-45b8-b1d5-5c7293c2df17', 1854, 'en', 'Calves foam roller', 'Move your calves slowly over the foam roller', 'pernas', '["panturrilhas"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1854/ccd3c18e-c864-426f-8176-15dce14305e3.webp', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1854/view/', 'calves foam roller panturrilhas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b02825ca-bbe4-4a07-a162-2b7a6c0a662b', 1911, 'en', 'Cat Plank', 'On your fours and raise the knees of the floor ever so slightly. 
Curl your back out and push back from your shoulders as to resemble a cat making itself look large.', 'pernas', '["quadríceps","abdômen"]', '["ombros"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1911/view/', 'cat plank quadriceps abdomen ombros peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5c4065d5-5e0a-4155-92e5-34a080587a64', 1938, 'en', 'Cat-Cow', 'On all fours. Arch spine up (cat) then drop it down (cow). Breathe with movement.', 'costas', '["costas"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1938/view/', 'cat-cow costas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('aa22b0b7-795d-47a6-8c0b-fdd0f6b9c8fc', 1774, 'en', 'Chair dips', 'Starting position: 

 Sit down on the front edge of a chair, back straight, hands holding the front edge. Still holding the edge of the chair, arms extended, lift your butt and walk forward slightly so that it is a few inches from the chair.

 Steps: 

 

• 
 Slowly lower your body, keeping the back straight, until your arms are at a right angle.

• 
 Raise your body again to the initial position, arms extended.

• 
 Repeat.', 'ombros', '["tríceps"]', '["ombros","peito"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1774/view/', 'chair dips triceps ombros peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5c414175-fe72-455a-ba8f-a0575cf792bd', 129, 'en', 'Chest Press', '• Adjust the seat height so that the grips are parallel to your chest.

• Use your legs to push the foot forward pedal.

• Bring the handles to the start position.

• Keep your back in contact with the back pad, press outwards.

• Press the handles away from your chest and exhale.

• Allow the handles to come in gently until they reach your chest.

• Allow the handles to return to your chest as you inhale.', 'peito', '["peito"]', '[]', '[]', 'https://wger.de/media/exercise-images/129/b263c968-e067-4750-916a-d8758a7df23e.webp', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/129/view/', 'chest press peito', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('25cbc266-aa84-44f5-989b-53c9cc8fdc77', 1825, 'en', 'Chest-Supported Rear Delt Raise', '"The Y"Position: Set an incline bench to 30-45 degrees. Lie face-down with your chest supported, keeping your head neutral or looking slightly down to avoid neck strain.Grip: Hold light dumbbells with a neutral or thumbs-up grip (thumb pointing to the ceiling).Movement: With straight or slightly bent elbows, raise the dumbbells up and out in a "Y" shape. Focus on moving the shoulders and shoulder blades rather than just lifting the arms.Top Position: Squeeze the shoulder blades together and reach high, ensuring the arms are angled to form a "Y".Control: Lower the dumbbells slowly to the starting position.', 'ombros', '["ombros"]', '["trapézio"]', '["Banco","Halteres"]', NULL, 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1825/view/', 'chest-supported rear delt raise ombros trapezio banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('87e6abc5-a701-442a-b4fb-bb2a7598a754', 152, 'en', 'Chin Up', 'The chin-up (also known as a chin or chinup) is a strength training exercise. People frequently do this exercise with the intention of strengthening muscles such as the latissimus dorsi and biceps, which extend the shoulder and flex the elbow, respectively. In this maneuver, the palms are faced towards the body. It is a form of pull-up in which the range of motion is established in relation to a person''s chin.', 'costas', '["bíceps","dorsais"]', '["braquial","trapézio"]', '["Barra fixa"]', 'https://wger.de/media/exercise-images/152/6c1a7459-266d-491a-bd50-7cbaea2bc771.png', 'CC0', 'BFad07', 'https://wger.de/en/exercise/152/view/', 'chin up biceps dorsais braquial trapezio barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ca3ca5d0-5231-4420-ad06-fa3d32693a1b', 1823, 'en', 'Clamshell', 'Position 
Side plank with the elbow and the forearm on the ground and the legs slightly bent.

 Execution 
Lift your upper knee while keeping your feet close together, like a “shell opening,” then slowly return to the starting position. Keep your core stable and your hips aligned.', 'core', '["glúteos","abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'teus_ergaster', 'https://wger.de/en/exercise/1823/view/', 'clamshell gluteos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f77b7cc6-e163-4f92-afa8-5ec431f32588', 2449, 'en', 'Clamshell to Reverse Clamshell', 'Lie on your side with your hips and knees bent, keeping your legs stacked. Lift your top knee into a clamshell position and keep the leg elevated throughout the movement. From there, alternate between opening the knee upward and lifting the foot upward, moving through hip external and internal rotation.

 Keep the movement slow and controlled. Do not let the top leg rest on the bottom leg between repetitions.', 'pernas', '["glúteos"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'TobiasFalk', 'https://wger.de/en/exercise/2449/view/', 'clamshell to reverse clamshell gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fdeb0973-121f-494d-8b94-54f1d7ba003f', 1554, 'en', 'Clap Push-UP', 'The clap push-up is an explosive upper body movement that builds power and fast-twitch muscle strength. It adds a plyometric challenge to the traditional push-up by requiring the hands to leave the ground mid-rep.

 

• Start in a strong push-up position with your hands slightly wider than shoulder-width and core engaged

• Lower your body explosively and push off the ground with enough force to lift your hands.

• Quickly clap your hands together at chest level before returning them to the floor.

• Land with soft elbows to absorb the impact and immediately move into the next rep', 'peito', '["peito"]', '["ombros","abdômen","tríceps"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1554/49207a62-8799-4b47-8c0b-7bde02926f3d.png', 'CC-BY-SA 4', 'Settebello', 'https://wger.de/en/exercise/1554/view/', 'clap push-up peito ombros abdomen triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ecf9c0e2-a1d0-4e6e-90e9-5c029e98f2c9', 1223, 'en', 'Claps over the head', 'Stand with your feet shoulder width apart. Raise your arms and clap over your head', 'braços', '["ombros"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1223/bf20836a-23b0-4f50-8b98-cfdd97684527.webp', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1223/view/', 'claps over the head ombros peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a8f76beb-b6d8-430b-8e45-cc03d4959043', 1438, 'en', 'Clean', 'Regular olympic lift clean.
Pull bar from ground, catch on shoulders performing a front squat.', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa","dorsais","abdômen"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1438/view/', 'clean gluteos quadriceps posteriores de coxa dorsais abdomen barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8c509754-c86f-4c1b-bfa9-29c906ffc409', 1446, 'en', 'Clean and Jerk OL', 'Olympic lift clean and jerk.
Combination of clean and jerk in one motion.', 'ombros', '["ombros","posteriores de coxa","glúteos","quadríceps"]', '["dorsais","abdômen","trapézio","tríceps"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1446/view/', 'clean and jerk ol ombros posteriores de coxa gluteos quadriceps dorsais abdomen trapezio triceps barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2a125f64-1d10-4926-95ad-33a48e61b3d6', 1901, 'en', 'Clean and Press', '• The First Pull: Lift the bar from the floor to knee-height by driving with the legs, keeping the angle of your back constant.

• The "Power" Position: As the bar reaches mid-thigh, explosively shrug and extend your hips to create vertical momentum.

• The Quick Elbow Turnover: In the catch phase, rotate your elbows rapidly under the bar to create a "shelf" on your front deltoids.

• The Vertical Press: Press the bar in a straight line; your head should shift slightly forward once the bar clears your forehead to reach full lockout.', 'ombros', '["ombros"]', '["quadríceps"]', '["Barra"]', 'https://wger.de/media/exercise-images/1901/046f0f42-0ed5-48c5-a9ee-41de25e3b6a0.png', 'CC-BY-SA 4', 'nishant0712', 'https://wger.de/en/exercise/1901/view/', 'clean and press ombros quadriceps barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2536b8cd-a287-48ee-b8da-58d8bd595f43', 1449, 'en', 'ClimbMill', 'The ClimbMill, also known as a stair climber, is a cardio-focused machine that simulates climbing stairs. It provides an effective way to improve endurance while strengthening the lower body. To use the machine, step onto the moving stairs, maintain an upright posture, and use the handrails for balance if needed. Adjust the speed and intensity to match your fitness level. This exercise helps improve cardiovascular health, burns calories, and enhances lower body muscle endurance.', 'cardio', '["quadríceps"]', '["posteriores de coxa","glúteos"]', '[]', NULL, 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1449/view/', 'climbmill quadriceps posteriores de coxa gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b50a3d3e-cf75-42de-8729-80e163748fb1', 1015, 'en', 'Clockwise neck circles', 'Starting position:

 Start sitting or standing. Drop your head down, bringing your chin toward your chest, but not pushing.

 Steps:

 In a slower fluid motion and with your head relaxed and not pushing in any direction:

 

• lean toward your right shoulder.

• then bring your head back, facing up.

• then lean toward your left shoulder.4.and back toward the starting position.

 Keep repeating this as part of one slower fluid motion.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1015/view/', 'clockwise neck circles costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('63fbb8e5-6ebc-4def-8844-3e65e097213b', 158, 'en', 'Close-grip Lat Pull Down', 'Grip the pull-down bar with your hands closer than shoulder width apart, with your palms facing away from you. Lean back slightly. Pull the bar down towards your chest, keeping your elbows close to your sides as you come down. Pull your shoulders back at the end of the motion.', 'costas', '["dorsais"]', '[]', '[]', 'https://wger.de/media/exercise-images/158/0d51a0f2-622f-434b-beb8-1a003c54712a.png', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/158/view/', 'close-grip lat pull down dorsais', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('44cfa56c-d8c2-4f2c-8b5a-f29810fd60e7', 1086, 'en', 'Close-grip Press-ups', 'Drop into a strong plank position, bringing your hands close together until they''re almost touching. (picture 1)Bend your elbows to slowly bring your chest to the floor (picture 2). Keep your elbows close to your body as you push back up explosively. Repeat. Ensure you take your time lowering on each rep, keeping your form sharp.', 'peito', '["braquial","dorsais","peito","trapézio"]', '["ombros","bíceps","tríceps"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1086/b2ee8d9b-0480-4992-8494-c223b37c2696.jpg', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1086/view/', 'close-grip press-ups braquial dorsais peito trapezio ombros biceps triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4eb41bfb-cbeb-4683-b9c6-902ee7e028e0', 1127, 'en', 'Close-grip supinated lat pulldown', 'Downward movement
• Pull the bar down so that it passes close to your chin and touches the upper part of your chest.
• Keep the rest of your body still.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1127/4942b7c0-6bda-4983-88e5-86547c3d445e.png', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1127/view/', 'close-grip supinated lat pulldown dorsais maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d8d1b919-94e1-4e91-b37e-29bb8a479740', 1450, 'en', 'Cobra Stretch', 'The Cobra Stretch is a back extension exercise that helps improve spinal flexibility and relieve lower back tension. To perform, lie face down on the floor with your hands placed under your shoulders. Press your palms into the floor and lift your chest while keeping your hips on the ground. Keep your elbows slightly bent and your shoulders relaxed. Hold the stretch for a few seconds, then slowly lower yourself back down. This exercise is beneficial for improving posture and reducing lower back stiffness.', 'costas', '["abdômen"]', '["peito"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1450/view/', 'cobra stretch abdomen peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e872658a-3bac-4d9e-bcf2-15919ebea43a', 980, 'en', 'commando pull-ups', 'variation of the pull-up exercise, it is performed with a grip of one hand supine and one hand prone, do not twist the torso to get back to the front, the head passes once to one side, once to the other.', 'costas', '["ombros","bíceps","dorsais","trapézio"]', '[]', '["Barra fixa"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/980/view/', 'commando pull-ups ombros biceps dorsais trapezio barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5597bafc-0478-4124-9745-85f9df22be3e', 2555, 'en', 'Controlled Kegels', 'Moderate voluntary pelvic floor contraction practice. Use approximately 40 to 60 percent effort, hold about 3 to 5 seconds, then allow approximately 6 to 10 seconds of deliberate relaxation.', 'core', '["core"]', '[]', '[]', NULL, 'CC-BY-SA 3', '', 'https://wger.de/en/exercise/2555/view/', 'controlled kegels core', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1544c78d-fe6d-423d-876e-0ba1998063c6', 2487, 'en', 'Cool-Down Swim', 'Swim at an easy, unhurried pace — freestyle, backstroke, or just floating/gliding — with zero focus on technique or drills. The only goal here is to let your heart rate come down gradually and your muscles relax before you get out of the pool.', 'cardio', '["ombros","dorsais","peito"]', '["glúteos","abdômen","tríceps"]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2487/view/', 'cool-down swim ombros dorsais peito gluteos abdomen triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('dbed4613-e1d5-483f-90ae-6db5d593911e', 1605, 'en', 'Copenhagen Adduction Exercise', 'Lie on your side with the elbow placed directly under the shoulder, similar to a side plank position. Place the upper leg on a bench with the inside of the foot or ankle resting on it. Lift your hips and hold your body in a straight line while keeping the lower leg off the floor. The exercise strongly activates the adductors of the upper leg while also challenging the core and hip stabilizers.', 'pernas', '["glúteos","quadríceps"]', '["oblíquos","serrátil","trapézio"]', '["Banco"]', NULL, 'CC-BY-SA 4', 'RiccaBaro', 'https://wger.de/en/exercise/1605/view/', 'copenhagen adduction exercise gluteos quadriceps obliquos serratil trapezio banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1b140999-e1fa-49b5-9f2b-690bac959db3', 1912, 'en', 'Core Rotation', 'Sit back, raise feet above the ground with knees bent and start rotating left and right with hands touching the ground every move.', 'core', '["quadríceps","abdômen"]', '["oblíquos","serrátil"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1912/view/', 'core rotation quadriceps abdomen obliquos serratil peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('96a899ee-16a4-457d-8f66-efdd39fd38a0', 1407, 'en', 'Cossack squat', 'The Cossack Squat is a multi-joint exercise that works mainly on the legs and buttocks, but also involves stabilizing muscles. It is an excellent exercise for improving strength, mobility and stability in a functional way.', 'pernas', '["glúteos","quadríceps"]', '["panturrilhas","abdômen"]', '[]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1407/view/', 'cossack squat gluteos quadriceps panturrilhas abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('26168c76-5e2a-4321-8755-5ca42bd341ad', 2525, 'en', 'Couch Stretch', '• Stand facing away from a bench, couch or similar-height object.

• Extend one leg backwards, resting your foot "laces-down" on the edge of the bench.

• Lower yourself until your rear knee is on the floor and you are in a lunge position, with your torso hanging forwards slightly.

• Brace your core, tense your rear glute, and straighten up your torso to vertical, under control. Relax and repeat.

 Repeat for the other leg, too.', 'pernas', '["pernas"]', '[]', '["Banco"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2525/view/', 'couch stretch pernas banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('00ecb956-9483-4d08-a9b1-6a236d4d8ff3', 1016, 'en', 'Counterclockwise neck circles', 'Starting position:

 Start sitting or standing. Drop your head down, bringing your chin toward your chest, but not pushing.

 Steps:

 In a slower fluid motion and with your head relaxed and not pushing in any direction:

 

• lean toward your left shoulder.

• then bring your head back, facing up.

• then lean toward your right shoulder.4.and back toward the starting position.

 Keep repeating this as part of one slower fluid motion.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1016/view/', 'counterclockwise neck circles costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6e00afb6-272d-44a2-8ae3-e7fa41b50f06', 161, 'en', 'Cross-Bench Dumbbell Pullovers', 'Grasp a moderately weighted dumbbell so your palms are flat against the underside of the top plates and your thumbs are around the bar. Lie on your back across a flat bench so only your upper back and shoulders are in contact with the bench. Your feet should be set about shoulder-width apart and your head should hang slightly downward. With the dumbbell supported at arm''s length directly about your chest, bend your arms about 15 degrees and keep them bent throughout the movement. Slowly lower the dumbbell backward and downward in a semicircle arc to as low a position as is comfortably possible. Raise it slowly back along the same arc to the starting point, and repeat for the required number of repetitions.', 'peito', '["dorsais","peito","serrátil"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/161/b9b1803e-2817-40bf-8ac7-e398ca86d8b4.png', 'CC-BY-SA 3', 'powerade69', 'https://wger.de/en/exercise/161/view/', 'cross-bench dumbbell pullovers dorsais peito serratil halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('37314b67-1aad-4405-aa88-70846d5f035d', 1458, 'en', 'Cross-Body Cable Y-Raise', 'Attach a D-Bar to the cable machine. Perform a motion akin to drawing a sword from across your body.', 'costas', '["ombros","dorsais","trapézio"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1458/view/', 'cross-body cable y-raise ombros dorsais trapezio maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4f38cc2e-5904-4ef5-b811-e729105cfd3b', 1400, 'en', 'Crossbody Hamstring Stretch', 'While standing, cross one leg behind the other (keep this leg straight). Reach downward and try to touch the toes of that leg. Slightly bend the other leg so that you can bend down.', 'pernas', '["posteriores de coxa"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1400/view/', 'crossbody hamstring stretch posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('bb948d34-8948-4995-9e59-003d7b6fc1b2', 1395, 'en', 'Crossbody Leg Swings', 'Hold onto a wall or something near you for support. Swing one leg across the front of your body, then back and out to the side. Repeat while slowly increasing your range of motion.', 'pernas', '["posteriores de coxa"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1395/view/', 'crossbody leg swings posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('401989e0-64c3-459d-bc47-2c171ab4f41d', 172, 'en', 'Crunches on Machine', 'The procedure is very similar as for regular crunches, only with the additional weight of the machine. Sit on the machine, put both feet firmly on the ground. Grab the to the weights, cables, etc. and do a rolling motion forwards (the spine should ideally lose touch vertebra by vertebra). Slowly return to the starting position.', 'core', '["abdômen"]', '[]', '[]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/172/view/', 'crunches on machine abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('29175281-afaf-4ffd-85e8-cfc38493e304', 173, 'en', 'Crunches With Cable', 'Take the cable on your hands and hold it next to your temples. Knee down and hold your upper body straight and bend forward. Go down with a fast movement, rolling your back in (your ellbows point to your knees). Once down, go slowly back to the initial position.', 'core', '["abdômen"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/173/view/', 'crunches with cable abdomen maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b7ff64bc-7a7c-4dbc-af6f-fabc20425f5f', 174, 'en', 'Crunches With Legs Up', 'On your back, legs extended straight up, reach toward your toes with your hands and lift your shoulder blades off the ground and back.', 'core', '["abdômen"]', '["oblíquos"]', '[]', NULL, 'CC-BY-SA 4', 'krisbbb', 'https://wger.de/en/exercise/174/view/', 'crunches with legs up abdomen obliquos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9828f705-350b-4afd-86c4-fcc0e8a0fb4b', 1666, 'en', 'Curl  - With Shoulder Elevated', 'Place elbow so that it is about level with the shoulder. Curl the wieght to your shoulder. Focus on the stretch in the eccentric part of the curl', 'braços', '["bíceps"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1666/view/', 'curl  - with shoulder elevated biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4b67ccf1-6bbc-406a-b88b-e2f72b10085e', 2452, 'en', 'Curl De Muñeca Con Barra', 'This is a variation of the flat bench press designed to emphasize the clavicular head of the pectoralis major (the upper portion). By tilting the torso, the angle of the push changes, shifting more tension to the upper chest and shoulders, which helps achieve a more aesthetic, balanced, and three-dimensional development of the torso.

 

• 
 Starting Position: Grip a bar with an overhand grip (palms facing up) at a width similar to your shoulders.

• 
 Position on the Bench: Kneel in front of a flat bench and rest the backs of your forearms on it. Your wrists and hands should extend slightly beyond the edge of the bench to allow for a full range of motion.

• 
 Eccentric Phase (Lowering): Lower the bar in a controlled manner by extending your wrists toward the floor. At the bottom of the movement, slightly spread your fingers to let the bar roll down a bit, maximizing the stretch.

• 
 Concentric Phase (Lift): First, close your fingers to secure the bar, then flex your wrists upward explosively but in a controlled manner, bringing the bar as high as possible. Strongly contract your forearms at the top position for one second.

• 
 Form: Keep your forearms firmly pressed against the bench throughout the exercise; only your wrists and fingers should move.', 'braços', '["braços"]', '[]', '["Barra","Banco"]', 'https://wger.de/media/exercise-images/2452/f6262118-1e01-4a98-b8aa-1cc69d383311.png', 'CC-BY-SA 4', 'xWan', 'https://wger.de/en/exercise/2452/view/', 'curl de muneca con barra bracos barra banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3de523ee-d359-4044-a792-6de22eef0495', 974, 'en', 'Curl with kettlebell two hands', 'Stand upright and grip the kettlebell with both hands. Perform the elbow flexion motion, starting from a fully extended position until your hand reaches shoulder height. Spread your legs a little for stability and, to perform the exercise correctly, try not to push with your back or body in general. Change the weight of the kettlebell to adjust the difficulty.', 'braços', '["bíceps"]', '[]', '["Kettlebell"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/974/view/', 'curl with kettlebell two hands biceps kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8dedde58-a5dc-4a23-ad20-fd7cf524f8b5', 177, 'en', 'Cycling', 'Cycling, also called bicycling or biking, is the use of bicycles for transport, recreation, exercise or sport. People engaged in cycling are referred to as cyclists, bicyclists, or bikers. Apart from two-wheeled bicycles, cycling also includes the riding of unicycles, tricycles, quadracycles, recumbent and similar human-powered vehicles.', 'cardio', '["oblíquos","trapézio"]', '["posteriores de coxa","braquial","glúteos","dorsais","quadríceps"]', '["Peso corporal"]', NULL, 'CC0', 'BFad07', 'https://wger.de/en/exercise/177/view/', 'cycling obliquos trapezio posteriores de coxa braquial gluteos dorsais quadriceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('038f7cb1-6aa3-4c48-a19d-a31993f7b0d8', 1502, 'en', 'DB Cross Body Hammer Curls', 'Dumbbell cross body biceps curls, works on the braccialis', 'braços', '["bíceps"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1502/view/', 'db cross body hammer curls biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2dd388dd-e7fa-44f1-9973-6f9c1185e0a4', 2497, 'en', 'DB Floor Press (5kg Single Arm)', 'Vasco custom single-arm DB floor press for 5kg dumbbell home training. Unilateral work for symmetry and core anti-rotation. Part of Monday Push day.', 'peito', '["peito"]', '["ombros","oblíquos"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Vasco Custom', 'https://wger.de/en/exercise/2497/view/', 'db floor press (5kg single arm) peito ombros obliquos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6e5e15f0-5722-46d6-ad89-719c581da436', 2504, 'en', 'DB Hammer Curls (5kg)', 'Vasco custom single-arm hammer curl for 5kg dumbbell. Targets brachialis for arm thickness. Part of Tuesday Pull day.', 'braços', '["bíceps"]', '["braquial"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Vasco Custom', 'https://wger.de/en/exercise/2504/view/', 'db hammer curls (5kg) biceps braquial halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ef7d621e-ddb2-490f-ae2b-e73dd509d396', 2502, 'en', 'DB Single-Arm Row (5kg)', 'Vasco custom single-arm DB row for 5kg dumbbell home training. Unilateral horizontal pull. Part of Tuesday Pull day.', 'costas', '["dorsais"]', '["bíceps","braquial"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Vasco Custom', 'https://wger.de/en/exercise/2502/view/', 'db single-arm row (5kg) dorsais biceps braquial halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7b40813b-80a3-42cc-8938-0c5199ef7620', 1497, 'en', 'DB Underhand bench press', 'Underhand grip DB, perform a normal bench press movement, keeping the elbows close to the chest', 'peito', '["peito"]', '["ombros"]', '["Banco","Halteres"]', NULL, 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1497/view/', 'db underhand bench press peito ombros banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4b23738a-67a8-41af-996d-abc53a7c3f97', 1496, 'en', 'DB Upper Chest Variation', 'Dumbbell in hand in a curl fashion, lean body into the arm to help the dumbbell up above the chest, next to the head, to activate chest and delt combo', 'peito', '["peito"]', '["ombros"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1496/view/', 'db upper chest variation peito ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('73646b21-62e3-493b-8d75-4179326cd404', 1881, 'en', 'DB Wrist Extension', ': Grab two dumbbells with an overhand grip and lay your forearms across your knees.

 : Let your wrists flex fully, then extend your wrists.', 'braços', '["braços"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Deflation', 'https://wger.de/en/exercise/1881/view/', 'db wrist extension bracos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c9cfd9d8-8daa-49d8-a659-2dd4bd591cbc', 2554, 'en', 'Dead Bug', 'Controlled trunk stability exercise emphasizing breathing, abdominal control, and coordination of opposite limbs.', 'core', '["abdômen"]', '[]', '[]', NULL, 'CC-BY-SA 3', '', 'https://wger.de/en/exercise/2554/view/', 'dead bug abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('816d8bff-73c0-436c-8479-e0145f2324fc', 2505, 'en', 'Dead Bug (Core L1)', 'Vasco custom dead bug - foundational deep core stability and anti-extension. Teaches lumbar-pelvic dissociation, breath-coordination, and proximal stability for distal mobility. Prerequisite for all core training.', 'core', '["abdômen"]', '["oblíquos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Vasco Custom', 'https://wger.de/en/exercise/2505/view/', 'dead bug (core l1) abdomen obliquos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d4db2355-4c99-4d80-a179-6aeced7c7fed', 178, 'en', 'Deadbug', 'Lie on your back, with your hips and knees bent to 90°. Raise both arms toward the ceiling. Pull your lower back to the floor to eliminate the gap. Start by pressing one leg out, and tapping the heel to the floor. "As you extend one leg, exhale as much as you can, keeping your lower back glued to the floor," Dunham says. When you can’t exhale any more, pull your knee back to the starting position. Make this more difficult by holding weight in your hands, or by lowering opposite arm and leg.', 'core', '["abdômen"]', '["oblíquos"]', '[]', NULL, 'CC-BY-SA 4', 'Metin', 'https://wger.de/en/exercise/178/view/', 'deadbug abdomen obliquos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('74d4697d-8a97-4ea2-9d05-fa4d2bd7221e', 182, 'en', 'Deadhang', 'Deadhang performed on an edge either with or without added weight (adujst edge or weight to adjust difficulty)', 'braços', '["braços"]', '[]', '[]', NULL, 'CC-BY-SA 4', '2dPREtEZP221u68Akf0JImv5L48', 'https://wger.de/en/exercise/182/view/', 'deadhang bracos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9ac4813e-79a6-4a4d-ab93-9cfa5bf7b8fa', 1889, 'en', 'Decline Bench Leg Raise', '• Setup : Lie on a decline bench with your head at the top and grip the handles.

• The Start : Extend legs fully, keeping them slightly elevated to engage your core.

• The Lift : Raise your legs toward the ceiling using your abs, not momentum.

• The Squeeze : Pause and contract your lower abdominals at the top.

• The Return : Lower your legs slowly to the starting position with control.', 'core', '["abdômen"]', '[]', '["Banco inclinado"]', 'https://wger.de/media/exercise-images/1889/bc51ef67-0c12-4340-a36c-42ef722778dd.png', 'CC-BY-SA 4', 'nishant0712', 'https://wger.de/en/exercise/1889/view/', 'decline bench leg raise abdomen banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('bcd801f0-9a38-4615-a91c-900153c8c234', 185, 'en', 'Decline Bench Press Barbell', 'Lay down on a decline bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up.', 'peito', '["peito"]', '[]', '["Barra","Banco"]', 'https://wger.de/media/exercise-images/100/Decline-bench-press-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/185/view/', 'decline bench press barbell peito barra banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('dda69c96-62d4-4690-aa07-a4a0f6ceb63a', 186, 'en', 'Decline Bench Press Dumbbell', 'Take two dumbbells and sit on a decline bench, the feet are firmly on the floor, the head is resting the bench. Hold the weights next to the chest, at the height of your nipples and press them up till the arms are stretched. Let the weight slowly and controlled down.', 'peito', '["peito"]', '[]', '["Banco","Halteres"]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/186/view/', 'decline bench press dumbbell peito banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fae44c34-2e85-4d22-8fb8-7b14faf14719', 1591, 'en', 'Deep breathing (standing or seated)', 'A conscious breathing technique to improve oxygenation, reduce stress and connect with the present moment.', 'peito', '["oblíquos","abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'MrAlfaRobot', 'https://wger.de/en/exercise/1591/view/', 'deep breathing (standing or seated) obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e7a964cd-e68e-4926-bc7c-577065137e18', 189, 'en', 'Deficit Deadlift', 'Preparation

 Stand on weight plate, bumper plate, or shallow elevated platform with loaded bar above feet. Squat down and grasp bar with shoulder width or slightly wider overhand or mixed grip.

 Execution

 Lift bar by extending hips and knees to full extension. Pull shoulders back at top of lift if rounded. Return weights to floor by bending hips back while allowing knees to bend forward, keeping back straight and knees pointed same direction as feet. Repeat.

 Comments

 Throughout lift, keep hips low, shoulders high, arms and back straight. Knees should point same direction as feet throughout movement. Keep bar close to body to improve mechanical leverage. Grip strength and strength endurance often limit ability to perform multiple reps at heavy resistances. Gym chalk, wrist straps, grip work, and mixed grip can be used to enhance grip. Mixed grip indicates one hand holding with overhand grip and other hand holding with underhand grip. Lever barbell jack can be used to lift barbell from floor for easier loading and unloading of weight plates.

 Barbell Deficit Deadlift emphasizes building strength through lowest portion of Deadlift. Target muscle is exercised isometrically. Heavy barbell deadlifts significantly engages Latissmus Dorsi. See Barbell Deficit Deadlift under Gluteus Maximus. Also see Deadlift Analysis.', 'costas', '[]', '["posteriores de coxa","glúteos","dorsais","abdômen","sóleo"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'bobbyprince89', 'https://wger.de/en/exercise/189/view/', 'deficit deadlift posteriores de coxa gluteos dorsais abdomen soleo barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b7dd3766-f660-45dc-bbe1-10e15e2f7cee', 1777, 'en', 'Deficit Push ups', 'Pushup on blocks or grips, so you can dip lower than the hands in the decent.', 'peito', '["peito"]', '["tríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1777/view/', 'deficit push ups peito triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6a448382-0ea9-4f41-8a83-0b7cd7d8a2bf', 1536, 'en', 'Delt Stretch', 'Stretch your deltoids for a certain period of time.', 'ombros', '["ombros"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1536/view/', 'delt stretch ombros peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('bb9b994e-426f-4693-9d16-3f8d5a9c72b8', 1556, 'en', 'Devil’s Press', 'The Devil’s Press is a hybrid movement combining a dumbbell burpee and a double dumbbell snatch. It’s a full-body, high-intensity exercise that develops strength, power, and metabolic conditioning.

 

• Start with a dumbbell in each hand and perform a burpee, letting your chest touch the ground while holding the dumbbells.

• Explosively jump your feet forward and swing the dumbbells between your legs.

• Drive the dumbbells overhead in one continuous motion, locking out your arms.

• Lower the dumbbells with control to return to the starting position and repeat', 'ombros', '["ombros","glúteos","peito"]', '["posteriores de coxa","dorsais","oblíquos","tríceps"]', '["Halteres"]', 'https://wger.de/media/exercise-images/1556/a23c820b-e08b-4911-a6a4-80f16c15d2e0.png', 'CC-BY-SA 4', 'Settebello', 'https://wger.de/en/exercise/1556/view/', 'devil’s press ombros gluteos peito posteriores de coxa dorsais obliquos triceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('14d5cdbc-9b17-4296-a282-0a81cd3c4c4e', 193, 'en', 'Diagonal Shoulder Press', 'You sit at the bench press device, back slightly tilted to the back. The bar should be about 20 cm in front of you. Then you push the bar and take it back again, as you would with a bench press.

 In this position you strain your chest muscles a lot less, which is nice if you want to train, but your chest hasn''t recovered yet.', 'ombros', '["ombros"]', '[]', '["Banco"]', NULL, 'CC-BY-SA 4', 'oboema', 'https://wger.de/en/exercise/193/view/', 'diagonal shoulder press ombros banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('de22963a-5d42-4999-860e-377f64359432', 386, 'en', 'Diamond push ups', 'Start: Get into a plank. Place hands close together under your chest so thumbs and index fingers form a diamond shape.

 Lower: Bend your elbows to lower your chest toward your hands. Keep your body straight.

 Push: Push back up until arms are fully extended.

 New note Keep elbows close to your body and core tight.', 'peito', '["peito"]', '["tríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'notdefine', 'https://wger.de/en/exercise/386/view/', 'diamond push ups peito triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7c8eb1ac-2d7e-4ca7-919a-1848ba38e0f4', 197, 'en', 'Dips Between Two Benches', 'Put two benches so far appart, that you can hold onto one with your hands and are just able to reach the other with your feet. The legs stay during the exercise completely stretched. With your elbows facing back, bend them as much as you can. Push yourself up, but don''t stretch out the arms.', 'braços', '["tríceps"]', '[]', '["Banco"]', 'https://wger.de/media/exercise-images/83/Bench-dips-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/197/view/', 'dips between two benches triceps banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('adbb1d4c-962b-4a26-a353-9c47a2b37a93', 1713, 'en', 'Doorway Pectoral Stretch', '• Place the forearm vertically on a door frame or stationary object at head height

• Step forward past the arm, keeping it still against the object to stretch the chest', 'peito', '["peito"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1713/view/', 'doorway pectoral stretch peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fe249e2f-5856-420f-8a34-1b02c7fde141', 1360, 'en', 'Double Kettlebell Clean and Press', 'Full-body muscles building exercise. This exercise provides a huge range of benefits in terms of strength & size and is extremely functional.', 'braços', '["ombros","bíceps","braquial","quadríceps","trapézio","tríceps"]', '["posteriores de coxa","glúteos","dorsais","abdômen"]', '["Kettlebell"]', NULL, 'CC-BY-SA 4', 'm4k3r', 'https://wger.de/en/exercise/1360/view/', 'double kettlebell clean and press ombros biceps braquial quadriceps trapezio triceps posteriores de coxa gluteos dorsais abdomen kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a030a4e9-970c-4442-b0b3-e49b42143de0', 1361, 'en', 'Double Kettlebell Front Squat', 'The kettlebell front squat is a compound, multi-joint exercise that works several muscle groups.', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa","panturrilhas","abdômen"]', '["Kettlebell"]', NULL, 'CC-BY-SA 4', 'm4k3r', 'https://wger.de/en/exercise/1361/view/', 'double kettlebell front squat gluteos quadriceps posteriores de coxa panturrilhas abdomen kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('58ca3e51-ea64-4771-a74a-a74d29f5c40c', 1243, 'en', 'Double Leg Calf Raise', 'The double leg heel raise is important to strengthen and create control and stability around the ankle and knee, and provide balance and control for the hip and pelvis.', 'pernas', '["panturrilhas","sóleo"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1243/53d4fabe-c994-4907-873f-8d82813a9832.png', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1243/view/', 'double leg calf raise panturrilhas soleo peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f0823bb5-3f18-48d4-98de-cbe38f9fd8ff', 1827, 'en', 'Double-Leg Abdominal Press', 'Lie on your back with knees and hips bent at 90 degrees (tabletop).

 Place your hands on your thighs just above your knees. Push your hands against your knees as hard as possible while using your abs to pull your knees toward your hands.

 Hold for 10 seconds of maximum effort. Your abs should be shaking.', 'core', '["abdômen"]', '[]', '["Colchonete"]', NULL, 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1827/view/', 'double-leg abdominal press abdomen colchonete', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('02b96dc1-d1d9-4fc7-b54c-82dda1691485', 1481, 'en', 'Drag Pushdown', '• Starting
position for this rope pushdown is standing facing a cable machine with
the handles of a rope attachment in both hands and feet shoulder width
apart.

• Hinge
forward slightly at the hips maintaining an upright chest and bring the
shoulders and elbows behind the body so that when you push down on the
cable attachments, you can get a fully contracted triceps long head.

• Drag
the cable machine rope attachment as close to the body as possible and
straighten your elbows until lockout.', 'braços', '["tríceps"]', '[]', '["Máquina de cabo","Barra W"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1481/view/', 'drag pushdown triceps maquina de cabo barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8c132ea0-7885-474f-8514-0909ae22bdf6', 1201, 'en', 'Dragon squat', 'Start standing with your feet hip-width apart. Cross your right foot behind you to the left corner and back of the room while bending both knees. Return and repeat, alternating sides. Keep your hips and shoulders forward as you cross your feet and bend your knees.', 'pernas', '["quadríceps"]', '["posteriores de coxa","panturrilhas","glúteos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1201/view/', 'dragon squat quadriceps posteriores de coxa panturrilhas gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f5ad82a8-adf8-4795-9874-1f6d183c56ed', 1409, 'en', 'Dragon-flag', 'Keep your body completely rigid throughout the movement, avoiding sagging in your lower back.
Use a firm grip to stabilize your upper body.
Start with simpler versions (such as with bent knees) to build strength and control.', 'core', '["oblíquos","abdômen"]', '["ombros","glúteos","dorsais","tríceps"]', '[]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1409/view/', 'dragon-flag obliquos abdomen ombros gluteos dorsais triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('15ee508d-fbd7-4acf-ab44-e35525582693', 1512, 'en', 'Drop Curl', 'Drop curls in a modified position at a slow pace effectively engage the brachialis for arm width.
Starting position is with both arms in a slight angle towards each other at chest height with a dumbbell in each hand. Lower one dumbbell close to full extended arm position slowly and in a controlled manner during the first half of the curl, then curl it back up to starting position, while the other dumbbell stays at its starting position. Now lower the other dumbbell down. This keeps tension on the brachialis. As we pass the 90deg mark on our way down, the biceps will take over the work.', 'braços', '["bíceps"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1512/view/', 'drop curl biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('51ab6376-eb3e-42dc-ad48-46166c94adac', 1639, 'en', 'Dumbbell Bent Over Face Pull', 'This exercise involves using dumbbells to perform a bent over face pull, which targets the upper back and shoulders. The movement involves pulling the weights towards the face while keeping the elbows high and squeezing the shoulder blades together.', 'costas', '["ombros","dorsais"]', '["trapézio"]', '["Halteres"]', 'https://wger.de/media/exercise-images/1639/8927346e-f5ca-4795-bdf1-5ac9309401e7.webp', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1639/view/', 'dumbbell bent over face pull ombros dorsais trapezio halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('cbdfde11-8a76-471f-ae6a-1e0155908bce', 2608, 'en', 'Dumbbell Bent-Over Reverse Fly', 'Custom description created by the Integrated Conditioning routine importer for wger.', 'ombros', '["trapézio"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2608/view/', 'dumbbell bent-over reverse fly trapezio halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8675ea3b-0e8b-4a08-9e82-4525ec91dd23', 1226, 'en', 'Dumbbell bicep curl to press', 'Bend your elbows and lift the dumbbells to your shoulders.
Push the dumbbells over your head while rotating your arms to make your palms face forward. Reverse it to lower down. Repeat the exercise.', 'braços', '["bíceps"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1226/a6154dbd-67a0-4a36-8748-0f5af3865e83.jpg', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1226/view/', 'dumbbell bicep curl to press biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('82f19d1c-f12b-49f0-bfdd-24239f93eabc', 1504, 'en', 'Dumbbell Bradford press', 'From a front hold of the DBs in a OHP, press above the head, bring back towards the rear of the shoulders, down, and press back forward.', 'ombros', '["ombros"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1504/view/', 'dumbbell bradford press ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('31a58615-d3ae-4233-9c50-9143c899ce8c', 1482, 'en', 'Dumbbell Cheat Curl', '• Starting position is standing
with feet shoulder width apart.

• Hands should take an underhand
or supinated grip on the dumbbells holding them with hands shoulder
width apart.

• Keeping elbows tucked into your
sides throughout the entire movement, use momentum to curl the dumbbells,
squeezing your biceps at the top of the movement.

• Slowly lower to return to the
starting position. Keep the core tight throughout the exercise.

 Cheating
through the concentric curling portion of this challenging exercise gives us a
great opportunity to increase time under tension and create eccentric overload
with heavier weight when we lower.', 'braços', '["bíceps"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1482/view/', 'dumbbell cheat curl biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('428112f3-3918-45ba-870a-dc58cf3959cf', 1228, 'en', 'Dumbbell close grip bench press', 'Lie down with your back on a flat bench. Hold a dumbbell in each hand. Raise your arms towards the ceiling with your palms facing each other and dumbbells pressed together.
Slowly lower the dumbbells to your chest, then slowly push them back. Repeat the exercise.', 'braços', '["peito","tríceps"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1228/view/', 'dumbbell close grip bench press peito triceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('46e0f60c-fdc0-489a-82e4-a5b7476a5c21', 202, 'en', 'Dumbbell Concentration Curl', 'Sit on bench. Grasp dumbbell between feet. Place back of upper arm to inner thigh. Lean into leg to raise elbow slightly.', 'braços', '["braquial"]', '["bíceps"]', '["Halteres"]', NULL, 'CC-BY-SA 3', 'http://www.exrx.net/WeightExercises/Brachialis/DBC', 'https://wger.de/en/exercise/202/view/', 'dumbbell concentration curl braquial biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b48e4d9d-f7fc-4619-85fb-6dabe5d7c999', 1415, 'en', 'Dumbbell Crunches', 'Dumbbell crunches are a weighted variation of traditional crunches designed to target the abdominal muscles more intensely. Lie flat on your back with your knees bent and feet flat on the floor. Hold a dumbbell with both hands close to your chest or above your head. Lift your shoulders and upper back off the ground in a crunching motion, engaging your core. Slowly lower yourself back to the starting position. Ensure controlled movements throughout the exercise to prevent strain.', 'core', '["abdômen"]', '["oblíquos"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1415/view/', 'dumbbell crunches abdomen obliquos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('99846da5-5dc8-4de1-ba55-ae2b4c03c30d', 1931, 'en', 'Dumbbell Curl', 'The Dumbbell Curl is a classic isolation exercise for the arms. Unlike the Hammer Curl, it involves rotating your wrists (supination) as you lift the weights, which allows for a full contraction of the biceps.', 'braços', '["bíceps","braquial"]', '["ombros","abdômen"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1931/view/', 'dumbbell curl biceps braquial ombros abdomen halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b199baca-7353-4dee-bbcf-620f96dba5b4', 1370, 'en', 'Dumbbell Deadlift', '• Controlled execution

• Don''t use momentum

• Slow execution', 'pernas', '["posteriores de coxa","glúteos"]', '["quadríceps","trapézio"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1370/view/', 'dumbbell deadlift posteriores de coxa gluteos quadriceps trapezio halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2539f907-0c10-4af5-807c-48cd15fd0878', 1616, 'en', 'Dumbbell donkey kick', 'The dumbbell donkey kick is an effective exercise for working the glute and hamstring muscles. This exercise is usually performed on all fours, using a dumbbell to add resistance. The steps for performing it correctly are described below.
Starting position: Get on all fours on a mat, with your hands aligned under your shoulders and your knees aligned under your hips.
Placing the dumbbell: Take a dumbbell and place it behind the knee of the leg you are going to lift. Make sure it is held securely to prevent it from falling during the exercise.
Exercise:
Inhale and, as you exhale, lift the leg with the dumbbell upward, keeping the knee bent at a 90-degree angle.
Raise the leg until it is parallel to the floor, feeling the contraction in the glutes.
Hold the position for one second at the top and then slowly lower the leg back to the starting position.
Repetitions: Perform 10 to 15 repetitions per leg, making sure to maintain good form throughout the exercise.
Sets: Complete 2 to 3 sets, depending on your fitness level.', 'pernas', '["posteriores de coxa","glúteos"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1616/97e6fd98-2ca6-486f-b9b2-f0499fe38044.jpg', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1616/view/', 'dumbbell donkey kick posteriores de coxa gluteos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2418b290-801c-45fd-a990-fc9f234ab1e5', 1224, 'en', 'Dumbbell drag curls', 'Hold a dumbbell in each hand with your palms facing forward. Pull your elbows back and lift the dumbbells to your chest height. Slowly lower the dumbbell and repeat the exercise.', 'braços', '["bíceps"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1224/view/', 'dumbbell drag curls biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3393db0b-98b7-4d53-a0d4-985f97875295', 1116, 'en', 'Dumbbell farmer''s carry', 'Grab half your body weight in each hand and walk.', 'pernas', '["pernas"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1116/view/', 'dumbbell farmer''s carry pernas halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e4966cb8-9089-4595-9c78-99a27821e6ff', 1084, 'en', 'Dumbbell Floor Press', 'Grab your dumbbells and lay flat on your back with your knees bent and your feet flat on the ground (use a bench if you have one). Press the weights up, locking out your elbows (A). Lower them slowly until your upper arms are resting on the floor (B) close to your body. Pause here before explosively pressing back up. Squeeze your chest hard and repeat.', 'peito', '["peito"]', '["ombros","bíceps","tríceps"]', '["Halteres"]', 'https://wger.de/media/exercise-images/1084/91dd5a95-1c45-46f2-a074-de41b6ad599b.jpg', 'CC-BY-SA 4', 'admin', 'https://wger.de/en/exercise/1084/view/', 'dumbbell floor press peito ombros biceps triceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b407768d-d519-47b8-818a-44c9761a8be6', 1503, 'en', 'Dumbbell Frog Press', 'Similar to hip thrust, but with feet put up together, lifting the butt off the ground in a frog like position.', 'pernas', '["glúteos"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1503/view/', 'dumbbell frog press gluteos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4621b41f-0d32-4033-acff-dc079c792606', 1640, 'en', 'Dumbbell Front Squat', 'This exercise involves holding a dumbbell in each hand at shoulder height and performing a squat. It targets the lower body muscles, including the quads, hamstrings, and glutes, while also engaging the core and upper body.', 'pernas', '["glúteos","quadríceps"]', '["ombros","abdômen"]', '["Halteres"]', 'https://wger.de/media/exercise-images/1640/bdea82f1-15ef-4649-8b5a-1303cfc178e7.webp', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1640/view/', 'dumbbell front squat gluteos quadriceps ombros abdomen halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b7c6a444-90ea-4f5b-9fea-748311606eaa', 203, 'en', 'Dumbbell Goblet Squat', 'Grasp dumbbell with both hands at the sides of the upper plates. Hold dumbbell in front of chest, close to torso. Place feet about shoulderwide apart, keep knees slightly bent.

 Squat down until thighs are parallel to floor. Keep back straight, bend and move hips backward to keep knees above feet. Return, keep knees slightly flexed. Repeat.

 Keep bodyweight on heels and look ahead or slightly above to keep back straight.', 'pernas', '["quadríceps"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/203/1c052351-2af0-4227-aeb0-244008e4b0a8.jpeg', 'CC-BY-SA 4', 'ataraxie67', 'https://wger.de/en/exercise/203/view/', 'dumbbell goblet squat quadriceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f0f53b8e-0136-4195-baf3-781903651359', 1087, 'en', 'Dumbbell Hang Power Cleans', 'On your feet, stand tall with your dumbbells, holding them at your sides. Hinge at the hips to lower them to your knees (picture 1). Stand back up with a slight jump, using the momentum to pull the dumbbells up on to your shoulders (picture 2). Stand up straight, then lower under control to your sides and repeat. Keep this fast and explosive; if your heart rate doesn’t hit the roof, you’re doing them wrong.', 'costas', '["posteriores de coxa","glúteos"]', '["panturrilhas","quadríceps","trapézio"]', '["Halteres"]', 'https://wger.de/media/exercise-images/1087/d85f4e02-b20c-457c-bdfb-0b00e2d14150.jpg', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1087/view/', 'dumbbell hang power cleans posteriores de coxa gluteos panturrilhas quadriceps trapezio halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('587af8f1-516b-44c3-8660-70f262e1bef8', 1353, 'en', 'Dumbbell Hex Press', '• Engage the muscles

• Position your feet wide

• Controlled movement

• Slow movement

• Bring the weights toward your lower chest/stomach', 'peito', '["peito","tríceps"]', '["ombros"]', '["Halteres"]', 'https://wger.de/media/exercise-images/1353/138cb483-7d4d-4519-b029-63e4269810a6.webp', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1353/view/', 'dumbbell hex press peito triceps ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('af77220c-098c-47c2-9f8c-92a651998903', 1642, 'en', 'Dumbbell Hip Thrust', 'This exercise involves sitting on the ground with a dumbbell resting on the hips, then thrusting the hips upward while squeezing the glutes. It is a great exercise for strengthening the glutes and improving hip mobility.', 'pernas', '["glúteos","quadríceps"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1642/a81ad922-caf5-47f8-99b4-640cb0717436.webp', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1642/view/', 'dumbbell hip thrust gluteos quadriceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('43e85cb8-51d0-4892-b1bf-80a3cb111ff6', 204, 'en', 'Dumbbell Incline Curl', '• Setup: Set an adjustable bench to an incline of approximately 45 to 60 degrees .

• Starting Position: Sit back against the bench with a dumbbell in each hand. Let your arms hang straight down toward the floor with your palms facing forward (supinated grip).

• The Curl: Keeping your upper arms stationary and shoulders pinned back against the bench, exhale and curl the weights upward toward your shoulders.

• Peak Contraction: Squeeze your biceps hard at the top of the movement, ensuring your elbows do not swing forward.

• The Descent: Inhale and slowly lower the dumbbells back to the starting position, maintaining full control and feeling the stretch in the biceps.', 'braços', '["bíceps"]', '["braquial"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'ExRx', 'https://wger.de/en/exercise/204/view/', 'dumbbell incline curl biceps braquial halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('dcc6e237-a8bb-4eca-bbc5-7fb852636f6a', 206, 'en', 'Dumbbell Lunges Walking', '• Starting Position: Stand with feet hip-width apart and hands either on your hips or holding dumbbells at your sides.

• The Stride: Take a wide step forward with your right leg.

• The Descent: Lower your hips until both knees are bent at approximately 90-degree angles .

• The Transition: Drive through your front heel to stand up, bringing your back foot forward to step directly into the next lunge.', 'pernas', '["quadríceps"]', '["glúteos"]', '["Halteres"]', 'https://wger.de/media/exercise-images/113/Walking-lunges-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/206/view/', 'dumbbell lunges walking quadriceps gluteos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7299c75d-d586-4729-8109-baf123dcf36a', 2609, 'en', 'Dumbbell or Machine Calf Raise', 'Custom description created by the Integrated Conditioning routine importer for wger.', 'panturrilhas', '["panturrilhas"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2609/view/', 'dumbbell or machine calf raise panturrilhas halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('68e5eae7-7fd0-4d69-9b50-d0df15feac91', 801, 'en', 'Dumbbell Push-Up', 'Normal Push-ups on Dumbbells, this brings a further range of movement', 'peito', '["peito"]', '["ombros","tríceps"]', '["Halteres"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/801/view/', 'dumbbell push-up peito ombros triceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('adb6067f-fd48-4a25-a9b4-0793c5f158fa', 1227, 'en', 'Dumbbell rear delt row', 'Hold a dumbbell in each hand. Bend at your hips to make your back almost parallel to the floor. Let your arms hang down. Keep your arms in line with your shoulders. bend and lift your elbows out to the sides until your upper arms are parallel to the floor. Slowly return and repeat', 'ombros', '["ombros","braquial","trapézio"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1227/57415c3c-2963-4130-9f6f-79f6a96113b6.gif', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1227/view/', 'dumbbell rear delt row ombros braquial trapezio halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('75e34967-b0ec-40d5-811e-b474b234a7a9', 1651, 'en', 'Dumbbell Rear Lunge', 'This exercise involves holding a dumbbell in each hand and stepping back into a lunge position, then returning to standing. It primarily targets the glutes, hamstrings, and quadriceps.', 'pernas', '["glúteos","quadríceps"]', '["sóleo"]', '["Halteres"]', 'https://wger.de/media/exercise-images/1651/04ab2679-a04d-4d05-9c85-0d36e898328c.webp', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1651/view/', 'dumbbell rear lunge gluteos quadriceps soleo halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('65d12ecf-54b8-466d-a412-e55c396cad69', 1652, 'en', 'Dumbbell Romanian Deadlift', 'This exercise involves holding a dumbbell in each hand and bending forward at the hips while keeping the back straight, then returning to a standing position. It primarily targets the hamstrings and glutes.', 'pernas', '["posteriores de coxa","glúteos"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1652/0306c8c0-70cc-45d4-92de-6fa72ceaa834.webp', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1652/view/', 'dumbbell romanian deadlift posteriores de coxa gluteos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d420baf8-977b-499e-8f91-416374227b91', 1602, 'en', 'Dumbbell Scaption', 'Starting position:

 Stand upright with your feet shoulder-width apart.

 Hold a dumbbell in each hand with a neutral grip (palms facing each other).

 Keep a slight bend in your elbows, shoulders relaxed and shoulder blades pulled back.

 Execution:

 Slowly raise the dumbbells forward and slightly to the side, at about a 30–45° angle from your body (between a front raise and a lateral raise).

 Lift until your arms are about shoulder height (do not go overhead).

 Pause for a second at the top and feel the activation in your shoulders and scapular stabilizers.

 Lower the dumbbells back down under control to the starting position.

 Breathing:

 Inhale as you lower the dumbbells.

 Exhale as you lift them.

 Common mistakes:

 Using dumbbells that are too heavy (causing jerky movements).

 Lifting above shoulder height (puts unnecessary stress on the shoulder joint).

 Arching the lower back instead of keeping the movement controlled at the shoulders.

 Purpose of the exercise:

 Activates the lower trapezius, serratus anterior, and scapular stabilizers.

 Helps correct posture and improve shoulder balance.', 'ombros', '["trapézio"]', '["ombros"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'zdelko', 'https://wger.de/en/exercise/1602/view/', 'dumbbell scaption trapezio ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5a9f4fa4-6b71-4bc7-a284-e76e43e3106a', 1429, 'en', 'Dumbbell Shoulder Rotations', 'Dumbbell shoulder rotations are designed to strengthen the rotator cuff muscles and improve shoulder stability and mobility.

 

• External Rotation : Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm outward, away from your body, keeping your elbow stationary. Slowly return to the starting position.

• Internal Rotation : Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm inward, toward your body, and slowly return to the starting position. Perform the exercise with controlled movements to avoid strain.', 'ombros', '["ombros"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1429/view/', 'dumbbell shoulder rotations ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3e9b3bb0-7958-4836-89a5-ed0c5f7eeb03', 1650, 'en', 'Dumbbell Side Bend', 'This exercise involves holding a dumbbell in one hand and bending sideways to work the oblique muscles on the side of the body. It can be done standing or seated and is often used as a core strengthening exercise.', 'core', '["oblíquos"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1650/1d7a5336-ec0b-4898-a474-78ba32789bf3.webp', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1650/view/', 'dumbbell side bend obliquos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('412ba9ab-ae29-4411-9bbc-74af1263494c', 1653, 'en', 'Dumbbell Side Squat', 'This exercise involves holding a dumbbell in one hand and performing a squat while stepping to the side. It targets the legs, glutes, and core muscles.', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa"]', '[]', 'https://wger.de/media/exercise-images/1653/c10c4e17-1e14-4cf9-930b-cc3a614f15dd.webp', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1653/view/', 'dumbbell side squat gluteos quadriceps posteriores de coxa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7cc24acf-3fc9-4d14-a461-cd00d1d18f0e', 1234, 'en', 'Dumbbell Single-leg Hip Thrust', 'The single-leg hip thrust is performed by placing your upper back on a weight bench, raising one leg, and extending the hip of the other leg to achieve an isolated contraction of the glute.
By working each side separately, you can fully isolate your glutes unilaterally, providing maximal training stimulus.', 'pernas', '["glúteos"]', '["posteriores de coxa","quadríceps"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1234/view/', 'dumbbell single-leg hip thrust gluteos posteriores de coxa quadriceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('51fe0871-1390-4755-bd04-01a93e32f533', 1947, 'en', 'dumbbell snatch', 'Key Steps to Execute Correctly:

 Setup: Place the dumbbell between your feet, with your shoulders above your hips, chest up, and back flat.

 The Pull: Explosively extend your hips, knees, and ankles (triple extension) to drive the dumbbell upward, keeping your elbow high and the dumbbell close to your body.

 The Catch: Quickly flex your hips and knees to drop under the dumbbell and receive it overhead with your arm locked in position, landing in a half-squat stance.

 Common Mistakes: Using your arms too much to lift the weight instead of your legs, having a low elbow during the pull phase, and misaligning your shoulder, elbow, and wrist in the final position. For beginners, it’s recommended to start with light loads, focus on technique, and perform 3 to 5 sets of 3 to 5 reps per arm.', 'pernas', '["posteriores de coxa","glúteos","quadríceps"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1947/4201a9c0-f9e4-48ca-80f1-b46c7ffe5640.webp', 'CC-BY-SA 4', 'Aleid', 'https://wger.de/en/exercise/1947/view/', 'dumbbell snatch posteriores de coxa gluteos quadriceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8a3e08ab-4e97-4aee-897a-60d8693b9b43', 1366, 'en', 'Dumbbell Split Squat', '• Controlled execution

• No momentum

• Execute slowly', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa","panturrilhas"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1366/view/', 'dumbbell split squat gluteos quadriceps posteriores de coxa panturrilhas halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0c30c543-e2cc-499b-bc31-8c28db445ed2', 1088, 'en', 'Dumbbell sumo deadlift', 'Lower your dumbbell to the ground between your legs. Assume a wide stance and with a straight back squat down. With the dumbbell standing upright, grip it by the top of the ‘head’ (picture 1).Keeping your chest up and core braced, push the floor away, driving back upwards to a standing position (picture 2). Repeat. If you can easily achieve 20-30 reps, use two dumbbells.', 'pernas', '["posteriores de coxa","glúteos"]', '["quadríceps","trapézio"]', '["Halteres"]', 'https://wger.de/media/exercise-images/1088/9f66b288-ce8f-4154-ba80-78fee267263c.jpg', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1088/view/', 'dumbbell sumo deadlift posteriores de coxa gluteos quadriceps trapezio halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ae6a522e-db10-45ba-9642-987468d8a4de', 1684, 'en', 'Dumbbell Thruster', 'Start with the dumbbells resting on your shoulders and squat down. Push
into standing and raise the dumbbells into an overhead position. Bring
the dumbbells back to your shoulders and repeat.', 'pernas', '["posteriores de coxa","glúteos","quadríceps"]', '["ombros"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'meldun', 'https://wger.de/en/exercise/1684/view/', 'dumbbell thruster posteriores de coxa gluteos quadriceps ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d8bddb58-91b0-4d7b-8ec1-cd742584b607', 211, 'en', 'Dumbbell Triceps Extension', 'Position one dumbbell over head with both hands under inner plate (heart shaped grip).

 With elbows over head, lower forearm behind upper arm by flexing elbows. Flex wrists at bottom to avoid hitting dumbbell on back of neck. Raise dumbbell over head by extending elbows while hyperextending wrists. Return and repeat.', 'braços', '["tríceps"]', '["ombros","peito"]', '["Halteres"]', NULL, 'CC-BY-SA 3', 'tuninx', 'https://wger.de/en/exercise/211/view/', 'dumbbell triceps extension triceps ombros peito halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1dca10f9-a976-4a09-ab85-b95fafaa1a28', 1463, 'en', 'Dumbbell Underhand Dead Row', 'The Dumbbell Underhand Dead Row will involve the back, which means you can try a bit heavier weight. The catch is that you need to be able to control the weight for all the reps.

 

• Start by holding a pair of dumbbells with your feet shoulder-wide apart and your knees slightly bent.

• Hinge at your hips to lower your torse forward until it''s almost parallel to the floor, keeping your back flat and maintaining a slight bend in your knees.

• Exhale as you row the dumbbells to your sides up to chest height, leading with your elbows until your upper arms are just past parallel to the floor and the dumbbells are at ribcage level.

• Slowly lower to the starting position and repeat. Keep your back flat all the time.', 'braços', '["bíceps"]', '["dorsais"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1463/view/', 'dumbbell underhand dead row biceps dorsais halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fd38d854-a244-4646-842b-ef1e0fbfede8', 1225, 'en', 'Dumbbell wide bicep curls', 'Hold a dumbbell in each hand with your hands slightly wider than shoulder-width apart and palms facing forward.
Bend your elbows and lift the dumbbells to your shoulders. Slowly return and repeat.', 'braços', '["bíceps"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1225/39a0b7e7-9780-425d-84f5-56d10d1690ac.gif', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1225/view/', 'dumbbell wide bicep curls biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2affa71f-7308-4448-af57-dc44b424090e', 1824, 'en', 'Dumbell Tate Press', '• Set Up : Lie flat with a dumbbell in each hand. Extend your arms straight up over your chest as if you were at the top of a dumbbell bench press

• Starting Position : Position the dumbbells so they are touching or very close together with a pronated grip (palms facing your feet and thumbs facing each other)

• Lowering : Without moving your upper arms or shoulders, bend your elbows and flare them outward to the sides. Lower the inner ends of the dumbbells toward the center of your chest

• Touch and Pause : Gently touch the dumbbells to your chest. Do not rest the weight on your body; maintain constant tension in your triceps

• Press : Forcefully extend your elbows to return the dumbbells to the starting position. Focus on "pushing your pinkies toward the sky" to maximize triceps engagement

 https://www.youtube.com/watch?v=IgSjoXbpy1M&t=2', 'braços', '["tríceps"]', '["ombros","peito"]', '["Banco","Halteres"]', NULL, 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1824/view/', 'dumbell tate press triceps ombros peito banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('73dbe7a5-e8f3-48fd-814e-bc3378c15be2', 1286, 'en', 'Dynamic Planche', '• Start in a plank position, with your hands directly under your shoulders and your feet hip-width apart.

• Engage your core to keep your body in a straight line from head to toe.

• From this position, bend your knees slightly and jump with both feet inward, bringing them as close to your core as possible

• As soon as your feet touch the ground, push off forcefully to jump again and return to the starting plank position.

• Continue repeating this jumping motion, maintaining control and core stability throughout the exercise.

• Make sure to keep your breathing steady while jumping, breathing deeply and controlling your breathing.

• Keep your gaze fixed on the ground to maintain proper spinal alignment.

• Repeat the jumps for the desired length of time or the number of repetitions recommended for your workout program.

• To finish the exercise, rest by releasing the plank position, then stretch if necessary to loosen your muscles.', 'core', '["abdômen"]', '["oblíquos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'painDpice', 'https://wger.de/en/exercise/1286/view/', 'dynamic planche abdomen obliquos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('45d89ca5-f5c7-4e56-9833-fd160cd2666d', 1099, 'en', 'Dynamic side hold', 'Sling a rubber band on a kettlebell and lift the kettlebell by the rubber band. Let it hang by your side and stand on one leg, switch leg while continuing hold. Repeat with other hand', 'core', '["oblíquos"]', '["abdômen"]', '["Kettlebell"]', NULL, 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1099/view/', 'dynamic side hold obliquos abdomen kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('81c6b9ef-7cb7-4328-8cb4-47ae8ecc42be', 1288, 'en', 'Dynamic side plank', 'The dynamic side plank involves positioning yourself on your side, supported on one elbow and the side of your foot, then dipping your hips up and down while keeping your body in a straight line.', 'core', '["oblíquos"]', '["abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'painDpice', 'https://wger.de/en/exercise/1288/view/', 'dynamic side plank obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ddf4111d-907d-4d6c-b583-58323b96ca03', 2480, 'en', 'Easy Continuous Swim (Freestyle)', 'Swim freestyle at a relaxed, steady pace without stopping — think conversation pace, not racing. Focus on smooth, even strokes rather than speed or breathing technique; this is just to get your body moving and your heart rate up.', 'cardio', '["ombros","dorsais","peito"]', '["posteriores de coxa","panturrilhas","glúteos","quadríceps","abdômen","tríceps"]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2480/view/', 'easy continuous swim (freestyle) ombros dorsais peito posteriores de coxa panturrilhas gluteos quadriceps abdomen triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1d1a53dd-e00f-477e-83f7-09c8ef9a71cd', 2531, 'en', 'elbow lever', '​A calisthenics static balance skill where the entire body is held straight and parallel to the ground, supported by tucking the elbows firmly into the abdomen or pelvic bones.', 'core', '["abdômen"]', '["ombros","tríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'ege', 'https://wger.de/en/exercise/2531/view/', 'elbow lever abdomen ombros triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('732a9a7f-fb45-41ea-94a3-6a7246a699f6', 1498, 'en', 'Elbows Tucked DB Bench Press', 'Elbows Tucked DB Bench Press, chest press movement focusing on the triceps. DB stays parallel with body', 'braços', '["tríceps"]', '["peito"]', '["Banco","Halteres"]', NULL, 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1498/view/', 'elbows tucked db bench press triceps peito banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('34cce09a-edb3-4140-892a-1cf70da8d98b', 1391, 'en', 'Elephant Walks', 'Hinge at your hips until you feel a stretch behind your knees. Bend one leg while the other is straight then fluidly bend the other knee while straightening the first knee.', 'pernas', '["posteriores de coxa"]', '["panturrilhas"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1391/view/', 'elephant walks posteriores de coxa panturrilhas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a2fa24ba-597f-4746-b9b0-fbabae6396e6', 1707, 'en', 'Elevación lateral polea', 'Lateral elevation unilateral using a polea', 'costas', '["ombros"]', '[]', '["Banco inclinado"]', NULL, 'CC-BY-SA 4', 'polloperro', 'https://wger.de/en/exercise/1707/view/', 'elevacion lateral polea ombros banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('302e02df-4270-4a0b-8c5d-b743cdb06fc9', 1027, 'en', 'Elevated prayer stretch', 'Starting position: 
Kneel in front of a bench, far enough so that your torso can fit between your knees and the bench. With your back straight, place your elbows on the bench, with palms together, hands pointing up.
 Steps: 

 

• On exhale, stretch your chest down toward the floor without moving your lower back. At the same time, bring your hands toward your shoulders, keeping palms together and elbows on the bench.

• Hold for a few seconds.

• On inhale, relax your back to return to the starting position.

• 
 

• Repeat.', 'costas', '["dorsais"]', '[]', '["Banco"]', NULL, 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1027/view/', 'elevated prayer stretch dorsais banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('95a300de-2ad8-492e-9364-13766d9e7618', 962, 'en', 'Elliptical', 'It improves muscle toning, strengthens the leg muscles (quads, glutes, calves), helps vascularisation and increases resistance. The elliptical is also very useful if you aim to lose weight. Teste', 'cardio', '["glúteos","quadríceps","trapézio"]', '["bíceps","abdômen","tríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/962/view/', 'elliptical gluteos quadriceps trapezio biceps abdomen triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('29a361d5-1300-4fb4-90d6-d6350bec9cb9', 1241, 'en', 'Exercise Band Dorsiflexion', 'This exercise uses an exercise band. It targets the Soleus and Tibialis anterior.', 'pernas', '["sóleo"]', '[]', '["Elástico"]', NULL, 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1241/view/', 'exercise band dorsiflexion soleo elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('70c97a79-5e88-4549-a74c-0e5190a5c048', 1242, 'en', 'Exercise Band Plantarflexion', 'Banded plantarflexion is a great way to bridge the gap between plantarflexion range of motion and the more strenuous calf raises in weight bearing. This can help strengthen the calf muscles, load the Achilles tendon, and improve plantarflexion range of motion.', 'pernas', '["panturrilhas"]', '["sóleo"]', '["Elástico"]', NULL, 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1242/view/', 'exercise band plantarflexion panturrilhas soleo elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('253813a0-b33f-48b3-991e-ca66116e053f', 2529, 'en', 'explosive push ups', 'Explosive Push-Ups

 Start in a standard push-up position, lower your chest, then explosively push off the ground so your hands leave the floor. Land softly and immediately repeat.', 'peito', '["peito"]', '["ombros","tríceps"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/2529/e97b7a36-3414-4c4f-9d66-fe37182e829b.png', 'CC-BY-SA 4', 'ege', 'https://wger.de/en/exercise/2529/view/', 'explosive push ups peito ombros triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a4413bcc-dcd1-4332-a09a-fee94a265e22', 1835, 'en', 'External Rotation Stretch', '• Sit with your feet pressed against each other, and one knee raised all the way out to the side of your body.

• Place your elbow on your raised knee, bend it at 90 degrees, and point your hand directly forward, holding your barbell/dumbbell.

• Keep your shoulder depressed and retracted, raise your hand until your forearm is vertical, as if you were about to wave at someone like a robot.

• Lower your hand to the original position and repeat.', 'ombros', '["ombros","trapézio"]', '[]', '["Barra"]', 'https://wger.de/media/exercise-images/1835/ca4a0b7e-9fdd-4173-843a-f0392824abe1.jpg', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1835/view/', 'external rotation stretch ombros trapezio barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ab808c2c-2e84-42bb-a65d-287a06ca7aa2', 1921, 'en', 'Extreme Lat Stretch', 'Deep loaded stretch for latissimus dorsi, performed after pulling movements.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1921/view/', 'extreme lat stretch costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3c33c9fd-20cc-4dff-ac88-c992bb9b2e33', 1919, 'en', 'Extreme Pec Stretch', 'Deep loaded stretch for pectorals, typically performed at end of chest work.', 'peito', '["peito"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1919/view/', 'extreme pec stretch peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4925b6c0-bbe6-4864-a649-23ec18d49985', 1920, 'en', 'Extreme Shoulder Stretch', 'Deep loaded stretch for deltoids, performed after pressing movements.', 'ombros', '["ombros"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1920/view/', 'extreme shoulder stretch ombros peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('52093ce1-2544-4b48-ad15-6e02de9b576d', 2503, 'en', 'Face Pulls (Bodyweight Doorframe/Towel)', 'Vasco custom face pull variation using doorframe or towel for rear delt development. Zero equipment. Part of Tuesday Pull day.', 'costas', '["ombros","trapézio","tríceps"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Vasco Custom', 'https://wger.de/en/exercise/2503/view/', 'face pulls (bodyweight doorframe/towel) ombros trapezio triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7bf4e131-d4a3-44c0-8fca-9e10002492e7', 1732, 'en', 'Face pulls with yellow/green band', 'Face pulls with band – standing horizontal pull. Grab the band at face height, pull elbows high and wide towards your face while squeezing shoulder blades together. Trains upper back, rear shoulders and improves posture.', 'costas', '["dorsais"]', '["trapézio"]', '["Elástico"]', 'https://wger.de/media/exercise-images/1732/d13b9adb-968e-4f73-95e6-b16690bcf616.jpg', 'CC-BY-SA 4', '54str', 'https://wger.de/en/exercise/1732/view/', 'face pulls with yellow/green band dorsais trapezio elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d7a418d4-d0cb-4f85-8a7c-1e9d97152cbd', 222, 'en', 'Facepull', 'Attach a rope to a pulley station set at about chest level.

 Step back so you''re supporting the weight with arms completely outstretched and assume a staggered (one foot forward) stance. Bend the knees slightly for a stable base.

 Retract the scapulae (squeeze your partner''s finger with your shoulder blades) and pull the center of the rope slightly up towards the face. A good cue is to think about pulling the ends of the rope apart, not just pulling back.

 As you near your face, externally rotate so your knuckles are facing the ceiling.

 Hold for one second at the top position and slowly lower.', 'ombros', '["trapézio"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'abeworld', 'https://wger.de/en/exercise/222/view/', 'facepull trapezio maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('676e8149-863e-4174-a09a-a327b247c00d', 1217, 'en', 'Finger Pushup', '• Hand Positioning:

 

• Start in a plank position with your hands directly beneath your shoulders.

• Spread your fingers wide apart, placing them firmly on the ground.

 

• Finger Placement:

 

• Gradually lift your palms off the ground, shifting the weight onto your fingers.

• Focus on distributing the load evenly across your fingertips and thumbs.

 

• Body Alignment:

 

• Maintain a straight line from head to heels to engage your core.

• Keep your body in a controlled and stable position throughout the exercise.

 

• Lowering Phase:

 

• Slowly bend your elbows, lowering your chest towards the ground.

• Ensure controlled movement, maintaining stability on your fingertips.

 

• Pushing Up:

 

• Press through your fingertips to straighten your arms, returning to the starting position.

• Emphasize the engagement of your fingers and thumbs throughout the push-up.', 'braços', '["peito"]', '["ombros","abdômen","tríceps"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1217/590e65db-de60-4727-b7eb-55f80af56043.png', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1217/view/', 'finger pushup peito ombros abdomen triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0ecd5f3a-f156-4f1b-b29e-16fb80802a50', 820, 'en', 'Fingerboard 20 mm edge', 'Hang for 10 seconds on a fingerboard with a 20 mm edge', 'braços', '["braços"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'marcelbader', 'https://wger.de/en/exercise/820/view/', 'fingerboard 20 mm edge bracos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5d40cca8-ec48-4711-b97c-f744c5afabbf', 1956, 'en', 'Fire Hydrant Circles', 'Fire Hydrant Circles
Part of: Limber 11
Source: Joe DeFranco
Prescription: 10 forward / 10 backward
Type: dynamic', 'pernas', '["pernas"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1956/view/', 'fire hydrant circles pernas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('03f7fc27-e64f-4417-ab0c-a52adac60fda', 1694, 'en', 'Flat Machine Press', 'Execution 
 

• 
 Start position: 

 

• Elbows bent at roughly 90°, hands just outside your chest.

• Keep wrists straight and aligned with your forearms.

• 
 Pressing phase (concentric): 

 

• Push the handles forward until your arms are almost fully extended — don’t lock out.

• Focus on squeezing your chest at the end of the movement.

• 
 Returning phase (eccentric): 

 

• Slowly bring the handles back toward your chest, feeling the stretch in your pecs .

• Maintain tension — don’t let the weight stack touch down between reps.', 'peito', '["peito"]', '[]', '["Banco"]', NULL, 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1694/view/', 'flat machine press peito banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d6b2ac1d-4363-45e9-8fdb-9fba0a47b27d', 1833, 'en', 'Floor Glider Hamstring Curls', 'Lie on back with heels on floor gliders or towels. Lift hips into a bridge, then slide heels toward glutes while keeping hips elevated. Slowly return to the starting position while maintaining the hip bridge.', 'ombros', '["posteriores de coxa"]', '["panturrilhas","glúteos"]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1833/view/', 'floor glider hamstring curls posteriores de coxa panturrilhas gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6b68043c-a900-41f4-89fb-ea5c8193f216', 1468, 'en', 'Floor Skull Crusher', 'Allowing you to safely load more weight than a regular skull crusher, lie on the floor and rest the weight on the floor in between each repetition.', 'braços', '["tríceps"]', '[]', '["Barra W"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1468/view/', 'floor skull crusher triceps barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fdc550b6-ec58-4023-ba62-b54045e9a10d', 235, 'en', 'Flutter Kicks', '-Laying on the back, lift your straightened legs from the ground at a 45 degree angle.

 -As your Left foot travels downward and nearly touches the floor, your Right foot should seek to reach a 90 degree angle, or as close to one as possible.

 -Bring your R foot down until it nearly touches the floor, and bring your L foot upwards. Maintain leg rigidity throughout the exercise. Your head should stay off the ground, supported by tightened upper abdominals.

 -(L up R down, L down R up, x2) ^v, v^, ^v, v^ = 1 rep

 -Primarily works the Rectus Abdominus, the hip flexors and the lower back. Secondarily works the Obliques. Emphasis placed on the lower quadrant of the abs.', 'core', '["oblíquos","abdômen"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/235/view/', 'flutter kicks obliquos abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('07c5b9f4-2be5-4a3d-b6d2-16235da1ae3a', 237, 'en', 'Fly With Cable', 'cable machine, two steps forward, straight back', 'peito', '["peito"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/122/Incline-cable-flyes-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/237/view/', 'fly with cable peito maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('95d226ad-3bf7-4cd6-aa64-2f26b526d8b6', 238, 'en', 'Fly With Dumbbells', 'Take two dumbbells and lay on a bench, make sure the feet are firmly on the ground and your back is not arched, but has good contact with the bench. The arms are stretched in front of you, about shoulder wide. Bend now the arms a bit and let them down with a half-circle movement to the side. Without changing the angle of the elbow bring them in a fluid movement back up.', 'peito', '["peito"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/238/2fc242d3-5bdd-4f97-99bd-678adb8c96fc.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/238/view/', 'fly with dumbbells peito halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('55d0a5ec-b147-40c3-aa77-314e61c93689', 239, 'en', 'Fly With Dumbbells, Decline Bench', 'The exercise is the same as with a regular bench:

 Take two dumbbells and lay on a bench, make sure the feet are firmly on the ground and your back is not arched, but has good contact with the bench. The arms are stretched in front of you, about shoulder wide. Bend now the arms a bit and let them down with a half-circle movement to the side. Without changing the angle of the elbow bring them in a fluid movement back up.', 'peito', '["peito"]', '[]', '["Banco","Halteres"]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/239/view/', 'fly with dumbbells, decline bench peito banco halteres', '2026-09-10T15:18:12.614Z');
