INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('17947bd2-db2d-4ba6-998c-1bbf31cf228a', 1333, 'en', 'Forearm Curls (underhand grip)', '• Engage the muscles

• Don''t use momentum

• Controlled movement

• Slow movement', 'braços', '["braços"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1333/89f43354-32e3-473a-9bcf-caca51f1a8e3.webp', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1333/view/', 'forearm curls (underhand grip) bracos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0c6764f2-fb86-43f1-bd35-04a35f74d5e4', 2507, 'en', 'Forearm Plank (Core L1)', 'Vasco custom forearm plank - foundational anterior core stability exercise. Teaches full-body tension, breath control, and anti-extension. Prerequisite for all advanced core work.', 'core', '["panturrilhas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Vasco Custom', 'https://wger.de/en/exercise/2507/view/', 'forearm plank (core l1) panturrilhas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('00eae665-ff78-4373-9c43-f44a4a1b43e0', 1238, 'en', 'Frog stand', 'Starting position:
Stand with your feet shoulder-width apart and your toes pointing forward, facing a wall or bench for support if needed.
Bend your knees into a squat position.
Place your hands on the ground in front of you, shoulder-width apart, with your fingers spread wide.
Make sure your elbows are under your shoulders and your body forms a straight line from your head to your heels.
Upward phase:
Push with your feet and hands to lift your body off the ground.
Straighten your legs and arms, keeping your body aligned.
Engage your core and glutes to maintain the position.
If needed, rest your knees on the wall or bench for assistance.', 'core', '["ombros","bíceps","braquial","abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1238/view/', 'frog stand ombros biceps braquial abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a37001e9-b4b3-45db-8ee3-046f40350efa', 1844, 'en', 'Frog Stretch', '• Get on your hands and knees.

• Widen your knees outwards, and drop to your elbows.

• Without moving your elbows or knees, start to rock forwards and backwards, trying to get your bum closer to your feet.', 'pernas', '["glúteos"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1844/view/', 'frog stretch gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f41ac754-45a0-443b-afe5-e624e215229f', 1245, 'en', 'Front Lever', 'The front lever is a figure where the body is kept in a horizontal position parallel to the floor.', 'core', '["dorsais","abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1245/view/', 'front lever dorsais abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b61dff58-6e47-4671-853b-208e7cd0ced4', 1252, 'en', 'Front lever pull-up', 'in the front lever position, with legs extended or easier if collected, pull by bringing the chest closer to the bar.', 'core', '["bíceps","dorsais","abdômen"]', '["ombros"]', '["Barra fixa"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1252/view/', 'front lever pull-up biceps dorsais abdomen ombros barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e79616cb-f5fb-4b10-b99d-09d43774e142', 1214, 'en', 'Front lever tuck', 'The muscles involved in the Front Lever, most subjected to stress, are mainly the extensors such as: the latissimus dorsi, the teres major, the posterior deltoid and the long head of the biceps.', 'costas', '["ombros","bíceps","dorsais"]', '["tríceps"]', '["Barra fixa"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1214/view/', 'front lever tuck ombros biceps dorsais triceps barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('dd9dcfd2-879f-422a-ad06-d2c187c58d1f', 1307, 'en', 'Front Plank', 'The plank is a bodyweight exercise. As a multi-functional movement, the plank not only targets your abdominal muscles but also the spine and hip. Plank strengthens and tightens your entire body, improves your posture and balance, reduces body fat, and can help boost your metabolism.
Exercises such as the “plank pose” help strengthen the stamina of stabilizing abdominal muscles. It can also help relieve back pain associated with a weakening of the function of the stabilizing muscles of the body.
Planks are a versatile exercise that targets many of the most important muscle groups in the body, so they can be applied by anyone to improve endurance and overall body strength.', 'core', '["abdômen"]', '["oblíquos","peito","quadríceps","serrátil"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1307/321d796a-f394-40b8-a1ea-874bbed6ecee.png', 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1307/view/', 'front plank abdomen obliquos peito quadriceps serratil peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('be9dfe16-9fc3-463d-a9cd-7aade27ef571', 1731, 'en', 'Front Raise (Cable)', 'Raise the handle in a slight arc with controlled movement.

 Don’t swing your torso to start the rep.', 'ombros', '["ombros"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1731/view/', 'front raise (cable) ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9c35594c-bbcc-4656-bdcb-376814c90e96', 256, 'en', 'Front Raises', 'To execute the exercise, the lifter stands with their feet shoulder width apart and weights or resistance handles held by their side with a pronated (overhand) grip.

 The movement is to bring the arms up in front of the body to eye level and with only a slight bend in the elbow. This isolates the anterior deltoid muscle (front of the shoulder) and uses the anterior deltoid to lift the weight.

 When lifting it is important to keep the body still so the anterior deltoid is fully utilised; if the weight cannot be lifted by standing still then it is too heavy and a lower weight is needed. It is important to keep a slight bend in the elbow when lifting as keeping the elbow locked will add stress to the elbow joint and could cause injury.

 A neutral grip, similar to that used in the hammer curl, can also be used. With this variation the weight is again raised to eye level, but out to a 45 degree angle from the front of the body. This may be beneficial for those with shoulder injuries, particularly those related to the rotator cuff.', 'ombros', '["ombros"]', '[]', '["Barra","Halteres"]', 'https://wger.de/media/exercise-images/256/b7def5bc-2352-499b-b9e5-fff741003831.png', 'CC-BY-SA 3', 'Manu, wikipedia', 'https://wger.de/en/exercise/256/view/', 'front raises ombros barra halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('68e0dbba-2d1e-4a56-8378-8824c1de3342', 254, 'en', 'Front Raises with Plates', 'The plate front raise is a variation of the dumbbell front raise where the lifter holds a weight plate between two hands, rather than using a dumbbell, barbell, or other weight. It can provide variety in a shoulder-focused muscle-building workout, or as part of an upper body or full-body circuit.

 

• While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip : The arms will remain in this position throughout the exercise. This will be your starting position.

• Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. As you inhale, slowly lower the plate back down to the starting position.

• Repeat for the recommended amount of repetitions.', 'ombros', '["ombros","trapézio"]', '[]', '[]', NULL, 'CC-BY-SA 3', 'Marius', 'https://wger.de/en/exercise/254/view/', 'front raises with plates ombros trapezio', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d5e5c5a1-69af-42b0-9106-dc8284e7262a', 2527, 'en', 'Front Split Stretch', '• Start kneeling.

• Extend one leg out forwards, fully straightened. Follow with your hips so your back leg begins to unfold.

• Carefully lower yourself into the stretch. Do not go beyond your limit.

• Hold for the required time.', 'pernas', '["posteriores de coxa","quadríceps"]', '["panturrilhas"]', '["Colchonete"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2527/view/', 'front split stretch posteriores de coxa quadriceps panturrilhas colchonete', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d677de4c-5bd9-412a-91f1-857116a666a2', 257, 'en', 'Front Squats', 'This variation of the squat trains the hamstrings and gluteus maximus. It also works the back extensors and abductors.', 'pernas', '["glúteos"]', '["abdômen"]', '["Barra"]', 'https://wger.de/media/exercise-images/191/Front-squat-1-857x1024.png', 'CC-BY-SA 3', 'sistab2', 'https://wger.de/en/exercise/257/view/', 'front squats gluteos abdomen barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e5a62151-5350-4c86-8a19-3e9ca7bf0f38', 260, 'en', 'Full Sit Outs', '(A) Get in high plank position on your hands and toes.(B) Shift your weight to your left hand as you turn your body to the right; bend your right leg behind you and extend your right arm up. Return to the center and repeat on the opposite side. Continue, alternating sides. Make it easier: Don’t raise your arm after you bend your leg behind you. Make it harder: Balance with your arm and leg extended for two counts.', 'core', '["glúteos","oblíquos","abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'http://www.realsimple.com/health/fitness-exercise/', 'https://wger.de/en/exercise/260/view/', 'full sit outs gluteos obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ceb0c2d0-06ac-4a49-89e7-8d7b1c1e5672', 265, 'en', 'Glute Bridge', 'Lie on you back with your hips and knees flexed, feet on the ground. From this position, raise your butt off of the ground to a height where your body makes a straight line from your knees to your shoulders. To make the exercise more intense, you can add weight by letting a barbell rest on your hips as you complete the motion, or you can put your feet on a slightly higher surface such as a step or a bench.', 'pernas', '["glúteos"]', '["posteriores de coxa"]', '[]', 'https://wger.de/media/exercise-images/265/7528acb4-b2cc-4b75-b6ae-d514cbd4f78b.png', 'CC-BY-SA 4', 'tdprice12', 'https://wger.de/en/exercise/265/view/', 'glute bridge gluteos posteriores de coxa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8c4a9c16-294b-40e5-ba6d-50ae523704ba', 1686, 'en', 'Glute Bridge Single-Arm Press', 'With one dumbbell in hand, perform a glute bridge. Now hold the dumbbell above your chest, this is the rep starting position. Lower the dumbbell so that your elbow touches the floor or is roughly 45 degrees below your shoulder if using a bench. Push the dumbbell back into the starting position.', 'braços', '["peito"]', '["ombros","bíceps","posteriores de coxa","glúteos","tríceps"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'meldun', 'https://wger.de/en/exercise/1686/view/', 'glute bridge single-arm press peito ombros biceps posteriores de coxa gluteos triceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ce21d3a2-cdc5-410c-9970-c25029ca3769', 1528, 'en', 'Glute Drive', 'Lie down on the back pad and strap yourself in with the waistband. Position yout feet shoulder-length apart. They should be slightly splayed.', 'pernas', '["glúteos"]', '["posteriores de coxa","quadríceps"]', '[]', NULL, 'CC-BY-SA 4', 'schweezer', 'https://wger.de/en/exercise/1528/view/', 'glute drive gluteos posteriores de coxa quadriceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('66ed6788-a1d8-49a2-af4d-397107fbf5fb', 1723, 'en', 'Glute Kickback (Machine)', 'Drive through your heel, not your toes, to hit the glute.

 Don’t hyperextend your lower back at the top.', 'pernas', '["glúteos"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1723/view/', 'glute kickback (machine) gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b7a5aa6b-4997-42a2-87b3-243a74b26234', 2546, 'en', 'Glute sidekick(machine)', 'This exercise uses the cable kickback machine but latterally', 'pernas', '["glúteos"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'ckzi', 'https://wger.de/en/exercise/2546/view/', 'glute sidekick(machine) gluteos maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('537b41a8-870b-4b45-b8a5-e9672c6a359b', 2478, 'en', 'Glute-Ham Raise', 'Kneel on a glute-ham developer or have a partner hold your ankles. Keeping hips straight, lower your torso toward the floor under control, then curl back up by contracting the hamstrings and glutes.', 'pernas', '["posteriores de coxa"]', '["glúteos"]', '["Banco"]', NULL, 'CC0', 'personal use', 'https://wger.de/en/exercise/2478/view/', 'glute-ham raise posteriores de coxa gluteos banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6d04d788-80e7-4aa8-a7d9-b5d9cb2e0e40', 2565, 'en', 'Goblet Squat', 'Goblet squat emphasizing controlled depth, stable trunk position, and comfortable knee tracking.', 'pernas', '["quadríceps"]', '["glúteos"]', '["Halteres"]', NULL, 'CC-BY-SA 3', '', 'https://wger.de/en/exercise/2565/view/', 'goblet squat quadriceps gluteos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('77a56810-d050-4083-9501-d648f773376a', 1392, 'en', 'Good Morning', 'Stand with your feet more than shoulder-width apart (wider stance) and place your hands on your hips. Hinge at your hips and lower your upper body towards the ground while keeping your back straight then come back up.', 'pernas', '["posteriores de coxa"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1392/a02c9c7d-f42d-43e0-9946-1b99b014daee.png', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1392/view/', 'good morning posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7edb6156-70a7-4d79-9e78-f5c540897ce2', 2545, 'en', 'Grip Trainer Crush', 'Hand gripper: full squeeze, 2s hold, slow release. Use the 20-40kg gripper for reps; the 45kg for max holds.', 'braços', '["braços"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2545/view/', 'grip trainer crush bracos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f462df26-3264-48c2-b5aa-2374d0670c24', 1414, 'en', 'Hack Squats', 'Hack squats target the lower body and are performed on a hack squat machine or with a barbell. For the machine variation, position yourself on the platform with your shoulders under the pads and feet slightly forward. Push through your heels to lift the weight, then bend your knees to lower the platform in a controlled motion until your thighs are parallel to the ground. Push back up to the starting position. For the barbell variation, hold the bar behind your legs with your arms extended and perform a squat-like motion.', 'pernas', '["quadríceps"]', '["posteriores de coxa","panturrilhas","glúteos"]', '[]', NULL, 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1414/view/', 'hack squats quadriceps posteriores de coxa panturrilhas gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('04365177-e078-489b-983a-8ac61b7346f1', 275, 'en', 'Hammercurls on Cable', 'Take a cable in your hands (palms parallel, point to each other), the body is straight. Bend the arms and bring the weight up with a fast movement. Without any pause bring it back down with a slow, controlled movement, but don''t stretch completely your arms.

 Don''t swing your body during the exercise, the biceps should do all the work here. The elbows are at your side and don''t move.', 'braços', '["bíceps"]', '["braquial"]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/138/Hammer-curls-with-rope-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/275/view/', 'hammercurls on cable biceps braquial maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('920692b2-0842-428a-b925-ba0daf6b41db', 1831, 'en', 'Hammerstrength Decline Chest Press', '• Sit upright in a hammerstrength decline chest press machine while squeezing your shoulder blades together and placing your heels firmly on the ground underneath your knees.

• The back pad should be contact with your head, shoulders, and butt at all times.

• Grab ahold of the handles with an overhand grip just outside shoulder-width apart just below your chest.

• Keeping your core braced by breathing into your stomach and flexing the abdominal muscles, push through your palms to extend your elbows while keeping them at a 45 degree angle from your torso.

• Once your arms are fully extended, return to the starting position.', 'peito', '["peito"]', '["ombros","tríceps"]', '[]', 'https://wger.de/media/exercise-images/1831/2d9d509f-707b-4132-961e-91a2459ca198.jpg', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1831/view/', 'hammerstrength decline chest press peito ombros triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('638756b5-a957-48f4-93ca-8994cead818f', 1398, 'en', 'Hamstring Chokes', 'Sit on the ground and bend one leg, bringing your knee toward you. Place your hand behind your hamstring and gently pull your leg toward your chest, feeling a stretch in the back of your thigh. Straighten your leg, extending up toward the ceiling.', 'pernas', '["posteriores de coxa"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1398/view/', 'hamstring chokes posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fae5378b-db4b-4ab5-9207-07a6abab917f', 1855, 'en', 'Hamstring Foam roller', 'Move your hamstrings slowly over the foam roller', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1855/a6597ed8-1613-4458-ba56-4b63bc946a35.webp', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1855/view/', 'hamstring foam roller pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('66aef559-02e8-4f35-91f6-600f103e9cbf', 1387, 'en', 'Hamstring Kicks', 'Stand with your feet hip-width apart and extend one arm in front of you. Swing that leg up in front of you and back down while keeping your leg as straight as possible and your toes pointed up.Repeat with the other leg.', 'pernas', '["posteriores de coxa"]', '["glúteos"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1387/a2cf7eda-5540-4105-b30e-1c2f2679a6c7.png', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1387/view/', 'hamstring kicks posteriores de coxa gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4e238360-a4c1-4509-85c1-f96d01e69cf9', 279, 'en', 'Hand Grip', 'chrome Hand Flex Grip to build up forearms muscles', 'braços', '["braços"]', '[]', '[]', 'https://wger.de/media/exercise-images/279/36605bc8-d7e1-43e1-87c1-b9cb50db62b2.webp', 'CC-BY-SA 4', 'vince63', 'https://wger.de/en/exercise/279/view/', 'hand grip bracos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('35008ce6-74ca-40db-b965-44a1eccfa061', 1516, 'en', 'Handstand', 'Handstand free standing by pressing arms into the ground and contracting core and glutes', 'ombros', '["ombros"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Fittness69', 'https://wger.de/en/exercise/1516/view/', 'handstand ombros', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7704e810-c05d-47cc-a384-265e0231a497', 282, 'en', 'Handstand Pushup', 'The handstand push-up (press-up) - also called the vertical push-up (press-up) or the inverted push-up (press-up) also called commandos- is a type of push-up exercise where the body is positioned in a handstand. For a true handstand, the exercise is performed free-standing, held in the air. To prepare the strength until one has built adequate balance, the feet are often placed against a wall, held by a partner, or secured in some other way from falling. Handstand pushups require significant strength, as well as balance and control if performed free-standing.', 'ombros', '["ombros","tríceps"]', '["trapézio"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/282/f6121ac9-330e-4ed7-8219-91ce246bf871.png', 'CC0', 'BFad07', 'https://wger.de/en/exercise/282/view/', 'handstand pushup ombros triceps trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9b993e99-8701-43f0-84d6-689123183880', 283, 'en', 'Hanging Leg Raises', 'Hanging from bar or straps, bring legs up with knees extended or flexed', 'core', '["abdômen"]', '[]', '["Barra fixa"]', NULL, 'CC-BY-SA 3', 'robhoyt', 'https://wger.de/en/exercise/283/view/', 'hanging leg raises abdomen barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('36eaf240-db34-4d83-bba9-94d0e989c9e2', 1018, 'en', 'Head tilts', 'Starting position:

 Sit or stand with your back straight.

 Steps:

 

• Tilt your head to one side and hold for a bit.2.Return your head to neutral position and hold for a bit.

• Tilt your head to the other side and hold for a bit.

• Return your head to neutral position yet again and hold for a bit.

• Repeat.', 'costas', '["costas"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1018/5bbd3879-b6fc-4aaa-9e8e-33ae9a688112.png', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1018/view/', 'head tilts costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('cfe3f20e-d078-4e6c-91fc-37da62f5ac0a', 1411, 'en', 'Heel Touches', '• 
 Starting Position: 

 

• Lie on your back on an exercise mat.

• Bend your knees, keeping your feet flat on the floor and hip-width apart.

• Place your arms along your sides, palms facing inward, just off the floor.

• 
 Engage Core: 

 

• Lift your head, shoulders, and upper back slightly off the ground.

• Keep your neck neutral and chin slightly tucked.

• 
 Perform the Movement: 

 

• Side-bend to the right, reaching your right hand toward your right heel.

• Return to the center, then side-bend to the left, reaching your left hand toward your left heel.

• Continue alternating sides in a controlled manner.

• 
 Breathing: 

 

• Exhale as you reach toward your heel and inhale as you return to the center.', 'core', '["oblíquos"]', '["abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1411/view/', 'heel touches obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e781dae5-90b8-4105-8aa6-82d278ac5ff5', 1303, 'en', 'Helms Row', 'Setup: Place your chest on the end of a bench, using a towel or anything soft to keep your chest protected. You want your chest to be in contact with the bench around the nipple line. Your back should be almost parallel to the floor
Execution: When you’re starting the exercise, focus on pulling your elbows back until you feel maximum tightness in the lats.
If you want to get some trap activation with the exercise, relax your shoulder blades when the weights are hanging down and then retract them as you start the rep.', 'costas', '["dorsais"]', '["trapézio"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1303/view/', 'helms row dorsais trapezio halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8381f40c-3168-4d98-af60-6a89800dd308', 284, 'en', 'Hercules Pillars', 'Grab two cables stand in the middle so both have tension and hold', 'braços', '["bíceps","braquial","tríceps"]', '["ombros"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 3', 'GrosseHund', 'https://wger.de/en/exercise/284/view/', 'hercules pillars biceps braquial triceps ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3edbb63e-f326-4bd0-8af3-2d5deabb864f', 285, 'en', 'High Knee Jumps', '• Start with legs slightly wider than shoulder width

• Drop into a bodyweight squat

• As you hit the bottom of the squat, explode upwards into a jump while simultaneously tucking your knees into your chest midflight. Remain tucked until the apex of your jump.

• Land on both feet, making sure your knees are not locked so as to avoid excessive strain upon your joints. Collect yourself into the next rep as quickly but under control as possible.', 'cardio', '["posteriores de coxa","panturrilhas","quadríceps","sóleo"]', '["oblíquos","abdômen","serrátil"]', '[]', 'https://wger.de/media/exercise-images/285/4141e8b2-d9f2-4597-8ef0-7768127fd0ec.png', 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/285/view/', 'high knee jumps posteriores de coxa panturrilhas quadriceps soleo obliquos abdomen serratil', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('32942c8c-0572-4d8b-9aec-48cb026fda1f', 1318, 'en', 'High Knee Skips HD', 'You can use this exercise both as a dynamic warm-up before training and add it to your cardio training routine to burn fat.
High knee skips are a plyometric exercise. Plyometrics are explosive aerobic moves that increase speed, quickness, and power and they work your whole body.
High knee skips target the oblique, leg muscles, hip muscles and hip flexors and also work on the thighs, knee tendons, quadriceps and shoulders.
Jumps are beneficial to your health because they combine cardiovascular conditioning with strength work. Since jumps elevate your heart rate, they can also improve your cardiovascular fitness.', 'cardio', '["oblíquos","abdômen"]', '["bíceps","glúteos","quadríceps","tríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1318/view/', 'high knee skips hd obliquos abdomen biceps gluteos quadriceps triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b526b17b-408d-4da2-8940-ceaf9dae9d93', 289, 'en', 'High Pull', 'Use a light barbell, perform explosive lift up starting from underneath knee cap level. Lift/raise explosively using hips, at shoulder level. Tempo: 2111', 'ombros', '["ombros"]', '["glúteos"]', '[]', NULL, 'CC-BY-SA 3', 'Mahoney', 'https://wger.de/en/exercise/289/view/', 'high pull ombros gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f80468f2-7c5d-45c5-9470-46a88c1a75c2', 1492, 'en', 'High Row', 'Kneeling down on one leg and pulling cable down while driving elbow into the lats.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'aahuja', 'https://wger.de/en/exercise/1492/view/', 'high row dorsais maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4ef75e13-c058-4410-91c0-2f2d2df98130', 1298, 'en', 'High-Cable Cross Tricep Extention - NB', 'The high-cable cross tricep extension is an isolation exercise for targeting the triceps,
particularly the long head. It utilizes cables and handles grasped with opposite hands, allowing for a unique pressing motion that can be effective for building tricep strength. Unlike exercises that use a straight bar or rope, this variation can be more comfortable on your wrists and elbows', 'braços', '["tríceps"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1298/ec4b83ec-5a8f-4303-9050-99ec4389bc2a.png', 'CC-BY-SA 4', 'JackSparrow', 'https://wger.de/en/exercise/1298/view/', 'high-cable cross tricep extention - nb triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('47b244f0-ebc6-4498-9d9f-7e7bff47322e', 1882, 'en', 'High-Cable Lateral Raise', 'Stand next to a cable machine with the pulley set to waist height.

 Grab the opposite-side handle with the hand farthest from the
pulley, keeping your palm facing in.

 Keep your core engaged, chest lifted, and shoulders relaxed. Maintain a slight bend in the elbow throughout the lift.

 Lift your arm out to the side until your elbow reaches shoulder height, keeping your wrist aligned with your elbow.

 Briefly pause at the top, then slowly lower the handle back to your side with control. Repeat for the desired reps.', 'ombros', '["ombros"]', '["dorsais","serrátil"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Deflation', 'https://wger.de/en/exercise/1882/view/', 'high-cable lateral raise ombros dorsais serratil maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ecba2395-f364-4e5f-a34c-04f178c8b822', 1508, 'en', 'High-Incline Smith Machine Press', 'Set the bench to a 45-60° incline. Touch the upper chest with the bar.', 'peito', '["ombros","peito","tríceps"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1508/view/', 'high-incline smith machine press ombros peito triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e87b76b8-2960-4225-9146-47f78bf8c630', 1137, 'en', 'High-pulley pullover', 'Stand facing the machine, feet slightly apart, gripping the bar with an overhand grip, arms extended, hands shoulder-width apart.

 

• Keeping your back fixed and your abdominal muscles contracted, inhale and bring the bar down to your thighs while keeping your arms extended (or your elbows slightly bent).
Exhale at the end of the movement.', 'costas', '["dorsais","serrátil"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1137/42f22229-c0a0-4bfc-aca6-66fe5e1ab10d.PNG', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1137/view/', 'high-pulley pullover dorsais serratil maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('476c1d96-6590-4f86-98f0-3f12808fab53', 1080, 'en', 'Hindu Pushups', 'Exercise to strengthen the shoulders and pectorals. Its name is due to the fact that it begins in the Yoga position "Dog Facing Down", passing to "Cobra" but without resting the legs or torso on the ground to finally end with a normal flexion. The exercise can also be performed backwards (back to the starting position). As a variation, after doing the push-up, the hip can be raised to return to downward facing dog.', 'ombros', '["ombros","peito"]', '["tríceps"]', '[]', 'https://wger.de/media/exercise-images/1080/c4bf7ba1-6058-4d14-928f-7187885d5d57.webp', 'CC-BY-SA 4', 'Imobard', 'https://wger.de/en/exercise/1080/view/', 'hindu pushups ombros peito triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1d610575-eed0-42cf-8737-29788a372af6', 291, 'en', 'Hindu Squats', 'Start with your feet shoulder width apart and arms slightly behind your back.

 As you descend towards the floor, raise your heels off the ground, while keeping your back as vertical as possible.

 Upon attaining the bottom position, touch the hands to the heels.

 Then stand up ending with the heels on the ground, arms extended in front of the chest then rowing into the start position.', 'pernas', '["quadríceps"]', '["glúteos"]', '[]', NULL, 'CC-BY-SA 4', 'Vilhelmo', 'https://wger.de/en/exercise/291/view/', 'hindu squats quadriceps gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('553fb643-32f0-447f-aecb-cdf75398d742', 2447, 'en', 'Hip Airplane', 'Stand on one leg and lean your upper body slightly forward while keeping your back straight. Extend the free leg behind you so that your torso and leg form roughly one line. Slowly open your hip to the side by rotating your pelvis and upper body in a controlled way. Then close the hip again and return to the starting position.

 The movement should mainly come from the hip. Keep your standing foot stable and avoid letting your knee collapse inward.', 'pernas', '["glúteos"]', '["posteriores de coxa","panturrilhas","sóleo"]', '["Kettlebell"]', NULL, 'CC-BY-SA 4', 'TobiasFalk', 'https://wger.de/en/exercise/2447/view/', 'hip airplane gluteos posteriores de coxa panturrilhas soleo kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6b127132-cc0b-4b40-ac8c-177a28ccb6e2', 1906, 'en', 'Hip Bridge', 'Get into bridge position, balance yourself on heels and start extending legs unilaterally.

 Keep hip extended as much as possible.', 'pernas', '["glúteos","abdômen"]', '["oblíquos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1906/view/', 'hip bridge gluteos abdomen obliquos peso corporal', '2026-09-10T15:18:12.614Z');
