INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e4c9bfde-cf06-4c24-9c56-c0bbc13c49b5', 1578, 'en', 'Hip hinge', 'Hip Hinge Exercise DescriptionThe hip hinge is a fundamental movement pattern that involves bending at the hips while keeping the spine neutral. It is commonly used in exercises like deadlifts, kettlebell swings, and good mornings. To perform a hip hinge: Starting Position: Stand with your feet hip-width apart and a slight bend in your knees. Hinge at the Hips: Push your hips back while maintaining a straight back. Your torso should lean forward, and your chest should stay up. Lowering Phase: Continue to hinge until your torso is nearly parallel to the ground, or until you feel a stretch in your hamstrings. Return to Standing: Drive through your heels and thrust your hips forward to return to the starting position.', 'pernas', '["posteriores de coxa","glúteos"]', '["panturrilhas","quadríceps","abdômen"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'mountain.potato', 'https://wger.de/en/exercise/1578/view/', 'hip hinge posteriores de coxa gluteos panturrilhas quadriceps abdomen barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('541941e0-0fa5-4474-a382-9baf04948f8d', 292, 'en', 'Hip Raise, Lying', 'Lying down on your back, with your feet flat on the floor. Raise your hips up evenly as high as you can and hold for as long as you can.', 'costas', '["glúteos"]', '["posteriores de coxa"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'James Mackay', 'https://wger.de/en/exercise/292/view/', 'hip raise, lying gluteos posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('19a289c0-33af-4055-bb34-3570c2975d3d', 294, 'en', 'Hip Thrust', 'The bar should go directly on your upper thigh, directly below your crotch. Your feet should be directly under your knees. Push your hips up so that you form a straight line from your knees to your shoulders. Use a pad for comfort.', 'pernas', '["glúteos"]', '[]', '["Barra","Banco"]', NULL, 'CC-BY-SA 4', 'Bret Contreras', 'https://wger.de/en/exercise/294/view/', 'hip thrust gluteos barra banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a4f78033-90d7-45a2-96fa-509b41281ea3', 2618, 'en', 'Hip-Out and Hip-In Lateral Steps', 'Overview of Hip-Out and Hip-In Lateral Steps
 Hip-out and hip-in lateral steps are effective exercises designed to strengthen the hip abductors and enhance lateral stability. These movements are beneficial for improving coordination and overall hip function.

Exercise Descriptions
Hip-Out Steps
 

• Movement: Step out to the side with one leg, keeping the other leg stable.

• Target Muscles: Primarily engages the hip abductors, including the gluteus medius and minimus.

• Benefits: Increases lateral stability and strength in the hip area.

Hip-In Steps
 

• Movement: Bring the leg back in toward the center after stepping out.

• Target Muscles: Continues to engage the hip abductors while also activating the adductors.

• Benefits: Enhances coordination and control of the hip joint.

Key Benefits of Lateral Steps
 | Benefit | Description |
|---|---|
| Strengthening Hip Abductors | Improves muscle strength around the hip joint. |
| Enhancing Stability | Increases lateral stability, reducing the risk of falls. |
| Improving Coordination | Develops better control and movement patterns in the hips. |

 Incorporating hip-out and hip-in lateral steps into a regular exercise routine can lead to improved hip strength and stability, which is essential for various physical activities and daily movements.', 'pernas', '["pernas"]', '[]', '["Elástico"]', 'https://wger.de/media/exercise-images/2618/e0a5c993-37a8-4271-9056-7cdf1ad677be.jpg', 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/2618/view/', 'hip-out and hip-in lateral steps pernas elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2b165c5c-403f-43e5-b28d-83c8b914505b', 2510, 'en', 'Hollow Body Hold (Core L1)', 'Vasco custom hollow body hold - foundational anti-extension core stability. Teaches global anterior chain tension, breath control under load, and positional awareness for gymnastics/calisthenics.', 'cardio', '["panturrilhas","glúteos","oblíquos"]', '["ombros","bíceps","braquial","dorsais"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Vasco Custom', 'https://wger.de/en/exercise/2510/view/', 'hollow body hold (core l1) panturrilhas gluteos obliquos ombros biceps braquial dorsais peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d059c63d-0a81-48a3-912a-44070c0def2e', 297, 'en', 'Hollow Hold', 'Get on a mat and lie on your back. Contract your abs, stretch your arms and legs and raise them (your head and shoulders are also be raised). Make sure your lower back remains in contact with the mat.', 'core', '["oblíquos","abdômen"]', '[]', '["Colchonete"]', 'https://wger.de/media/exercise-images/297/b10d3341-baa8-49ab-b462-5b3529389aac.png', 'CC0', 'Behrooz', 'https://wger.de/en/exercise/297/view/', 'hollow hold obliquos abdomen colchonete', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ca4c8872-e53c-47ca-bc33-448b9ba9360f', 1712, 'en', 'Horizontal Shoulder Flexion Stretch', '• Raise your arm out to the side, placing your hand on a wall or doorway beside you at shoulder height

• Turn your body away from your arm to stretch the chest, as far as is comfortable', 'ombros', '["peito"]', '["ombros"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1712/view/', 'horizontal shoulder flexion stretch peito ombros peso corporal', '2026-09-10T15:18:12.614Z');
