INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('36411665-4a87-4ab5-b5d3-e4eaa2802a62', 1846, 'en', 'Horse Stance (Side Splits)', '• Stand as for a squat, with your feet wide and your toes pointed slightly outwards.

• Gently squat into a deep, wide squat - your hips should be below your knees.

• Hold for 3 to 5 seconds.

• Come up under control, and repeat as needed.', 'pernas', '["glúteos"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1846/view/', 'horse stance (side splits) gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ebe7d74b-78a8-4757-9310-6fb22b23aa58', 1487, 'en', 'Hyper Y W Combo', '• Use a glute-ham raise or a
stability ball for this exercise and a light weight plate in each hand.

• Raise your torso to form a straight line with your legs and raise the
arms outward slightly beyond a 90-degree angle into a W position to hit
the rotator cuff muscles, and then lower back to the starting position.

• Then raise up again with arms
in a Y position to activate the lower traps.', 'costas', '["dorsais"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1487/view/', 'hyper y w combo dorsais', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('37f6bd56-815a-4975-99af-05e749fae4b2', 301, 'en', 'Hyperextensions', 'Lie on the hyperextension pillow with your navel at the front edge, allowing your upper body to hang freely. Tighten all your back muscles and raise your torso until you''re horizontal, but no higher. Lower yourself slowly, maintaining a steady flow of muscles.', 'costas', '["trapézio"]', '[]', '[]', 'https://wger.de/media/exercise-images/301/2d5c2f99-b8ff-4095-b515-4c2a85afde70.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/301/view/', 'hyperextensions trapezio', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('662b9911-fa55-4564-b830-fdb6a046b162', 1248, 'en', 'Ice cream maker', 'From the final phase of a pull-up, we push ourselves back with our shoulders until we reach the front lever position. From there, we pull ourselves back up to the starting position.', 'core', '["dorsais"]', '["abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1248/view/', 'ice cream maker dorsais abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('275fb49f-975c-4d6e-9d63-2c86ed740f40', 538, 'en', 'Incline Bench Press - Barbell', 'To do slowly, tempo is 4010', 'peito', '["peito"]', '["ombros","tríceps"]', '["Barra","Banco inclinado"]', 'https://wger.de/media/exercise-images/41/Incline-bench-press-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/538/view/', 'incline bench press - barbell peito ombros triceps barra banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4e941b0d-4b2f-4393-89cf-6a5e9b69252e', 1138, 'en', 'Incline bench pulldown', 'Lying face down on the incline bench facing the cable machine, perform the pulldown.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1138/6c35fd79-ef35-4cf3-abf5-9c969457b8d4.PNG', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1138/view/', 'incline bench pulldown dorsais maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('70c99a4e-3340-4993-a7f1-2d2709dada1a', 828, 'en', 'Incline Bench Reverse Fly', 'The incline dumbbell reverse fly is an upper-body exercise targeting the posterior or rear deltoids, as well as the postural muscles of the upper back. Because it targets such small muscles, this exercise is usually performed with light weight for high reps, such as 10-15 reps per set or more.', 'costas', '["ombros","trapézio"]', '[]', '["Halteres","Banco inclinado"]', 'https://wger.de/media/exercise-images/828/2e959dab-f39b-4c7c-9063-eb43064ab5eb.png', 'CC-BY-SA 4', 'cshep442', 'https://wger.de/en/exercise/828/view/', 'incline bench reverse fly ombros trapezio halteres banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('51a2d520-b510-4b6e-bd65-9fc40365e8de', 1283, 'en', 'Incline Chest-Supported Dumbbell Row', 'Set up an adjustable bench at a 45-degree angle.
Lay on your stomach with your head hanging just above the edge of the bench.
Grab a dumbbell in each hand and set up with a good posture – core and lats engaged and shoulders neutral.
Row the dumbbells toward the top of the stomach and squeeze the back at the top of the rep.
Finally, lower the dumbbells back to the starting position and repeat until all reps are completed.', 'costas', '["bíceps","dorsais","trapézio"]', '[]', '["Banco","Halteres"]', 'https://wger.de/media/exercise-images/1283/e7262f70-7512-408a-8d00-4c499ef632fc.jpg', 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1283/view/', 'incline chest-supported dumbbell row biceps dorsais trapezio banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fca05168-7212-42ec-8927-efb1e8dd0971', 1467, 'en', 'Incline Close Grip Barbell Bench Press', 'Narrower grip than regular bench press, just outside shoulder width.', 'braços', '["tríceps"]', '["ombros","peito"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1467/view/', 'incline close grip barbell bench press triceps ombros peito barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7de7b8a8-313d-465f-bb22-8527ae45110a', 171, 'en', 'Incline Crunches', 'Lay down on your back on a inclined bench, feet are on one end of the bench. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back.', 'core', '["abdômen"]', '[]', '["Banco inclinado"]', 'https://wger.de/media/exercise-images/56/Decline-crunch-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/171/view/', 'incline crunches abdomen banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('16bd91ca-a9fe-47fc-b3a8-a9d70549e929', 1879, 'en', 'Incline DB Y-Raise', '• Set
an incline bench to a 45-degree angle and sit facing the bench, chest
against the pad, with a dumbbell in each hand, palms facing each other.

• Position your feet firmly on the ground for stability and let your arms hang down naturally with a slight bend in your elbows.

• Engage your core and keep your back straight throughout the movement.

• Raise your arms forward and out to form a Y shape, keeping the movement controlled and your elbows slightly bent.

• Lift until your arms are roughly parallel to the floor and in line with your ears.

• Pause
briefly at the top of the movement to engage your shoulder muscles
fully, then slowly lower your arms back down to the starting position.

• Ensure
the movement is slow and controlled during both the ascent and descent
to maximize engagement of the deltoids and supporting muscles.

• Repeat for the desired number of repetitions, maintaining proper form throughout.', 'ombros', '["ombros"]', '["trapézio"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Deflation', 'https://wger.de/en/exercise/1879/view/', 'incline db y-raise ombros trapezio halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('55ff32e6-24ab-4303-9b50-176d60d48796', 308, 'en', 'Incline Dumbbell Fly', 'Use inclined bench. Hold dumbbells straight out to your sides, elbows slightly bent. Bring arms together above you, keeping angle of elbows fixed.', 'peito', '["peito"]', '[]', '["Halteres","Banco inclinado"]', NULL, 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/308/view/', 'incline dumbbell fly peito halteres banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('27eb3d4a-8677-4c1f-bf34-251e2b4741cb', 310, 'en', 'Incline Dumbbell Row', '• Using a neutral grip, lean into an incline bench.

• Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.

• Retract the shoulder blades and flex the elbows to row the dumbbells to your side.

• Pause at the top of the motion, and then return to the starting position.', 'costas', '[]', '["dorsais"]', '["Halteres","Banco inclinado"]', NULL, 'CC-BY-SA 4', 'cal.zabel', 'https://wger.de/en/exercise/310/view/', 'incline dumbbell row dorsais halteres banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f89b3662-f911-4aab-9402-cfa6d47cea2b', 1441, 'en', 'Incline OHP DB', '• Sit on a bench with 45° incline

• Ellbows 45° out

• Move dumbbells down until upper arms are parallel to shoulders

• Move dumbbells up, meeting overhead', 'ombros', '["ombros"]', '["tríceps"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1441/view/', 'incline ohp db ombros triceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('aae91ecf-ffa4-4730-812c-cb00e423f91c', 312, 'en', 'Incline Plank With Alternate Floor Touch', 'Perform the plank with legs elevated, feet on a gymball. Once stabilised, slowly move one foot sideways off the ball, then make it touch the floor, then come back to starting position. Alternate with the other foot.

 This is a core exercise.', 'core', '["abdômen"]', '["oblíquos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 3', 'Mahoney', 'https://wger.de/en/exercise/312/view/', 'incline plank with alternate floor touch abdomen obliquos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2cc5644d-a8d7-49f5-8978-db0f2184864e', 2499, 'en', 'Incline Push-ups (Vasco L2)', 'Vasco custom incline push-up progression for beginner home training. Bridges wall push-ups to floor push-ups. Part of Monday Push day.', 'peito', '["peito"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Vasco Custom', 'https://wger.de/en/exercise/2499/view/', 'incline push-ups (vasco l2) peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('743690d3-dbfb-417a-a049-8b77fd5df31b', 1716, 'en', 'Incline Shoulder Press Up', '• Place your hands on the bench in a press up position

• Push your chest away from the bench to separate your shoulder blades

• Keeping your elbows straight , lower your chest towards the bench so your shoulder blades move closer together

• Push your chest away from the bench again', 'peito', '["ombros","peito"]', '[]', '["Banco"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1716/view/', 'incline shoulder press up ombros peito banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('76a2f8a6-374b-42c8-b8ac-e8d64612f046', 911, 'en', 'Incline Skull Crush', 'Siting in a 45 Degree Angle, using DB to do Incline Skull Crush', 'braços', '["tríceps"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/911/view/', 'incline skull crush triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('88afb956-8d4a-45b3-8c7c-c23719316bfe', 1693, 'en', 'Incline Static Hold', 'Execution 
 

• 
 Hold Position: 

 

• Lower the dumbbells a few inches above your chest — about the midpoint of a normal incline press.

• This is where your upper chest is under maximum tension.

• 
 Static Hold: 

 

• Hold the position for 20–45 seconds while keeping the chest tight.

• Breathe slowly but stay tense — do not relax your chest or shoulders .

• 
 End the set: 

 

• After the hold, carefully bring the dumbbells down and rest.', 'peito', '["peito"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1693/view/', 'incline static hold peito halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1639425c-7dc6-4776-b039-47ef14a328ee', 1927, 'en', 'Inverted Lat Pull Down', 'The Inverted Lat Pull Down (most commonly known as the Reverse Grip Lat Pull Down ) is a variation of the standard exercise that uses an underhand (supinated) grip with hands at shoulder-width. This position shifts more emphasis to the lower lats and increases biceps involvement, often allowing for a greater range of motion and a deeper squeeze at the bottom of the movement.', 'costas', '["dorsais","trapézio"]', '["bíceps","braquial","oblíquos","abdômen","serrátil"]', '["Barra fixa"]', NULL, 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1927/view/', 'inverted lat pull down dorsais trapezio biceps braquial obliquos abdomen serratil barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8d56eb18-b000-41ff-8b31-c74df3a4b34b', 1198, 'en', 'Inverted Rows', 'Maintain a straight body, retract your shoulder blades, and pull your
chest to the bar for an effective back and upper body workout.', 'peito', '["bíceps","dorsais"]', '["peito","abdômen","trapézio"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1198/864906ac-4ac7-4e52-a886-c6bb97950a9f.jpg', 'CC-BY-SA 4', 'Gavru', 'https://wger.de/en/exercise/1198/view/', 'inverted rows biceps dorsais peito abdomen trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7a1e0cd7-0076-4d4d-b05f-1d114235f199', 1914, 'en', 'Isometria alle parallele', 'The parallel bars isometric hold is a static upper-body exercise performed on dip bars (parallel bars). Instead of moving up and down like in a traditional dip, you hold a fixed position under tension.', 'ombros', '["peito","trapézio"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1914/view/', 'isometria alle parallele peito trapezio', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5fd01c23-6c54-40cb-9a67-87c7a325baee', 1282, 'en', 'Isometria trazioni impugnatura inversa', 'Trazioni in isometria con impugnatura inversa', 'costas', '["dorsais"]', '["bíceps","trapézio"]', '["Barra fixa"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1282/view/', 'isometria trazioni impugnatura inversa dorsais biceps trapezio barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('06cb77ba-e56d-4422-bc14-77cc367c9fd8', 1733, 'en', 'Isometric Squat to Failure', 'sometric Squat to Failure: A Strength Training Technique

 Definition

 The isometric squat to failure is a variation of the squat exercise where you hold a static squat position at a specific angle, maintaining the position until your muscles can no longer sustain the contraction.', 'pernas', '["glúteos","quadríceps"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1733/4ef77069-beb2-4504-a4f3-b181d5f35212.png', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1733/view/', 'isometric squat to failure gluteos quadriceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2f5032de-df6d-406b-b709-9223ef5c3e24', 314, 'en', 'Isometric Wipers', 'Assume push-up position, with hands slightly wider than shoulder width.

 Shift body weight as far as possible to one side, allowing the elbow on that side to flex.

 Reverse the motion, moving completely over to the other side.

 Return to the starting position, and repeat for the desired number of repetitions.', 'peito', '["peito"]', '["abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'cal.zabel', 'https://wger.de/en/exercise/314/view/', 'isometric wipers peito abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c9de4551-f1bc-4490-98f4-c9f87c2a2cac', 1702, 'en', 'Jalón al pecho con agarre ancho', 'The lat pulldown is a pulling exercise that primarily targets the latissimus dorsi muscles (commonly known as “lats”) in your back. It involves pulling a cable bar or handle down towards your chest while seated on a machine specifically designed for this exercise. The lat pulldown is typically performed with a wide grip, but can also be done with a narrow grip or underhand grip to target different muscle groups in the back and arms. It is a popular exercise for building upper body strength and improving posture.', 'costas', '["dorsais","trapézio"]', '["bíceps","braquial"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Mariano_O', 'https://wger.de/en/exercise/1702/view/', 'jalon al pecho con agarre ancho dorsais trapezio biceps braquial maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('dcd81ab4-1e6f-4123-b4a5-3364195faf7b', 1719, 'en', 'Jalon caballero unialteral', 'Pull performed in knight''s stance', 'costas', '["braquial","oblíquos"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'polloperro', 'https://wger.de/en/exercise/1719/view/', 'jalon caballero unialteral braquial obliquos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('85c28424-ab47-40d4-9a27-e1b9bfb01e7c', 1445, 'en', 'Jerk OL', 'Olympic lift jerk

 

• Hold bar in front on shoulders like push press

• Bend and extend knees pushing bar up while diving under the bar

• Catch bar overhead with straight arms using lunge

• Move feet parallel while holding bar in lockout', 'ombros', '["ombros"]', '["glúteos","quadríceps","tríceps"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1445/view/', 'jerk ol ombros gluteos quadriceps triceps barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('67c2fe41-f1e9-4f75-b2cb-72d1f2e092f7', 1302, 'en', 'JM Press', 'The JM press keeps your shoulders stationary, relying on the elbow flexion and extension to move the weight using your triceps strength. That means you get all the benefits of the best triceps-strengthening exercises without overtaxing that delicate shoulder joint. Classic win-win!', 'braços', '["tríceps"]', '["bíceps","peito"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'Epiphany8424', 'https://wger.de/en/exercise/1302/view/', 'jm press triceps biceps peito barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('89443e49-e5be-4b67-a5f6-e3f5ff80f6ea', 1314, 'en', 'Jumping Jack HD', 'Jumping jack are a plyometric exercise. Plyometrics are explosive aerobic moves that increase speed, quickness, and power and they work your whole body.
Jumping jack target the arm, shoulder, abdominal muscles, hip muscles and hip flexors and also work on the thighs, knee tendons and quadriceps.
Jumps are beneficial to your health because they combine cardiovascular conditioning with strength work. Since jumps elevate your heart rate, they can also improve your cardiovascular fitness.', 'cardio', '["quadríceps"]', '["glúteos","oblíquos","abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1314/view/', 'jumping jack hd quadriceps gluteos obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('20b17b71-6d91-4b56-978a-04b7f94c04cc', 1641, 'en', 'Kettlebell One Legged Deadlift', 'This exercise involves holding a kettlebell in one hand and standing on one leg while bending forward to touch the kettlebell to the ground. It targets the hamstrings, glutes, and lower back while also improving balance and stability.', 'pernas', '["glúteos"]', '[]', '["Halteres","Kettlebell"]', 'https://wger.de/media/exercise-images/1641/68d9488d-2596-420f-be0f-52aa70732c83.webp', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1641/view/', 'kettlebell one legged deadlift gluteos halteres kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5cbaa028-114d-4a15-9a95-70d9b3146f30', 1612, 'en', 'kettlebell sumo deadlift', 'Place your feet wider than shoulder-width apart, pointing your toes outward.
Keep your back straight, shoulders back, and chest up.
The knees must follow the same direction as the toes and not move forward.
When going up, it is advisable to contract your glutes to maximize the effectiveness of the exercise..', 'pernas', '["posteriores de coxa","glúteos","quadríceps"]', '[]', '["Kettlebell"]', 'https://wger.de/media/exercise-images/1612/3dc33f57-2786-4305-8b91-e011d7055923.jpg', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1612/view/', 'kettlebell sumo deadlift posteriores de coxa gluteos quadriceps kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('03960339-fe14-4670-a7b3-4974b859ed37', 1970, 'en', 'Kettlebell sumo high pull', 'A compound exercise combining elements of a sumo deadlift and a high pull. It targets the posterior chain, particularly the glutes, hamstrings, and upper back. The sumo stance increases hip engagement, while the high pull adds an explosive element, promoting power development.

 

• Stand upright overtop of a kettlebell with your feet wider than shoulder-width apart angled out slightly.

• Maintain a braced core and neutral spine throughout the exercise.

• Hinge your hips backward and extend your arms to grab ahold the kettlebell with a double overhand grip.

• With you lower legs nearly vertical to the ground, extend your hips to raise the kettlebell with your elbows high keeping it close to your body.

• Once the kettlebell has reached shoulder height, lower back to the starting position.', 'costas', '["trapézio"]', '["ombros","posteriores de coxa","glúteos","quadríceps"]', '["Kettlebell"]', NULL, 'CC-BY-SA 4', 'wgerpott', 'https://wger.de/en/exercise/1970/view/', 'kettlebell sumo high pull trapezio ombros posteriores de coxa gluteos quadriceps kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d813ef7c-b10a-4c5c-ba55-6b9518e7ff4c', 960, 'en', 'Kettlebell Swing', 'While kettlebell swings are a full-body workout, they mostly target the muscles along the posterior chain (back of the body). The main muscles used are the glutes, hamstrings, spinal erectors, and muscles of the upper back.', 'pernas', '["ombros","glúteos"]', '["quadríceps","abdômen","trapézio"]', '["Kettlebell"]', 'https://wger.de/media/exercise-images/960/da4d0560-da89-4bb5-b91f-746458fb04ad.png', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/960/view/', 'kettlebell swing ombros gluteos quadriceps abdomen trapezio kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8b311259-4f67-4dbf-9574-8c38faa92160', 331, 'en', 'Kettlebell Swings', 'Hold the kettlebell securely in both hands. Keep your back flat throughout the move, avoiding any rounding of the spine.Keeping your knees "soft", hinge your hips backwards, letting the kettlebell swing between your knees.

 You want to bend from the hips as far as you can without letting your back round forwards . Then, snap your hips forwards quickly and standing up straight, locking your body in an upright posture.

 The speed you do this will cause your arms and the kettlebell to swing up in front of you. Don''t try to lift the kettlebell with your arms. The snapping forwards of your hips will cause the kettlebell to swing forwards through momentum. Depending on the weight of the kettlebell and the speed of your hip movement, your arms will swing up to about shoulder height. At the top of this swing, let your hips hinge backwards again as the kettlebell swings back down to between your legs and the start of the next repetition.', 'pernas', '["glúteos"]', '["posteriores de coxa"]', '["Kettlebell"]', NULL, 'CC-BY-SA 3', 'J120290,cerin', 'https://wger.de/en/exercise/331/view/', 'kettlebell swings gluteos posteriores de coxa kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('57d1a6fc-fc28-43a7-9beb-0e851a47a976', 2481, 'en', 'Kick with Board', 'Hold a kickboard with both hands, arms extended in front of you, face in the water (lift head forward to breathe when needed). Kick from your hips, not your knees, keeping your legs mostly straight with a slight bend and a steady, compact flutter kick. This builds leg endurance and keeps your body horizontal without needing to worry about your arms.', 'cardio', '["glúteos","quadríceps"]', '["posteriores de coxa","panturrilhas","abdômen"]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2481/view/', 'kick with board gluteos quadriceps posteriores de coxa panturrilhas abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('107ea68a-d976-49ed-be75-3b0cf253c36a', 1688, 'en', 'Kickstand RDL', 'use non-working leg''s toes to help with balance and perform an RDL.', 'pernas', '["posteriores de coxa"]', '[]', '["Barra"]', NULL, 'CC-BY-SA 4', 'eriktrinkle', 'https://wger.de/en/exercise/1688/view/', 'kickstand rdl posteriores de coxa barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2b61df61-f71e-4b8f-9f95-6a565238a8ae', 1218, 'en', 'knee push-ups', '• Start by kneeling on the floor, keeping your knees together. Place your hands on the floor in front of you, slightly wider than shoulder-width apart.

• Make sure your body forms a straight line from head to knees. Hands should be positioned below shoulders.

• Lower your torso towards the ground, bending your elbows while keeping your trunk stable. Keep your knees in contact with the floor.

• Push through your hands to return to the starting position. Be sure to maintain contraction of chest, shoulder and arm muscles at the top of the movement.

• Perform the desired number of repetitions, controlling the movement and maintaining good form.', 'braços', '["ombros","peito"]', '["serrátil","tríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'PaukOne', 'https://wger.de/en/exercise/1218/view/', 'knee push-ups ombros peito serratil triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f4991a98-6422-4884-8ad3-43412f91fac1', 978, 'en', 'Knee Raises', 'The 90° leg raise on the bar is a very intense exercise that involves all the abdominal muscles.', 'core', '["abdômen"]', '["oblíquos"]', '["Barra fixa"]', 'https://wger.de/media/exercise-images/978/d3ffe51f-7eb8-4cc9-9eae-105847af3005.png', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/978/view/', 'knee raises abdomen obliquos barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('492e90a5-1ecb-4a06-8e9d-26a00042560e', 1452, 'en', 'Knee to Chest Stretch', 'The knee to chest stretch is a simple yet effective exercise for relieving lower back tension and improving hip mobility. To perform, lie flat on your back with your legs extended. Bring one knee toward your chest, wrapping your hands around your shin or behind your thigh. Gently pull the knee closer to your chest while keeping the other leg straight on the floor. Hold the stretch for 15–30 seconds, then switch sides. For a deeper stretch, both knees can be pulled toward the chest simultaneously.', 'pernas', '["glúteos"]', '["posteriores de coxa"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1452/85a6b9de-4eec-445b-8ebb-f1950b076aba.png', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1452/view/', 'knee to chest stretch gluteos posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('00f4a2b1-b1ac-49e6-a657-1d27e46522fd', 1910, 'en', 'Kneeling Superman', '• 
 Push one foot back until leg fully extended, concentrating on the having the foot high and pushed back as if pulled.

• 
 Extend arm forward with focus having the shoulder high up.

 Unilateral and static hold.', 'costas', '["posteriores de coxa","trapézio"]', '["abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1910/view/', 'kneeling superman posteriores de coxa trapezio abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('329d2adc-4b2c-4bb2-95d7-f5f6fedb9b96', 1511, 'en', 'Kong Curl', 'This exercise is somewhat similar to a cable curl and a cable crossover. But instead of a chest/biceps exercise, this exercise targets the brachialis muscle, responsible for that broad arm when viewed from a front view.
During the exercise, maintain a pronated forearm position with starting position of approx. 45 degree pronated. Start with slightly bend elbows and alternately curl until your hands (your thumb first) meet your upper middle chest (similar to how Kong hits his chest, thus the name of this exercise).', 'braços', '["bíceps"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1511/view/', 'kong curl biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b4e78b5a-6141-4fc9-a6f7-cba13ce6559b', 1442, 'en', 'Kreis Press DB', '• Sit on a bench with 45° incline

• Hold dumbbells overhead

• Move dumbbells down as if doing overhead press

• Rotate dumbbells palms facing up and extend your arms in front of your body

• Move hands together until dumbbells meet, keep arms extended

• Reverse the motion until dumbbells are overhead again

• This is one repetition', 'ombros', '["ombros"]', '["bíceps","peito","abdômen","tríceps"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1442/view/', 'kreis press db ombros biceps peito abdomen triceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('84b38ac6-9628-4f80-8940-204047fa2544', 1471, 'en', 'Kroc Row', 'Dumbbell rows with looser technique but heavier weight.', 'costas', '["dorsais","trapézio"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1471/view/', 'kroc row dorsais trapezio', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('16089e03-5afc-4a18-a40a-beb337806ac0', 382, 'en', 'L Hold', 'Hold the L position for as long as possible', 'core', '["core"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 3', 'bizyguy', 'https://wger.de/en/exercise/382/view/', 'l hold core peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('16202754-f567-4d23-a866-2c9cc8eba71d', 1852, 'en', 'L-sit', 'Sit on the ground with your legs together and your arms by your sides. Push your body off the ground using your hands, maintaining the same sitting position so that your legs are straight and your feet do not touch the floor.

 Hold for as long as required.', 'core', '["dorsais","peito","abdômen"]', '["quadríceps","tríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1852/view/', 'l-sit dorsais peito abdomen quadriceps triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a092afaf-aa5a-4384-b407-a6b52cf1c008', 1853, 'en', 'L-Sit (Foot Supported)', 'As with an L-sit, but allow your feet to touch the floor to support the some of the weight of your legs.', 'core', '["dorsais","peito","abdômen","serrátil"]', '["quadríceps","tríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1853/view/', 'l-sit (foot supported) dorsais peito abdomen serratil quadriceps triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('547217ec-cb9e-4713-8bab-2d8bfb160667', 1741, 'en', 'L-Sit Pull-ups', 'L-Sit Pull-ups train both upper body and core muscles.', 'braços', '["dorsais"]', '["bíceps","braquial","abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Happy', 'https://wger.de/en/exercise/1741/view/', 'l-sit pull-ups dorsais biceps braquial abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('73c1e130-fba9-473b-a093-a5712e2ae34d', 1779, 'en', 'Landmine Rotation', 'Start with landmine barbell straight up by using your shoulders to push it up above you. Then, from that position, bring it your side to target your abdominals and return to starting position.', 'core', '["oblíquos"]', '["ombros","abdômen"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/1779/view/', 'landmine rotation obliquos ombros abdomen barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('67bca611-d9f1-4855-9e02-ecc8d7d688e9', 1829, 'en', 'Landmine Squat to Press', 'Bar Position: Anchor one end of a barbell in a landmine attachment or a secure corner.
Stance: Stand facing the barbell with feet slightly wider than shoulder-width. Turn your toes out 10–35 degrees to allow for better pelvic movement and depth.
Grip: Cup the free end of the barbell with both hands (fingers interlaced or overlapping) and hold it at mid-chest level, just below the collarbone.

 Descent: Brace your core and sit back into a squat, keeping your chest up and weight on your heels.
Depth: Lower until your thighs are at least parallel to the floor. A good reference is when your elbows touch the tops of your thighs or just inside your knees.
Posture: Ensure your back remains flat and your spine neutral throughout the movement.

 Drive: Powerfully drive through your heels to stand up. Use the momentum from your legs to "thrust" the weight upward.
Extension: In one fluid motion, press the bar overhead until your arms are fully extended. At the top, your biceps should be near your ears.
The "Lean": As you reach the top of the press, lean slightly forward into the bar to encourage proper upward rotation of the shoulder blades and avoid lower back arching.

 Slowly lower the barbell back to chest height in a controlled manner before immediately beginning the next repetition.', 'pernas', '["ombros","glúteos","quadríceps"]', '["posteriores de coxa","abdômen"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1829/view/', 'landmine squat to press ombros gluteos quadriceps posteriores de coxa abdomen barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('87f30f6d-dc8a-4b26-8c4f-640b66ecacf0', 1546, 'en', 'Larsen Press', 'Put your legs up on a separate Bench and press with no leg drive', 'peito', '["peito"]', '["tríceps"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1546/view/', 'larsen press peito triceps barra', '2026-09-10T15:18:12.614Z');
