INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('82aec7f9-ee03-4b24-8994-f6bde07c6a41', 379, 'en', 'Leverage Machine Chest Press', 'Be sure to adjust seat height so that the handles are towards the bottom of your pectorals.', 'peito', '["peito"]', '[]', '[]', NULL, 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/379/view/', 'leverage machine chest press peito', '2026-09-10T15:18:12.614Z');
