INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9816dc3a-9739-4c70-bce0-4131f889e4f2', 1478, 'en', 'Levitation Crunch', 'For
this top down movement, we’re trying to move the upper torso without moving the
lower torso. Start lying on the ground with feet flat on the floor and crossed
arms above your head with hands behind head. Lift upper body up and clear your
shoulder blades off the ground and then hold and pause at the top for a one or
two count. Try to make the upper abs work and hold that contraction for 10 good
quality reps.', 'core', '["abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1478/view/', 'levitation crunch abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2cd0135b-8ef1-4bca-8a75-5fe2f507bee6', 1949, 'en', 'Limber 11', 'Limber 11
Source: Joe DeFranco

1. Foam Roll IT Band [soft_tissue] - 10-15 passes
2. Foam Roll Adductors [soft_tissue] - 10-15 passes
3. SMR Glutes (lax ball) [soft_tissue] - 30 sec-2 min
4. Bent-knee Iron Cross [dynamic] - 5-10 reps each side
5. Roll-overs into V-sits [dynamic] - 10 reps
6. Rocking Frog Stretch [dynamic] - 10 reps
7. Fire Hydrant Circles [dynamic] - 10 forward / 10 backward
8. Mountain Climbers [dynamic] - 10 reps each leg
9. Cossack Squats [dynamic] - 5-10 reps each side
10. Seated Piriformis Stretch [isometric] - 20-30 sec each side
11. Rear-foot-elevated Hip Flexor Stretch [dynamic + 3s hold] - 5-10 reps each side', 'pernas', '["pernas"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Pete-E automation probe', 'https://wger.de/en/exercise/1949/view/', 'limber 11 pernas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('692d294d-925d-4a4e-8059-02a1a0ffdae4', 2526, 'en', 'Long Lunge Pulse Stretch', '• Hold the resistance band (or any other rope-like object, the elasticity is not necessary) above your head, between your hands, with your arms straight. Pull it taught to engage your lats.

• Step forwards into a lunge, dropping until your knee is almost touching the floor.

• Slowly and controlledly pulse your body up and down by about an inch. Repeat for required reps.

• Repeat for other leg.', 'pernas', '["pernas"]', '[]', '["Elástico"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2526/view/', 'long lunge pulse stretch pernas elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('77c98954-b50d-46f0-9912-3981f856d5a6', 395, 'en', 'Long-Pulley, Narrow', 'The exercise is the same as the regular long pulley, but with a narrow grip:

 Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched.', 'costas', '["dorsais"]', '["bíceps","braquial"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/395/view/', 'long-pulley, narrow dorsais biceps braquial maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('183e7279-f052-4c70-8381-bbbda3bb9afe', 397, 'en', 'Low Box Squat - Wide Stance', 'Unrack the bar and set your stance wide, beyond your hips. Push your hips back and sit down to a box that takes you below parallel. Sit completely down, do not touch and go. Then explosively stand up. Stay tight in your upper back and torso throughout the movement.', 'pernas', '["glúteos","quadríceps"]', '[]', '["Barra"]', NULL, 'CC-BY-SA 4', 'taylorbarbell', 'https://wger.de/en/exercise/397/view/', 'low box squat - wide stance gluteos quadriceps barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d5116fbd-bf14-492a-86b3-140035cb48b2', 1270, 'en', 'Low Pulley Cable Fly', 'Adjust the cable machine: Set the pulley to the lowest setting possible.
Choose your handles: You can use neutral grip handles (palms facing each other) or straight handles depending on your preference. Neutral grip might be easier on your wrists.
Stand with proper form: Stand with your feet shoulder-width apart, knees slightly bent, and core engaged. Maintain a slight arch in your lower back throughout the exercise.
Grip the handles: Grab the handles with your chosen grip and step back a small step or two until there''s slight tension on the cables.
Initiate the movement: Keep your elbows slightly bent throughout the exercise. Imagine you''re giving someone a big hug. Squeeze your chest muscles as you bring your hands together in front of your chest.
Control the movement: Focus on squeezing your chest muscles rather than using your arms to pull the handles.
Peak contraction: Briefly hold the squeeze at the top of the movement with your hands together at chest level.
Return slowly: Slowly release the tension and return the handles back down to the starting position with your arms slightly extended but not locked out.', 'peito', '["peito"]', '["ombros"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'FEFFO', 'https://wger.de/en/exercise/1270/view/', 'low pulley cable fly peito ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('bbcf5019-a57f-4e67-bd44-98cba129a0b7', 2489, 'en', 'Low row', 'Based on Low Row Sel. by Technogym. In this version, you use it with two arms.', 'costas', '["trapézio"]', '["bíceps","dorsais"]', '[]', NULL, 'CC-BY-SA 4', 'lbroggi', 'https://wger.de/en/exercise/2489/view/', 'low row trapezio biceps dorsais', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ac6e6a09-5175-4fea-9e56-e2ff3c00b0f2', 1296, 'en', 'Low-Cable Cross-Over - NB', 'The low-cable cross-over is an isolation movement that uses a cable stack to target the upper portion of the pectoral muscles. It is common in upper-body and chest-focused muscle-building workouts, often in combination with presses or flyes from other angles to target all portions of the chest.', 'peito', '["peito"]', '["ombros"]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1296/c42782fe-337a-44f4-9079-7f6dedab4885.png', 'CC-BY-SA 4', 'JackSparrow', 'https://wger.de/en/exercise/1296/view/', 'low-cable cross-over - nb peito ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('50a8f1f6-6772-4319-be9d-3bad1374dadf', 1348, 'en', 'Lower Back Extensions', '• Engage the muscles

• Lift your bottom slightly

• Controlled movement

• Slow movement

• Don''t use momentum

• Keep your upper body straight', 'costas', '["costas"]', '[]', '[]', 'https://wger.de/media/exercise-images/1348/a3769120-2445-49f2-97d3-afc1238bfc2a.webp', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1348/view/', 'lower back extensions costas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('558b3385-f1a2-47d2-8473-e1be2c7726aa', 1868, 'en', 'Lunge with Twist Stretch', 'View the video to undestand the exercise', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1868/446e7065-215d-4a91-9da7-9416101442bb.png', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1868/view/', 'lunge with twist stretch pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('861f7396-f34e-486c-a903-3c326086f920', 1530, 'en', 'Lying Dumbbell Curls', 'Take a
dumbbell in each hand and lie backwards on a bench, similar to a classic chest press.
Let your arms hang down at your sides, with the dumbbells possibly touching the
floor. Now start to lift the dumbbells upwards until your forearms are
perpendicular to the ceiling. Slowly lower the dumbbells until they almost
touch the floor again. Keep your ellbows in place to minimize cheating.', 'braços', '["bíceps"]', '[]', '["Banco","Halteres"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1530/view/', 'lying dumbbell curls biceps banco halteres', '2026-09-10T15:18:12.614Z');
