INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b5529305-04a2-4ca2-af6a-4a67d3e4aca4', 1870, 'en', 'Lying Hamstring Stretch with Band', 'View the video to undestand the exercise', 'pernas', '["pernas"]', '[]', '["Elástico"]', 'https://wger.de/media/exercise-images/1870/7465bbcf-3b86-42a6-8d2f-12a3d1f60a15.png', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1870/view/', 'lying hamstring stretch with band pernas elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('aa3b4ebe-6dee-45ad-a345-cf2acebf4159', 406, 'en', 'Lying Rotator Cuff Exercise', 'This is an excercise for problems with the rotator cuff. Primary Infraspinatus, secondary Teres Minor.

 Lying on side. Keep elbow on waist and in 90 dgr angle. Rotate towards stomach. Add weight as fit.', 'ombros', '["ombros"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Trix', 'https://wger.de/en/exercise/406/view/', 'lying rotator cuff exercise ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8a356e9a-0058-4f60-b8d7-89147c3c371f', 1480, 'en', 'Lying Triceps Extensions', '• Starting position for this
practical triceps exercise is lying on a standard bench holding a barbell or two dumbbells in both hands with an overhand grip, hands at shoulder width apart.

• Begin with arms over your upper
chest and elbows bent back at about a 45-degree angle.

• First bend at the elbows and
then allow the upper arm to drop back, bringing the barbell/dumbbells behind your
head and down toward the floor. In terms of upper arm position, the barbell/dumbbells should never be fully above your head, but instead behind it, to
ensure that you’re targeting the triceps.

• Keep the shoulder blades tucked
under, the elbows tight in toward your head and your core active during
this entire movement.', 'braços', '["tríceps"]', '[]', '["Barra","Halteres"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1480/view/', 'lying triceps extensions triceps barra halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9c979645-78d1-44be-92a0-7940430a6a98', 1490, 'en', 'Lying Triceps Kickback', 'Set the bench to an 60deg angle. Stand still and rest your upper body on the inclined bench, ensuring a nearly straight line of your entire body. Squeeze your shoulder blades together, so that your elbows are located behind your torso with your upper arms nearly parallel to the floor. Lift the dumbbells until your arms form a straight line. Slowly lower the dumbbells back to the initial position. Initial position corresponds to an rectangular position of upper and lower arms.', 'braços', '["tríceps"]', '[]', '["Halteres","Banco inclinado"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1490/view/', 'lying triceps kickback triceps halteres banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1e827ef8-0a01-4b26-9e26-eff9d200acca', 926, 'en', 'Machine chest fly', 'seated machine, straight back, slow exercise', 'peito', '["peito"]', '[]', '[]', 'https://wger.de/media/exercise-images/926/ae9deb5d-a1e9-4c30-b1e3-c128ba5d4969.png', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/926/view/', 'machine chest fly peito', '2026-09-10T15:18:12.614Z');
