INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('40f41034-556c-4f3c-8839-6a441febe252', 2561, 'en', 'Machine Dip', 'Machine assisted dip emphasizing controlled elbow extension and stable shoulder positioning.', 'braços', '["tríceps"]', '["peito"]', '[]', NULL, 'CC-BY-SA 3', '', 'https://wger.de/en/exercise/2561/view/', 'machine dip triceps peito', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ab872d04-ca20-4341-b3c9-76763b25ef42', 1132, 'en', 'Machine glute extension', 'A GHD hip extension is one of the best exercises for the glutes. While the exercise mainly targets the glutes, it is also excellent for the lower back, the calves and the hamstrings.', 'pernas', '["glúteos"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1132/view/', 'machine glute extension gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b5726562-82ed-451a-89d8-8c8b13c5019a', 1748, 'en', 'Machine Hip Abduction', 'Technique and Execution

 Starting Position

 Seated Positioning: Sit in the machine with back against the pad

 Leg Placement: Inner thighs against the machine''s padded resistance points

 Adjust Machine: Set seat position to align your hip joint with the machine''s pivot point

 Movement Technique

 Start with legs together or slightly pressed against the inner pads

 Slowly push legs outward, spreading them apart

 Move until maximum comfortable lateral range is reached

 Pause briefly at the outer point of the movement

 Slowly return to the starting position with controlled movement

 Biomechanical Breakdown

 Muscle Engagement

 Primary Activation: Gluteus Medius (side hip muscle)

 Stabilization: Engages core and lower back muscles

 Functional Movement: Mimics lateral leg movement used in walking, sports, and daily activities

 Benefits

 Strength and Stability

 Improves Hip Stability

 Reduces Risk of Knee Injuries

 Enhances Lateral Movement Capabilities

 Targets Often-Neglected Muscle Groups', 'pernas', '["glúteos"]', '[]', '[]', 'https://wger.de/media/exercise-images/1748/923a3ff7-c269-49bd-9f03-697151a40f06.jpg', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1748/view/', 'machine hip abduction gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ef3792dd-66f0-4fc7-a6e1-a8868219cb49', 2559, 'en', 'Machine Incline Chest Press', 'Incline machine chest press performed with controlled repetitions and stable shoulder mechanics.', 'peito', '["peito"]', '["tríceps"]', '[]', NULL, 'CC-BY-SA 3', '', 'https://wger.de/en/exercise/2559/view/', 'machine incline chest press peito triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a83b89f0-e58c-42c6-a303-502e2aa70878', 2558, 'en', 'Machine Lat Pulldown', 'Machine assisted vertical pulling movement emphasizing the latissimus dorsi with controlled scapular motion.', 'costas', '["dorsais"]', '["bíceps"]', '[]', NULL, 'CC-BY-SA 3', '', 'https://wger.de/en/exercise/2558/view/', 'machine lat pulldown dorsais biceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c690034b-400c-4da8-8c71-37afac81ec3f', 2495, 'en', 'Machine Leg Flexion', 'Adjust the back seat or pad so your knees align with the side pivot axis.Place the lower roller pad against your lower calves, just above the back of your ankles.Lower the upper thigh restraint pad so your legs stay firmly on the seat.Pick a light weight on the stack with the pin.', 'pernas', '["posteriores de coxa"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/2495/5978ac7d-f4d4-4807-87e6-03e457485191.png', 'CC-BY-SA 4', 'Me', 'https://wger.de/en/exercise/2495/view/', 'machine leg flexion posteriores de coxa maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('38e8c694-5148-47af-bc5f-1e9cc709df3f', 2553, 'en', 'Machine Seated Calf Raise', 'Seated calf raise emphasizing the soleus through a controlled plantarflexion movement.', 'panturrilhas', '["sóleo"]', '["panturrilhas"]', '[]', NULL, 'CC-BY-SA 3', '', 'https://wger.de/en/exercise/2553/view/', 'machine seated calf raise soleo panturrilhas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b172856a-2335-48b9-9b9a-e7f9c21421bb', 2551, 'en', 'Machine Seated Leg Curl', 'Seated machine knee-flexion exercise emphasizing the hamstrings. Use controlled motion and avoid forcing the end range.', 'pernas', '["posteriores de coxa"]', '[]', '[]', NULL, 'CC-BY-SA 3', 'Personal routine', 'https://wger.de/en/exercise/2551/view/', 'machine seated leg curl posteriores de coxa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('dc87b735-016c-410b-915c-e3521fea4be7', 1744, 'en', 'Machine Side Lateral Raises', 'Machine side lateral raises are an isolation exercise for the side (lateral) deltoids, performed on a machine for stability, targeting the outer shoulder by lifting pads or handles out to the sides to shoulder height, then lowering slowly, keeping elbows slightly bent and traps down to focus on the delts. This exercise helps build shoulder width by preventing swinging and providing constant tension, making it great for beginners or as a finisher.

 How to Perform Machine Lateral Raises

 Setup: Adjust the seat so your shoulders align with the machine''s pivot point, your chest is against the pad (or back if facing out), and your arms are at a 90-degree angle with the pads/handles.

 Starting Position: Grip the handles with a relaxed grip, elbows slightly bent, and shoulders down (depressed) away from your ears.

 Lifting Phase: Exhale and lift your arms out to the sides, moving your upper arms laterally, until they are parallel to the floor.

 Peak Contraction: Pause briefly at the top, squeezing the side delts, but don''t shrug your shoulders up.

 Lowering Phase: Inhale and slowly lower the weight back down with control, resisting the weight on the way down.', 'ombros', '["ombros"]', '[]', '[]', 'https://wger.de/media/exercise-images/1744/cb9263c4-39fc-4261-8d30-a5d6d57841c1.jpg', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1744/view/', 'machine side lateral raises ombros', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('564dc73e-e8d4-4fd1-85ab-64dce4dd3ea0', 1584, 'en', 'March or jog in place', 'Low-impact cardiovascular exercise that simulates running without moving, ideal for warming up, improving endurance, or training in small spaces.', 'cardio', '["posteriores de coxa","panturrilhas","glúteos","quadríceps"]', '["ombros","bíceps","oblíquos","abdômen","tríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'MrAlfaRobot', 'https://wger.de/en/exercise/1584/view/', 'march or jog in place posteriores de coxa panturrilhas gluteos quadriceps ombros biceps obliquos abdomen triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fad49a13-b2a0-4b1f-b262-29b32248257d', 1965, 'en', 'Marching High Knees', 'A low-impact cardio and mobility exercise that strengthens the hip flexors and improves balance.

 

• ​Movement: Stand tall and lift one knee toward your chest as high as comfortable.

• ​Arms: Swing the opposite arm forward as you lift your knee, similar to a walking motion.

• ​Core: Keep your abs engaged to maintain an upright posture.

• ​Pace: Perform the movement with control, alternating legs rhythmically.', 'pernas', '["quadríceps"]', '["panturrilhas","glúteos","abdômen"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1965/03c08a42-dedb-4a46-8d15-acaf497a35a2.png', 'CC-BY-SA 4', 'Anon#2', 'https://wger.de/en/exercise/1965/view/', 'marching high knees quadriceps panturrilhas gluteos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('28b65190-cae2-4d15-8f4e-dde0d9cc4d4b', 1304, 'en', 'Meadows Row', 'The Meadows row is a unilateral row performed with a landmine setup, overhand grip, and staggered stance. Lean your torso forward and grip the barbell. Rest the other forearm on the forward leg. Start this movement by driving the elbow behind you while retracting the shoulder-blade. Keep the working shoulder down. Pull toward your back hip until the elbow is level with your torso.', 'costas', '["dorsais","trapézio"]', '["bíceps","abdômen"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1304/view/', 'meadows row dorsais trapezio biceps abdomen barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('346634cf-3896-4c10-bd66-28fb69d02573', 976, 'en', 'Medicine ball booklet crunch', 'Using a medicine ball as an overload will make the exercise heavier.', 'core', '["abdômen"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/976/94649ea6-bf58-4fd9-90c1-b2ec96ee20cd.png', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/976/view/', 'medicine ball booklet crunch abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('66c7eb38-77b5-4d2f-810f-cddd8d97d5a3', 1089, 'en', 'Medicine ball twist', 'In a seated position, the torso is rotated from side to side without forcing, approaching the knees and making the ball touch the ground from time to time', 'core', '["oblíquos","abdômen"]', '[]', '["Bola suíça"]', 'https://wger.de/media/exercise-images/1089/49f51716-535d-41dd-aeb5-cff5bb906bc1.jpeg', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1089/view/', 'medicine ball twist obliquos abdomen bola suica', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c4185277-1d30-4684-9bc0-024ab7f2336a', 1971, 'en', 'Mentzer Pulldown', 'Close grip front facing Pull down, while focusing on Biceps, Increases activation of biceps over the whole range, Avoid activating Lats.', 'braços', '["bíceps"]', '["dorsais"]', '["Máquina de cabo","Banco inclinado"]', 'https://wger.de/media/exercise-images/1971/729af526-19a0-4d3d-a258-196c7575d139.jpg', 'CC-BY-SA 4', 'Mike Mentzer', 'https://wger.de/en/exercise/1971/view/', 'mentzer pulldown biceps dorsais maquina de cabo banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7b1e458f-1857-4c2f-8463-7d67d4b2db93', 418, 'en', 'Military Press mit SZ-Bar', 'On an SZ-bar grip your hands on the outside of each bend and stand with your arms straight down, palms facing your legs. Pull the bar (bending your arms at the elbow) to your chest, and the push the bar above your head (arms as straight as possible). Return the bar to your chest by dropping your arms at the elbows. Return the bar to it''s origional position (stand with your arms straight down, palms facing your legs.)', 'ombros', '["ombros"]', '["trapézio","tríceps"]', '["Barra W"]', 'https://wger.de/media/exercise-images/418/fa2a2207-43cb-4dc0-bc2a-039e32544790.png', 'CC-BY-SA 3', 'mbozi1', 'https://wger.de/en/exercise/418/view/', 'military press mit sz-bar ombros trapezio triceps barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5851e2b1-3a80-42ff-91da-530e6b143a34', 1635, 'en', 'Modified pulldown', 'With an inclined bench in front of the pulldown machine, use a close-grip to do latfocused pulldowns.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo","Banco inclinado"]', 'https://wger.de/media/exercise-images/1635/b8c34e3a-7474-41ea-99e3-8d7fdb1e12d6.png', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1635/view/', 'modified pulldown dorsais maquina de cabo banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0027b172-a83e-4f79-af47-483302a22c02', 423, 'en', 'Muscle up', 'The body is then explosively pulled up by the arms in a radial pull-up, with greater speed than a regular pull-up. When the bar approaches the upper chest, the wrists are swiftly flexed to bring the forearms above the bar. The body is leaned forward, and the elbows are straightened by activating the triceps. The routine is considered complete when the bar is at the level of the waist and the arms are fully straight.

 To dismount, the arms are bent at the elbow, and the body is lowered to the floor, and the exercise can be repeated.

 As a relatively advanced exercise, muscle-ups are typically first learned with an assistive kip. The legs swing (kip) up and provide momentum to assist in the explosive upward force needed to ascend above the bar. More advanced athletes can perform a strict variation of the muscle-up which is done slowly, without any kip. This variation begins with a still dead hang and uses isometric muscle contraction to ascend above the bar in a slow, controlled fashion.', 'costas', '["bíceps","dorsais"]', '["ombros","tríceps"]', '["Barra fixa"]', NULL, 'CC-BY-SA 4', 'arson', 'https://wger.de/en/exercise/423/view/', 'muscle up biceps dorsais ombros triceps barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0d50ce1e-1731-40e8-82e0-c8f512d0a8c9', 1939, 'en', 'Neck CARs', 'Controlled Articular Rotations. Slow full circles 3 each way. Cervical mobility.', 'ombros', '["ombros"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1939/view/', 'neck cars ombros', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d27a93fa-7066-477c-a475-c6b6170831db', 1717, 'en', 'Neck extension', 'Unilateral triceps exercise with your back to the pulley, with the pulley at the top', 'braços', '["bíceps"]', '[]', '["Máquina de cabo","Barra W"]', NULL, 'CC-BY-SA 4', 'polloperro', 'https://wger.de/en/exercise/1717/view/', 'neck extension biceps maquina de cabo barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8bffd3b2-663a-4617-9d95-dce24e795470', 1017, 'en', 'Neck half circles', 'Starting position:

 Start sitting or standing. Lean your head against one of your shoulders, but don''t push.

 Steps:

 In one slower fluid motion and with your head relaxed and not pushing in any direction:

 

• bring your head down toward your chest.

• then lean back aganst your other shoulder.

• then back toward the chest again.4.and finally toward the starting position.

 Keep repeating this.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1017/view/', 'neck half circles costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('cbc5fbc9-9bca-4766-941d-4b6903d4a521', 427, 'en', 'Negative Crunches', 'Sit yourself on the decline bench and fix your legs. Cross your arms over the chest and bring with a rolling movement your upper body up, go now without a pause and with a slow movement down again. Don''t let your head move during the exercise.', 'core', '["abdômen"]', '[]', '[]', 'https://wger.de/media/exercise-images/93/Decline-crunch-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/427/view/', 'negative crunches abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3cad7b92-a16b-45dc-a53e-d6a01a158f8e', 1510, 'en', 'Neutral Grip Lat Pulldown', 'Lat pull downs with a neutral grip on the bar.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1510/view/', 'neutral grip lat pulldown dorsais maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('eaa7927e-6ea0-4fd5-bbcd-525fe90a184b', 1136, 'en', 'Neutral-grip chest pulldown', 'The lat pulldown is an important exercise for strengthening the back and improving posture, which can contribute to a healthier life. To perform this exercise correctly and avoid injury, it is important to follow a few key steps:

 

• 
 Position yourself in front of the cable machine with your knees slightly bent and your feet on the floor.

• 
 Grip the cable handle with your palms facing each other and your hands shoulder-width apart.

• 
 Pull the handle down until it touches or comes close to your chest, holding the position for one or two seconds.

• 
 Slowly raise the handle back to the starting position, making sure to keep your arms and hands straight and your back straight throughout the movement.', 'costas', '["bíceps","dorsais","serrátil"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1136/5778a8e9-c606-4843-89c8-9d9469eeb6e4.PNG', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1136/view/', 'neutral-grip chest pulldown biceps dorsais serratil maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('15fda45b-108b-4b28-bfe5-d0e55a0914bf', 1738, 'en', 'Neutral-grip pull-ups or TRX rows', '• 
 Pull-Up: Vertical Pull — Focuses more on the Lats (back width). 

 TRX Row: Horizontal Pull — Focuses more on the Rhomboids/Traps (mid-back thickness and posture).', 'braços', '["dorsais"]', '["bíceps"]', '["Barra fixa"]', 'https://wger.de/media/exercise-images/1738/0529acdf-ede8-42a2-a3e5-8d0c57b7a0e1.jpg', 'CC-BY-SA 4', '54str', 'https://wger.de/en/exercise/1738/view/', 'neutral-grip pull-ups or trx rows dorsais biceps barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('10b0684c-1c48-4be6-913e-19bf1419107b', 1461, 'en', 'No Leg Drive Dumbbell Chest Press', 'Set up for a normal Dumbbell chest press but lift your leg ups straight or put them on another bench to remove the leg drive.', 'peito', '["peito"]', '["ombros","tríceps"]', '["Banco","Halteres"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1461/view/', 'no leg drive dumbbell chest press peito ombros triceps banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9b0f7101-b78a-4c47-b680-fbef15469a8a', 910, 'en', 'Nordic Curl', 'The Nordic hamstring curl is one of the best lower-body exercises to build posterior leg strength, improve knee health, and prevent injury.', 'pernas', '["posteriores de coxa"]', '["glúteos"]', '[]', NULL, 'CC-BY-SA 4', 'karly', 'https://wger.de/en/exercise/910/view/', 'nordic curl posteriores de coxa gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ac00021c-12f9-4827-8003-ea07de980b76', 1484, 'en', 'Omni Cable Cross-over', 'Adjust the weights based on the
motion. When pulling from top to bottom, increase the weight by 20% to 40%
more than the bottom-to-top motion. This accounts for the fact that when
operating from top down, the upper chest muscles are naturally weaker than
the lower chest muscles. So, adjust your weight stack to
compensate.

 

• Position one cable at a high
setting and the other at the lowest level setting. Get into a staggered
stance in between the cable towers.

• For the cable set low, pull it
upward and across your body. This effectively targets the upper chest.

• For the cable set high, draw it
downward and across your body. This will primarily engage the lower chest.

 Once you’re done, swap the
positions of the cables. Change the previously high cable to the lowest
position and vice versa. Repeat the exercise sequence, ensuring you’re
targeting both chest regions effectively.', 'peito', '["peito"]', '[]', '["Máquina de cabo","Barra W"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1484/view/', 'omni cable cross-over peito maquina de cabo barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6b6c69bc-0b1e-4b2f-ab61-4945eb18047e', 1186, 'en', 'One Arm Bent Row', 'One arm bent over row on cable with a machine', 'costas', '["dorsais"]', '["bíceps","trapézio"]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1186/1987a039-cf35-437e-bbdc-40c53dd7d053.jpg', 'CC-BY-SA 4', 'anto.kreegyr', 'https://wger.de/en/exercise/1186/view/', 'one arm bent row dorsais biceps trapezio maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0db2e53e-7075-4a63-aea7-ca15f55621ee', 2566, 'en', 'One Arm Dumbbell Row', 'Single arm dumbbell row emphasizing controlled horizontal pulling and stable trunk positioning.', 'costas', '["dorsais"]', '["bíceps"]', '["Halteres"]', NULL, 'CC-BY-SA 3', '', 'https://wger.de/en/exercise/2566/view/', 'one arm dumbbell row dorsais biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5ed12527-c8be-4e86-8f2a-cf9dd4781f5b', 1668, 'en', 'One Arm Overhead Cable Tricep Extension', 'Set the pulley at the bottom of the cable machine and grab onto it without using any attachments. Extend the cable directly overhead.

 While keeping your back straight and upper arm stationary, lower the cable behind your head until you feel a good stretch in your triceps, and then extend it back upward until your elbow is locked out.', 'braços', '["tríceps"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1668/view/', 'one arm overhead cable tricep extension triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8911c37d-8907-4077-b883-86a7c5fcb606', 1293, 'en', 'One armed push-ups', 'Perform push-ups with one hand, alternating the sides', 'core', '["peito","tríceps"]', '["ombros","abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1293/view/', 'one armed push-ups peito triceps ombros abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d8ec22e5-8575-483f-bd66-5203fd4bfe84', 1701, 'en', 'One-Arm Heavy Row', 'Execution 
 

• 
 Rowing phase (concentric): 

 

• Pull the dumbbell toward your lower chest or waist , leading with your elbow .

• Keep your torso stable — avoid twisting or rotating your shoulders.

• Pause at the top and squeeze your lats .', 'costas', '["dorsais"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1701/view/', 'one-arm heavy row dorsais halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d7d4fc16-08cd-4568-87e7-d9e4e2f77393', 975, 'en', 'one-handed kettlebell curls', 'Standing with the kettlebell in one hand and bent at the elbow, start from a fully extended position until your hand reaches shoulder height. To perform the movement correctly, try not to push with your back or body.', 'braços', '["bíceps"]', '[]', '["Kettlebell"]', 'https://wger.de/media/exercise-images/975/41d9267a-99bc-4e94-b1c4-0e39fe7a968f.png', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/975/view/', 'one-handed kettlebell curls biceps kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('164b83aa-195e-4eed-b820-b81df950d9bb', 1822, 'en', 'Open Book', 'Basic exercise 

 

• Focus: enhances thoracic mobility and
spinal segmentation while opening the shoulders and chest.

• **Position:**kneeling on the floor with your right side facing a wall. Hips are square and stable, with the right knee down and the left foot forward. Lengthen your spine and align your head comfortably.
Begin with your arms relaxed and open in front of your chest, palms
facing each other and hands apart.

• Inhale 
to initiate the movement, allowing your left arm —the one farther from
the wall— to open outward and backward. Lead the twist from your thoracic
spine, rotating your upper back progressively while keeping your pelvis
still.

• Exhale as you complete the rotation, guiding your left hand
toward the wall as your gaze follows your hand.

• Return by inhaling and
slowly bringing your arm forward, reversing the spinal rotation segment
by segment.

• Repeat on the opposite side. 

 Progression 

 

• **Position:**kneeling on the floor with your right side facing a wall. Left knee down and right foot forward.

• Before the basic exercise: inhale , exhale while moving the right arm along the wall with a circle upwards and backwards, inhale while bringing back the arm.

• Basic exercise. 

• Repeat on the opposite side.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'teus_ergaster', 'https://wger.de/en/exercise/1822/view/', 'open book costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c7058ff8-ca3b-4822-abdb-6341ce37c4d1', 439, 'en', 'Overhand Cable Curl', 'Hands at shoulder height, curl arms in toward head, then back out.', 'core', '["bíceps"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 3', 'ThisGirl0819', 'https://wger.de/en/exercise/439/view/', 'overhand cable curl biceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2500c212-6f14-4a8d-a997-04e9e7c04116', 1893, 'en', 'Overhead Barbell Press', '• Setup: Stand with feet together and grip the bar slightly wider than shoulders.

• Position: Rest the bar on your upper chest.

• Press: Brace your core and push the bar straight up until your arms lock out.

• Finish: Control the bar back down to your chest.

• https://youtu.be/ZXpdJOLNoWw?si=u27cGyODoblXHBu1', 'ombros', '["ombros"]', '[]', '["Barra"]', 'https://wger.de/media/exercise-images/1893/7dbad19e-0616-41fd-9d7d-3e21649c0eea.png', 'CC-BY-SA 4', 'nishant0712', 'https://wger.de/en/exercise/1893/view/', 'overhead barbell press ombros barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f2e17c8d-7285-4fd5-bfe8-26f407802850', 1513, 'en', 'Overhead Cable Tricep Extension', 'Use rope handle with your back against the cable machine. Straighten your arms until they are filly extended and reverse the motion resisting on the negative.', 'braços', '["tríceps"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1513/view/', 'overhead cable tricep extension triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('993c7f0c-729b-4834-a0f5-67d126d92fbf', 2537, 'en', 'Overhead Press Isometric', 'An isometric overhead press involves holding a weight statically overhead or pushing against an immovable object at a specific point in the press without moving the joint.', 'ombros', '["ombros","tríceps"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2537/view/', 'overhead press isometric ombros triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('bc45125b-58da-4ee9-8895-16a7b930b789', 441, 'en', 'Overhead Squat', 'The barbell is held overhead in a wide-arm snatch grip; however, it is also possible to use a closer grip if balance allows.', 'pernas', '["glúteos","quadríceps"]', '["ombros","posteriores de coxa","trapézio"]', '[]', NULL, 'CC-BY-SA 4', 'geraldbaeck', 'https://wger.de/en/exercise/441/view/', 'overhead squat gluteos quadriceps ombros posteriores de coxa trapezio', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c5797bdf-1aa1-4d51-9775-c929ec5a2aaf', 1519, 'en', 'Overhead Triceps Extension', 'Overhead Triceps Extension with EZ Bar – Quick Guide 

 The overhead position emphasizes the long head of the triceps (because it''s stretched under load), the exercise does engage all three triceps heads (long, lateral, and medial) to some degree during extension.

 

• Setup :
Sit on a bench (or stand) and hold an EZ bar with a narrow, overhand
grip. Lift the bar overhead, arms fully extended. Keep your core tight
and elbows close to your head.

• Execution :
Slowly lower the bar behind your head by bending your elbows until they
reach ~90°. Keep elbows pointed forward (not flaring out).

• Finish : Extend your arms back up to the starting position, squeezing your triceps at the top.

 Tips :

 

• Control the movement to avoid straining your shoulders.

• Use a moderate weight for full range of motion.

• Keep your back straight and avoid arching.', 'braços', '["trapézio"]', '[]', '["Barra W"]', 'https://wger.de/media/exercise-images/1519/fab7f641-27d4-40b5-8edd-1a0a137bfd94.gif', 'CC-BY-SA 4', 'benjamin.yildiz@proton.me', 'https://wger.de/en/exercise/1519/view/', 'overhead triceps extension trapezio barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e56f2970-e4c9-45eb-8e8c-52abb590e7a6', 1194, 'en', 'Pallof Press', 'The Pallof press is an anti-rotation exercise that trains the larger and smaller muscles around the spine to resist rotation.

 

• Stand parallel to the cable machine or to the anchor point to the
resistance band and clasp with the handle or band with both hands.

• Make sure your torso is front on and bring your hands to the center of your chest and slowly press out.

• Slowly return your hands to the chest and repeat.', 'core', '["ombros","glúteos","oblíquos","abdômen","serrátil","trapézio"]', '["peito","tríceps"]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1194/34c03421-0803-4859-a2b0-5710f2bd94cd.png', 'CC-BY-SA 4', 'prevail90', 'https://wger.de/en/exercise/1194/view/', 'pallof press ombros gluteos obliquos abdomen serratil trapezio peito triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('934856f3-6eb3-4b37-9536-0ff67a6aa036', 1808, 'en', 'Parallel Bar Hold', '• Stand between a set of parallel bars.

• Place your hands, knuckles outwards, on the bars.

• Push down on your hands to lift yourself off the floor.

• Hold yourself in this position with your arms straight for the required time.', 'braços', '["ombros","peito","tríceps"]', '["dorsais","oblíquos","abdômen"]', '[]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1808/view/', 'parallel bar hold ombros peito triceps dorsais obliquos abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('17dd0986-5248-410d-89a4-9268282d103b', 1703, 'en', 'Patadas traseras', 'The dumbbell kickback is a popular strength training exercise that targets the triceps muscles in the back of your upper arms. It helps strengthen and tone the triceps, contributing to overall arm strength and aesthetics.

 Among the exercises that work the arm muscles, kickback and its variations are very effective. You can easily apply these exercises with dumbbells, cables or resistance bands.', 'braços', '["tríceps"]', '[]', '["Banco","Halteres"]', NULL, 'CC-BY-SA 4', 'Mariano_O', 'https://wger.de/en/exercise/1703/view/', 'patadas traseras triceps banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6441ff9e-037e-48d9-8800-67b430dc8e37', 445, 'en', 'Pause Bench', 'Lower the bar to your chest and pause (but do not rest) there for 2 seconds. Press back up. use the same weight you would on bench press, but perform only single reps. Total the number of reps you did in one set of bench press (if you did 3 sets of 8 do 8 sinlge pause bench reps.', 'peito', '["peito"]', '["tríceps"]', '["Barra","Banco"]', NULL, 'CC0', 'Mens Fitness', 'https://wger.de/en/exercise/445/view/', 'pause bench peito triceps barra banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1b329beb-fcda-4471-ba70-eea62da410dd', 1464, 'en', 'Pause Hack Squats', 'Hack Squats but with a 1-2s pause at the bottom of the movement. This makes sure that there is no more elastic energy stored in the muscles.', 'pernas', '["quadríceps"]', '["posteriores de coxa","panturrilhas","glúteos"]', '[]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1464/view/', 'pause hack squats quadriceps posteriores de coxa panturrilhas gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('71b9da1a-ac07-49c8-8b2d-7179032181fd', 1904, 'en', 'Pec Deck', 'Pectoral issolation exercise - full range of motion is best with full contraction and slow negative', 'peito', '["peito"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1904/view/', 'pec deck peito', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e797ca42-f9fc-480a-8f48-7f6905978c72', 1775, 'en', 'Pec deck rear delt fly', 'Seated rear delt fly on pec deck machine (facing the machine and extending arms backwards, the hands should be at the height of the shoulders)', 'ombros', '["ombros"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'eufvksruh', 'https://wger.de/en/exercise/1775/view/', 'pec deck rear delt fly ombros', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('cf935163-d2b7-4740-8421-99140da5fd58', 2556, 'en', 'Pelvic Endurance Hold', 'Low to moderate intensity pelvic floor endurance hold. Prioritize controlled breathing and complete relaxation after the hold.', 'core', '["core"]', '[]', '[]', NULL, 'CC-BY-SA 3', '', 'https://wger.de/en/exercise/2556/view/', 'pelvic endurance hold core', '2026-09-10T15:18:12.614Z');
