INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('748e9635-7958-4a41-b1ed-93de74c7ef72', 448, 'en', 'Pendelay Rows', 'Back excercise with a barbell with a starting position which is in a bent over position with the back paralell to the ground. The barbell is on the ground at chest level.For the movement grab the barbell at shoulder width grip and pull towards your chest without losing the bent over position and without moving anything but your arms', 'costas', '["dorsais","trapézio"]', '["bíceps","tríceps"]', '["Barra"]', NULL, 'CC-BY-SA 3', 'Nallitnas', 'https://wger.de/en/exercise/448/view/', 'pendelay rows dorsais trapezio biceps triceps barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('daaf1459-e748-4c95-8990-ed3101b2e20d', 1521, 'en', 'Pendular hack', 'Pendulum hack, made on a pendulum machine', 'pernas', '["pernas"]', '[]', '[]', 'https://wger.de/media/exercise-images/1521/e4e4aa78-3c96-4b1d-95c0-f9f73a0779d0.webp', 'CC-BY-SA 4', 'polloperro', 'https://wger.de/en/exercise/1521/view/', 'pendular hack pernas', '2026-09-10T15:18:12.614Z');
