INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7ae1aca7-cdd4-4a81-b22c-f31778462b6b', 1580, 'en', 'Perpendicular Unilateral Landmine Row', 'Using a landmine attachment with the barbell running at 90 degrees to either side, hinge slightly at the hips and grip the barbell by the plate sleeve. Raise the barbell to chest height, with your upper arm parallel to the floor at the top of the movement.', 'ombros', '["ombros","trapézio"]', '[]', '["Barra"]', NULL, 'CC-BY-SA 4', 'CptnFatbeard', 'https://wger.de/en/exercise/1580/view/', 'perpendicular unilateral landmine row ombros trapezio barra', '2026-09-10T15:18:12.614Z');
