INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('abd2854b-114a-4584-8746-30bd40127863', 1436, 'en', 'Pin Bench Press BB', '• Set security pins to about the height of your sticking point

