INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('12418067-6cb5-44db-8973-b5be25c0146b', 1766, 'en', 'Plank Reach', 'Position your body in plank position, keeping your eyes on the ground. Raise one arm in front of you and return it. Repeat with the other arm. Raise and return slowly while keeping your body as still as possible.', 'core', '["abdômen"]', '["ombros","oblíquos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1766/view/', 'plank reach abdomen ombros obliquos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('75d730d0-3b26-4a25-8f1a-7119a98e02ef', 1091, 'en', 'Plank Shoulder Taps', 'In the correct plank position, place your feet slightly wider than shoulder-width apart. alternately lift and touch the opposite shoulder with one hand.', 'core', '["ombros","glúteos","abdômen"]', '["dorsais"]', '["Colchonete"]', 'https://wger.de/media/exercise-images/1091/50c8912d-54ef-46c9-99d1-633b6196aa1e.jpg', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1091/view/', 'plank shoulder taps ombros gluteos abdomen dorsais colchonete', '2026-09-10T15:18:12.614Z');
