INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e75629ed-4991-4a48-984c-b297f3f9fb58', 1406, 'en', 'Plank-to-Elbow Extension', 'The Plank-to-Elbow Extension is a dynamic exercise that combines the plank with an elbow extension movement', 'core', '["ombros","abdômen","tríceps"]', '["oblíquos","peito"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1406/view/', 'plank-to-elbow extension ombros abdomen triceps obliquos peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f397656d-6f26-47c6-9e4c-221687f3f2fa', 1275, 'en', 'Plantarflexion Stretch with Band', 'This stretch is for the ankles, as well as Tibialis anterior.', 'pernas', '["pernas"]', '[]', '["Elástico"]', 'https://wger.de/media/exercise-images/1275/0652d306-93eb-42f0-b564-7c3261ea809a.png', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1275/view/', 'plantarflexion stretch with band pernas elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('493fb1ac-c45a-4b18-bcbb-58b809881e6f', 1430, 'en', 'Plate Pinch Hold', 'The plate pinch hold is a grip strength exercise designed to target the forearms and improve grip endurance. Select one or two weight plates (smooth-edged plates work best) and pinch them together between your thumb and fingers. Hold the plates with your arm straight down by your side or extended slightly in front of you. Maintain the hold for as long as you can, keeping your shoulders relaxed and your grip firm. This exercise can be done for time or repetitions.', 'braços', '["ombros"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1430/view/', 'plate pinch hold ombros', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0e8fd83f-4e97-4749-b5fd-da9d0e85e97a', 2488, 'en', 'Posterior Pelvic Tilt', 'Lie on your back with knees bent, feet flat on the floor. Flatten your lower back against the floor by tilting your pelvis posteriorly, engaging your abs and glutes. Hold 5 seconds, release. This retrains pelvic positioning to counter anterior pelvic tilt.', 'core', '["abdômen"]', '["glúteos","oblíquos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Raj', 'https://wger.de/en/exercise/2488/view/', 'posterior pelvic tilt abdomen gluteos obliquos peso corporal', '2026-09-10T15:18:12.614Z');
