INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('dd52fb99-9426-4a78-b446-20a8e3e4ec47', 465, 'en', 'Preacher Curls', 'Place the EZ curl bar on the rest handles in front of the preacher bench. Lean over the bench and grab the EZ curl bar with palms up. Sit down on the preacher bench seat so your upper arms rest on top of the pad and your chest is pressed against the pad. Lower the weight until your elbows are extended and arms are straight. Bring the weights back up to the starting point by contracting biceps. Repeat', 'braços', '["braquial"]', '[]', '["Barra W"]', 'https://wger.de/media/exercise-images/193/Preacher-curl-3-1.png', 'CC-BY-SA 3', 'cgoob883', 'https://wger.de/en/exercise/465/view/', 'preacher curls braquial barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f9866335-e489-404b-84b5-248fb8512702', 1208, 'en', 'Prisoner Squat', 'Stand upright with your chest slightly raised, your feet hip-width apart and your toes pointing straight ahead.
Bring your hands to the back of your head with your fingers slightly interlaced and your elbows pointing to the side. Push your hips back and bend your knees, keeping your upper body as upright as possible. 
Push your knees outwards, they must never point towards each other. If your upper body moves slightly forward, make sure that it does not bend. Always keep your elbows level with your ears by tensing the muscles between your shoulder blades. If you are flexible enough, you can sink down until your buttocks touch your calves.
However, make sure that you do not bend your spine. 
Before this happens, reverse the movement and use your heels and glutes to push yourself upwards with so much momentum that your feet lift off briefly and you do a little hop. 
If necessary, correct the position of your feet, arms and upper body before you move on to the next repetition.
Translated with www.DeepL.com/Translator (free version)', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'lxmx', 'https://wger.de/en/exercise/1208/view/', 'prisoner squat gluteos quadriceps posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
