INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1f490456-b426-4b89-b70c-e155c3571422', 1696, 'en', 'Pull-Ups (Neutral Grip)', 'Execution 
 

• 
 Pulling phase (concentric): 

 

• Drive your elbows down and back , pulling your chest toward your hands .

• Keep your shoulders depressed and retracted (avoid shrugging).

• Focus on squeezing your lats and upper back at the top.

• 
 Top position: 

 

• Chin should clear or reach the level of your hands.

• Pause briefly and contract your lats hard.', 'costas', '["dorsais"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1696/view/', 'pull-ups (neutral grip) dorsais', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('be4eb0b6-2c39-4ff5-b57d-419f1687c90f', 1695, 'en', 'Pull-Ups (Wide Grip)', 'Execution 

 

• 
 Pulling phase (concentric): 

 

• Drive your elbows down and slightly back , pulling your chest toward the bar .

• Focus on leading with your chest , not your chin.

• Keep your shoulders depressed (avoid shrugging).

• 
 Top position: 

 

• Chin should clear the bar (or at least reach bar level).

• Pause for a brief squeeze in your lats .', 'costas', '["dorsais"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1695/view/', 'pull-ups (wide grip) dorsais peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('289bd40b-e3dd-4217-8670-e475771a0ea7', 1905, 'en', 'Pullback', 'Set weight and grip for the cables in the cage. Take a few steps away, bend over, pull and extend the back at the same time.', 'costas', '["bíceps","dorsais"]', '["braquial"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1905/view/', 'pullback biceps dorsais braquial maquina de cabo', '2026-09-10T15:18:12.614Z');
