INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4284336c-6cfa-4c4d-a440-26b30db035d1', 478, 'en', 'Push Press', 'Clean your dumbbells onto your shoulders, palms facing in. Take a breath and brace your core. (picture 1)Dip at the knees and use your legs to help (picture 2) press your dumbbells overhead. Lower under control with a slow tempo to your shoulders and repeat.', 'ombros', '["trapézio"]', '["glúteos"]', '[]', 'https://wger.de/media/exercise-images/478/70a2d72c-a822-45f3-8de2-54ea85951b84.jpg', 'CC-BY-SA 3', 'sistab2', 'https://wger.de/en/exercise/478/view/', 'push press trapezio gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f5b84269-18af-4464-a61f-b767cbcd81dc', 1551, 'en', 'Push-Up', 'The push-up is a fundamental bodyweight exercise that targets the chest, arms, and shoulders while engaging the core for stability. It requires no equipment and is excellent for building upper body strength.

 Instructions:

 

• Start in a plank position with hands placed slightly wider than shoulder-width, feet together, and body in a straight line from head to heels.

• Engage your core and lower your body by bending your elbows, keeping them close to your body or flared slightly outward.

• Lower until your chest nearly touches the ground while maintaining a neutral spine.

• Push through your palms to return to the starting position, fully extending your arms.', 'peito', '["peito"]', '["ombros","abdômen","tríceps"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1551/a6a9e561-3965-45c6-9f2b-ee671e1a3a45.png', 'CC-BY-SA 4', 'Settebello', 'https://wger.de/en/exercise/1551/view/', 'push-up peito ombros abdomen triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('50037aaf-34f1-4018-b504-206623b77c46', 1112, 'en', 'Push-Ups | Decline', 'Decline push-ups are another modified version of the traditional push-up that target the upper body muscles in a different way. To perform a decline push-up, elevate your feet on an elevated surface, such as a bench, chair, or step, while placing your hands on the ground in a push-up position. Lower your body towards the ground while maintaining a straight line from your shoulders to your ankles, and then push back up to the starting position.
Unlike the inclined push-up, the decline push-up places more emphasis on the shoulders and triceps, while still engaging the chest muscles to a lesser extent. By elevating your feet, you increase the difficulty of the exercise by placing more weight on your upper body, forcing your shoulders and triceps to work harder to push your body back up. The decline push-up can be a great way to challenge your upper body strength and improve your ability to perform other push-up variations. As with any exercise, be sure to use proper form and start with a height that is appropriate for your strength and fitness level.', 'peito', '["peito"]', '["ombros","tríceps"]', '["Banco","Banco inclinado"]', 'https://wger.de/media/exercise-images/1112/81f40bee-4adf-4317-8476-1a87706e3031.png', 'CC-BY-SA 4', 'anon1337', 'https://wger.de/en/exercise/1112/view/', 'push-ups | decline peito ombros triceps banco banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4aa7e2a7-86ad-4322-978f-ff8b391f556c', 1111, 'en', 'Push-Ups | Incline', 'Inclined push-ups primarily target the chest muscles (pectoralis major and minor), but also work the triceps, shoulders, and core to a lesser extent. Because the upper body is elevated, the incline push-up places less emphasis on the triceps compared to regular push-ups, which may be beneficial for individuals looking to specifically target their chest muscles.', 'peito', '["peito"]', '["tríceps"]', '["Banco","Banco inclinado"]', NULL, 'CC-BY-SA 4', 'anon1337', 'https://wger.de/en/exercise/1111/view/', 'push-ups | incline peito triceps banco banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('bd141adb-b9ad-4038-b11f-1db8665f72bc', 1113, 'en', 'Push-Ups | Parallettes', 'Parallettes push-ups are a variation of the traditional push-up that are performed with the hands on parallel bars, known as parallettes. To perform a parallettes push-up, assume a push-up position with your hands on the parallettes and your feet on the ground. Lower your body towards the ground while keeping your elbows close to your sides, and then push back up to the starting position.
Parallettes push-ups place more emphasis on the chest and shoulders compared to traditional push-ups, as they allow for a greater range of motion in the shoulder joint. This increased range of motion can also help to improve shoulder stability and mobility. Additionally, parallettes push-ups engage the core muscles more than traditional push-ups, as the instability of the parallettes requires greater activation of the core muscles to maintain proper form.
The added challenge of balancing on the parallettes also requires greater upper body strength and control, making parallettes push-ups a more advanced variation of the traditional push-up. They can be a great way to challenge yourself and add variety to your upper body workout routine. As always, be sure to use proper form and start with a level that is appropriate for your strength and fitness level.', 'peito', '["peito"]', '["ombros","tríceps"]', '[]', NULL, 'CC-BY-SA 4', 'anon1337', 'https://wger.de/en/exercise/1113/view/', 'push-ups | parallettes peito ombros triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2867cd51-f911-47db-9ea5-ca09aa44ca8f', 2617, 'en', 'Quad Sets', 'What Are Quad Sets?
 Quad sets are a fundamental exercise used in knee rehabilitation. They focus on strengthening the quadriceps muscles located at the front of the thigh. This exercise is particularly beneficial for individuals recovering from knee injuries or surgeries.

How to Perform Quad Sets
Steps to Execute Quad Sets
 

• Positioning: Sit or lie down with your legs straight.

• Tightening: Tighten the quadriceps muscles while keeping the leg straight. You should see the kneecap move upward.

• Holding: Maintain the contraction for about 5 seconds.

• Releasing: Relax the muscle after the hold.

• Repetitions: Aim for 10 to 15 repetitions, gradually increasing as strength improves.

Tips for Effective Quad Sets
 

• Ensure no other muscles are contracting to assist the quadriceps.

• Perform the exercise on a flat surface, like a bed or couch, with a towel or pillow under your heel for comfort.

• It is recommended to do these exercises multiple times a day, especially during the early stages of recovery.

Benefits of Quad Sets
 

• Restores Muscle Function: Helps rebuild strength in the quadriceps.

• Improves Stability: Enhances stability in the knee joint.

• Increases Range of Motion: Aids in regaining mobility after injury or surgery.

 Incorporating quad sets into your rehabilitation routine can significantly aid in recovery and improve overall knee function.', 'pernas', '["pernas"]', '[]', '["Colchonete"]', NULL, 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/2617/view/', 'quad sets pernas colchonete', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6c6d7b02-20e1-49ac-b734-f5ee5f72f5a3', 1873, 'en', 'Quad Stretch', 'View the video to undestand the exercise', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1873/c0ed299b-6d87-4d90-885d-bb3b5d85f1eb.png', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1873/view/', 'quad stretch pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('80c167b9-3749-48a1-8686-fc2163a1e7fb', 957, 'en', 'Quadriped Arm and Leg Raise', 'In this exercise, the back muscles and the muscles of the back of the leg and back of the arm are activated by lifting the crossed arm and leg at the same time in the crawling position. It also improves balance and proprioception. The movement is done symmetrically.

 

• Get into a crawling posture.2. Draw your abdomen in, then raise your right leg and left arm.3. You should keep your abdomen in for 8 seconds.4. After 8 seconds, slowly lower your arm and leg.5. Then release your muscle.', 'costas', '["ombros","glúteos","serrátil","trapézio"]', '["dorsais"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/957/0fd94587-6021-4763-856e-7227f5fcba2a.png', 'CC-BY-SA 4', 'utkb', 'https://wger.de/en/exercise/957/view/', 'quadriped arm and leg raise ombros gluteos serratil trapezio dorsais peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2a1f7c0c-c63d-43f1-9934-a209ed405ff8', 1915, 'en', 'Quadruped Hip Abduction', 'Distribute your body weight evenly on all knees and arms.
Keep the torso stable, with the abdomen engaged and the lumbar spine
straight without twisting the back (imagine: a glass on your lower back
won''t fall off). Raise one leg outwards without twisting it.

 Pay attention to the right angle at the hips and knees. Always train both sides of the body.

 To increase resistance, a resistance band can be used.', 'panturrilhas', '["panturrilhas"]', '[]', '["Elástico"]', NULL, 'CC-BY-SA 4', 'treder', 'https://wger.de/en/exercise/1915/view/', 'quadruped hip abduction panturrilhas elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('25854f7a-485a-4280-a0fa-f024655733b0', 1028, 'en', 'Quadruped thoracic rotation left', 'Starting position: 
Start kneeling on all fours, knees shoulder-width apart. Place your left hand behind your head while keeping your right hand outstretched and touching the floor.
 Steps: 

 

• On inhale, move your left elbow toward your right hand, keeping your left hand behind your head.

• On exhale, move your left elbow to point up toward the ceiling.

• Repeat.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1028/view/', 'quadruped thoracic rotation left costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('da588c5e-ab8b-42a7-a52c-1e680a484334', 1029, 'en', 'Quadruped thoracic rotation right', 'Starting position: 

 Start kneeling on all fours, knees shoulder-width apart. Place your right hand behind your head while keeping your left hand outstretched and touching the floor.

 Steps: 

 

• On inhale, move your right elbow toward your left hand, keeping your right hand behind your head.

• On exhale, move your right elbow to point up toward the ceiling.

• Repeat.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1029/view/', 'quadruped thoracic rotation right costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('914bbd2a-6be5-4475-b39d-fd3d6af529f9', 2562, 'en', 'Quick Kegels', 'Brief controlled pelvic floor contractions with full relaxation between repetitions.', 'core', '["core"]', '[]', '[]', NULL, 'CC-BY-SA 3', '', 'https://wger.de/en/exercise/2562/view/', 'quick kegels core', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6c21c09b-90c8-4e43-a43c-ed566f812784', 1287, 'en', 'Reach ups', 'To perform this exercise, lie on your back with your arms extended overhead. Then, contract your abdominals and lift your torso off the floor while reaching your arms toward the ceiling to "reach" as high as possible. Slowly return to the starting position, controlling the movement. Reach ups strengthen the abdominal muscles and improve the flexibility of the spine. They can be incorporated into a variety of training routines to work on core strength and stability.', 'core', '["oblíquos"]', '["abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'painDpice', 'https://wger.de/en/exercise/1287/view/', 'reach ups obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3f93459a-d06e-465c-85db-2137da759440', 487, 'en', 'Rear Delt Raises', 'Seated on a bench with the dumbbells on the floor bend over at 45 Degrees and then slowly raise each dumbbell to shoulder height and hold for a couple seconds before lowering to the starting position.', 'ombros', '["ombros"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/487/ad724e5c-b1ed-49e8-9279-a17545b0dd0b.png', 'CC-BY-SA 3', 'YYCfit', 'https://wger.de/en/exercise/487/view/', 'rear delt raises ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2f2192c3-6e95-41b5-9438-2f1497f56767', 1960, 'en', 'Rear-foot-elevated Hip Flexor Stretch', 'Rear-foot-elevated Hip Flexor Stretch
Part of: Limber 11
Source: Joe DeFranco
Prescription: 5-10 reps each side
Type: dynamic
Includes dynamic movement plus 3s hold.', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1960/view/', 'rear-foot-elevated hip flexor stretch pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6705ec92-c6c6-4b2c-b919-bddb8177bf98', 2486, 'en', 'Recovery Bobbing', 'Same motion as the Bobbing Exhale Drill, but done in slightly deeper water (so you''re not touching the bottom) and at a slower, more relaxed pace — think of it as a recovery/reset exercise rather than a hard drill. Use it between harder drills to reset your breathing rhythm and calm down if you''re feeling rushed or out of sync.', 'cardio', '["abdômen"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2486/view/', 'recovery bobbing abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('cf434716-f846-46d8-b267-8b33d311d8b5', 1216, 'en', 'Recruitment Pulls', 'Find a few specific edge sizes on a hangboard, get fixed underneath them with the board overhead, and pull with max effort, 1 arm at a time, for 3-5 seconds. When positioning for this get set up with a large elbow angle (120-150 degrees) and not in full extension.', 'braços', '["braços"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1216/view/', 'recruitment pulls bracos', '2026-09-10T15:18:12.614Z');
