INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('443fec2e-dcca-46fe-ab4a-9a8beb50891e', 1120, 'en', 'Remo maquina agarre estrecho supino', 'Remo en máquina o polea con agarre cerrado supino', 'costas', '["dorsais"]', '["bíceps","trapézio"]', '[]', 'https://wger.de/media/exercise-images/1120/df9a5256-e977-44d0-bc9c-b53253faeb22.png', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1120/view/', 'remo maquina agarre estrecho supino dorsais biceps trapezio', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2b6c09f7-dbf1-45ea-baf6-9a12e0b12396', 490, 'en', 'Renegade Row', 'Get into pushup position gripping some dumbbells. Perform one pushup, then drive your left elbo up, bringing the dumbell up to your body. Return the dumbell to starting position.

 Perform another pushup and then row with the other arm to complete one rep.', 'costas', '["dorsais","trapézio"]', '[]', '["Halteres"]', NULL, 'CC0', 'fletchgraham', 'https://wger.de/en/exercise/490/view/', 'renegade row dorsais trapezio halteres', '2026-09-10T15:18:12.614Z');
