INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('39c13706-6a8c-4ab5-b605-b9b716665a20', 1473, 'en', 'Reverse Cable Flye', 'Attach D-Handles to two cable pulleys in the upper position. Grab the left on with your right hand and vice-versa.', 'costas', '["ombros"]', '["trapézio"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1473/view/', 'reverse cable flye ombros trapezio maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('cf6bf132-fe21-4b70-8f73-006545246f05', 2448, 'en', 'Reverse Clamshell', 'Lie on your side with your hips and knees bent, keeping your knees stacked on top of each other. Keep your feet together at first, then keep your knees touching while lifting your top foot upward. Slowly lower the foot back down with control.

 Move only through the hip and avoid rolling your pelvis backward. The movement should be small, controlled, and focused on hip rotation.', 'pernas', '["glúteos"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'TobiasFalk', 'https://wger.de/en/exercise/2448/view/', 'reverse clamshell gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5d8d3581-bce5-4a28-868f-8b299eaedbdd', 1772, 'en', 'Reverse crunch', '• Lay down

• Place your hands near your butt (often slightly in front or under or both)

• Raise your legs, but about 70% of the way you should be able to also raise your pelvis

• (optional/variable) Hold 1/2 seconds at the top

• Go back to starting position', 'core', '["abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'eufvksruh', 'https://wger.de/en/exercise/1772/view/', 'reverse crunch abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2cd5e3c6-a8c0-456a-ab47-5e7b3a435407', 495, 'en', 'Reverse Curl', 'The reverse-grip barbell curl is a variation on the biceps curl where the palms face downward. The switch from an underhand to an overhand grip brings the forearm and brachialis muscles more into the exercise.', 'braços', '["bíceps","braquial"]', '[]', '["Barra","Halteres"]', NULL, 'CC0', 'BFad07', 'https://wger.de/en/exercise/495/view/', 'reverse curl biceps braquial barra halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('960697af-9a0e-4bfd-a8ba-989718b6b5c7', 914, 'en', 'Reverse EZ Bar Cable Curls', 'Standing in front of cable tower using a SZ Bar', 'braços', '["bíceps"]', '[]', '["Máquina de cabo","Barra W"]', NULL, 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/914/view/', 'reverse ez bar cable curls biceps maquina de cabo barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('440cf10c-effb-4b63-a6e0-182fe47376f6', 1709, 'en', 'Reverse Fly Standing', '• Stand with a good posture holding a cable in each hand opposite the machine

• Starting with the hands in front of your chest pull the arms out to
your side into the shape of a T with the elbows nearly straight

• Slowly release the arms forward to the start

• Repeat with the arms moving into the shape of a Y

• Repeat with the arms in the shape of a W

• Repeat with the arms in the shape of an L by your side', 'ombros', '["ombros","trapézio"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1709/view/', 'reverse fly standing ombros trapezio maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('dd6e8753-a574-476e-900a-b794eb592e7b', 1290, 'en', 'Reverse Grip Barbell Curls', 'Hold the barbell with an overhand grip (palms facing down) approximately shoulder-width apart. Ensure your back is straight, shoulders slightly pulled back, and arms fully extended.
Curl the barbell upwards towards your chest in a controlled motion, keeping your elbows close to your body. The motion should be smooth without any swinging or momentum use.
Once the barbell is at chest level, pause briefly to maximize contraction in the biceps and forearms.
Slowly lower the barbell back to the starting position with a controlled movement, fully extending your arms.', 'braços', '["bíceps"]', '["braquial"]', '["Barra"]', 'https://wger.de/media/exercise-images/1290/c05818bf-1c81-46df-9f24-42e354265388.png', 'CC-BY-SA 4', 'sTiKyt', 'https://wger.de/en/exercise/1290/view/', 'reverse grip barbell curls biceps braquial barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1b95d961-1d5c-4ded-b25e-c090295ffe37', 498, 'en', 'Reverse Grip Bench Press', 'Upper chest focuses exercise that also works triceps', 'peito', '["peito","tríceps"]', '["ombros"]', '["Barra","Banco"]', NULL, 'CC-BY-SA 4', 'bl0sh', 'https://wger.de/en/exercise/498/view/', 'reverse grip bench press peito triceps ombros barra banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('682ea312-af02-450a-9880-fea7bf8e854a', 1809, 'en', 'Reverse Hyperextension', 'Lie face-down on a bench with your legs hanging off the edge.

 

• Bend your hips so your thighs are vertical, bending your knees at the same time so your shins stay horizontal.

• Straighten out your legs so they are not bent and your toes are pointing backwards horizontally.

• Return to the original position, and repeat.', 'pernas', '["posteriores de coxa","glúteos"]', '[]', '["Banco"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1809/view/', 'reverse hyperextension posteriores de coxa gluteos banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6cbdd70c-0691-4288-b58a-24001384f1b3', 909, 'en', 'Reverse Nordic Curl', 'Natural Leg Extension is alternative to Leg Extension machine with no equipment.', 'pernas', '["quadríceps"]', '["glúteos","abdômen"]', '[]', 'https://wger.de/media/exercise-images/909/159222d9-c1e4-46ae-89ee-6a2dfaab978d.png', 'CC-BY-SA 4', 'karly', 'https://wger.de/en/exercise/909/view/', 'reverse nordic curl quadriceps gluteos abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('09349391-375b-42d5-8979-00a5d7196a5b', 500, 'en', 'Reverse Plank', 'Plank with stomach towards ceiling', 'core', '["core"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'spacetowaste', 'https://wger.de/en/exercise/500/view/', 'reverse plank core peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('edc44b1a-35d7-4c37-ab20-05842fb40576', 913, 'en', 'Reverse Preacher Curl (Close Grip)', 'Sitting reverse on a Biceps Bench with a close grip', 'braços', '["bíceps"]', '[]', '["Barra W"]', NULL, 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/913/view/', 'reverse preacher curl (close grip) biceps barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('603895ca-20a0-4272-a62b-293d14220390', 1215, 'en', 'Reverse Snow Angel', 'Lay flat on your stomach with your arms extended in front of you on the ground as your legs are lying flat. Lift both your arms and move them to your side slowly. Then, move them back.', 'costas', '["trapézio"]', '["ombros","posteriores de coxa","glúteos","oblíquos","abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'mike6426', 'https://wger.de/en/exercise/1215/view/', 'reverse snow angel trapezio ombros posteriores de coxa gluteos obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('04063ba5-05d1-48b9-9571-eae2b8edab29', 2620, 'en', 'Reverse V-Squat', 'Single-Leg Soft-Landing Holds
 Single-leg soft-landing holds are exercises that focus on balance and stability by landing softly on one leg and holding the position. This exercise helps improve proprioception and can be beneficial for rehabilitation and athletic training.

Overview
 Single-leg soft-landing holds are exercises designed to enhance balance, stability, and proprioception. They involve landing softly on one leg and maintaining that position for a brief period. This exercise is particularly useful in rehabilitation settings and for athletes looking to improve their performance.

Benefits
 

• Improves balance: Enhances stability by training the body to control weight distribution on one leg.

• Enhances proprioception: Increases awareness of body position, which is crucial for injury prevention.

• Supports rehabilitation: Helps individuals recover from lower-limb injuries by strengthening muscles and improving joint stability.

How to Perform Single-Leg Soft-Landing Holds
Steps
 

• Preparation: Stand on a stable surface or a box.

• Takeoff: Step off the box or surface with one leg, ensuring that you do not jump.

• Landing: Land softly on the target leg, allowing the knee and hip to bend slightly.

• Hold position: Maintain balance in the landed position for up to 2 seconds.

• Reset: Return to the starting position and repeat.

Key Points to Remember
 

• Keep your chest up and engage your core for better stability.

• Ensure your knee aligns with the midline of your foot during landing.

• Focus on a controlled descent to minimize impact.

Conclusion
 Incorporating single-leg soft-landing holds into your training routine can significantly enhance your balance and stability, making it a valuable exercise for both rehabilitation and athletic performance.', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa"]', '[]', 'https://wger.de/media/exercise-images/2620/561eb05a-b0e4-4cde-a338-5855a30dffd4.jpg', 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/2620/view/', 'reverse v-squat gluteos quadriceps posteriores de coxa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6f5d4373-66d1-4acd-a16f-ba0e636fe979', 1433, 'en', 'Reverse Wood Chops', '• Attach a looping resistance band to a rack below knee height

• Grip the other end of the band like holding a baseball bat with both hands

• Stretch the band facing it

• Start with your hands at the side of your hips, knees bent

• Rotate your hips while moving your hands towards over the top of your opposite shoulder

• Imagine the motion as striking a baseball with a bat', 'costas', '["glúteos","dorsais"]', '["ombros","bíceps","oblíquos","quadríceps","abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1433/view/', 'reverse wood chops gluteos dorsais ombros biceps obliquos quadriceps abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2acb5ba1-caa3-4204-9903-ff0095b032ba', 1292, 'en', 'Reverse-grip pull-ups', 'Pull-ups on the bar with your thumbs pointing outward.', 'core', '["bíceps","dorsais"]', '["abdômen"]', '["Barra fixa"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1292/view/', 'reverse-grip pull-ups biceps dorsais abdomen barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8374a856-9293-4b90-900e-00c3bfe21cc4', 1014, 'en', 'Right levator scapulae stretch', 'Starting position:

 Start standing up or sitting down. Turn your head to the right, around 45 degrees or just above your nipple. Place your left hand behind your back or sit on it. Take your right hand and use it to hold the back of your head. Lean your head down slightly.

 Steps:

 

• After assuming the starting position, press your head against your right hand with slight force. Your hand should press back with equal force, so that your head doesn''t move. Hold this position.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1014/view/', 'right levator scapulae stretch costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7671b16c-5023-4663-b00d-86dd018e024f', 501, 'en', 'Ring Dips', 'Dips peformed on gymnastic rings.', 'braços', '["tríceps"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Nash', 'https://wger.de/en/exercise/501/view/', 'ring dips triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6c9c9d14-e6bf-43ed-9859-a689e2131fe0', 1832, 'en', 'Ring Support Hold', 'Hold yourself in a support position on gymnastic rings with arms straight at sides. Focus on keeping rings turned out slightly and maintaining hollow body position. This is an isometric hold for chest, shoulders, and triceps.', 'peito', '["peito"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1832/view/', 'ring support hold peito', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0dfe655e-ee2e-4c49-a279-c672d5591613', 1485, 'en', 'Rocking Triceps Pushdown', 'Set your feet below the rope and lean your upper body towards the rope. Set one foot back. Push down the rope and lean your entire body back onto the rear foot as you push down to get your hands behind your body. Don''t forget to bring your chest to the front during the pushdown. As you release the rope slowly, lean your body back onto the front foot.', 'braços', '["tríceps"]', '[]', '["Máquina de cabo","Barra W"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1485/view/', 'rocking triceps pushdown triceps maquina de cabo barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d5ee3b1f-2879-406f-97a9-51a8b0817cd4', 1399, 'en', 'Roll Down', 'Stand with your feet hip-width apart and slowly roll your upper body forward, one vertebra at a time, until your hands touch the ground or as far as you can comfortably go. Roll back up to the starting position in the same controlled manner.', 'costas', '[]', '["posteriores de coxa"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1399/view/', 'roll down posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('752c0380-a0f9-4332-8265-cf503bac4703', 1954, 'en', 'Roll-overs into V-sits', 'Roll-overs into V-sits
Part of: Limber 11
Source: Joe DeFranco
Prescription: 10 reps
Type: dynamic', 'pernas', '["pernas"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1954/view/', 'roll-overs into v-sits pernas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4519f85a-9191-4224-89e6-90fe71f4e045', 2547, 'en', 'roman chair', 'A hip-hinge machine where you position yourself face-down at an angle, with a pad behind your calves/lower legs to anchor you and a pad in front of your hips/thighs. From there, you bend forward at the hips, then drive back up by squeezing your glutes and hamstrings — essentially a machine-guided RDL pattern.', 'pernas', '["posteriores de coxa","glúteos"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'ckzk', 'https://wger.de/en/exercise/2547/view/', 'roman chair posteriores de coxa gluteos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('af2f774c-296c-4d14-8e4a-fad77175ae37', 505, 'en', 'Roman Chair Crunch', 'Crunches on roman chair. Keep your torso straight, abs tight, and don''t come up all the way vertical or lie flat to keep constant tension on your abs.', 'core', '["abdômen"]', '["oblíquos"]', '[]', NULL, 'CC-BY-SA 3', 'MaddieBeasley', 'https://wger.de/en/exercise/505/view/', 'roman chair crunch abdomen obliquos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2e7ffff9-e603-4b28-98c8-31d1a6ce8cd9', 507, 'en', 'Romanian Deadlift', 'DL from top to pos 2: https://www.youtube.com/watch?v=WtWtjViRsKo', 'pernas', '["posteriores de coxa","glúteos"]', '["trapézio"]', '["Barra"]', 'https://wger.de/media/exercise-images/507/13d526ab-12fc-461e-828a-051dd7c13fb1.png', 'CC-BY-SA 4', 'pjwirth', 'https://wger.de/en/exercise/507/view/', 'romanian deadlift posteriores de coxa gluteos trapezio barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('148f2ffc-05e2-486b-874f-2a401337a1c6', 1634, 'en', 'Rope Pullover/row', 'Set up bench in front of cable row machine. Lean over bench to do a row/pullover with rope that targets lats. See picture.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo","Banco inclinado"]', 'https://wger.de/media/exercise-images/1634/9a4704d3-1b25-43e3-b244-3885f4d3db87.png', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1634/view/', 'rope pullover/row dorsais maquina de cabo banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('849f2fa6-42f9-4c59-90f6-275c8ada6725', 1374, 'en', 'Rotary Torso Machine', '• Slow and Steady

• Not too much weight', 'core', '["abdômen"]', '[]', '[]', NULL, 'CC-BY-SA 4', '6LXBO', 'https://wger.de/en/exercise/1374/view/', 'rotary torso machine abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4b7cb037-0789-4014-ab6f-a451716b7538', 508, 'en', 'Row', 'In strength training, rowing (or a row, usually preceded by a qualifying adjective — for instance a seated row) is an exercise where the purpose is to strengthen the muscles that draw the rower''s arms toward the body (latissimus dorsi) as well as those that retract the scapulae (trapezius and rhomboids) and those that support the spine (erector spinae). When done on a rowing machine, rowing also exercises muscles that extend and support the legs (quadriceps and thigh muscles). In all cases, the abdominal and lower back muscles must be used in order to support the body and prevent back injury.', 'costas', '["dorsais","trapézio"]', '["quadríceps"]', '["Barra","Halteres","Barra fixa"]', NULL, 'CC0', 'BFad07', 'https://wger.de/en/exercise/508/view/', 'row dorsais trapezio quadriceps barra halteres barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f6d8e157-c233-4a22-9c1a-83cb8f613ea5', 1093, 'en', 'Rowing Machine', 'Sit on a rowing machine with your back straight.', 'cardio', '["ombros","bíceps","posteriores de coxa","braquial","panturrilhas","glúteos","dorsais","oblíquos","quadríceps","abdômen","serrátil","sóleo","trapézio"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Boertie', 'https://wger.de/en/exercise/1093/view/', 'rowing machine ombros biceps posteriores de coxa braquial panturrilhas gluteos dorsais obliquos quadriceps abdomen serratil soleo trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('00fcf603-b0d0-48d2-9b5e-c7f0d510d46c', 512, 'en', 'Rowing seated, narrow grip', '• Tighten muscles

• Controlled movement

• Slow movement

• Keep upper body upright

• Do not lean back

• Pull toward chest', 'costas', '["dorsais"]', '[]', '[]', 'https://wger.de/media/exercise-images/512/b938437e-ff00-4679-9036-acb41bb28bbd.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/512/view/', 'rowing seated, narrow grip dorsais', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8766d43c-e035-4c37-b824-b94dce5bf710', 674, 'en', 'Rowing with TRX band', 'Rowing with resistance bands - Bodyweight Exercise', 'costas', '["dorsais"]', '["bíceps","trapézio"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Skadi', 'https://wger.de/en/exercise/674/view/', 'rowing with trx band dorsais biceps trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('32c129f7-cc28-4ebc-8465-e4fa62e220b1', 513, 'en', 'Rowing, T-bar', 'The execution of this exercise is very similar to the regular bent over rowing, only that the bar is fixed here.

 Grab the barbell with a wide grip (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest''s out during the whole exercise. Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don''t swing with your body and keep your arms next to your body.', 'costas', '["dorsais"]', '["ombros","bíceps","braquial"]', '[]', 'https://wger.de/media/exercise-images/106/T-bar-row-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/513/view/', 'rowing, t-bar dorsais ombros biceps braquial', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('4221c8af-b3ca-4a53-9176-bd66e46d10f2', 1613, 'en', 'rubber band glute kickback', 'A rubber band glute kickback is an exercise performed on hands and knees, where you anchor a resistance band to your foot and kick your heel back and up, squeezing your glute at the top of the movement, while maintaining a stable core and flat back to target and strengthen the gluteal muscles.', 'pernas', '["glúteos"]', '[]', '["Elástico"]', 'https://wger.de/media/exercise-images/1613/a851fe9d-771f-44da-82f0-799e02ae3fd1.jpg', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1613/view/', 'rubber band glute kickback gluteos elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('92cd0459-5cd1-46a0-934d-e7cff8d4ccda', 1874, 'en', 'Runners Lunge Stretch', 'View the video to undestand the exercise', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1874/66fca8a5-41e8-42d1-8776-5e46a4902650.png', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1874/view/', 'runners lunge stretch pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('58ba2ce1-c140-4a9f-9bbc-d99776909690', 2530, 'en', 'Russian Push Ups', 'Russian Push-Ups

 Start in a standard push-up position with your hands slightly wider than shoulder-width apart. Lower your chest toward the floor, then shift your body forward while keeping your chest close to the ground. Extend your arms to return to the starting position, then reverse the movement smoothly. Keep your core tight and maintain controlled movement throughout the exercise.', 'peito', '["peito"]', '["ombros","abdômen","tríceps"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/2530/c39eccd5-c7a5-47cd-85c2-76cac547ad7c.png', 'CC-BY-SA 4', 'ege', 'https://wger.de/en/exercise/2530/view/', 'russian push ups peito ombros abdomen triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('10510fb5-6ebd-4ddc-b03e-423b15deceea', 1193, 'en', 'Russian Twist', '• Hold a dumbbell, barbell weight or something else that is heavy with both hands, but make sure it is not too heavy and you are able to keep in form.

• Lean back to a 45-degree angle from the floor. For an extra challenge, lift your feet off the floor.

• Rotate your arms to one side to the same level as your chest, touch the floor for a little extra challenge, and then do the same to the other side. When you''re back in your original position after doing both sides it will count as 1 rep.', 'core', '["dorsais","oblíquos","abdômen"]', '[]', '["Halteres","Colchonete","Bola suíça"]', 'https://wger.de/media/exercise-images/1193/70ca5d80-3847-4a8c-8882-c6e9e485e29e.png', 'CC-BY-SA 4', 'lion', 'https://wger.de/en/exercise/1193/view/', 'russian twist dorsais obliquos abdomen halteres colchonete bola suica', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2a983b8f-b77e-4f8f-8335-0e5caecd715f', 1435, 'en', 'Scapula Pulls', '• Hang straight on a pull-up bar

• Pull shoulder blades together, moving the body slightly up', 'costas', '["dorsais","trapézio"]', '[]', '["Barra fixa"]', NULL, 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1435/view/', 'scapula pulls dorsais trapezio barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e28b0685-7a8f-4343-9c0b-63b38386d30b', 545, 'en', 'Scissors', 'Scissors is an abdominal exercise that strengthens the transverse abdominals, helping flatten your belly and strengthen your entire core. Scissors is not only a core strength move, but it is also a great stretch for your hamstrings and your lower back. Everyone is looking for new ways to work the core, to flatten the belly and to improve flexibility. If you learn how to do Scissors you will get everything rolled together in one move.', 'core', '["abdômen"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'vkylamba', 'https://wger.de/en/exercise/545/view/', 'scissors abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('89651d40-9abf-49b5-9ee5-7b0ecb25fd03', 1207, 'en', 'Scorpion Kick', 'Get into the push-up position with your shoulders directly above your hands and your feet hip-width apart. 

 Make sure that your body forms a straight line from your head to your heels. 

 Now pull your right knee towards your chest. While keeping your knee bent, lift your right leg as high as possible with your lower right leg pointing straight up. 

 Now rotate your hips so that your right foot swings over your left leg. 

 Continue to rotate and move your right foot towards the floor until you are forced to roll onto the outside of your left standing foot. Make sure that you do not rotate your upper body. 

 Now return to the starting position and repeat the exercise with your left leg.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'lxmx', 'https://wger.de/en/exercise/1207/view/', 'scorpion kick costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('117df66c-bc8d-43cc-9903-0be2a0864486', 1094, 'en', 'Seated Bench Press', 'Set up the chest press machine so that the grips are aligned with your lower chest when you sit down. Make sure you''re sitting with your back flat against the seat. Grab a handle in each hand, stick your chest out, and keep your head against the headrest. Breathe deeply and slowly push the handles forward until your arms are almost fully extended. Pause just before the lockout, then slowly return the handles to the starting position. Pause just before the handles come to a complete stop and perform another repetition.', 'peito', '["peito"]', '[]', '["Banco"]', NULL, 'CC-BY-SA 4', 'colundrum', 'https://wger.de/en/exercise/1094/view/', 'seated bench press peito banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('139772c6-e401-4281-8aa6-c7ff7fb49f6a', 1922, 'en', 'Seated Cable chest fly', '• Place a bench between two cable pulleys and adjust the pulleys so they are at chest/shoulder height when you are seated.

• Grab the handles with a neutral grip and lean against the upright backrest.

• Bring your arms together in front of your chest in a controlled motion, focusing on squeezing your chest muscles. Keep your elbows slightly bent throughout the movement.

• Pause briefly at the top position.

• Slowly lower your arms back to the starting position while maintaining control of the movement.

• Repeat for reps.', 'peito', '["peito"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1922/eb750ee5-3220-4128-aef1-5e2f1ccff40a.webp', 'CC-BY-SA 4', 'shushu', 'https://wger.de/en/exercise/1922/view/', 'seated cable chest fly peito maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ad3716b1-5fc9-45aa-9de4-9a1c0153915d', 922, 'en', 'Seated Cable Mid Trap Shrug', 'seated straight back, slight hold at top', 'costas', '["trapézio"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/922/view/', 'seated cable mid trap shrug trapezio maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0ecfec6f-5d0f-4e8a-8d37-f6203a8923b8', 1117, 'en', 'Seated Cable Row', '• Take a seat on the machine with your feet planted, a little wider than shoulder width. Drive the heels, and squeeze the glutes. Grab onto the cable handle.

• Sit up tall with a slight bend through the knees. Tighten up the abs and low back to maintain a perpendicular angle to the floor with your torso.

• Roll the shoulders back and down. Squeeze them together as you row, thinking about pinching a pencil in between them. As you do this, pull the handle back towards you, landing right above your belly button.

• Pause here for a moment before returning the handle, still squeezing the shoulder blades. Once you''ve returned the weight to the stack, then allow the shoulder blades to relax, without pulling the torso forward.

• Repeat the movement.', 'costas', '["dorsais"]', '["bíceps","trapézio"]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1117/2555c4c3-a84d-47db-b83b-cbf721f12e45.png', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1117/view/', 'seated cable row dorsais biceps trapezio maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e9891a94-b1d4-47f4-a82b-c1aa82121abb', 1477, 'en', 'Seated Corkscrew', 'To
do this abs and obliques exercise, start with your hands back behind your body
and bring your knees in and across, really trying to contract the obliques.
Then extend your legs back out to starting position and repeat toward the
opposite side of the abs.
Beginners
might find that they can’t even get through the first 45 seconds of this
challenging reverse crunches variation. That’s ok because it gives you a
place to start and something to improve upon.', 'core', '["oblíquos","abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1477/view/', 'seated corkscrew obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6995c30a-037f-4de3-ac4a-45384a1f38f9', 1620, 'en', 'Seated Dumbbell Calf Raise', 'The seated dumbbell calf raise is a targeted exercise for strengthening the lower leg muscles. It follows the same movement pattern as the machine version: you place the weight on your knees, and by extending and flexing your ankles, you move the weight.', 'panturrilhas', '["panturrilhas"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1620/edd40e39-e337-4460-a8dd-6127d40ddd16.jpeg', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1620/view/', 'seated dumbbell calf raise panturrilhas halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('19fba43a-8363-4da3-82c6-d8a14628b5e7', 1289, 'en', 'Seated Dumbbell Curls', 'Seated Dumbbell Curls are an effective bicep workout that isolates the muscles by stabilizing the upper body, reducing momentum that can detract from the exercise’s effectiveness. This exercise is performed sitting down with a dumbbell in each hand, focusing on controlled movement to maximize engagement of the bicep muscles.', 'braços', '["bíceps"]', '["braquial"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'sTiKyt', 'https://wger.de/en/exercise/1289/view/', 'seated dumbbell curls biceps braquial halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6d010eae-2e36-4ec6-b191-c0373f237bb4', 918, 'en', 'Seated Dumbbell Side Lateral', 'seated slightly leaned forward at beginning of exercise', 'ombros', '["ombros"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/918/view/', 'seated dumbbell side lateral ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('73144238-414e-438f-8b0c-832a6591aa2f', 1680, 'en', 'seated figure four', 'Seat on a bench. Feet flat on the ground. Place your left ankle over your right knee. Your right knee stays flat. Keep your back straight. Gently push your left knee down.', 'pernas', '["glúteos"]', '[]', '["Banco"]', NULL, 'CC-BY-SA 4', 'ricardodavidrd', 'https://wger.de/en/exercise/1680/view/', 'seated figure four gluteos banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b144ac00-ec0c-4c43-898f-b2ac65048d98', 1672, 'en', 'Seated Hip Abduction', 'Starting Position:

 

• Adjust the seat height so that your knees are aligned with the pivot point of the machine.

• Sit with your back flat against the backrest, maintaining good posture.

• Place the outside of your thighs against the machine''s padded levers.

• Position your feet flat on the footrests or platform of the machine.

• Grasp the handles or sides of the seat for stability.

• Ensure your spine is neutral and your core is slightly engaged.

 Movement:

 

• Exhale as you slowly push your legs outward against the resistance pads.

• Focus on initiating the movement from your hips, not your knees.

• Continue opening your legs until you feel a strong contraction in your outer hips and thighs.

• Hold the fully abducted position briefly (1-2 seconds) to maximize muscle engagement.

• Inhale as you slowly control the return of your legs to the starting position, resisting the weight throughout the movement.

• Avoid allowing the weight stack to touch down between repetitions to maintain constant tension on the muscles.

• Repeat for the desired number of repetitions, maintaining control throughout the set.', 'pernas', '["glúteos"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Iko', 'https://wger.de/en/exercise/1672/view/', 'seated hip abduction gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('53906cd1-61f1-4d56-ac60-e4fcc5824861', 12, 'en', 'Seated Hip Adduction', 'Starting Position: Sit on the machine with your knees inward and against the pads. Pull the pin to release the pads. Grab the handles on the sides.b', 'pernas', '["glúteos"]', '[]', '[]', 'https://wger.de/media/exercise-images/12/4a42cc6f-648d-40cc-a72a-c49dd47e1667.webp', 'CC-BY-SA 3', 'flori', 'https://wger.de/en/exercise/12/view/', 'seated hip adduction gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('371cfda2-1de6-419a-b40c-fc98fd3f7e41', 1105, 'en', 'Seated Knee Tuck', 'Sit on floor or mat. Place arms slightly behind you. Raise legs. Now extend your legs and pull them back.', 'core', '["abdômen"]', '["oblíquos"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1105/36776818-799a-40bf-9eca-aebb3aa5008f.png', 'CC-BY-SA 4', 'utkb', 'https://wger.de/en/exercise/1105/view/', 'seated knee tuck abdomen obliquos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('96583e33-e643-486d-95e9-67d0d5935b05', 1845, 'en', 'Seated Pancake Good Morning', '• Sit with your legs completely straight (knees locked), spread wide in a straddle position.

• Place your hands on the back of your neck.

• Hinge your torso and head towards the floor.', 'pernas', '["glúteos"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1845/view/', 'seated pancake good morning gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ad5653e4-098e-4a84-af5b-a9349b108555', 1959, 'en', 'Seated Piriformis Stretch', 'Seated Piriformis Stretch
Part of: Limber 11
Source: Joe DeFranco
Prescription: 20-30 sec each side
Type: static
Includes isometric hold.', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1959/view/', 'seated piriformis stretch pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c302fd80-ce74-4202-9eee-30834872cffb', 1098, 'en', 'Seated rear delt rise', 'Seated, bent 45 deg forward. Arms fully stretched out, raise arms up to shoulder height and back down', 'costas', '["dorsais"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1098/fa5328a2-64cb-4afb-a283-b3d948ddaf3f.jpg', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1098/view/', 'seated rear delt rise dorsais halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9bcc7b4f-4172-4db7-be95-d7b659c486f5', 1725, 'en', 'Seated Row (Machine)', 'Keep your chest up and squeeze your shoulder blades at the end.

 Don’t hunch forward or round your back during the pull.', 'costas', '["dorsais"]', '["ombros","trapézio"]', '[]', 'https://wger.de/media/exercise-images/1725/f0ebd44e-b8e1-400c-b598-ca371f3a07af.png', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1725/view/', 'seated row (machine) dorsais ombros trapezio', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a00b852c-0d2b-4b4a-bbc2-ef538f211b6c', 1841, 'en', 'Seated Shoulder Extension Stretch', '• Sit with your hands behind you, shoulder width apart.

• Lock your elbows.

• Scoot your feet and hips out forwards, lowering your shoulders down towards ground.

• Go as far as possible to obtain a good stretch.

 See the video: https://www.youtube.com/watch?v=ihUAbG0e8zw', 'ombros', '["dorsais","peito"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1841/view/', 'seated shoulder extension stretch dorsais peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('cc5bf1a3-29b5-4c5a-8600-5e35c79ab4bf', 549, 'en', 'Seated Triceps Press', 'Sit down on a back (better with back support). Take a dumbbell firmly with both hands and hold it with extended arms over your head. With your palms facing upward and holding the weight of the dumbbell, slowly lower the weight behind your head.', 'braços', '["tríceps"]', '[]', '["Banco","Halteres"]', NULL, 'CC-BY-SA 4', 'richmr2174@gmail.com', 'https://wger.de/en/exercise/549/view/', 'seated triceps press triceps banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b2ca4a13-6fe2-4c4f-85b2-dcb5af28d2be', 1928, 'en', 'Seated V-Grip Row', 'The Seated V-Grip Row is a compound pulling exercise performed on a cable machine using a close-grip "V" handle. While seated with your feet braced, you pull the handle toward your midsection, focusing on back thickness and mid-back development.', 'costas', '["dorsais","trapézio"]', '["ombros","bíceps","abdômen","serrátil"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1928/view/', 'seated v-grip row dorsais trapezio ombros biceps abdomen serratil maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ecc46519-94b8-4ecc-b5b8-973e753e98a6', 1448, 'en', 'Seated W Curl', '• Sit on bench with 60° incline

• Hold dumbbells beside body near the ground, palms facing outwards, arms fully extended

• Move dumbbells up using only biceps and without momentum', 'braços', '["bíceps","braquial"]', '[]', '["Banco","Halteres"]', 'https://wger.de/media/exercise-images/1448/2184e68c-32b5-413f-a7c1-4a2d1bb98c35.png', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1448/view/', 'seated w curl biceps braquial banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7936d8ad-6a39-4459-aa60-3e1e325f5e2b', 2523, 'en', 'Serratus Wall Slide Stretch', '• Stand facing a wall. Place your forearms vertically against the wall so your elbows and wrists are both touching it.

• Point your arms slightly outwards from "straight up".

• Protract your shoulders had, then slide your forearms up the wall until your elbows are about level with your chin.

• Slide your forearms back down the wall. Repeat as necessary.', 'ombros', '["ombros"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2523/view/', 'serratus wall slide stretch ombros', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ceb58be5-2927-48c5-bb2d-4cc42b0a60e2', 1884, 'en', 'Shinbox IR Stretch', '• Starting Position: Sit on the floor with both hips and knees bent at 90-degree angles.

• Leg Placement: 
Place one leg in front of you (external rotation) and the other leg out
to the side/behind you (internal rotation). The shins and knees should
remain flat on the ground.

• The Movement: 
Keeping your hips square, hinge your torso forward or tilt it laterally
(side-to-side) toward the front leg to deepen the stretch.

• Target Areas: 
Stretches the glutes and piriformis (front leg) and the hip flexors and
quads (back leg). Engages the core and obliques during lateral flexion.

• Goal: Improves hip mobility, specifically internal and external rotation, and relieves lower back tension.', 'pernas', '["glúteos","oblíquos"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'teus_ergaster', 'https://wger.de/en/exercise/1884/view/', 'shinbox ir stretch gluteos obliquos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('169896b2-90e3-4497-9d73-56bee4a34697', 562, 'en', 'Shotgun Row', '• Attach a single handle to a low cable.

• After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position.

• Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go.

• After a brief pause, return to the starting position.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'cal.zabel', 'https://wger.de/en/exercise/562/view/', 'shotgun row dorsais maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('664ddd40-a595-420d-801f-148e4bf0594c', 1081, 'en', 'Shoulder dislocates', 'Starting position: 
Stand up with your back straight and a resistance band, towel, or broomstick handle in hand. With your hands straight in front of your body and the band between your hands, push your hands apart to both be at around 45 degrees from your body, thumbs facing down. If using a towel or broomstick handle instead, grab it with an overhand grip.
 Steps: 

 

• Keeping your arms outstretched, rotate at the shoulders to bring your arms overhead and then down toward your glutes.

• Rotate at the shoulders in the opposite direction — overhead and then toward your groin.

• Repeat.', 'ombros', '["ombros"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1081/view/', 'shoulder dislocates ombros', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e237611c-2730-4d0c-891b-bb29d3d15297', 1714, 'en', 'Shoulder Dumbbell Pendular Exercise', '• Lean forward to rest your hand on a chair or other object, holding a dumbbell in the other hand

• Gently swing the dumbbell in a circular motion', 'ombros', '["ombros","dorsais","peito","trapézio"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1714/view/', 'shoulder dumbbell pendular exercise ombros dorsais peito trapezio halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b283cd47-9a1c-4004-9bf5-220560ef0a16', 1729, 'en', 'Shoulder External Rotation (Cable)', 'Keep elbow fixed at your side and rotate forearm outward smoothly.

 Don’t let your wrist or elbow drift upward — stay in one plane.', 'ombros', '["ombros"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1729/view/', 'shoulder external rotation (cable) ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2eead109-098e-4c59-bdef-f580a6a82748', 1715, 'en', 'Shoulder External Rotation with Dumbbell', '• Lie on your side holding a dumbbell in your upper hand

• Tuck your elbow into your side and rest the hand in front of you

• Rotate the shoulder so the hand raises up

• Lower the hand down', 'ombros', '["ombros","braquial"]', '["trapézio"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1715/view/', 'shoulder external rotation with dumbbell ombros braquial trapezio halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('dadecc94-6322-4c66-93b5-9cb44ec79e46', 1728, 'en', 'Shoulder Internal Rotation (Cable)', 'Keep your elbow tucked to your side like it''s superglued there.

 Don’t rotate your torso — only your forearm should move.', 'ombros', '["ombros"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1728/view/', 'shoulder internal rotation (cable) ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8b0a0371-c0a9-42a7-aab7-68d520542fb2', 566, 'en', 'Shoulder Press, Barbell', 'Sit on a bench, the back rest should be almost vertical. Take a barbell with a shoulder wide grip and bring it up to chest height. Press the weight up, but don''t stretch the arms completely. Go slowly down and repeat.', 'ombros', '["ombros"]', '[]', '["Barra"]', 'https://wger.de/media/exercise-images/119/seated-barbell-shoulder-press-large-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/566/view/', 'shoulder press, barbell ombros barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('87affa4b-395b-437c-9581-2bd20ea5aa7c', 567, 'en', 'Shoulder Press, Dumbbells', 'Sit on a bench, the back rest should be almost vertical. Take two dumbbells and bring them up to shoulder height, the palms and the elbows point during the whole exercise to the front. Press the weights up, at the highest point they come very near but don''t touch. Go slowly down and repeat.', 'ombros', '["ombros"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/123/dumbbell-shoulder-press-large-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/567/view/', 'shoulder press, dumbbells ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('141bc870-56be-4749-a3b9-e56d5d5618b4', 569, 'en', 'Shoulder Press, on Multi Press', 'The exercise is basically the same as with a free barbell:

 Sit on a bench, the back rest should be almost vertical. Take a bar with a shoulder wide grip and bring it down to chest height. Press the weight up, but don''t stretch the arms completely. Go slowly down and repeat.', 'ombros', '["ombros"]', '[]', '[]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/569/view/', 'shoulder press, on multi press ombros', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9a644b0e-8691-4216-b2cc-f058f58ec96d', 1338, 'en', 'Shoulder Raise (Dumbbell)', '• Engage the muscles

• Don''t use momentum

• Controlled movement

• Slow movement

• Always keep the arms bent

• Don''t overextend', 'ombros', '["ombros"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1338/9d157b4d-5af0-43c1-bd34-f52144ba1b54.webp', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1338/view/', 'shoulder raise (dumbbell) ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c146fa3c-35a4-4e6e-9000-e12a9ee19cbd', 1443, 'en', 'Shoulder Raise Side and Front DB', '• Stand while holding dumbbells beside body

• Keep arms almost fully extended

• Without momentum raise dumbbells to the side of your body until shoulder height, palms facing down

• Lower dumbbells beside body, palms facing inwards

• Immediately raise dumbbells in front of your body until shoulder height, palms facing down

• Down again

• This is one repetition', 'ombros', '["ombros"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1443/view/', 'shoulder raise side and front db ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('716286dd-05b1-4f87-8b3b-a0c559bcafc4', 1209, 'en', 'Shoulder width three-point push-up', 'Get into a push-up position with your shoulders directly above your hands and your feet hip-width apart. Draw your belly button in towards your spine and tighten your abdominal muscles. Lift your left foot about five centimetres off the floor. Point your toes straight down. Do not move your hips. Your body forms a straight line from your head to your heels throughout the exercise. Now bend your elbows, lower your chest to the floor and push yourself back up. Repeat the exercise on the other side.', 'braços', '["peito"]', '["ombros","abdômen","tríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'lxmx', 'https://wger.de/en/exercise/1209/view/', 'shoulder width three-point push-up peito ombros abdomen triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7e039ac7-37ab-49f9-9ae8-c7efeef070cd', 1755, 'en', 'Shoulder Y-pull cable', 'on a cable rack cross the cables and pull elbows to ceiling close to the body.', 'ombros', '["ombros"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1755/view/', 'shoulder y-pull cable ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('43eeec70-df51-4cad-9bef-a35261b0caaf', 1739, 'en', 'Shrimp Squad', 'Single leg squad where one leg is behind you.', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa","panturrilhas"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Happy', 'https://wger.de/en/exercise/1739/view/', 'shrimp squad gluteos quadriceps posteriores de coxa panturrilhas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('270e108d-3cd2-45a9-807b-c357317eb15c', 571, 'en', 'Shrugs, Barbells', 'Take a barbell and stand with a straight body, the arms are hanging freely in front of you. Lift from this position the shoulders as high as you can, but don''t bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position.

 When training with a higher weight, make sure that you still do the whole movement!', 'ombros', '["ombros"]', '[]', '["Barra"]', 'https://wger.de/media/exercise-images/150/Barbell-shrugs-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/571/view/', 'shrugs, barbells ombros barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('72a945ec-3a7f-424b-9a05-1616ef7dce91', 572, 'en', 'Shrugs, Dumbbells', 'Stand with straight body, the hands are hanging freely on the side and hold each a dumbbell. Lift from this position the shoulders as high as you can, but don''t bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position.

 When training with a higher weight, make sure that you still do the whole movement!', 'ombros', '["ombros"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/151/Dumbbell-shrugs-2.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/572/view/', 'shrugs, dumbbells ombros halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d36fdd3c-9a35-4643-a3fd-57db78c866d6', 1188, 'en', 'Side bend', 'With a weight in one hand, extend that arm down and bend the other arm, resting your hand on your head. Now move the hand holding the weight by rotating your torso up and down.', 'core', '["oblíquos"]', '["abdômen"]', '["Halteres"]', 'https://wger.de/media/exercise-images/1188/43e714e4-b736-4f3a-8ab4-97821fdff86a.jpg', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1188/view/', 'side bend obliquos abdomen halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2f8ee51b-f493-47f7-8b2a-1da16c128f73', 576, 'en', 'Side Crunch', 'Hold weight in one hand. Bend side ways to the knee. Pull upo to upright position using your obliquus.', 'core', '["oblíquos"]', '["abdômen"]', '["Colchonete"]', 'https://wger.de/media/exercise-images/176/Cross-body-crunch-1.png', 'CC-BY-SA 3', 'kwrindy', 'https://wger.de/en/exercise/576/view/', 'side crunch obliquos abdomen colchonete', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('cf1f0fed-6310-4210-8f7d-22e375e6c60c', 577, 'en', 'Side Dumbbell Trunk Flexion', 'AKA dumbbell side bends. Stand in line with the hips with slightly bent knees, maintain the natural curvature of the spine, hand stretched by the body, grip the barbell with one hand. Make slow and controlled torso side flexions till you reach the angle of approximately 45°.', 'core', '["oblíquos"]', '["abdômen"]', '["Halteres"]', NULL, 'CC-BY-SA 3', 'GiglioRosso', 'https://wger.de/en/exercise/577/view/', 'side dumbbell trunk flexion obliquos abdomen halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('065ff3ca-a9e8-4339-997e-d65556d9ebf3', 1753, 'en', 'Side lateral raise - Back (Cable)', 'on a cable rack do a side lateral raise with the cable behind you. focus on tension in the front of the shoulder.', 'ombros', '["ombros"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1753/view/', 'side lateral raise - back (cable) ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7f9c13ab-1718-4f8a-8636-232f05f5f640', 1752, 'en', 'Side lateral raise - Front (Cable)', 'in a cablerack do a side lateral raise with cable in front of you, with focus in tension on the back of your shoulder.', 'ombros', '["ombros"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1752/view/', 'side lateral raise - front (cable) ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('dba57084-d148-4b22-bb90-2fdd3a845ca4', 1730, 'en', 'Side Lateral Raise (Cable)', 'Lift with your elbows leading, not your hands.

 Don’t shrug your shoulders; keep traps quiet.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1730/view/', 'side lateral raise (cable) dorsais maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7212cc74-656e-47ce-8292-d211676f2ee1', 1202, 'en', 'Side Lying Hip Abduction', '• Begin by lying down on your side with your top leg straight and your bottom leg bent for support.

• Lift your top leg off the ground

• (optional) - Hold position at the top

 Resources:

 

• 40 seconds YouTube video: https://www.youtube.com/watch?v=g9FtnmsIYgI', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'wakanda90', 'https://wger.de/en/exercise/1202/view/', 'side lying hip abduction pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2caf3474-9855-4d0b-a50f-dbc08772b151', 2509, 'en', 'Side Plank (Core L1)', 'Vasco custom side plank - foundational lateral core stability. Targets obliques, QL, and hip abductors. Essential for spinal stability and rotational control.', 'core', '["ombros","dorsais","peito"]', '["bíceps","braquial","oblíquos"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/2509/41318de7-85ad-4a8c-8d94-dff73206e2fb.png', 'CC-BY-SA 4', 'Vasco Custom', 'https://wger.de/en/exercise/2509/view/', 'side plank (core l1) ombros dorsais peito biceps braquial obliquos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('cd7bbafc-4092-4194-aa20-e380f1fe45f0', 1195, 'en', 'Side Slides + Squats', 'With feet a little wider than shoulder-width apart and staying low to mimic a defensive position, you should step with their lead leg and push off with their plant leg.
After three slides, rotate your body for 180 degree on the guiding (/outer) leg and do a squat. Continue.', 'pernas', '["quadríceps"]', '["panturrilhas","glúteos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Insight', 'https://wger.de/en/exercise/1195/view/', 'side slides + squats quadriceps panturrilhas gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0dd4dde7-9712-4c06-8ebe-16bc7a0b1917', 1727, 'en', 'Side Straight-Arm Pulldown (Cable)', 'Keep your torso still, pulling the handle down along your side using the outer lat.

 Don’t twist your body or rotate your torso to cheat the rep.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1727/view/', 'side straight-arm pulldown (cable) dorsais maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e3f424e1-4c9f-4892-8df2-230624680439', 1861, 'en', 'Side stretch', 'View the video to undestand the exercise', 'costas', '["costas"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1861/0ffe4e99-71ad-47fb-b98c-1f243faa0499.png', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1861/view/', 'side stretch costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9374fdaf-411f-4ae6-8f0c-21cc2d3dc667', 583, 'en', 'Side to Side Push Ups', '-start in push up position

 -lean the body weight to the right side, and complete a push up with the chest over the right hand

 -come back to the centered position

 -on rep 2, lean to the left side', 'peito', '["ombros","oblíquos","peito","tríceps"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/583/view/', 'side to side push ups ombros obliquos peito triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6ec2d684-8091-4da9-8814-8a3052d0a302', 2484, 'en', 'Side-Kick Breathing (Kickboard)', 'Push off the wall on your side (not flat on your stomach), one arm extended forward holding the board or just extended, kicking continuously. Keep your head in a neutral position looking at the bottom of the pool, and when you need air, rotate your head sideways (one ear stays in the water, other faces up) to breathe, then rotate back to neutral. Swim a length like this, then repeat on the other side. This teaches the exact head position and rotation you''ll use once full stroke breathing comes in.', 'cardio', '["glúteos"]', '["ombros","posteriores de coxa","oblíquos","quadríceps"]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2484/view/', 'side-kick breathing (kickboard) gluteos ombros posteriores de coxa obliquos quadriceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d9c1f78c-7bf6-4e6a-92e4-7bf4ed4a0a67', 1582, 'en', 'Side-laying interior rotation', 'Laying on your side and using the arm closest to the bench, maintain a 90 degree bend at the elbow and allow the weight to fall towards the ground past the bench as low as comfortable. Bring the weight up using only rotation of the shoulder to the opposing shoulder.', 'ombros', '["trapézio"]', '[]', '["Barra","Banco","Halteres"]', 'https://wger.de/media/exercise-images/1582/5094fe30-eea2-4269-b0de-4b8a20558fd7.png', 'CC-BY-SA 4', 'CptnFatbeard', 'https://wger.de/en/exercise/1582/view/', 'side-laying interior rotation trapezio barra banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d9f6c15a-b224-4ef6-93e9-fd6509b66add', 578, 'en', 'Side-lying External Rotation', 'With a weight in one hand, lie on your side opposite the weight. Keep your knees slightly bent. Hold your elbow against your side, and extend your upper arm straight ahead of you. While continuing to hold your elbow against your side, rotate your upper arm 90 degrees upwards.

 It is helpful to place a towel under your armpit to help with the form on this exercise. Placing a support under your head for the duration of the exercise is also a good idea.', 'ombros', '["ombros"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'apeschel', 'https://wger.de/en/exercise/578/view/', 'side-lying external rotation ombros', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('768e0703-a04d-4d97-89ce-a49cd6be2b06', 1022, 'en', 'Single Arm Plank to Row', 'Start position as row, extend to plank and back. Finish with row and repeat', 'costas', '["ombros","bíceps","braquial","dorsais","oblíquos","abdômen","serrátil"]', '[]', '["Kettlebell"]', 'https://wger.de/media/exercise-images/1022/f74644fa-f43e-46bd-8603-6e3a2ee8ee2d.jpg', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1022/view/', 'single arm plank to row ombros biceps braquial dorsais obliquos abdomen serratil kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('81dd44b3-67b3-4198-9e57-c2a80b3c4102', 1637, 'en', 'Single arm row', 'Sitting on the ground, use a high cable in a single grip, to do lat pulldowns with a focus on a long stretch in the lats.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo","Banco inclinado"]', 'https://wger.de/media/exercise-images/1637/a1fbe83a-a3e5-49f6-a2c2-5d5b533c2be8.png', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1637/view/', 'single arm row dorsais maquina de cabo banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('68f1efb8-e7d2-4a79-99bb-65f128e10a11', 1740, 'en', 'Single Leg Glute Bridge', 'A glute bridge, where you use just one leg at a time.', 'pernas', '["glúteos"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Happy', 'https://wger.de/en/exercise/1740/view/', 'single leg glute bridge gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('45cd73d7-98ac-4451-849a-a645fcfe9bee', 1393, 'en', 'Single Leg Hamstring Stretch', 'Sit on the ground with one leg straight out in front of you and the other leg bent in toward you. Reach forward with both hands, trying to touch the toes of your straight leg.', 'pernas', '["posteriores de coxa"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1393/view/', 'single leg hamstring stretch posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('957ca37c-b6d7-4c30-8ba9-9512b0fa2659', 1388, 'en', 'Single Leg RDL', '• Stand upright and hold weights in both hands if using loads.

• Brace your core and lift one leg off the ground.

• Keep your back straight, hinge at the hips while lowering your torso forward, ensuring you don’t rotate your hips.

• Lower until you feel a stretch in your standing leg''s hamstring, then return to standing position. Repeat on both sides.', 'pernas', '["posteriores de coxa"]', '["glúteos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'admin', 'https://wger.de/en/exercise/1388/view/', 'single leg rdl posteriores de coxa gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('83af8d94-319b-456b-92d8-75cec821a195', 1969, 'en', 'Single-arm cable pushdown', 'Single-arm cable pushdown is a unilateral isolation exercise that targets the triceps brachii. By working one arm at a time, it helps correct strength imbalances between sides while also engaging the core for stability.
Starting position:
Stand facing the cable machine with your feet shoulder-width apart. Attach a single handle to the high pulley. Grab the handle with one hand using an overhand grip (pronated), with your elbow bent at approximately 90° and tucked close to your body. Keep your core braced and your back straight.
Execution:
Push the handle downward in a controlled motion by extending your elbow until your arm is fully extended. Hold the contraction for 1 second at the bottom, then slowly return to the starting position.', 'braços', '["tríceps"]', '["abdômen"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'evtimovgeorg', 'https://wger.de/en/exercise/1969/view/', 'single-arm cable pushdown triceps abdomen maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9dfce8f0-39fc-4204-9f84-500ec42074e9', 1968, 'en', 'Single-arm dumbbell shoulder press', 'Press the dumbbell vertically overhead in a controlled motion until your arm is fully extended, without locking the elbow. Slowly lower the dumbbell back to the starting position at shoulder height.', 'ombros', '["ombros"]', '["abdômen","serrátil","trapézio","tríceps"]', '["Halteres"]', 'https://wger.de/media/exercise-images/1968/cd92e973-a0d9-4e5f-9011-5369012598d3.png', 'CC-BY-SA 4', 'evtimovgeorg', 'https://wger.de/en/exercise/1968/view/', 'single-arm dumbbell shoulder press ombros abdomen serratil trapezio triceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b86fd8df-e726-4998-a7ee-000de0f70bf0', 1972, 'en', 'Single-Arm Lat Pulldown', 'Sit at the lat pulldown machine and grab the single handle with a neutral grip. Keep your torso stable, your chest lifted, and your shoulder blades slightly retracted. Start with your arm fully extended overhead, then pull the handle down toward your upper chest following a controlled, slightly diagonal path. Focus on engaging the latissimus dorsi while keeping the shoulder depressed and avoiding any torso rotation. Slowly return to the starting position, maintaining full control throughout the movement.', 'costas', '["dorsais","trapézio"]', '["bíceps","braquial"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'evtimovgeorg', 'https://wger.de/en/exercise/1972/view/', 'single-arm lat pulldown dorsais trapezio biceps braquial maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c85e6137-2577-4e28-82c2-427407d534eb', 584, 'en', 'Single-arm Preacher Curl', 'Sit on the preacher curl bench and perform a bicep curl with a dumbbell in one hand. Your other hand can be at rest, or beneath your curling arm''s elbow.', 'braços', '["bíceps"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/584/view/', 'single-arm preacher curl biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('53b8727f-ad5c-402a-83e6-7b8e9c0bd99a', 2616, 'en', 'Single-leg BOSU balance', 'Single-Leg BOSU Balance Exercise
 The exercise for balancing on a BOSU ball while standing on one leg is known as the single-leg BOSU balance exercise. This exercise is effective for enhancing balance, coordination, and core stability.

Benefits of the Single-Leg BOSU Balance Exercise
 

• Improves Balance: Standing on one leg challenges your stability.

• Enhances Coordination: Engaging different muscle groups helps improve overall coordination.

• Strengthens Core: The exercise activates core muscles, promoting better posture and stability.

How to Perform the Single-Leg BOSU Balance Exercise
 

• Positioning: Stand on the dome side of the BOSU ball with one leg.

• Balance: Keep your opposite leg lifted and your core engaged.

• Duration: Aim to hold the position for 10-20 seconds, gradually increasing the time as you improve.

Progression Tips
 

• Add Movement: Try reaching for objects around you while maintaining balance.

• Close Your Eyes: This increases the challenge by removing visual stability cues.

• Use a Ball: Catch or toss a ball while balancing to further engage your core and coordination.

 This exercise is a great way to build foundational balance skills before progressing to more complex movements.', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/2616/view/', 'single-leg bosu balance pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a630de17-9170-434c-b486-96a6b8705506', 1736, 'en', 'Single-Leg Deadlift with Dumbbell', 'Starting Position: Stand upright with a slight bend in your knees, holding a dumbbell in one or both hands. Shift your weight onto your supporting leg (e.g., your right leg) and lift your non-supporting foot slightly off the floor.

 The Hinge: Keeping your back flat and core engaged, hinge at your hips, pushing your glutes backward. As your torso lowers, extend your non-supporting leg straight back behind you for balance, keeping your hips square to the floor. The dumbbell(s) should lower toward the ground along the line of your supporting leg.

 Range of Motion: Continue lowering your torso until it is nearly parallel to the floor, or you feel an intense stretch in your supporting hamstring, ensuring your back remains neutral throughout the movement.

 Return to Start: Pause at the bottom, then contract your glutes and hamstrings to slowly raise your torso back to the starting position. Your non-supporting leg should return in line with the supporting one.

 Switch Sides: After completing your desired number of repetitions on one side, switch your weight and repeat the movement on the other leg.', 'pernas', '["posteriores de coxa","glúteos"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1736/aa724cc5-c485-4f3e-9d2a-0c6ae4baefbe.png', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1736/view/', 'single-leg deadlift with dumbbell posteriores de coxa gluteos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('caccd791-ff30-452a-816e-790edadb78cd', 1294, 'en', 'Single-leg hamstring curl', 'Specifically, the muscles involved are: biceps femoris, semimembranosus and semitendinosus.', 'pernas', '["posteriores de coxa"]', '["glúteos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1294/view/', 'single-leg hamstring curl posteriores de coxa gluteos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ff6c2fb1-5105-49ba-babe-c0d403940269', 1734, 'en', 'Single-Leg Lunge with Kettlebell:', 'How to do a single-leg kettlebell lunge

 Preparation: Stand with your feet together. Hold the kettlebell with both hands by the handle, keeping it close to your chest, or hold it with one hand (on the same side as the working leg).

 Step and Lower: Take a large step forward (or backward, which is safer for your knees) with one leg, lowering your hips until both knees form a 90-degree angle.

 Focus: Shift your weight onto your front (or bent) leg, keeping your back straight and your torso upright.

 Return: Push off with your front leg to return to the starting position.', 'pernas', '["panturrilhas","glúteos","quadríceps"]', '[]', '["Kettlebell"]', 'https://wger.de/media/exercise-images/1734/782e2fbb-1267-476d-a817-14f3b83e0564.png', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1734/view/', 'single-leg lunge with kettlebell: panturrilhas gluteos quadriceps kettlebell', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d28cf04f-4077-484b-82ed-abaea8d4053d', 1735, 'en', 'Single-leg side glute press', 'The Single-Leg Side Glute Press is a leg press machine variation where you angle your body sideways on the pad, placing one foot high and slightly angled to press the weight, powerfully targeting the outer glute (gluteus medius/minimus) and hamstrings for balanced leg development and stability, requiring focus on pushing through the heel and maintaining control without locking out.

 How to Perform:

 Setup: Sit in the leg press machine, rotate your body to one hip, placing one foot high on the platform at about a 45-degree angle with toes pointed slightly out/forward.

 Positioning: Keep your hip, knee, and ankle aligned, and ensure your lower back stays on the pad.

 Descent: Slowly lower the weight, allowing your knee to bend deeply (near 90 degrees), feeling a stretch in your glute and hamstring.

 Press: Drive through your heel (not your toes) to press the weight back up, squeezing your glutes and hamstrings, stopping just before your leg fully extends.

 Control: Avoid bouncing and don''t let your lower back lift off the pad; maintain tension throughout the movement.', 'pernas', '["panturrilhas","glúteos","quadríceps"]', '[]', '["Banco inclinado"]', 'https://wger.de/media/exercise-images/1735/43bca7d9-2333-43f3-8554-2d0b39fa2a07.png', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1735/view/', 'single-leg side glute press panturrilhas gluteos quadriceps banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('eb8d3fa8-8cfc-4961-8e3d-5bf0a5081797', 2619, 'en', 'Single-Leg Soft-Landing Holds', 'Single-Leg Soft-Landing Holds
 Single-leg soft-landing holds are exercises that focus on balance and stability by landing softly on one leg and holding the position. This exercise helps improve proprioception and can be beneficial for rehabilitation and athletic training.

Overview
 Single-leg soft-landing holds are exercises designed to enhance balance, stability, and proprioception. They involve landing softly on one leg and maintaining that position for a brief period. This exercise is particularly useful in rehabilitation settings and for athletes looking to improve their performance.

Benefits
 

• Improves balance: Enhances stability by training the body to control weight distribution on one leg.

• Enhances proprioception: Increases awareness of body position, which is crucial for injury prevention.

• Supports rehabilitation: Helps individuals recover from lower-limb injuries by strengthening muscles and improving joint stability.

How to Perform Single-Leg Soft-Landing Holds
Steps
 

• Preparation: Stand on a stable surface or a box.

• Takeoff: Step off the box or surface with one leg, ensuring that you do not jump.

• Landing: Land softly on the target leg, allowing the knee and hip to bend slightly.

• Hold position: Maintain balance in the landed position for up to 2 seconds.

• Reset: Return to the starting position and repeat.

Key Points to Remember
 

• Keep your chest up and engage your core for better stability.

• Ensure your knee aligns with the midline of your foot during landing.

• Focus on a controlled descent to minimize impact.

Conclusion
 Incorporating single-leg soft-landing holds into your training routine can significantly enhance your balance and stability, making it a valuable exercise for both rehabilitation and athletic performance.', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/2619/32c68e76-6456-4c29-b24d-89d5a5b12d02.jpg', 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/2619/view/', 'single-leg soft-landing holds pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5a5e8883-b185-40ff-b292-9e433d13b5e7', 1394, 'en', 'Sit & Reach', 'Sit on the ground with your legs extended straight in front of you. Reach both hands forward, trying to reach past your toes or as far as you can go. Return to the starting position and repeat.', 'costas', '["posteriores de coxa"]', '[]', '["Colchonete"]', NULL, 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1394/view/', 'sit & reach posteriores de coxa colchonete', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5af00591-2d77-4ea6-a347-825ad18beff1', 1479, 'en', 'Sit Up Elbow Thrust', 'This
is a top down rotation movement, and it’s a bit more
explosive, too.
Lying with knees bent and feet on the floor, sit up and then drive your left elbow across your entire body toward the right, then come back
to center and then finally lower yourself down. Then hit the other side.', 'core', '["oblíquos","abdômen"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1479/0305d98e-0887-4c0c-8992-7c220814efc2.webp', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1479/view/', 'sit up elbow thrust obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f38e9c23-031d-44d0-ac27-7f1026212c73', 591, 'en', 'Sit-ups', 'Sit on a mat, your calves are resting on a bench, the knees make a right angle. Hold your hands behind your neck. Go now up with a rolling movement of your back, you should feel how the individual vertebrae lose contact with the mat. At the highest point, contract your abs as much as you can and hold there for 2 sec. Go now down, unrolling your back.', 'core', '["abdômen"]', '[]', '[]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/591/view/', 'sit-ups abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6e46833d-fd83-4c1a-90af-eb3f3a917199', 590, 'en', 'Sitting Calf Raises', 'Sit on a bench for calf raises and check that the feet are half free and that you can completely stretch the calf muscles down. Pull your calves up, going as far (up) as you can. Make at the highest point a short pause of 1 or 2 seconds and go down.', 'panturrilhas', '["sóleo"]', '["panturrilhas"]', '[]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/590/view/', 'sitting calf raises soleo panturrilhas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9f9bfa54-4702-4eb1-a72a-0fc12c846c72', 1274, 'en', 'Sitting Calf Stretch (Dorsiflexion)', 'This is a light stretch for the calf that is great for rehab.', 'pernas', '["panturrilhas","sóleo"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1274/bcffdf52-3c36-4b0c-b787-fb84f20bf82d.png', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1274/view/', 'sitting calf stretch (dorsiflexion) panturrilhas soleo peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e29d9914-6b02-490b-8f3a-f9fe8f21993c', 1526, 'en', 'Ski Machine', '• Start standing on the platform with your feet hip-width apart.

• Reach overhead to grip the handles with your palms facing in.

• Soften your knees, then simultaneously drive your butt back as if you''re closing a door behind you while pulling your arms straight down past your hips until your hands pass by the side of your knees.

• Next, bring your arms back overhead while thrusting your hips forward until you''re standing with your arms fully extended.

• Repeat for reps, time or distance.', 'cardio', '["panturrilhas","dorsais","trapézio","tríceps"]', '["posteriores de coxa","glúteos","quadríceps","abdômen"]', '[]', NULL, 'CC-BY-SA 4', 'flanny', 'https://wger.de/en/exercise/1526/view/', 'ski machine panturrilhas dorsais trapezio triceps posteriores de coxa gluteos quadriceps abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e60125f0-3a88-4707-815f-fe0e2b4be3c4', 595, 'en', 'Skipping - Standard', 'Do a single, double footed jump for each swing of the rope.

 Work on a smooth, rhythmical movement, bouncing lightly on the balls of your feet.', 'cardio', '["panturrilhas"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Cerin', 'https://wger.de/en/exercise/595/view/', 'skipping - standard panturrilhas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('893c07ea-2e24-49b6-92e4-d0033eedec62', 245, 'en', 'Skullcrusher Dumbbells', 'Hold the dumbbells and lay down on a flat bench in such a way that around 1/4 of your head is over the edge. Stretch arms straight up and then lean dumbbells away from your toes to a 10-20 degree angle. Keep upper arm at this angle throughout exercise. Dumbbell shall not be amed at your head, but away over your head. This will maximise gain from exercise with load on triceps all the time.

 Pay attention to your elbows and arms: only the triceps are doing the work, the rest of the arms should not move.', 'braços', '["tríceps"]', '[]', '["Banco","Halteres"]', NULL, 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/245/view/', 'skullcrusher dumbbells triceps banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('95a7e546-e8f8-4521-a76b-983d94161b25', 246, 'en', 'Skullcrusher SZ-bar', 'Hold the SZ-bar and lay down on a flat bench in such a way that around 1/4 of your head is over the edge. Stretch your arms with the bar and bend them so that the bar is lowered. Just before it touches your forehead, push it up.

 Pay attention to your elbows and arms: only the triceps are doing the work, the rest of the arms should not move.', 'braços', '["tríceps"]', '[]', '["Banco","Barra W"]', 'https://wger.de/media/exercise-images/84/Lying-close-grip-triceps-press-to-chin-1.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/246/view/', 'skullcrusher sz-bar triceps banco barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('965b0d80-544b-4f22-a64b-32dc033f071a', 1210, 'en', 'Skydiver with arms in T-position', 'Lie on your stomach with your legs more than shoulder-width apart and your feet up. Your arms are stretched out to the side and form a T with your upper body, your palms are on the floor. Now raise your upper body, arms and legs as high as you can while keeping your body under tension. Turn your thumbs towards the ceiling and pull your shoulder blades together. While keeping your upper body and all limbs in the air, bring your legs together and then spread them again, keeping them constantly in the air. For the remaining repetitions, only move your legs open and closed.', 'costas', '["costas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'lxmx', 'https://wger.de/en/exercise/1210/view/', 'skydiver with arms in t-position costas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('32cc7175-3fda-4c7e-900f-8766c22e3b2b', 1523, 'en', 'Sled Push', '• Load the sled with 25% of your maximum load. If you don’t know this, choose a weight you can push for 10 minutes with short breaks. Beginners may choose to push the sled with no weight.

• Stand behind the sled and grab the poles with a high-grip hand position.

• Engage your core muscles and start pushing the sled forward as fast as you can, powering through your entire leg. Extend your hips and knees as you move the sled forward. Your foot stance should resemble your natural running position.', 'cardio', '["panturrilhas","glúteos","quadríceps"]', '["ombros","posteriores de coxa","tríceps"]', '[]', NULL, 'CC-BY-SA 4', 'flanny', 'https://wger.de/en/exercise/1523/view/', 'sled push panturrilhas gluteos quadriceps ombros posteriores de coxa triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('90f12b1b-b33e-4d83-9f9e-e26d3a4b8e0b', 1711, 'en', 'Sleeper Stretch', '• Lie on your side so that you are resting a little weight on your shoulder blade to keep it still

• Extend your arm to 90 degrees in front of you, resting on the floor/mat

• Lift your hand with your elbow so that your fingers point to the ceiling and your palm points towards your feet

• Keeping your elbow still, gently lower your palm toward the floor', 'ombros', '["ombros"]', '["trapézio"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1711/view/', 'sleeper stretch ombros trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('55bb8725-a7c9-48a0-b192-ec6c9db6f9bc', 1604, 'en', 'Sliding Lateral Lunge', 'Stand upright with your feet hip-width apart, holding a kettlebell close to your chest in goblet position. Place one foot on a slider, gliding disc, or towel. Keep your chest tall and core engaged. Slowly slide the foot outward to the side while bending the opposite knee, lowering your hips into a lateral lunge. Keep the working leg’s knee aligned with the toes and avoid letting it collapse inward. The non-working leg remains straight and slides smoothly along the floor. Push through the heel of the bent leg to return to the starting position while maintaining control of the kettlebell.', 'pernas', '["posteriores de coxa","glúteos","quadríceps"]', '["panturrilhas","oblíquos"]', '["Barra"]', 'https://wger.de/media/exercise-images/1604/7695428e-bfed-4021-b987-498d93153995.png', 'CC-BY-SA 4', 'RiccaBaro', 'https://wger.de/en/exercise/1604/view/', 'sliding lateral lunge posteriores de coxa gluteos quadriceps panturrilhas obliquos barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9f9edad8-7da0-448c-bfcb-ec61f2d28162', 804, 'en', 'Sloper hanging', 'Hanging on sloper holds of a fingerboard for a amount of seconds', 'braços', '["braços"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/804/6f4b8bd9-fa05-49de-870b-1f79b595ce89.png', 'CC-BY-SA 4', 'marcelbader', 'https://wger.de/en/exercise/804/view/', 'sloper hanging bracos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2398e14f-02a6-4fdc-9f69-029e52dfe033', 1963, 'en', 'Slow Squat', '​A tempo-based squat that uses controlled movement to increase muscle tension and improve lower-body stability.

 

• ​Lower: Descend slowly for 3 seconds.

• ​Pause: Hold at the bottom for 1 second.

• ​Stand: Return to the starting position at a normal pace.

• Form: Keep your chest up and weight in your heels.', 'pernas', '["quadríceps"]', '["posteriores de coxa","glúteos","abdômen"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1963/db285682-1ab3-4be0-ae00-5117ecce1ee6.png', 'CC-BY-SA 4', 'Anon#2', 'https://wger.de/en/exercise/1963/view/', 'slow squat quadriceps posteriores de coxa gluteos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('092d0fbb-0409-470e-a087-beb9a378f3f7', 598, 'en', 'Smith Machine Close-grip Bench Press', 'Perform a standard bench press on the smith machine, but have your hands on the bar about shoulder width apart, and keep your elbows close to your body.', 'braços', '["tríceps"]', '["peito"]', '[]', NULL, 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/598/view/', 'smith machine close-grip bench press triceps peito', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ef2df6a2-41df-4a25-b2e0-4808dc2c3305', 925, 'en', 'Smith Machine Slight Incline Press', '* Execution * Start position: 
 

• Unrack the bar and hold it above your upper chest with arms fully extended.

• Keep your shoulder blades retracted and pressed into the bench .

• Lowering phase (eccentric): 

• Slowly bring the bar down to just below your collarbone or upper chest.

• Maintain control — don’t bounce the bar.

• Pressing phase (concentric): 

• Push the bar upward in a straight line until your arms are fully extended.

• Focus on squeezing your upper chest at the top.

• Lock and repeat: 

• Complete your reps, then safely rack the bar back into the hooks.', 'peito', '["peito"]', '[]', '[]', 'https://wger.de/media/exercise-images/925/67dbb1c9-b378-46f9-adb6-1f55b3d3007a.png', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/925/view/', 'smith machine slight incline press peito', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b382dcb2-60a8-412d-b0ee-6afe9c9f36d7', 1593, 'en', 'Smith Machine Split Squat', 'The "Smith Machine Split Squat" is a strength exercise
performed on the Smith machine, ideal for targeting the legs and glutes.
It involves placing one foot forward and the other back, lowering the
body until the front thigh is parallel to the ground while the bar
slides vertically along the machine. This exercise helps improve
stability, correct muscle imbalances, and reduces stress on the back,
providing a safe environment for strength training.', 'pernas', '["posteriores de coxa","quadríceps"]', '[]', '["Barra"]', 'https://wger.de/media/exercise-images/1593/9815fcd6-cf40-4ddd-9b38-2eac25973de1.gif', 'CC-BY-SA 4', 'workout@rooven.anonaddy.me', 'https://wger.de/en/exercise/1593/view/', 'smith machine split squat posteriores de coxa quadriceps barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f3ef220b-a070-449c-a463-876d30cd9b14', 1747, 'en', 'Smith machine squat', 'Technique and Execution

 The Smith machine squat is a variation of the traditional barbell squat that uses a guided, fixed-path barbell. Here''s a detailed breakdown of the proper technique:

 Starting Position

 Foot Placement: Position feet slightly forward of the bar, about shoulder-width apart

 Bar Position: Rest the bar on your upper trapezius/shoulders, similar to a traditional back squat

 Stance: Feet can be slightly angled outward for natural hip rotation

 Squat Movement

 Unrack the bar by rotating it to release from the safety hooks

 Slowly lower your body by bending knees and hips

 Descend until thighs are parallel to the ground (or slightly below)

 Pause briefly at the bottom of the movement

 Drive through your heels to return to the starting position

 Benefits and Considerations

 Advantages

 Reduced Balance Requirements: Fixed bar path makes it easier for beginners

 Controlled Movement: Less risk of improper form compared to free weight squats

 Isolation: Allows focused leg muscle development', 'pernas', '["glúteos","quadríceps"]', '[]', '[]', 'https://wger.de/media/exercise-images/1747/af9647dd-04ec-4adf-9c07-4e33edb77277.jpg', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1747/view/', 'smith machine squat gluteos quadriceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('cbf4cf16-f188-4a60-a223-aa50b163f4b7', 916, 'en', 'Smith Press', 'Sitting almost 90 degree angle, smith machine', 'ombros', '["ombros"]', '[]', '["Banco inclinado"]', 'https://wger.de/media/exercise-images/916/9bf7555a-fec6-43a9-b343-aae496744e5e.png', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/916/view/', 'smith press ombros banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('99a7651b-afc1-4007-ab80-aac590bbfbfe', 1952, 'en', 'SMR Glutes (lax ball)', 'SMR Glutes (lax ball)
Part of: Limber 11
Source: Joe DeFranco
Prescription: 30 sec-2 min
Type: soft_tissue', 'pernas', '["pernas"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1952/view/', 'smr glutes (lax ball) pernas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c8f951dd-94e0-4548-bbed-3b7bc883f7ba', 1576, 'en', 'Snap Down', 'Begin in a standing position with your
arms up over your head and your toes pushing into the ground raising
your heels up becoming as tall as you can. From this position, perform a
small hop with both feet slightly coming off of the ground. As you
land, bend your knees and begin to hinge forward at your hips absorbing
the landing. Return to the starting position and repeat. 
You should feel the muscles in your lower body working. 
Start with your arms and knees fully
straightened out. Keep a stable balance as you land and briefly hold
that end position, don’t go too fast and become off balanced. Keep your
chest up. 
For a detailed video on landing mechanics, click here: https://youtu.be/RThUCYRDyZw', 'pernas', '["posteriores de coxa","glúteos","quadríceps"]', '["panturrilhas","abdômen"]', '[]', NULL, 'CC-BY-SA 4', 'mountain.potato', 'https://wger.de/en/exercise/1576/view/', 'snap down posteriores de coxa gluteos quadriceps panturrilhas abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8161de8b-7802-46c0-9bd4-db60f39b7677', 599, 'en', 'Snatch', 'Stand with your feet at hip width and your shins against the bar. Grasp the bar at double shoulder width and, keeping your lower back flat, drive your heels into the floor to begin lifting the bar. When it''s above your knees, explosively extend your hips and shrug your shoulders. Let the momentum carry the weight overhead.', 'ombros', '["ombros"]', '[]', '["Barra"]', NULL, 'CC0', 'Mens Fitness', 'https://wger.de/en/exercise/599/view/', 'snatch ombros barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('127033e0-46c5-44a6-825b-fbecfe60ed9a', 1447, 'en', 'Snatch OL', 'Olympic lift snatch

 

• Pull barbell from ground to overhead lockout using a wide grip and overhead squat.

• Move bar slowly until cleared knees then explosively extend hips, pull bar up and dive under the bar

• Catch bar overhead with straight arms

• Push head forward during lockout', 'costas', '["ombros","posteriores de coxa","glúteos","quadríceps"]', '["dorsais"]', '["Barra"]', NULL, 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1447/view/', 'snatch ol ombros posteriores de coxa gluteos quadriceps dorsais barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('33a55e1a-ff83-4c34-b056-887a121b0978', 1839, 'en', 'Solo Hip Flexor Stretch', 'See this instructive video: https://www.youtube.com/watch?v=qHwyBHS6MQs .', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1839/view/', 'solo hip flexor stretch pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b1051c3e-78a9-4b73-899c-c700098cf1a8', 604, 'en', 'Speed Deadlift', 'Deadlift with short (less than one 1min) rest between sets.', 'pernas', '["posteriores de coxa","glúteos"]', '["quadríceps","trapézio"]', '[]', NULL, 'CC-BY-SA 4', 'MrSteele', 'https://wger.de/en/exercise/604/view/', 'speed deadlift posteriores de coxa gluteos quadriceps trapezio', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('23d2b2ce-4ae7-441a-a122-9f6784f15aa6', 1810, 'en', 'Sphinx', 'Lie on your stomach flat, legs extended and the backs of your feet on
the ground. Bring your forearms under your shoulders, elbows directly
underneath. Then press your hands into the floor to lift your chest.
Draw your shoulder blades together, open your collarbones, and direct
your gaze forward, while keeping the lower back relaxed.', 'core', '["abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Joculari', 'https://wger.de/en/exercise/1810/view/', 'sphinx abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b3049397-a1d1-4442-9113-3532bcd1f278', 1465, 'en', 'Spider Curl', 'To get the most out of DB Spider Curls, you need an
adjustable weight bench set at a 45-degree incline. This inclined position
allows your arms to hang freely, putting them in an extended start position
with elbows slightly in front of your torso, which is the key to maintaining
low-level isometric tension throughout the movement pattern.

 

• Lie face-down on an adjustable
weight bench with your chest fully supported, holding a pair of dumbbells.

• Keep a neutral head position
and don’t crane your neck.

• Let your arms hang straight
down with your palms facing forward (for a standard Spider Curl) or palms
facing inward for a Hammer Curl exercise variation.

• Keep a stable foot position on
the floor to maintain balance and control.

• Start the curl motion by
flexing your biceps muscles and lifting the pair of dumbbells or curl bar
toward your shoulders.

• Keep your elbow flexion
controlled. Your arms should stay locked in position with no unnecessary
movement.

• Squeeze hard at the top for 1-2 seconds. This
is where maximum tension hits the biceps muscle fibers.

• Lower the weight under control
for 3-4 seconds to keep muscles under tension for the entire range of
motion.', 'braços', '["bíceps"]', '[]', '["Banco inclinado"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1465/view/', 'spider curl biceps banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('eaf6f39e-d46d-4460-b5a9-71e814b18f89', 607, 'en', 'Splinter Sit-ups', 'Lie on your back with your legs straight and arms at your sides, keeping your elbows bent at 90 degrees. As you sit up, twist your upper body to the right and bring your left knee toward your right elbow while you swing your left arm back. Lower your body to the starting position, and repeat to your right. That''s 1 rep.', 'core', '["oblíquos"]', '[]', '[]', NULL, 'CC-BY-SA 3', 'djblitzd', 'https://wger.de/en/exercise/607/view/', 'splinter sit-ups obliquos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('72e21c1e-4112-453d-805e-c84876cac2f2', 2610, 'en', 'Squat -> Stand Coordination', 'Custom description created by the Integrated Conditioning routine importer for wger.', 'pernas', '["glúteos","quadríceps"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2610/view/', 'squat -> stand coordination gluteos quadriceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5c0824dc-f2fb-4d19-a1e5-7c33219ad51d', 614, 'en', 'Squat Jumps', 'Jump wide, then close', 'pernas', '["quadríceps"]', '[]', '[]', NULL, 'CC-BY-SA 3', 'OGhTebfCxhexZXuf35mUxV9C--A', 'https://wger.de/en/exercise/614/view/', 'squat jumps quadriceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e6890815-de67-4882-9cd5-82b7630208ad', 2528, 'en', 'Squat Sky Reach Stretch', '• Drop into a squat.

• Hold one ankle with the opposite hand.

• Fold your other arm to your chest.

• Staying in the squat and keeping hold of your ankle, twist to turn your chest-hand back/outwards until your elbow is pointing at the sky.

• Return to the neutral squatting position with your hand on your chest. Repeat movement as required.

 Repeat on both sides.', 'peito', '["dorsais","peito"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2528/view/', 'squat sky reach stretch dorsais peito', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b3e433ed-0247-46b3-be77-9f2738a09a48', 1548, 'en', 'Stair Master', 'cardio and lower-body strength machine designed to simulate climbing stairs. It provides a low-impact, high-intensity workout that targets the legs, glutes, and core while improving cardiovascular endurance.', 'cardio', '["posteriores de coxa","panturrilhas","glúteos","quadríceps"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'MisterPinnacle', 'https://wger.de/en/exercise/1548/view/', 'stair master posteriores de coxa panturrilhas gluteos quadriceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('93b9b84c-7b72-4712-a7c2-0e14a5fab32a', 1724, 'en', 'Standing Adduction (Cable)', 'Keep your hips square and still, pulling the cable across your opposing leg using only your inner thigh.

 Don’t let your torso lean or twist — no side bending to help the rep.', 'pernas', '["pernas"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1724/view/', 'standing adduction (cable) pernas maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('eb61c7a1-e1c9-4c44-a8ce-2bbe98a39857', 621, 'en', 'Standing Bicep Curl', 'Stand holding dumbbells at shoulder width apart. Face forearm upward and keep upper arm still while raising each dumbbell up to your shoulder.', 'braços', '["bíceps","braquial"]', '[]', '["Halteres"]', NULL, 'CC0', 'BFad07', 'https://wger.de/en/exercise/621/view/', 'standing bicep curl biceps braquial halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a569e8c3-218f-40db-9d71-e155c68cb26e', 1232, 'en', 'Standing biceps stretch left', 'Stand with your left arm close to a wall. Extend your left arm and put your left hand on the wall, then gently turn your body to the right.', 'braços', '["ombros","bíceps","peito"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1232/2b6de046-5806-49e3-bf36-b6fae16af021.png', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1232/view/', 'standing biceps stretch left ombros biceps peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('671568f9-6653-4e11-ac71-3f34c74329a0', 1233, 'en', 'Standing biceps stretch right', 'Stand with your right arm close to a wall. Extend your right arm and put your right hand on the wall, then gently turn your body to the left.', 'braços', '["ombros","bíceps","peito"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1233/d7d6f9e1-7834-4cca-bd3b-f9def33ff44d.png', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1233/view/', 'standing biceps stretch right ombros biceps peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7ce443b6-eb84-4f65-b05f-461c1cc8bcc0', 622, 'en', 'Standing Calf Raises', 'Get onto the calf raises machine, you should able to completely push your calves down. Stand straight, don''t make a hollow back and don''t bend your legs. Pull yourself up as high as you can. Make a small pause of 1 - 2 seconds and go slowly down.', 'panturrilhas', '["panturrilhas"]', '["sóleo"]', '[]', 'https://wger.de/media/exercise-images/622/9a429bd0-afd3-4ad0-8043-e9beec901c81.jpeg', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/622/view/', 'standing calf raises panturrilhas soleo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f36dfa40-7586-4721-a434-1fd878232c62', 1239, 'en', 'Standing Calf Stretch', 'This stretch targets the gastrocnemius (the chief muscle of the calf of the leg, which flexes the knee and foot). It is easy to perform anywhere. All you need is a wall or a chair.', 'pernas', '["panturrilhas"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1239/5026373a-a7b4-4e26-a0aa-c46634205196.jpg', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1239/view/', 'standing calf stretch panturrilhas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('083bc8a6-0eb4-4049-b2ef-88415aa15459', 1575, 'en', 'Standing Dowel Shoulder press', 'Mobility - prone dowel press or standing dowel shoulder press alternating between front andback', 'ombros', '["ombros"]', '[]', '["Barra"]', NULL, 'CC-BY-SA 4', 'mountain.potato', 'https://wger.de/en/exercise/1575/view/', 'standing dowel shoulder press ombros barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f4bb000a-c855-4497-95e0-abc1b71725e7', 1875, 'en', 'Standing IT Band Stretch', 'View the video to undestand the exercise', 'pernas', '["pernas"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1875/e1128391-4b73-43a9-ab27-657d8bb43083.png', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1875/view/', 'standing it band stretch pernas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('af59f161-147a-49ba-85c8-6c9f4e5ffe63', 1396, 'en', 'Standing Pancake', 'Stand and open your legs as wide as possible into a straddle position. Then bend at the hips, pushing them back while keeping your back straight.', 'pernas', '["posteriores de coxa"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1396/view/', 'standing pancake posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('aa3c2791-74f7-4fed-a812-297ff454e2f9', 1397, 'en', 'Standing Pancake Good Morning', 'Stand with your feet wider than shoulder-width apart and toes pointed slightly outward. Place your hands on the back of your head. Hinge at your hips and lower your upper body towards the ground, keeping your back straight and chest open.', 'pernas', '["posteriores de coxa"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1397/view/', 'standing pancake good morning posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7dc59fa0-5552-4ffa-954f-9bc8c22740bf', 623, 'en', 'Standing Rope Forearm', 'Grab a wrist roller tool with both hands while standing with your feet about shoulder width apart. If your gym does not have a wrist roller tool, you can easily put one together. All you need is a 5 or 10 pound weight plate, a strong thin rope about 3 feet long and a 6-8 inch stick or bar. Securely fasten the rope to the middle of the bar/stick and tie the other end of the rope to the weight plate. To begin this exercise, grab the bar/stick with both hands using an overhand grip. Extend both arms straight out in front of you, parallel to the floor. Next, roll the weight up from the floor by rapidly twisting the bar/stick with your hands and wrists. Once the weight reaches the top, slowly lower the plate back to the floor by reversing the motion of your hands and wrists. Repeat (if you can!).', 'braços', '["braços"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'pwiltrout', 'https://wger.de/en/exercise/623/view/', 'standing rope forearm bracos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('864b0a80-5d29-4d87-9144-f6ee6f5087b9', 1426, 'en', 'Standing Side Crunches', 'Standing side crunches are a dynamic exercise that targets the obliques while improving balance and stability. Stand upright with your feet shoulder-width apart and hands behind your head or holding a dumbbell in one hand. Lean your torso to one side, contracting your obliques, while bringing your elbow toward your hip (or crunching toward the weight if using a dumbbell). Return to the starting position and alternate sides or perform all repetitions on one side before switching.', 'core', '["oblíquos"]', '["abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1426/view/', 'standing side crunches obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('56631e7a-471a-469c-958a-c3ff78b1e73c', 1240, 'en', 'Standing Soleus Stretch', 'This stretch targets the Soleus part of your calf. It may be performed with a wall or chair.', 'pernas', '["sóleo"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1240/view/', 'standing soleus stretch soleo peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2f10d91f-6c12-471b-bb9e-80840a56ce01', 1962, 'en', 'Step Jack', 'The Step Jack is a low-impact plyometric-style move that provides cardiovascular benefits without the joint stress of jumping. It works the entire body, specifically targeting the legs, core, and shoulders. This move is ideal for beginners, individuals with joint sensitivities, or as a dynamic warm-up to gradually elevate the heart rate.
Notes (Instructions):

 

• ​Stand upright with your feet together and arms at your sides.

• ​Step your right foot out to the side while simultaneously swinging both arms up above your head.

• Bring your right foot back to the center and lower your arms.

• ​Immediately repeat the movement, stepping out with your left foot.

• ​Continue alternating sides at a steady, rhythmic pace.', 'cardio', '["quadríceps"]', '["ombros","glúteos","oblíquos","abdômen"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1962/74041371-1019-4f89-9ebe-cec792484a46.png', 'CC-BY-SA 4', 'Anon#2', 'https://wger.de/en/exercise/1962/view/', 'step jack quadriceps ombros gluteos obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d2cf769a-9271-41ae-90fc-aef813e41740', 1847, 'en', 'Straddle L-Sit', 'With your legs in a sitting saddle position, push your body upwards off the ground. Your legs should be horizontal and point straight outwards. Your arms should be between your legs.

 Hold isometrically as long as required.', 'core', '["abdômen"]', '["dorsais","peito","quadríceps","serrátil"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1847/view/', 'straddle l-sit abdomen dorsais peito quadriceps serratil peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5abe2fee-6b82-4fce-9ff0-4f5fd2d3d01c', 2524, 'en', 'Straddle Stance Good Morning', '• Hold the barbell on your shoulders as if to squat.

• Take a half-step forwards with one leg, placing your foot on the ground.

• Lock the front leg, and either lock your back leg or allow it to bend very slightly.

• Bend forwards under control to stretch the rear of your front leg, then return to your standing position.

 Repeat as necessary for reps/time. You should also repeat for the other leg.', 'pernas', '["pernas"]', '[]', '["Barra"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2524/view/', 'straddle stance good morning pernas barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('36274d27-3812-4b8c-80e2-ab59acf82c4d', 912, 'en', 'Straight Bar Cable Curls', 'Standing upright in front of Cable Tower using a straight bar', 'braços', '["bíceps"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/912/e10a034f-6370-4dd6-b1c2-416b27844529.png', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/912/view/', 'straight bar cable curls biceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ca16aa3c-9b43-4d81-ae60-1e225163b767', 917, 'en', 'Straight Bar Cable Front Raise', 'Back to cable tower, cable between legs, SZ Bar', 'ombros', '["ombros"]', '[]', '["Máquina de cabo","Barra W"]', NULL, 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/917/view/', 'straight bar cable front raise ombros maquina de cabo barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0f5fc602-afb6-4500-87da-f115f3ef3f47', 628, 'en', 'Straight-arm Pull Down (bar Attachment)', 'Use the straight bar attachment on a high pulley. Grasp the two ends of the bar with your palms facing downward and your arms straight out in front of you. Pull your hands down towards your hips, while keeping your arms straight, then raise them back up to the starting position.', 'costas', '["dorsais"]', '["tríceps"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/628/view/', 'straight-arm pull down (bar attachment) dorsais triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2f7149c3-77ce-4313-a59c-aef82b5a730a', 629, 'en', 'Straight-arm Pull Down (rope Attachment)', 'Use the rope attachment on a high pulley. Grasp the two ends of the rope with your arms straight out in front of you. Pull your hands down towards your hips, while keeping your arms straight, then raise them back up to the starting position.', 'costas', '["dorsais"]', '["tríceps"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/629/view/', 'straight-arm pull down (rope attachment) dorsais triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a45123c6-34c2-43cf-b6bf-914a8f40995a', 1726, 'en', 'Straight-Arm Pulldown (Cable)', 'Keep arms straight but not locked, pulling with your lats, not your shoulders.

 Don’t let your shoulders shrug up during the movement.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1726/2e7e541b-5f55-405a-ae78-3e71b3f42db4.png', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1726/view/', 'straight-arm pulldown (cable) dorsais maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1c17c370-dd74-46c4-b4f2-039c510af058', 2485, 'en', 'Stroke-and-Roll Drill', 'Push off, swim a few strokes, and every breath roll fully onto your back for 2-3 breaths, then roll back into freestyle. This teaches you to rotate your body as a unit rather than just turning your head, and helps remove the fear of not having your face in the water.', 'cardio', '["ombros","oblíquos"]', '["dorsais","abdômen"]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2485/view/', 'stroke-and-roll drill ombros obliquos dorsais abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b6c19c36-34be-4d9f-8c07-8bdf9ab3ba1a', 1776, 'en', 'Suitcase Carry', 'Walk forward and backward with holding dumbbell on one side without leaning to counter the weight.', 'core', '["oblíquos"]', '["abdômen","trapézio"]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/1776/view/', 'suitcase carry obliquos abdomen trapezio halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('0c2d9b74-3d1e-481f-a7bf-3b3532f7d6b0', 630, 'en', 'Sumo Deadlift', '• Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.

• Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.

• As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.

• Return the weight to the ground by bending at the hips and controlling the weight on the way down.', 'pernas', '["posteriores de coxa","glúteos","quadríceps"]', '["trapézio"]', '[]', 'https://wger.de/media/exercise-images/630/b0f0c7d8-5878-4d9e-b820-21acc013741d.webp', 'CC-BY-SA 4', 'magdy', 'https://wger.de/en/exercise/630/view/', 'sumo deadlift posteriores de coxa gluteos quadriceps trapezio', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('66c90ca7-23d8-47b1-820f-dc0c8140603b', 636, 'en', 'Superman', 'Lay flat on your stomach with your arms extended in front of you on the ground as your legs are lying flat. Lift both your arms and legs at the same time, as if you were flying, and contract the lower back. Make sure that you are breathing and, depending on your fitness level, hold the movement for at least two to five seconds per repetition.', 'costas', '["glúteos","dorsais"]', '[]', '["Colchonete"]', NULL, 'CC-BY-SA 4', 'baldurmen', 'https://wger.de/en/exercise/636/view/', 'superman gluteos dorsais colchonete', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2fe15ae4-085b-4116-8d73-2a120cc2a231', 1886, 'en', 'Supine Hip Abduction', '• Starting Position: 
Lie on your back (supine) on a mat, with your legs extended and
relaxed. Arms can be placed alongside your body or out to the sides for
stability.

• The Movement: 
Slightly lift one leg off the floor (keeping it straight or with a
slight bend). Move it laterally outward, away from the other leg, as if
stepping over a small obstacle.

• Range of Motion: 
Move the leg as far as comfortable without lifting your pelvis or
rotating your torso, feeling a stretch in the inner thigh and hip.

• Return: Slowly bring the leg back to the starting position with controlled movement.

• Goal: Improves lateral hip mobility (abduction) and strengthens the pelvic stabilizer muscles.', 'pernas', '["glúteos","quadríceps"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'teus_ergaster', 'https://wger.de/en/exercise/1886/view/', 'supine hip abduction gluteos quadriceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2c31daac-17b1-4cc9-b1c1-f34266ee2038', 1583, 'en', 'Supine press', 'Take a close grip and push perpendicular to the bench. Keep back flat.', 'costas', '["trapézio"]', '[]', '["Barra","Banco"]', NULL, 'CC-BY-SA 4', 'CptnFatbeard', 'https://wger.de/en/exercise/1583/view/', 'supine press trapezio barra banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('86237d20-f4e3-49a6-bf28-9e4660377bc9', 1778, 'en', 'Supino inclinado', 'Inclinado 90 graus e movimentos leves e precisos', 'peito', '["peito"]', '["ombros","tríceps"]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1778/view/', 'supino inclinado peito ombros triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('b81f4e3c-64e2-4fbd-9198-d422f6f2151f', 1876, 'en', 'Supported Calf Stretch', 'View the video to undestand the exercise', 'panturrilhas', '["panturrilhas"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1876/ca7b3fe7-5908-4ec2-9d85-7fa1b80bb105.png', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1876/view/', 'supported calf stretch panturrilhas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a80bddee-6c40-4270-b4f4-68f876787a90', 2611, 'en', 'Supported Deep Squat Breathing', 'Custom description created by the Integrated Conditioning routine importer for wger.', 'pernas', '["glúteos","quadríceps"]', '[]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2611/view/', 'supported deep squat breathing gluteos quadriceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('15cfef4a-471f-4a00-a3c3-973b15bd7cda', 2557, 'en', 'Supported Split Squat', 'Supported split squat performed with stable balance support and controlled depth.', 'pernas', '["quadríceps"]', '["glúteos"]', '[]', NULL, 'CC-BY-SA 3', '', 'https://wger.de/en/exercise/2557/view/', 'supported split squat quadriceps gluteos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e0d9e9ef-09ee-4d26-9504-622093810414', 927, 'en', 'Suspended crossess', 'Suspension exercise with trx for chest training', 'cardio', '["peito"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/927/7b392101-9c47-4693-935e-a88b1887eec5.jpg', 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/927/view/', 'suspended crossess peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1eeccede-29c5-4f38-9ba7-d77c7c47993d', 919, 'en', 'T-Bar row', 'bent over with triangle grip, slightly bent knees', 'costas', '["dorsais","trapézio"]', '[]', '["Barra"]', NULL, 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/919/view/', 't-bar row dorsais trapezio barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a7a1e96f-2f34-48eb-93ad-75c08e9e2721', 2501, 'en', 'Table Bodyweight Rows (Vasco L1)', 'Vasco custom table bodyweight row for horizontal pulling in home training. Zero equipment except sturdy table. Part of Tuesday Pull day.', 'costas', '["dorsais"]', '["bíceps","trapézio"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Vasco Custom', 'https://wger.de/en/exercise/2501/view/', 'table bodyweight rows (vasco l1) dorsais biceps trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('42657bd4-bf4e-4429-8e6a-2f5f585aa22a', 1285, 'en', 'Talons fesses', 'Touch your heels to your buttocks, while remaining static or moving', 'cardio', '["panturrilhas"]', '["posteriores de coxa"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1285/1ab8005d-41e4-4505-9a7d-5277d59bb3cd.jpg', 'CC-BY-SA 4', 'painDpice', 'https://wger.de/en/exercise/1285/view/', 'talons fesses panturrilhas posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('51420ded-5c17-4ce0-b005-89f1b67b7c65', 650, 'en', 'Thruster', '• Start by doing a front squat

• At the top position, push the bar above your head (similar to a press)

• Lower the bar to the shoulders', 'pernas', '["ombros"]', '["trapézio"]', '["Barra"]', NULL, 'CC0', 'BeLikeWater', 'https://wger.de/en/exercise/650/view/', 'thruster ombros trapezio barra', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f5252fbe-1e00-4b8d-8781-2e56d6a5250f', 1200, 'en', 'Tibialis raises', '• Stand up straight

• Lift the balls of your feet, resting on your heels.', 'panturrilhas', '["panturrilhas"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1200/view/', 'tibialis raises panturrilhas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('33728393-2b84-4d39-8b68-462222e004e3', 1425, 'en', 'Toe Taps', 'Toe taps are a core-focused exercise performed lying on your back. Lie flat with your arms by your sides and your legs raised to a tabletop position (knees bent at 90 degrees). Slowly lower one foot to gently tap the floor, keeping your core engaged and your lower back pressed into the ground. Return to the starting position and alternate legs. This exercise strengthens the core while minimizing strain on the lower back.', 'core', '["abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1425/view/', 'toe taps abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a51de8df-4101-45cb-8da5-de230d9bac1d', 1390, 'en', 'Toe Touch', 'Stand with your feet closer together. Hinge at your hips and lower your upper body towards your toes. Reach your hands towards your feet, try to touch your toes, the ground, or as far down your legs as you can comfortably go.', 'pernas', '["posteriores de coxa","glúteos"]', '["panturrilhas"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1390/view/', 'toe touch posteriores de coxa gluteos panturrilhas peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('42d09639-a5a6-4aa6-b115-e4c96b1d3735', 1529, 'en', 'Toes to bar', 'The name "Toes to Bar" says it all: This exercise, in which you hang from a pull-up bar, involves bringing your toes toward the bar, pointing toward your face. This really works your abdominal muscles. "Toes to Bar" is popular in functional fitness programs like Freeletics and CrossFit, and is an effective exercise for six-pack training.', 'core', '["abdômen"]', '["dorsais","oblíquos"]', '["Barra fixa"]', NULL, 'CC-BY-SA 4', 'florian.bussmann', 'https://wger.de/en/exercise/1529/view/', 'toes to bar abdomen dorsais obliquos barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1e9b886f-0dbe-4434-829e-7159bcc40692', 1451, 'en', 'Torso rotation stretch', 'The torso rotation stretch helps improve spinal mobility and relieves tension in the lower back and obliques. It can be performed standing or seated.

 

• Standing Variation : Stand upright with your feet shoulder-width apart. Place your hands on your hips or extend your arms in front of you. Slowly rotate your torso to one side, keeping your hips stable. Hold for a few seconds, then rotate to the opposite side.

• Seated Variation : Sit on a chair with your feet flat on the floor. Place one hand on the outside of your opposite thigh and gently twist your torso toward that side. Hold the stretch before switching sides.', 'peito', '["oblíquos"]', '["peito"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1451/view/', 'torso rotation stretch obliquos peito peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('56a03260-2901-4b28-bd41-a030185f985a', 1377, 'en', 'Torso Twist', 'Standing Torso Twist WorkoutTarget your core and improve flexibility with this dynamic standing exercise! The Standing Torso Twist Workout involves twisting your torso while keeping your feet and hips stable, engaging your obliques, and stretching your entire upper body. This movement helps to:Strengthen core musclesIncrease flexibility in the spine and torsoImprove posture and balanceEnhance overall athletic performancePerform 3 sets of 10-15 reps, twisting to each side, to feel the benefits of this effective and efficient workout!', 'core', '["abdômen"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1377/12e7a231-d36a-4992-bf57-ff7bfe0f3ae4.jpg', 'CC-BY-SA 4', 'brucem', 'https://wger.de/en/exercise/1377/view/', 'torso twist abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f44cf553-067e-4f3a-b35b-e16549c1d055', 1455, 'en', 'Towel Superman', 'In this exercise, you lie flat on your stomach, hold a
towel with your arms extended in front of you, and pull it apart to
create tension. Then, you move it forward and back under your stomach.
This exercise targets the back and shoulder muscles as well as core
stability.', 'costas', '["dorsais"]', '["ombros"]', '[]', NULL, 'CC-BY-SA 4', 'Yderkone', 'https://wger.de/en/exercise/1455/view/', 'towel superman dorsais ombros', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d18407c2-75d0-43d8-8bbc-dfbb256b6b2f', 1803, 'en', 'Trap Bar Squat', 'A combination of squat and deadlift principles with the use of a hex/trap bar, easing stress on the lower back by better centering the weight.', 'pernas', '["quadríceps"]', '["posteriores de coxa"]', '[]', NULL, 'CC-BY-SA 4', 'kmcalderwood', 'https://wger.de/en/exercise/1803/view/', 'trap bar squat quadriceps posteriores de coxa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('41b9f5a5-73de-414d-b08a-54025eccedc6', 1581, 'en', 'Trap press', 'Laying flat with arm pointing straight upwards, elbow fully extended, use only your shoulder to raise the weight as high as comfortable and back to rest.', 'ombros', '["trapézio"]', '[]', '["Barra","Banco","Halteres"]', 'https://wger.de/media/exercise-images/1581/b71a6710-5798-4639-ac5a-22a2cdae2036.jpg', 'CC-BY-SA 4', 'CptnFatbeard', 'https://wger.de/en/exercise/1581/view/', 'trap press trapezio barra banco halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('62f90b5c-7451-4fd0-91ae-4dd93c51aa41', 1834, 'en', 'Trap-3 Raise', '• Hinge forwards and bend your knees slightly. Depress and retract the shoulder you will use. Rest the other hand on your knee.

• Raise your hand about 15 degrees overhead, maintaining the position of your shoulder.', 'costas', '["trapézio"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1834/view/', 'trap-3 raise trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5915fabe-c941-4dac-b196-bc4e8c7ce57b', 655, 'en', 'Tricep Dumbbell Kickback', '• Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.

• Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.

• After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.

• Repeat the movement for the prescribed amount of repetitions.

 Variations: This exercise can be executed also one arm at a time much like the one arm rows are performed.

 Also, if you like the one arm variety, you can use a low pulley handle instead of a dumbbell for better peak contraction. In this case, the palms should be facing up (supinated grip) as opposed to the torso (neutral grip).', 'braços', '["tríceps"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 3', 'http://www.bodybuilding.com/', 'https://wger.de/en/exercise/655/view/', 'tricep dumbbell kickback triceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('42cdddc2-970e-445c-a766-f6562bf63069', 2522, 'en', 'Tricep Pull-Down', 'Secure Band above you. 

 

• Stand facing band, with feet hip-width apart.

• Bend your knees slightly to engage your core.

• Keep your chest up, pin your shoulder blades back, and tuck your elbows tightly to the sides of your torso.

• Exhale and pull the band straight down toward your thighs.

• Inhale and slowly control the band as you let your arms return upwards to their starting position.', 'braços', '["tríceps"]', '["peito"]', '["Elástico"]', NULL, 'CC-BY-SA 4', 'G. Johnson', 'https://wger.de/en/exercise/2522/view/', 'tricep pull-down triceps peito elastico', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('ea63d85c-8579-4dda-b99f-c4c8930f9af6', 805, 'en', 'Tricep Pushdown on Cable', 'The cable rope push-down is a popular exercise targeting the triceps muscles. It''s easy to learn and perform, making it a favorite for everyone from beginners to advanced lifters. It is usually performed for moderate to high reps, such as 8-12 reps or more per set, as part of an upper-body or arm-focused workout.', 'braços', '["tríceps"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/805/7a437824-e2cc-46e1-804a-674f0ea31d25.png', 'CC-BY-SA 4', 'cshep442', 'https://wger.de/en/exercise/805/view/', 'tricep pushdown on cable triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('fc608f0e-d754-4911-ae59-8856952e7064', 1900, 'en', 'Tricep Rope Pushdowns', '• Setup: Stand facing the cable, feet shoulder-width apart, with a slight forward lean.

• Grip: Hold the rope with palms facing each other and elbows tucked tight to your ribs.

• Execution: Push the rope down until arms are fully straight, pulling the ends apart at the bottom.

• Control: Keep upper arms still and return to the start with a slow, controlled motion.', 'braços', '["tríceps"]', '["dorsais"]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1900/a8243245-8f8f-4e2b-93ca-694d416cb11d.png', 'CC-BY-SA 4', 'nishant0712', 'https://wger.de/en/exercise/1900/view/', 'tricep rope pushdowns triceps dorsais maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3dd0db1c-450a-46d1-ad46-d7854bdc26ed', 1372, 'en', 'Triceps Dips (Assisted)', 'Assisted triceps dips is a gym work out exercise that targets triceps and also involves chest.', 'braços', '["tríceps"]', '["peito"]', '[]', NULL, 'CC-BY-SA 4', 'matpn', 'https://wger.de/en/exercise/1372/view/', 'triceps dips (assisted) triceps peito', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3188868c-84e2-4a3b-b7dc-f79d8650988d', 659, 'en', 'Triceps Extensions on Cable', 'Grab the cable, stand with your feet shoulder wide, keep your back straight and lean forward a little. Push the bar down, making sure the elbows don''t move during the exercise. Rotate your hands outwards at the very end and go back to the initial position without pause.', 'braços', '["tríceps"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/659/a60452f1-e2ea-43fe-baa6-c1a2208d060c.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/659/view/', 'triceps extensions on cable triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('19133a0d-e6b2-4d57-8a84-8aac3d962a99', 1336, 'en', 'Triceps Overhead (Dumbbell)', '• Keep the elbows fixed

• Engage the muscles

• Don''t use momentum

• Controlled movement

• Slow movement

• Don''t overextend', 'braços', '["tríceps"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1336/ebf88217-df26-4ef7-94cb-f0c2220c6abe.webp', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1336/view/', 'triceps overhead (dumbbell) triceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6ebb138e-bb0a-402e-84e5-68fe0896e897', 1185, 'en', 'Triceps Pushdown', 'Triceps pushdown on cable using lat bar.', 'braços', '["tríceps"]', '[]', '["Máquina de cabo"]', 'https://wger.de/media/exercise-images/1185/c5ca283d-8958-4fd8-9d59-a3f52a3ac66b.jpg', 'CC-BY-SA 4', 'anto.kreegyr', 'https://wger.de/en/exercise/1185/view/', 'triceps pushdown triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('788b66aa-7e59-493f-ad9a-0522736c7ef0', 2541, 'en', 'Triceps Pushdown Isometric', 'A single-arm isometric or isolated triceps pushdown is an isolation cable exercise where you pin your upper arm against your torso, hinge at the hips, and extend the elbow to achieve a peak contraction in the triceps muscle.', 'braços', '["tríceps"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2541/view/', 'triceps pushdown isometric triceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('aa72741d-17ae-410e-b49a-1df7aaf0afe1', 1230, 'en', 'Triceps stretch left', 'Put your left hand on your back, use your right hand to grab your left elbow and gently pull it. Hold this position for a few seconds.', 'braços', '["tríceps"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1230/9fd1e2fd-f2c4-432d-b3ae-5e5f24085777.webp', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1230/view/', 'triceps stretch left triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1b9968f4-a00b-4157-8847-1c3c7dbb0d5a', 1231, 'en', 'Triceps stretch right', 'Put your right hand on your back, use your left hand to grab your right elbow and gently pull it. Hold this position for a few seconds.', 'braços', '["tríceps"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1231/b10457ce-5fa5-4d20-a32f-3c7100c6a9d9.webp', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1231/view/', 'triceps stretch right triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('90e9f590-7d68-4afb-9f95-8429246ea4aa', 672, 'en', 'Trunk Rotation With Cable', 'Seated trunk rotation with cable', 'core', '["oblíquos"]', '["dorsais"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Robertcoop', 'https://wger.de/en/exercise/672/view/', 'trunk rotation with cable obliquos dorsais maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8019be2c-47a3-475f-8e16-a2fca761a8fe', 1269, 'en', 'TRX dips', 'Start with the hands on the suspension trainer and feet on the ground.
Your hands should be under your shoulders with the feet slightly in front.
Lower yourself by bringing the hips between the handles and flexing the elbows.
Extend the elbows to come back to the starting position and repeat.', 'braços', '["tríceps"]', '["peito"]', '[]', NULL, 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1269/view/', 'trx dips triceps peito', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f9329ed4-8185-49a6-a0bb-e0f21c6cc3d8', 1261, 'en', 'TRX gorilla biceps curl', 'We''ll stand facing the TRX straps and grab them with our fists facing each other, facing forward, with our arms fully extended at about shoulder-width apart. We''ll keep our body straight, backward, as in the previous exercises, since we''ll be lifting our body toward the TRX straps by activating our biceps. Our body will be straight, with our feet flat on the floor. This time, we''ll place our arms open to the sides and at chest height. The movement we''ll perform is a contraction toward our chest. To achieve this, we''ll bend our elbows so that, by activating our biceps, we can pull our body toward the straps.', 'braços', '["braquial"]', '["bíceps"]', '[]', NULL, 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1261/view/', 'trx gorilla biceps curl braquial biceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f36a9fd0-7bd2-42a4-85fa-902b7cf3be45', 1260, 'en', 'TRX hammer curl', 'Place the grips as if they were a continuation of the straps. We will position our arms stretched forward and our body leaning back, completely straight. The biceps muscles will activate as you bend your elbows to bring your body towards the straps. The contraction movement will end with a slight outward movement of the hands, due to the grip we are using.', 'braços', '["bíceps"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1260/view/', 'trx hammer curl biceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6679b2ad-91b7-4a75-9230-3ae1101bdd50', 1259, 'en', 'TRX Obliques', '• Place your feet in the stirrups and assume a high plank with your hands directly beneath your shoulders.

• Pull your knees to your right elbow, then push them back out and to the centre.', 'core', '["oblíquos","abdômen","serrátil"]', '["ombros","peito"]', '[]', NULL, 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1259/view/', 'trx obliques obliquos abdomen serratil ombros peito', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('069711c7-565a-4abb-90a7-614f66dd9dc3', 1246, 'en', 'TRX roll out', 'Hold the handles in your hands, extend your arms and keep them parallel at chest height. The movement you need to perform is to open your arms in line with your shoulders while leaning your body forward. Try not to extend your shoulders beyond 90°, and keep your abdominal muscles and glutes contracted. Muscles involved: transverse abdominis, rectus abdominis and spinal erectors.', 'core', '["abdômen"]', '["oblíquos","serrátil"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1246/view/', 'trx roll out abdomen obliquos serratil peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('e2599e86-d8b0-434e-8a48-aa3c2df7e790', 959, 'en', 'TRX Rows', 'This exercise serves as a lead-up to Pull Ups.', 'costas', '["ombros","bíceps","dorsais"]', '[]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/959/53a5e008-bc31-4ee0-9463-69a858c2ec18.png', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/959/view/', 'trx rows ombros biceps dorsais peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('7f2628bf-6381-4228-9840-b75cbcc843a1', 1262, 'en', 'Trx Single Arm Bicep Curl', 'Step 1: Stand comfortably and grasp the handles of the suspension system. Step 2: Lean back resting your weight on one arm, keepng the spine neutral. Step 3: Slowly curl to pull your body weight to the up position. Supinate the arm and squeeze as you approach the end position. Step 4: Lower yourself back down and repeat.', 'braços', '["bíceps","braquial"]', '["ombros","trapézio"]', '[]', NULL, 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1262/view/', 'trx single arm bicep curl biceps braquial ombros trapezio', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('de8a3db6-2b05-4c4e-977b-b61342718356', 1266, 'en', 'TRX Tricep Extension', 'Attach the TRX or other suspension system overhead, having the handles hanging at chest level or slightly lower. Experiment to see what height allows you to set up in the best way.
Stand in front of the handles and grab them with your palms facing down.
Engage your abs, squeeze your glutes, take a breath and lean forward, lifting your heels off the floor. Keep your elbows straight.
Take another breath and lower yourself slowly by bending your elbows.
Go down until your elbows are at a 90-degree angle (to the point where your wrists are above your elbows). Hold the position for a moment.
Extend your arms by engaging your triceps and bring yourself to the starting position as you exhale.', 'braços', '["tríceps"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'cynomops', 'https://wger.de/en/exercise/1266/view/', 'trx tricep extension triceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9396a728-3da4-4390-ae4d-882395805008', 1704, 'en', 'Tuck L-sit', 'The tuck L-sit is a bodyweight hold where you support yourself on parallel bars, parallettes, or the floor with straight arms while pulling your knees toward your chest. Your hips stay lifted, your spine stays tall, and your feet hover off the ground. The goal is to keep your core tight, shoulders depressed, and arms locked out while maintaining the tucked position. It’s a core-intensive, shoulder-stabilizing static hold often used as a progression toward the full L-sit.', 'core', '["abdômen"]', '["braquial","peito","quadríceps","trapézio","tríceps"]', '["Banco"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1704/view/', 'tuck l-sit abdomen braquial peito quadriceps trapezio triceps banco', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3e9973f6-c218-4dd4-850b-da6f4f1622bb', 1916, 'en', 'Tuck planche', 'Basic calisthenics progression for the full planche', 'ombros', '["ombros","abdômen","serrátil"]', '["oblíquos","peito","tríceps"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1916/e7d97b4b-9fe4-4378-aea3-5a9d93b6eb8d.png', 'CC-BY-SA 4', 'ISSACS', 'https://wger.de/en/exercise/1916/view/', 'tuck planche ombros abdomen serratil obliquos peito triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('309bfd2b-1af4-49db-b64b-d7d7c7dd39bb', 675, 'en', 'Turkish Get-Up', 'Starting on back, move to the standing position with dumbbell in one hand. Switch hands between reps.', 'core', '["ombros","glúteos","oblíquos","serrátil"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'dookie1481', 'https://wger.de/en/exercise/675/view/', 'turkish get-up ombros gluteos obliquos serratil halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('075bff87-f676-4d9d-92b4-39d557453fc7', 1607, 'en', 'Typewriter Pull-ups', 'Hang from a pull-up bar with an overhand grip, slightly wider than shoulder-width. Pull yourself up until your chin is above the bar. At the top position, instead of going straight down, shift your body to one side by extending one arm while keeping the other arm bent. Move smoothly from one side to the other, like a typewriter motion, before lowering yourself back down. This exercise increases time under tension and strengthens the lats, biceps, and shoulders while building unilateral pulling strength.', 'costas', '["bíceps","dorsais"]', '["trapézio"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'tenebrizz', 'https://wger.de/en/exercise/1607/view/', 'typewriter pull-ups biceps dorsais trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('76965848-9776-4be5-b879-e3c97033b80f', 684, 'en', 'Underhand Lat Pull Down', 'Grip the pull-down bar with your palms facing you and your hands closer than shoulder-width apart. Lean back slightly and keep your back straight. Pull the bar down towards your chest, pulling your shoulders back slightly at the end of the motion.', 'costas', '["dorsais"]', '["bíceps"]', '[]', NULL, 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/684/view/', 'underhand lat pull down dorsais biceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('c1a9297d-6786-45dc-9047-5539fb61db9c', 1621, 'en', 'Unilateral Cable row', 'Put a vertical seated bench in front of the cable row machine.position it so that you can focus on one side, and then do slow pulls focusing on the lateral muscles and ensuring tention in those muscles when in a stretched position.', 'costas', '["dorsais","serrátil"]', '[]', '["Banco","Máquina de cabo"]', 'https://wger.de/media/exercise-images/1621/ca1bc68d-9c36-4dd3-8ec4-496c57b5c564.jpg', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1621/view/', 'unilateral cable row dorsais serratil banco maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d788811b-be46-485a-b8a0-0d9ba7f4cf85', 1795, 'en', 'unilateral cross body cable pull down', 'on a cable rack place cable high, and with a straight arm pull that cable across you from high to low. focus on tension in back shoulder.', 'ombros', '["dorsais"]', '["ombros"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1795/view/', 'unilateral cross body cable pull down dorsais ombros maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('139e3d1a-ccd5-46cd-b953-8db6cea7b005', 1913, 'en', 'Unilateral Hip Thrust', 'Extend one leg while laying down and start raising your body with one leg touching the ground through the heel.', 'pernas', '["glúteos"]', '["abdômen"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1913/view/', 'unilateral hip thrust gluteos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2dd1cf54-b8e3-4769-9455-48120d7cc427', 1907, 'en', 'Unilateral Lunges', 'No stops during movement, hands on the hips.', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1907/view/', 'unilateral lunges gluteos quadriceps posteriores de coxa peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('df18b577-0610-4804-a993-161024da67db', 1381, 'en', 'Upper Back', 'Upper Back is suitable for building up the core muscles with a special focus on the deltoid and rhomboid muscles and the upper back muscles', 'costas', '["ombros","trapézio"]', '["bíceps","dorsais"]', '[]', NULL, 'CC-BY-SA 4', 'phpi', 'https://wger.de/en/exercise/1381/view/', 'upper back ombros trapezio biceps dorsais', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6fc4815a-8852-4e89-a10b-bd36a9029dbb', 688, 'en', 'Upper External Oblique', 'Exercise for upper external oblique muscles', 'peito', '["oblíquos"]', '[]', '["Barra fixa"]', NULL, 'CC-BY-SA 3', 'http://www.carinatum.com/', 'https://wger.de/en/exercise/688/view/', 'upper external oblique obliquos barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('01976085-6701-45ea-b152-5c46ba60550d', 694, 'en', 'Upright Row w/ Dumbbells', 'Hold a dumbbell in each hand in front of your body. Keep your palms towards your body. Lift you hands straight up until your hands are under your chin, then lower them. Repeat the exercise.', 'ombros', '["ombros","trapézio"]', '["bíceps"]', '["Halteres"]', 'https://wger.de/media/exercise-images/694/119e6823-6960-4341-a9e1-aaf78d7fb57c.png', 'CC-BY-SA 4', 'koreyhinton', 'https://wger.de/en/exercise/694/view/', 'upright row w/ dumbbells ombros trapezio biceps halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('738137c0-5387-4215-b457-ea7af113b3ba', 691, 'en', 'Upright Row, on Multi Press', 'The movements are basically the same as with an SZ-bar, but you use the bar on the multi press:

 Stand straight, your feet are shoulder-width apart. Hold the bar with an overhand grip on your thighs, the arms are stretched. Lift the bar close to the body till your chin. The elbows point out so that at the highest point they form a V. Make here a short pause before going slowly down and repeating the movement.', 'ombros', '["ombros","trapézio"]', '["bíceps"]', '[]', 'https://wger.de/media/exercise-images/691/297d4ce1-7e9e-4adb-8f5c-7d54054be885.jpg', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/691/view/', 'upright row, on multi press ombros trapezio biceps', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5d40c67d-be59-4092-9c9c-301ca5310e2b', 693, 'en', 'Upright Row, SZ-bar', 'Stand straight, your feet are shoulder-width apart. Hold the SZ-bar with an overhand grip on your thighs, the arms are stretched. Lift the bar close to the body till your chin. The elbows point out so that at the highest point they form a V. Make here a short pause before going slowly down and repeating the movement.', 'ombros', '["ombros","trapézio"]', '["bíceps"]', '["Barra W"]', 'https://wger.de/media/exercise-images/693/05c91bd2-7814-40b6-b2d1-51ae942b8321.png', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/693/view/', 'upright row, sz-bar ombros trapezio biceps barra w', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d847301e-1613-4987-85cd-61d3ff9d7ef8', 695, 'en', 'V-Bar Pulldown', 'Pulldowns using close grip v-bar.', 'costas', '["dorsais"]', '["bíceps","trapézio"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'apeschel', 'https://wger.de/en/exercise/695/view/', 'v-bar pulldown dorsais biceps trapezio maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('36b6919a-0e9d-49c6-891b-28fb55ae88ad', 1090, 'en', 'Vpushup', 'Lift your body off the ground by pushing your arms upwards', 'core', '["peito","quadríceps","abdômen","tríceps"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1090/view/', 'vpushup peito quadriceps abdomen triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8b494562-012e-4944-be65-9b168f0c8c41', 1474, 'en', 'W-Raise', 'This challenging exercise is a variation of reverse crunches that is made up of three parts in which we’re basically drawing an upside down ‘W’ with our legs.
Start position is lying face up flat on the floor with legs extended at the low point of the outer leg of the ‘W’. Keeping a strong core and legs straight, go up, rise your hips and then slowly lower your legs down halfway. Then, lifting your legs back up to the top, rise your hips again, maintaining that straight line, use your core strength to finally come back all the way down to the other outer leg of the W. Then you reverse the ‘W’ to return to the start.', 'core', '["oblíquos","abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1474/view/', 'w-raise obliquos abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2e00d8e5-19a2-42ad-a954-f06a56f56561', 1104, 'en', 'Walking', 'Walking outdoor or indoor, try keeping a pace of at list 100 steps per minute.', 'cardio', '["posteriores de coxa","panturrilhas","glúteos","dorsais","oblíquos","quadríceps","abdômen"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/1104/view/', 'walking posteriores de coxa panturrilhas gluteos dorsais obliquos quadriceps abdomen peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f636ae1c-f678-48fe-96b3-1a9ae81f43ce', 1103, 'en', 'walking bridge', 'from a standing position with knees slightly bent and hands resting on the floor. From here, proceed forward with your hands keeping your buttocks contracted and without losing control of your lower back.', 'core', '["abdômen"]', '["ombros","bíceps","glúteos","dorsais"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1103/view/', 'walking bridge abdomen ombros biceps gluteos dorsais peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2eb61587-85d1-494f-b2fb-a92dd108b3d3', 1679, 'en', 'Wall Angels', 'The Wall Angels exercise primarily targets the upper back and shoulder muscles , helping improve posture , shoulder mobility , and scapular control .', 'ombros', '["trapézio"]', '["ombros"]', '[]', NULL, 'CC-BY-SA 4', 'bbayuwega', 'https://wger.de/en/exercise/1679/view/', 'wall angels trapezio ombros', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('6dac28e1-0bf1-44e5-82b5-b2ed2304d8e5', 2550, 'en', 'Wall Baby Breathing', 'Relaxed supine or wall-supported breathing emphasizing diaphragmatic expansion, rib movement, abdominal relaxation, and coordinated pelvic floor relaxation.', 'core', '["core"]', '[]', '[]', NULL, 'CC-BY-SA 3', 'Personal routine', 'https://wger.de/en/exercise/2550/view/', 'wall baby breathing core', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f20ab712-f953-4705-8710-9681392ddd07', 1100, 'en', 'Wall balls', 'Get a medicine ball, shoulder width stance, squat, thrust the ball as high as possible against the wall and catch', 'pernas', '["ombros","glúteos","quadríceps"]', '["bíceps","peito","abdômen","trapézio"]', '["Bola suíça"]', 'https://wger.de/media/exercise-images/1100/ab203e0c-8220-4537-987c-871eb259d687.jpg', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1100/view/', 'wall balls ombros gluteos quadriceps biceps peito abdomen trapezio bola suica', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('36a309ba-7dd1-43c9-9efc-788c7cd9fbd6', 1196, 'en', 'Wall Drills', 'Exercises for strengthening knee and leg musculature.

 

• Lateral Wall Drills March - https://youtu.be/9RiTlJ6Mmek

• Lateral Wall Drills OPEN - https://youtu.be/ADRlN8-Wfdg

