INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('37895cdd-aa94-43b5-8b76-4494b7ffeac2', 2496, 'en', 'Wall Push-ups (Vasco L1)', 'Vasco custom beginner wall push-up for zero-equipment home training. Part of 7-day Push/Pull/Core/Lower/Full/Recovery/Rest periodization. 6:30 AM wake, 1hr sessions. Stoic discipline focus.', 'peito', '["peito"]', '["ombros","oblíquos"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Vasco Custom', 'https://wger.de/en/exercise/2496/view/', 'wall push-ups (vasco l1) peito ombros obliquos peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('51a80676-92d8-4f91-b51a-4666888e40db', 713, 'en', 'Wall Pushup', 'Pushup against a wall', 'braços', '["ombros","peito","tríceps"]', '["glúteos","abdômen","serrátil","trapézio"]', '["Peso corporal"]', NULL, 'CC-BY-SA 3', 'Dexter', 'https://wger.de/en/exercise/713/view/', 'wall pushup ombros peito triceps gluteos abdomen serratil trapezio peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f1946fd4-793d-47a5-b66f-599b7f53695d', 716, 'en', 'Wall Slides', 'Stand with heels, shoulders, back of head, and hips touching the wall. Start with biceps straight out and elbows at a 90 degree angle. Straighten the arms while remaining againstthe wall without arching the back off of the wall, mimicking a shoulder press movement.', 'costas', '["bíceps","posteriores de coxa","peito","trapézio","tríceps"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Whythebigpaws', 'https://wger.de/en/exercise/716/view/', 'wall slides biceps posteriores de coxa peito trapezio triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('9a5d36b8-7fa5-4705-8e9b-fafa211a13d6', 2483, 'en', 'Wall-Hold Rotation', 'Hold the pool wall or edge with one hand, body horizontal at the surface, legs kicking gently behind you. Keep your face in the water, exhaling continuously, then rotate your head to the side — not lifting it up — so one goggle stays in the water while the other clears the surface. Take a quick breath, then rotate your face back down to neutral. This isolates the head-rotation motion without any arm strokes to think about.', 'cardio', '["oblíquos"]', '["abdômen"]', '[]', NULL, 'CC-BY-SA 4', '', 'https://wger.de/en/exercise/2483/view/', 'wall-hold rotation obliquos abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('3f8ad988-1aee-48ca-ad37-44e39ae1715d', 1408, 'en', 'Wall-sit', 'The Wall Sit (or wall chair) is an isometric exercise that mainly involves the leg muscles, improving muscular endurance and stability. Here are the main and secondary muscles activated during the exercise.', 'pernas', '["glúteos","quadríceps"]', '["panturrilhas","abdômen"]', '[]', NULL, 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1408/view/', 'wall-sit gluteos quadriceps panturrilhas abdomen', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8d333b94-148c-48f8-9154-8b13279500d1', 1648, 'en', 'Weighted Crunch', 'The Weighted Crunch is a variation of the classic crunch exercise that involves adding resistance (a weight) to increase the intensity of the abdominal work.

 

• Lay down

• (Optional) Bend your knees to add difficulty

• (Optional) Bend your knees and let your feet rest on a bench or a box or something (90 degree angle on knees)

• Lift your head and torso while bending your back forward (if you don''t it''s a sit-up and also involves some back muscles). The higher you go, the more you should feel your abs contracting.

• Go back to starting position an repeat', 'core', '["oblíquos"]', '[]', '["Halteres"]', 'https://wger.de/media/exercise-images/1648/63ae02d6-6dd9-4e9e-84da-d4905e78a33c.jpg', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1648/view/', 'weighted crunch obliquos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('37abbe32-2fab-4818-8355-fffcff2dc3e3', 1902, 'en', 'Weighted push-ups', '• Setup: Begin in a standard plank position with a weight plate balanced securely on your upper back.

• Alignment: Maintain a straight line from your head to your heels, engaging your core to prevent your back from sagging.

• Execution: Lower your body until your chest nearly touches the floor, keeping your elbows at a forty-five degrees .

• Ascent: Press through your palms to return to the starting position, fully extending your arms.', 'peito', '["peito"]', '["tríceps"]', '["Peso corporal"]', 'https://wger.de/media/exercise-images/1902/d0c3f170-543c-4be4-bc70-5c6dc606406c.png', 'CC-BY-SA 4', 'nishant0712', 'https://wger.de/en/exercise/1902/view/', 'weighted push-ups peito triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('591992cb-48ee-4b39-b790-e05b4a2c11e3', 722, 'en', 'Weighted Step-ups', 'box step ups w/ barbell and 45''s on each side', 'pernas', '["glúteos","quadríceps"]', '["posteriores de coxa","panturrilhas"]', '[]', NULL, 'CC0', 'jigglychipmunk', 'https://wger.de/en/exercise/722/view/', 'weighted step-ups gluteos quadriceps posteriores de coxa panturrilhas', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('1842e1be-ac67-4f34-a527-4ca2b72d8e11', 1964, 'en', 'Wide Push-Up', '​A push-up variation with a wider hand placement to increase the emphasis on the outer chest muscles and shoulders.

 

• ​Setup: Place hands wider than shoulder-width apart on the floor.

• Lower: Descend until your chest nearly touches the floor, keeping your core tight.

• ​Push: Drive through your palms to return to the start position.

• ​Form: Don''t let your lower back sag; keep a straight line from head to heels.', 'peito', '["peito"]', '["abdômen","tríceps"]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'Anon#2', 'https://wger.de/en/exercise/1964/view/', 'wide push-up peito abdomen triceps peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('55b9d286-c4cc-4a29-97ad-58cb13c2bb7e', 723, 'en', 'Wide-grip Pulldown', '• 
 Starting position: 

 

• Arms extended overhead, feeling a stretch in your lats.

• Keep your shoulders depressed (don’t shrug upward).

• 
 Pulling phase (concentric): 

 

• Pull the bar down to your upper chest or collarbone area by driving your elbows down and back.

• Keep your chest lifted and squeeze your shoulder blades together at the bottom.', 'costas', '["dorsais"]', '["ombros","braquial","serrátil","trapézio"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/723/view/', 'wide-grip pulldown dorsais ombros braquial serratil trapezio maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('d33f3b19-436f-48a2-aff6-946582c94bdb', 1125, 'en', 'Wide-grip supinated lat pulldown', 'Downward movement
• Pull the bar down so that it passes close to your chin and touches the upper part of your chest.
• Keep the rest of your body still.', 'costas', '["dorsais"]', '[]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1125/view/', 'wide-grip supinated lat pulldown dorsais maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('026d2939-9156-408b-bf11-21cfa8278851', 1743, 'en', 'Windshield Wipers', 'Hang from a pull-up bar, raise your legs to the ceiling. Move lower body from left to right with straight legs like a windshield wiper', 'core', '["oblíquos","abdômen"]', '[]', '["Barra fixa"]', NULL, 'CC-BY-SA 4', 'Happy', 'https://wger.de/en/exercise/1743/view/', 'windshield wipers obliquos abdomen barra fixa', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('a5828b61-2f5c-42a0-a085-71b91d18ecc3', 2543, 'en', 'Wrist circles', 'Wrist circles is warm-up exercise, where you rotate your wrists in a circular motion. They improve mobility and are recommended before exercises such as pull ups, hand stands and other exercises that put pressure on your wrists.', 'braços', '["braços"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'Awlex', 'https://wger.de/en/exercise/2543/view/', 'wrist circles bracos', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('f6471f4a-0290-4a71-9580-bf3d046fdb9d', 1771, 'en', 'Wrist curl, cable', '• Extend your arm down, then slightly lift your forearm

• Extend your wrist in a supinated form (palm up)

• Adjust cable height so that the cable handle is in your supinated hand

• Perform the movement by
curling your palms and wrists upwards

• (optional/variable) Pause at the top

• Slowly return to the starting position', 'braços', '[]', '["bíceps"]', '["Máquina de cabo"]', NULL, 'CC-BY-SA 4', 'eufvksruh', 'https://wger.de/en/exercise/1771/view/', 'wrist curl, cable biceps maquina de cabo', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('2cc92db8-b245-44b8-b1d6-bf91c78c2ab9', 1205, 'en', 'Wrist curl, dumbbells', '• Sitting on a bench, grab the dumbbell with your palms facing up
and your hands shoulder-width apart. Rest your forearms on your thighs
and allow your wrists to hang over your knees.

• Perform the movement by
curling your palms and wrists towards your face.

• (optional/variable) Pause at the top.

• Slowly return to the starting position.', 'braços', '["braços"]', '[]', '["Halteres"]', NULL, 'CC-BY-SA 4', 'wakanda90', 'https://wger.de/en/exercise/1205/view/', 'wrist curl, dumbbells bracos halteres', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('8ca01d32-2e86-49a1-a130-b99219432e42', 1244, 'en', 'Yoga exercise: Cow-cat', 'First get into the four-footed stance. The hands are underneath the shoulders. The fingers are fanned out wide and ensure a stable stance. It is best to rest your front body weight on your thumbs and index fingers. Now place your legs hip-width apart on the yoga mat. Your thighs should be vertically below your hips. Make sure that your weight is evenly distributed between your hands and knees. Your head is an extension of your spine and you are looking down at your mat. Your back is in a neutral position. Breathe in deeply and start with the cat. With the next exhalation, round your back vertebra by vertebra. Try to pull yourself as far as possible towards the ceiling. Pull your head towards your chest and tilt your pelvis. Now inhale deeply and move into the opposite position, cow pose. Bend your back down, pull your shoulders back slightly and lift your head as far as is comfortable for you. Your gaze is directed upwards. Breathe out consciously and switch back to the cat. With the next exhalation, switch back to cow. Repeat the exercise a few times and make sure that you are in the flow.', 'costas', '["ombros","dorsais","trapézio"]', '["oblíquos","abdômen"]', '["Colchonete"]', NULL, 'CC-BY-SA 4', 'damnlost', 'https://wger.de/en/exercise/1244/view/', 'yoga exercise: cow-cat ombros dorsais trapezio obliquos abdomen colchonete', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('142fcef5-63a7-4d30-81e4-bc9d7073fe99', 2454, 'en', 'YTW Raises', 'The YTW exercise for scapular retraction is designed to strengthen the inter-scapular muscles between your shoulder blades, to help retract or pull your shoulders back, helping to maintain proper upright posture.', 'ombros', '["ombros"]', '[]', '["Peso corporal"]', NULL, 'CC-BY-SA 4', 'probablyforging', 'https://wger.de/en/exercise/2454/view/', 'ytw raises ombros peso corporal', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('5986cd29-11ff-43f4-af65-fc48dec62156', 1885, 'en', 'YTWL Exercise', '• Purpose: Improves shoulder stability, posture, and scapular (shoulder blade) control. Often used in physical therapy and warm-ups.

• Starting Position: 
Stand with feet shoulder-width apart. Hinge forward at the hips (like a
deadlift) keeping your back flat, or lie face down on an incline bench.
Keep your thumbs pointing up throughout.

• Y (Arms up): 
Extend both arms straight forward and upward at a 135-degree angle from
your body, forming a "Y". Squeeze your shoulder blades together at the
top.

• T (Arms out): Open your arms straight out to the sides, perpendicular to your body, forming a "T". Focus on pinching your shoulder blades.

• W (Arms bent): Pull your elbows back, bending them to 90 degrees, and squeeze your shoulder blades to form a "W". Keep your wrists firm.

• L (Arms rotated): 
Start with elbows bent at 90 degrees and close to your body. Rotate
your forearms outward (external rotation) like a goalpost, forming an
"L" or a gate.

• Key Focus: 
Movements should be slow and controlled. Always lead with the thumbs
and think about moving the shoulder blades, not just the arms.', 'ombros', '["ombros","trapézio"]', '[]', '["Halteres","Banco inclinado"]', NULL, 'CC-BY-SA 4', 'teus_ergaster', 'https://wger.de/en/exercise/1885/view/', 'ytwl exercise ombros trapezio halteres banco inclinado', '2026-09-10T15:18:12.614Z');
INSERT INTO exercises (id, wger_id, language, name, description, category, muscles, muscles_secondary, equipment, image_url, license, license_author, source_url, search_blob, updated_at) VALUES ('981b07b6-e76e-438c-bad4-388441b7ff33', 1083, 'en', 'YWTs', 'Starting position: 
Lie down, preferably on a mat. Stretch your arms above your head in a "Y" position (arms pointing up diagonally at around 45 degrees). Your thumbs should be pointing up.
 Steps: 

 

• With arms in the Y position, lift your chest slightly from the ground, creating a pull tension in your arms upward.

• Hold this position for several seconds (15–30 is ideal).

• Keeping your chest up, bend at your elbows to move from a Y position to a "W" position, with arms bent at the elbows and maintaining the upward tension.

• Hold for around as long as with the Y position.

• Still with your chest up, move to a "T" position, straightening your arms out to the side to be perpendicular to your body.

• Hold for around as long as you held the W position.

• Move from the T position to the W position, then from the W position to the Y position.

• Repeat.', 'costas', '["costas"]', '[]', '[]', NULL, 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1083/view/', 'ywts costas', '2026-09-10T15:18:12.614Z');
